const { createProxyMiddleware } = require('http-proxy-middleware');

module.exports = function(app) {
  app.use(
    '/api',
    createProxyMiddleware({
      target: 'https://welovepalop.com',
      changeOrigin: true,
      secure: false,
    })
  );
};

import React, { createContext, useContext, useState, useCallback } from 'react';
import { CheckCircle, AlertCircle, X, Info } from 'lucide-react';

const ToastContext = createContext(null);

export const ToastProvider = ({ children }) => {
  const [toast, setToast] = useState(null);

  const showToast = useCallback((message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3500);
  }, []);

  return (
    <ToastContext.Provider value={{ showToast }}>
      {children}
      {toast && (
        <div className="fixed bottom-6 right-6 z-[9999] flex items-center gap-3 px-5 py-3 rounded-xl shadow-2xl text-white bg-gray-900 border border-gray-800">
          {toast.type === 'success' && <CheckCircle size={20} className="text-green-400 shrink-0" />}
          {toast.type === 'error' && <AlertCircle size={20} className="text-red-400 shrink-0" />}
          {toast.type === 'info' && <Info size={20} className="text-blue-400 shrink-0" />}
          <span className="text-sm font-medium tracking-wide">{toast.message}</span>
          <button onClick={() => setToast(null)} className="ml-2 text-gray-400 hover:text-white transition-colors">
            <X size={16} />
          </button>
        </div>
      )}
    </ToastContext.Provider>
  );
};

export const useToast = () => {
  const context = useContext(ToastContext);
  if (!context) throw new Error('useToast deve ser usado dentro de um ToastProvider');
  return context;
};

// src/components/AlojamentoRegisto/Comodidades.jsx
import React, { useState, useEffect, useCallback } from 'react';
import { Check, Loader, AlertCircle, Search } from 'lucide-react';
import { getIconeComodidade } from '../../utils/comodidadesQuarto';

const API_URL = 'https://welovepalop.com';

// ============================================================
// Helper local — usa a biblioteca central de ícones
// ============================================================
const getIcone = (iconeNome, nomeCompleto) => {
  return getIconeComodidade(nomeCompleto || iconeNome, 20);
};

const Comodidades = ({ alojamentoId, onChange, readOnly = false, initialComodidades = [] }) => {
  const [categoriaAtiva, setCategoriaAtiva] = useState('todas');
  const [busca, setBusca] = useState('');
  const [comodidades, setComodidades] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [saving, setSaving] = useState(false);
  const [toast, setToast] = useState(null);

  const showToast = (message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3000);
  };

  // ============================================================
  // SALVAR NO LOCALSTORAGE
  // ============================================================
  const salvarNoLocalStorage = useCallback((comodidadesSelecionadas) => {
    const comodidadesParaSalvar = comodidadesSelecionadas.map((c) => ({
      id: c.id,
      nome: c.nome,
      icone: c.icone,
      categoria: c.categoria,
    }));
    localStorage.setItem('propertyComodidades', JSON.stringify(comodidadesParaSalvar));
    console.log('💾 Comodidades salvas no localStorage:', comodidadesParaSalvar);
  }, []);

  // ============================================================
  // CARREGAR DO LOCALSTORAGE
  // ============================================================
  const carregarDoLocalStorage = useCallback(() => {
    const saved = localStorage.getItem('propertyComodidades');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed) && parsed.length > 0) {
          console.log('📦 Comodidades carregadas do localStorage:', parsed);
          return parsed;
        }
      } catch (e) {
        console.error('Erro ao carregar localStorage:', e);
      }
    }
    return [];
  }, []);

  // ============================================================
  // CARREGAR COMODIDADES DA API
  // ============================================================
  const fetchComodidades = async () => {
    try {
      setLoading(true);
      setError(null);

      let url;
      if (alojamentoId) {
        url = `${API_URL}/api/alojamento/buscar_comodidades_com_selecao.php?id=${alojamentoId}`;
      } else {
        url = `${API_URL}/api/alojamento/buscar_comodidades.php`;
      }

      console.log(`🔄 Buscando comodidades de: ${url}`);
      const response = await fetch(url);

      if (!response.ok) throw new Error(`HTTP ${response.status}`);

      const data = await response.json();
      console.log('📦 Resposta da API:', data);

      let comodidadesLista = [];

      if (alojamentoId) {
        if (data.success && Array.isArray(data.data)) {
          comodidadesLista = data.data;
        } else if (data.success && Array.isArray(data.comodidades)) {
          comodidadesLista = data.comodidades;
        }
      } else {
        if (data.success && Array.isArray(data.data)) {
          const savedComodidades = carregarDoLocalStorage();
          const savedIds = new Set(savedComodidades.map((c) => c.id));

          comodidadesLista = data.data.map((c) => ({
            ...c,
            selecionada: savedIds.has(c.id),
          }));
        }
      }

      if (comodidadesLista.length > 0) {
        setComodidades(comodidadesLista);

        const selecionadas = comodidadesLista.filter((c) => c.selecionada);
        if (onChange) {
          onChange(selecionadas);
        }

        if (!alojamentoId && selecionadas.length > 0) {
          salvarNoLocalStorage(selecionadas);
        }
      } else {
        setComodidades([]);
      }
    } catch (err) {
      console.error('❌ Erro ao carregar comodidades:', err);
      setError(err.message);

      const savedComodidades = carregarDoLocalStorage();
      if (savedComodidades.length > 0) {
        console.log('📦 Usando comodidades do localStorage como fallback');
        setComodidades(savedComodidades.map((c) => ({ ...c, selecionada: true })));
        if (onChange) onChange(savedComodidades);
      }
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchComodidades();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [alojamentoId]);

  // ============================================================
  // TOGGLE COMODIDADE
  // ============================================================
  const toggleComodidade = async (id) => {
    if (readOnly) return;

    const comodidade = comodidades.find((c) => c.id === id);
    if (!comodidade) return;

    const novoEstado = !comodidade.selecionada;

    setComodidades((prev) => {
      const novas = prev.map((c) =>
        c.id === id ? { ...c, selecionada: novoEstado } : c
      );

      const selecionadas = novas.filter((c) => c.selecionada);
      salvarNoLocalStorage(selecionadas);

      if (onChange) {
        onChange(selecionadas);
      }

      return novas;
    });

    showToast(
      novoEstado ? `${comodidade.nome} adicionada` : `${comodidade.nome} removida`,
      novoEstado ? 'success' : 'info'
    );

    if (alojamentoId) {
      setSaving(true);
      try {
        const response = await fetch(`${API_URL}/api/alojamento/alternar_comodidade.php`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            alojamento_id: alojamentoId,
            comodidade_id: id,
            ativar: novoEstado ? 1 : 0,
          }),
        });
        const data = await response.json();
        if (!data.success) {
          console.error('Erro ao salvar no backend');
        }
      } catch (error) {
        console.error('Erro ao salvar no backend:', error);
      } finally {
        setSaving(false);
      }
    }
  };

  // ============================================================
  // LIMPAR TODAS
  // ============================================================
  const limparTodas = () => {
    if (readOnly) return;

    setComodidades((prev) => {
      const novas = prev.map((c) => ({ ...c, selecionada: false }));
      salvarNoLocalStorage([]);
      if (onChange) onChange([]);
      return novas;
    });
    showToast('Todas as comodidades removidas', 'info');
  };

  // ============================================================
  // SELECIONAR TODAS DA CATEGORIA ATUAL
  // ============================================================
  const selecionarTodasDaCategoria = () => {
    if (readOnly) return;

    setComodidades((prev) => {
      const novas = prev.map((c) => {
        const categoria = c.categoria || 'Outros';
        if (categoriaAtiva === 'todas' || categoria === categoriaAtiva) {
          return { ...c, selecionada: true };
        }
        return c;
      });

      const selecionadas = novas.filter((c) => c.selecionada);
      salvarNoLocalStorage(selecionadas);
      if (onChange) onChange(selecionadas);
      return novas;
    });
    showToast(`Todas as comodidades da categoria selecionadas`, 'success');
  };

  const categorias = ['todas', ...new Set(comodidades.map((c) => c.categoria || 'Outros').filter((c) => c))];

  const comodidadesFiltradas = comodidades.filter((com) => {
    if (categoriaAtiva !== 'todas' && (com.categoria || 'Outros') !== categoriaAtiva) return false;
    if (busca && !com.nome?.toLowerCase().includes(busca.toLowerCase())) return false;
    return true;
  });

  const totalSelecionadas = comodidades.filter((c) => c.selecionada).length;
  const totalDisponiveis = comodidades.length;
  const porcentagemSelecionadas =
    totalDisponiveis > 0 ? Math.round((totalSelecionadas / totalDisponiveis) * 100) : 0;

  // ============================================================
  // ESTADOS DE LOADING / ERRO
  // ============================================================
  if (loading) {
    return (
      <div className="text-center py-12">
        <Loader className="animate-spin mx-auto text-[#006ce4]" size={40} />
        <p className="mt-3 text-gray-600">Carregando comodidades...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="bg-red-50 border border-red-200 rounded-lg p-6 text-center">
        <AlertCircle className="mx-auto text-red-500 mb-3" size={48} />
        <p className="text-red-700">Erro: {error}</p>
        <button
          onClick={() => fetchComodidades()}
          className="mt-4 px-4 py-2 bg-[#006ce4] text-white rounded-lg"
        >
          Tentar novamente
        </button>
      </div>
    );
  }

  // ============================================================
  // RENDER
  // ============================================================
  return (
    <div className="space-y-6">
      {/* Toast notifications */}
      {toast && (
        <div
          className={`fixed bottom-4 right-4 z-50 px-4 py-2 rounded-lg shadow-lg text-white ${
            toast.type === 'success' ? 'bg-green-500' : 'bg-blue-500'
          }`}
        >
          {toast.message}
        </div>
      )}

      {/* Indicador de salvamento */}
      {saving && (
        <div className="fixed bottom-4 left-4 bg-blue-500 text-white px-3 py-1 rounded-lg text-sm flex items-center gap-2 z-50">
          <Loader size={14} className="animate-spin" /> Salvando...
        </div>
      )}

      {/* Barra de pesquisa */}
      <div className="relative">
        <input
          type="text"
          value={busca}
          onChange={(e) => setBusca(e.target.value)}
          placeholder="Pesquisar comodidades..."
          className="w-full px-4 py-3 pl-10 border border-gray-300 rounded-lg focus:ring-2 focus:ring-[#006ce4] focus:border-transparent"
          disabled={readOnly}
        />
        <Search size={18} className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
      </div>

      {/* Cabeçalho com estatísticas */}
      <div className="flex flex-wrap items-center justify-between gap-4">
        <div className="flex gap-2">
          <button
            type="button"
            onClick={limparTodas}
            disabled={readOnly || totalSelecionadas === 0}
            className="px-3 py-1.5 text-sm bg-red-50 text-red-600 rounded-lg hover:bg-red-100 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            Limpar todas
          </button>
          <button
            type="button"
            onClick={selecionarTodasDaCategoria}
            disabled={readOnly}
            className="px-3 py-1.5 text-sm bg-blue-50 text-[#006ce4] rounded-lg hover:bg-blue-100"
          >
            Selecionar todas ({categoriaAtiva === 'todas' ? 'ativas' : 'da categoria'})
          </button>
        </div>

        <div className="text-sm text-gray-500">
          {totalSelecionadas} de {totalDisponiveis} comodidades selecionadas
          <div className="w-32 h-1.5 bg-gray-200 rounded-full mt-1 overflow-hidden">
            <div
              className="h-full bg-[#006ce4] rounded-full transition-all duration-300"
              style={{ width: `${porcentagemSelecionadas}%` }}
            />
          </div>
        </div>
      </div>

      {/* Categorias */}
      {categorias.length > 1 && (
        <div className="flex flex-wrap gap-2 overflow-x-auto pb-2">
          {categorias.map((cat) => (
            <button
              key={cat}
              type="button"
              onClick={() => setCategoriaAtiva(cat)}
              disabled={readOnly}
              className={`px-4 py-2 rounded-full text-sm font-medium transition-all whitespace-nowrap ${
                categoriaAtiva === cat
                  ? 'bg-[#006ce4] text-white'
                  : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
              }`}
            >
              {cat === 'todas' ? 'Todas' : cat}
              {cat !== 'todas' && (
                <span className="ml-2 text-xs">
                  ({comodidades.filter((c) => (c.categoria || 'Outros') === cat).length})
                </span>
              )}
            </button>
          ))}
        </div>
      )}

      {/* Grade de comodidades */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
        {comodidadesFiltradas.length === 0 && (
          <div className="col-span-full text-center py-8 text-gray-400">
            {busca ? 'Nenhuma comodidade encontrada para esta busca' : 'Nenhuma comodidade disponível'}
          </div>
        )}

        {comodidadesFiltradas.map((com) => (
          <button
            key={com.id}
            type="button"
            onClick={() => toggleComodidade(com.id)}
            disabled={readOnly}
            className={`flex items-center gap-3 p-3 rounded-lg border transition-all ${
              com.selecionada
                ? 'border-[#006ce4] bg-blue-50 text-[#006ce4] shadow-sm'
                : 'border-gray-200 hover:border-gray-300 hover:bg-gray-50'
            } ${readOnly ? 'cursor-default' : 'cursor-pointer'}`}
          >
            <div className={`${com.selecionada ? 'text-[#006ce4]' : 'text-gray-500'}`}>
              {getIcone(com.icone, com.nome)}
            </div>
            <span className="text-sm flex-1 text-left font-medium">{com.nome}</span>
            {com.selecionada && <Check size={16} className="text-[#006ce4]" />}
          </button>
        ))}
      </div>

      {/* Resumo das selecionadas */}
      {totalSelecionadas > 0 && (
        <div className="bg-gray-50 rounded-lg p-4 mt-4 border border-gray-200">
          <h4 className="font-semibold text-gray-700 mb-3 flex items-center gap-2">
            <Check size={16} className="text-green-500" />
            Comodidades selecionadas ({totalSelecionadas})
          </h4>
          <div className="flex flex-wrap gap-2">
            {comodidades.filter((c) => c.selecionada).map((com) => (
              <span
                key={com.id}
                className="px-3 py-1.5 bg-white border border-gray-200 rounded-full text-sm flex items-center gap-1.5 shadow-sm"
              >
                {getIcone(com.icone, com.nome)}
                {com.nome}
              </span>
            ))}
          </div>
        </div>
      )}

      {/* Mensagem de nenhuma selecionada */}
      {totalSelecionadas === 0 && !readOnly && (
        <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4 text-center">
          <AlertCircle size={24} className="mx-auto text-yellow-600 mb-2" />
          <p className="text-yellow-700 text-sm">
            Nenhuma comodidade selecionada. Selecione as comodidades disponíveis na sua propriedade.
          </p>
        </div>
      )}

      {/* Dica */}
      {totalSelecionadas > 0 && totalSelecionadas < 5 && (
        <div className="bg-blue-50 border border-blue-200 rounded-lg p-3 text-center">
          <p className="text-blue-700 text-sm">
            💡 Dica: Adicione mais comodidades para aumentar a visibilidade do seu anúncio!
          </p>
        </div>
      )}
    </div>
  );
};

export default Comodidades;

// src/components/AlojamentoRegisto/ComodidadesLista.jsx
import React, { useState } from 'react';
import {
  Check, ChevronDown, Grid, List, Search,
  Wifi, Snowflake, Tv, Coffee, Utensils, Waves, Car, Sun,
  Baby, Dumbbell, Wind, Flame, Refrigerator, Mic, Shirt, Lock,
  DoorOpen, Volume2, Fan, ShoppingBag,
} from 'lucide-react';
import { getIconeComodidade } from '../../utils/comodidadesQuarto';

// Mapeamento de ícones por categoria (para os cabeçalhos)
const CATEGORIAS = {
  'Internet e tecnologia':  <Wifi size={16} />,
  'Climatização':           <Snowflake size={16} />,
  'Entretenimento':         <Tv size={16} />,
  'Alimentação':            <Coffee size={16} />,
  'Cozinha':                <Utensils size={16} />,
  'Lazer':                  <Waves size={16} />,
  'Estacionamento':         <Car size={16} />,
  'Vistas':                 <Sun size={16} />,
  'Políticas':              <Baby size={16} />,
  'Utilidades':             <Shirt size={16} />,
  'Casa de banho':          <Wind size={16} />,
  'Segurança':              <Lock size={16} />,
  'Espaço exterior':        <Sun size={16} />,
  'Acessibilidade':         <DoorOpen size={16} />,
  'Desporto':               <Dumbbell size={16} />,
  'Serviços':               <ShoppingBag size={16} />,
  'Família':                <Baby size={16} />,
  'Roupa de cama e quarto': <Shirt size={16} />,
};

const ComodidadesLista = ({
  comodidades,
  className = '',
  showEmpty = true,
  compact = false,
  showSearch = true,
  showCategories = true,
  maxItems = 0,
  onVerMais,
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [expanded, setExpanded] = useState(false);
  const [viewMode, setViewMode] = useState('grid');

  // Filtrar comodidades por busca
  const comodidadesFiltradas = (comodidades || []).filter((com) =>
    (com.nome || '').toLowerCase().includes(searchTerm.toLowerCase())
  );

  // Agrupar por categoria
  const comodidadesPorCategoria = comodidadesFiltradas.reduce((acc, com) => {
    const categoria = com.categoria || 'Outras';
    if (!acc[categoria]) acc[categoria] = [];
    acc[categoria].push(com);
    return acc;
  }, {});

  // Ordenar categorias
  const categoriasOrdenadas = Object.keys(comodidadesPorCategoria).sort();

  // Limitar itens
  const totalItens = comodidadesFiltradas.length;
  const shouldTruncate = maxItems > 0 && totalItens > maxItems && !expanded;
  const itensToShow = shouldTruncate ? maxItems : totalItens;

  // Estado vazio
  if (!comodidades || comodidades.length === 0) {
    if (!showEmpty) return null;
    return (
      <div className={`text-center py-8 ${className}`}>
        <div className="w-12 h-12 mx-auto mb-3 bg-gray-100 rounded-full flex items-center justify-center">
          <Wifi size={24} className="text-gray-400" />
        </div>
        <p className="text-gray-400 text-sm">Nenhuma comodidade adicionada</p>
        <p className="text-gray-300 text-xs mt-1">Adicione comodidades para atrair mais hóspedes</p>
      </div>
    );
  }

  // Renderização compacta
  if (compact) {
    return (
      <div className={`flex flex-wrap gap-1.5 ${className}`}>
        {comodidades.slice(0, 8).map((com) => (
          <span
            key={com.id}
            className="inline-flex items-center gap-1 px-2 py-0.5 bg-gray-100 rounded-full text-xs text-gray-600"
          >
            {getIconeComodidade(com.nome, 14)}
            {com.nome}
          </span>
        ))}
        {comodidades.length > 8 && (
          <span className="text-xs text-gray-400">+{comodidades.length - 8}</span>
        )}
      </div>
    );
  }

  // Renderização em lista
  if (viewMode === 'list') {
    return (
      <div className={`space-y-2 ${className}`}>
        {showSearch && comodidades.length > 6 && (
          <div className="relative mb-4">
            <Search size={16} className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
            <input
              type="text"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              placeholder="Filtrar comodidades..."
              className="w-full pl-9 pr-4 py-2 text-sm border border-gray-200 rounded-lg focus:outline-none focus:border-[#006ce4]"
            />
          </div>
        )}

        <div className="divide-y divide-gray-100">
          {comodidadesFiltradas.slice(0, itensToShow).map((com) => (
            <div key={com.id} className="flex items-center gap-3 py-2">
              <div className="w-7 text-gray-400">{getIconeComodidade(com.nome, 18)}</div>
              <span className="text-sm text-gray-700 flex-1">{com.nome}</span>
              <span className="text-xs text-gray-400">{com.categoria}</span>
            </div>
          ))}
        </div>

        {shouldTruncate && (
          <button
            onClick={() => setExpanded(true)}
            className="text-sm text-[#006ce4] hover:underline mt-2 flex items-center gap-1"
          >
            Ver mais {totalItens - maxItems} comodidades <ChevronDown size={14} />
          </button>
        )}
      </div>
    );
  }

  // Renderização em grid (padrão)
  return (
    <div className={className}>
      {/* Barra de ferramentas */}
      <div className="flex justify-between items-center mb-4">
        <div className="flex items-center gap-2">
          <span className="text-sm font-medium text-gray-700">
            {comodidades.length} {comodidades.length === 1 ? 'comodidade' : 'comodidades'}
          </span>
          <button
            onClick={() => setViewMode('grid')}
            className={`p-1.5 rounded ${viewMode === 'grid' ? 'bg-gray-200' : 'hover:bg-gray-100'}`}
            title="Visualização em grade"
          >
            <Grid size={16} className="text-gray-500" />
          </button>
          <button
            onClick={() => setViewMode('list')}
            className={`p-1.5 rounded ${viewMode === 'list' ? 'bg-gray-200' : 'hover:bg-gray-100'}`}
            title="Visualização em lista"
          >
            <List size={16} className="text-gray-500" />
          </button>
        </div>

        {showSearch && comodidades.length > 6 && (
          <div className="relative">
            <Search size={14} className="absolute left-2 top-1/2 transform -translate-y-1/2 text-gray-400" />
            <input
              type="text"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              placeholder="Filtrar..."
              className="pl-7 pr-3 py-1 text-sm border border-gray-200 rounded-lg focus:outline-none focus:border-[#006ce4] w-36"
            />
          </div>
        )}
      </div>

      {/* Por categoria */}
      {showCategories ? (
        <div className="space-y-5">
          {categoriasOrdenadas.map((categoria) => {
            const coms = comodidadesPorCategoria[categoria];
            const catIcone = CATEGORIAS[categoria] || <Check size={14} />;

            return (
              <div key={categoria}>
                <div className="flex items-center gap-2 mb-2 pb-1 border-b border-gray-100">
                  <span className="text-blue-500">{catIcone}</span>
                  <h4 className="font-medium text-gray-700 text-sm">{categoria}</h4>
                  <span className="text-xs text-gray-400">({coms.length})</span>
                </div>
                <div className="flex flex-wrap gap-2">
                  {coms.map((com) => (
                    <span
                      key={com.id}
                      className="inline-flex items-center gap-1.5 px-2.5 py-1 bg-gray-50 hover:bg-gray-100 rounded-md text-xs text-gray-700 transition-colors"
                      title={com.nome}
                    >
                      <span className="text-gray-500">{getIconeComodidade(com.nome, 14)}</span>
                      <span className="max-w-[150px] truncate">{com.nome}</span>
                    </span>
                  ))}
                </div>
              </div>
            );
          })}
        </div>
      ) : (
        // Sem categorias
        <div className="flex flex-wrap gap-2">
          {comodidadesFiltradas.slice(0, itensToShow).map((com) => (
            <span
              key={com.id}
              className="inline-flex items-center gap-1.5 px-3 py-1.5 bg-gray-50 hover:bg-gray-100 rounded-lg text-sm text-gray-700 transition-colors"
            >
              <span className="text-gray-500">{getIconeComodidade(com.nome, 16)}</span>
              {com.nome}
            </span>
          ))}
        </div>
      )}

      {/* Botão ver mais */}
      {shouldTruncate && (
        <button
          onClick={() => setExpanded(true)}
          className="mt-4 text-sm text-[#006ce4] hover:underline flex items-center gap-1"
        >
          Ver mais {totalItens - maxItems} comodidades <ChevronDown size={14} />
        </button>
      )}

      {/* Resultado da busca vazia */}
      {searchTerm && comodidadesFiltradas.length === 0 && (
        <div className="text-center py-6">
          <p className="text-gray-400 text-sm">Nenhuma comodidade encontrada para "{searchTerm}"</p>
        </div>
      )}
    </div>
  );
};

