const API_BASE = 'https://welovepalop.com';

// Função para extrair o ID do utilizador do Token JWT de forma segura
const obterUserIdDoToken = () => {
  try {
    const token = localStorage.getItem('token') || localStorage.getItem('morabeza_token');
    if (!token) return null;
    const base64Url = token.split('.')[1];
    const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
    const jsonPayload = decodeURIComponent(atob(base64).split('').map(c => {
      return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
    }).join(''));
    const payload = JSON.parse(jsonPayload);
    return payload.data?.id || null;
  } catch (e) {
    return null;
  }
};

// ==================== TOAST INTERNO ====================
const ToastContext = createContext(null);

const ToastProviderInterno = ({ children }) => {
  const [toast, setToast] = useState(null);

  const showToast = useCallback((message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => {
      setToast(null);
    }, 3500);
  }, []);

  return (
    <ToastContext.Provider value={{ showToast }}>
      {children}
      {toast && (
        <div className="fixed bottom-6 right-6 z-50 flex items-center gap-3 px-5 py-3 rounded-xl shadow-2xl text-white bg-gray-900 border border-gray-800 transition-all">
          {toast.type === 'success' && <CheckCircle size={20} className="text-green-400 shrink-0" />}
          {toast.type === 'error' && <AlertCircle size={20} className="text-red-400 shrink-0" />}
          {toast.type === 'info' && <Info size={20} className="text-blue-400 shrink-0" />}
          <span className="text-sm font-medium tracking-wide">{toast.message}</span>
          <button onClick={() => setToast(null)} className="ml-2 text-gray-400 hover:text-white transition-colors">
            <X size={16} />
          </button>
        </div>
      )}
    </ToastContext.Provider>
  );
};

export const useToast = () => {
  const context = useContext(ToastContext);
  if (!context) {
    throw new Error('useToast deve ser usado dentro de um ToastProvider');
  }
  return context;
};

// ============================================================
// CARREGAR IMAGENS DOS QUARTOS FILTRADAS POR ALOJAMENTO
// ============================================================
const carregarImagensPorAlojamento = async (alojamentoId) => {
  try {
    const res = await fetch(`${API_BASE}/api/alojamento/get_quarto_imagens.php?t=${Date.now()}`, {
      cache: 'no-store',
    });
    const textData = await res.text();
    let data = null;

    try {
      data = JSON.parse(textData);
    } catch (e) {
      const match = textData.match(/\{[\s\S]*\}/);
      if (match) {
        try {
          data = JSON.parse(match[0]);
        } catch (err) {
          console.error('❌ JSON inválido:', err);
        }
      }
    }

    if (!data || !data.success) return {};

    const imagensPorQuarto = {};

    (data.data || []).forEach((img) => {
      if (Number(img.alojamento_id) !== Number(alojamentoId)) return;
      const quartoId = String(img.quarto_id);
      if (!imagensPorQuarto[quartoId]) imagensPorQuarto[quartoId] = [];
      imagensPorQuarto[quartoId].push(img.caminho_url);
    });

    console.log(`📸 [EditarAlojamento] Imagens do alojamento ${alojamentoId}:`, imagensPorQuarto);
    return imagensPorQuarto;
  } catch (err) {
    console.error('Erro ao carregar imagens:', err);
    return {};
  }
};

// ============================================================
// CARREGAR COMODIDADES DOS QUARTOS FILTRADAS POR ALOJAMENTO
// ============================================================
const carregarComodidadesPorAlojamento = async (alojamentoId) => {
  try {
    const res = await fetch(
      `${API_BASE}/api/alojamento/get_comodidades_quartos.php?alojamento_id=${alojamentoId}&t=${Date.now()}`,
      { cache: 'no-store' }
    );

    if (!res.ok) {
      console.warn(`⚠️ get_comodidades_quartos.php devolveu ${res.status}`);
      return {};
    }

    const data = await res.json();
    console.log('🛎️ [EditarAlojamento] Comodidades dos quartos:', data);

    let comodidadesPorQuarto = {};

    if (data.success && data.data) {
      const raw = data.data.quarto_comodidades || data.data;

      if (Array.isArray(raw)) {
        raw.forEach((item) => {
          const qId = item.quarto_id || item.id;
          if (qId) comodidadesPorQuarto[String(qId)] = item.comodidades || [];
        });
      } else if (typeof raw === 'object') {
        Object.entries(raw).forEach(([key, value]) => {
          comodidadesPorQuarto[String(key)] = value;
        });
      }
    } else if (Array.isArray(data)) {
      data.forEach((item) => {
        const qId = item.quarto_id || item.id;
        if (qId) comodidadesPorQuarto[String(qId)] = item.comodidades || [];
      });
    }

    return comodidadesPorQuarto;
  } catch (err) {
    console.error('Erro ao carregar comodidades dos quartos:', err);
    return {};
  }
};

// ==================== COMPONENTE PRINCIPAL ====================
const EditarAlojamentoContent = () => {
  const navigate = useNavigate();
  const { id } = useParams();
  const { showToast } = useToast();

  const [fase, setFase] = useState(1);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [alojamentoId, setAlojamentoId] = useState(id ? parseInt(id) : null);
  const [isLoading, setIsLoading] = useState(id ? true : false);
  const [quartosSelecionados, setQuartosSelecionados] = useState([]);

  // FASE 1 - Informações Básicas
  const [informacoesBasicas, setInformacoesBasicas] = useState({
    titulo: '',
    tipo_propriedade: 'Apartamento',
    capacidade: 2,
    estrelas: 4.5,
    descricao: '',
    descricao_detalhada: '',
    preco_noite: '',
    tempo_resposta: 'Dentro de 1 hora',
    quartos: 1,
    camas: 1,
    casas_banho: 1,
    checkin_inicio: '14:00',
    checkin_fim: '22:00',
    checkout_limite: '11:00',
    checkin_flexivel: 0,
    checkin_flexivel_nota: '',
  });

  // FASE 2 - Localização
  const [localizacaoDados, setLocalizacaoDados] = useState({
    endereco: '',
    cidade: '',
    ilha: '',
    codigo_postal: '',
    num_apartamento: '',
    morada_completa: '',
    latitude: null,
    longitude: null,
    coordenadas: { lat: null, lng: null },
  });

  // FASE 3 - Comodidades
  const [comodidadesSelecionadas, setComodidadesSelecionadas] = useState([]);

  // FASE 4 - Regras
  const [regras, setRegras] = useState([]);
  const [regrasAdicionais, setRegrasAdicionais] = useState('');

  // FASE 5 - Fotos Principais
  const [fotos, setFotos] = useState([]);

  // ==================== MODELO DE VENDA ====================
  const modeloVenda = modeloVendaPorTipo(informacoesBasicas.tipo_propriedade);
  const mostraQuartos = modeloVenda === 'por_quarto';

  // ==================== CARREGAR DADOS ====================
  const carregarDadosAlojamento = async (alojamentoIdParam) => {
    if (!alojamentoIdParam) return;

    setIsLoading(true);
    try {
      console.log(`📥 Carregando alojamento ID: ${alojamentoIdParam} para edição`);

      const resultado = await buscarAlojamentoParaEdicao(alojamentoIdParam);

      if (resultado.success && resultado.data) {
        const dados = resultado.data;

        setInformacoesBasicas({
          titulo: dados.titulo || '',
          tipo_propriedade: dados.tipo_propriedade || 'Apartamento',
          capacidade: dados.capacidade || 2,
          estrelas: dados.estrelas || 4.5,
          descricao: dados.descricao || '',
          descricao_detalhada: dados.descricao_detalhada || '',
          preco_noite: dados.preco_noite || '',
          tempo_resposta: dados.tempo_resposta || 'Dentro de 1 hora',
          quartos: dados.quartos || 1,
          camas: dados.camas || 1,
          casas_banho: dados.casas_banho || 1,
          checkin_inicio: dados.checkin_inicio ? String(dados.checkin_inicio).substring(0, 5) : '14:00',
          checkin_fim: dados.checkin_fim ? String(dados.checkin_fim).substring(0, 5) : '22:00',
          checkout_limite: dados.checkout_limite ? String(dados.checkout_limite).substring(0, 5) : '11:00',
          checkin_flexivel: dados.checkin_flexivel ? 1 : 0,
          checkin_flexivel_nota: dados.checkin_flexivel_nota || '',
        });

        // 🔥 CARREGAR QUARTOS DESTE ALOJAMENTO
        let quartosDaBd = [];
        if (dados.quartos && Array.isArray(dados.quartos) && dados.quartos.length > 0) {
          quartosDaBd = dados.quartos;
        } else {
          const quartosResult = await buscarQuartosDoAlojamento(alojamentoIdParam);
          if (quartosResult.success && quartosResult.data) {
            quartosDaBd = quartosResult.data;
          }
        }

        // 🔥 CARREGAR IMAGENS SÓ DESTE ALOJAMENTO
        const imagensPorQuarto = await carregarImagensPorAlojamento(alojamentoIdParam);

        // 🔥 CARREGAR COMODIDADES SÓ DESTE ALOJAMENTO
        const comodidadesPorQuarto = await carregarComodidadesPorAlojamento(alojamentoIdParam);

        console.log('🔑 IDs dos quartos da BD:', quartosDaBd.map((q) => q.id));
        console.log('🗺️ Comodidades por quarto:', comodidadesPorQuarto);

        // 🔥 CRUZAR: cada quarto recebe APENAS as suas imagens E comodidades
        const quartosMapeados = quartosDaBd.map((q) => {
          // ⚠️ ID REAL DA BD — NUNCA sobrescrever, é a chave para comodidades e imagens
          const quartoId = String(q.id);
          const tipoQuartoId = q.tipo_catalogo_id || q.tipo_quarto_id || q.tipo_id;

          const fotosDesteQuarto = imagensPorQuarto[quartoId] || [];
          const comodidadesDesteQuarto = comodidadesPorQuarto[quartoId] || [];

          return {
            ...q,
            // ⚠️ GARANTIR que o id real é preservado (não usar tipo_quarto_id como id)
            id: q.id,
            tipo_quarto_id: tipoQuartoId,
            tipo_catalogo_id: tipoQuartoId,
            quantidade_disponivel: q.quantidade ?? q.quantidade_disponivel ?? 1,
            preco_personalizado: q.preco_noite ?? q.preco_personalizado ?? null,
            fotos: fotosDesteQuarto,
            imagens: fotosDesteQuarto,
            comodidades: comodidadesDesteQuarto,
          };
        });

        console.log('✅ Quartos mapeados com comodidades:', quartosMapeados.map((q) => ({
          id: q.id,
          tipo_nome: q.tipo_nome,
          qtd_comodidades: q.comodidades?.length || 0,
          qtd_fotos: q.fotos?.length || 0,
        })));

        setQuartosSelecionados(quartosMapeados);

        const endereco = dados.localizacao || dados.endereco || '';
        const cidade = dados.cidade || '';
        const ilha = dados.ilha || '';
        const codigo_postal = dados.codigo_postal || '';
        const num_apartamento = dados.num_apartamento || '';
        const latitude = dados.latitude ? parseFloat(dados.latitude) : null;
        const longitude = dados.longitude ? parseFloat(dados.longitude) : null;

        const partes = [];
        if (endereco) partes.push(endereco);
        if (num_apartamento) partes.push(num_apartamento);
        if (cidade) partes.push(cidade);
        if (codigo_postal) partes.push(codigo_postal);
        if (ilha) partes.push(ilha);
        if (partes.length > 0) partes.push('Cabo Verde');
        const morada_completa = partes.join(', ');

        const localizacao = {
          endereco: endereco,
          cidade: cidade,
          ilha: ilha,
          codigo_postal: codigo_postal,
          num_apartamento: num_apartamento,
          morada_completa: morada_completa,
          latitude: latitude,
          longitude: longitude,
          coordenadas: { lat: latitude, lng: longitude },
        };
        setLocalizacaoDados(localizacao);

        const comodidadesList = Array.isArray(dados.comodidades) ? dados.comodidades : [];
        setComodidadesSelecionadas(comodidadesList);

        const regrasList = dados.regras?.regras || [];
        const regrasAdd = dados.regras?.regrasAdicionais || dados.regras?.regras_adicionais || '';
        setRegras(regrasList);
        setRegrasAdicionais(regrasAdd);

        try {
          const imagensResult = await buscarImagensDoAlojamento(alojamentoIdParam);
          if (imagensResult.success && imagensResult.data) {
            let fotosList = Array.isArray(imagensResult.data)
              ? imagensResult.data
              : imagensResult.data.imagens || [];
            const fotosMapeadas = fotosList.map((foto, index) => ({
              id: foto.id || index,
              url: foto.caminho_url || foto.url || foto.path || '',
              caminho_url: foto.caminho_url || foto.url || foto.path || '',
              principal: foto.principal || (index === 0 ? 1 : 0),
              ordem: foto.ordem || index,
            }));
            setFotos(fotosMapeadas);
          }
        } catch (imgError) {
          console.error('Erro ao carregar imagens:', imgError);
        }

        setAlojamentoId(dados.id);
      } else {
        showToast(`Erro ao carregar dados do alojamento: ${resultado.message}`, 'error');
        setTimeout(() => navigate('/alojamento-registro/meus'), 2000);
      }
    } catch (error) {
      console.error('Erro ao carregar dados:', error);
      showToast('Erro ao carregar dados do alojamento.', 'error');
      setTimeout(() => navigate('/alojamento-registro/meus'), 2000);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    if (id) carregarDadosAlojamento(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  // ==================== HANDLERS ====================
  const handleLocalizacaoChange = useCallback((dados) => {
    setLocalizacaoDados(dados);
  }, []);

  const handleComodidadesChange = useCallback((comodidades) => {
    setComodidadesSelecionadas(comodidades);
  }, []);

  const handleRegrasChange = useCallback((dadosRegras) => {
    setRegras(dadosRegras.regras || []);
    setRegrasAdicionais(dadosRegras.regrasAdicionais || '');
  }, []);

  // ⚠️ useCallback + comparação por JSON para evitar loop infinito de renders
  const handleQuartosChange = useCallback((quartos) => {
    setQuartosSelecionados((prev) => {
      if (JSON.stringify(prev) === JSON.stringify(quartos)) return prev;
      return quartos;
    });
  }, []);

  // ==================== NAVEGAÇÃO ====================
  const handleSaveInformacoes = () => {
    if (!informacoesBasicas.titulo.trim()) {
      showToast('O título é obrigatório', 'error');
      return;
    }
    if (!informacoesBasicas.descricao.trim()) {
      showToast('A descrição é obrigatória', 'error');
      return;
    }
    if (!informacoesBasicas.preco_noite) {
      showToast('O preço por noite é obrigatório', 'error');
      return;
    }

    if (informacoesBasicas.checkin_flexivel && !informacoesBasicas.checkin_flexivel_nota?.trim()) {
      showToast('Explique como o hóspede faz o check-in.', 'error');
      return;
    }
    if (!informacoesBasicas.checkin_flexivel) {
      if (!informacoesBasicas.checkin_inicio || !informacoesBasicas.checkin_fim) {
        showToast('Defina o intervalo de check-in.', 'error');
        return;
      }
      if (informacoesBasicas.checkin_inicio >= informacoesBasicas.checkin_fim) {
        showToast('A hora final do check-in deve ser depois do início.', 'error');
        return;
      }
    }
    if (!informacoesBasicas.checkout_limite) {
      showToast('Defina a hora limite de check-out.', 'error');
      return;
    }

    setFase(2);
  };

  const handleSaveLocalizacao = () => {
    if (!localizacaoDados.endereco?.trim()) {
      showToast('Insira o endereço', 'error');
      return;
    }
    if (!localizacaoDados.cidade?.trim()) {
      showToast('Insira a cidade', 'error');
      return;
    }
    if (!localizacaoDados.ilha?.trim()) {
      showToast('Selecione a ilha', 'error');
      return;
    }
    setFase(3);
  };

  const handleSaveComodidades = () => setFase(4);
  const handleSaveRegras = () => setFase(5);

  // ==================== FINALIZAR ====================
  const handleFinalizar = async () => {
    if (isSubmitting) return;
    setIsSubmitting(true);

    try {
      if (fotos.length === 0) {
        showToast('⚠️ Adicione pelo menos uma foto do seu alojamento', 'error');
        setIsSubmitting(false);
        return;
      }

      const quartosFormatados = quartosSelecionados.map((q) => {
        const fotosValidas = (q.fotos || [])
          .map((f) => (typeof f === 'string' ? f : f.url || f.caminho_url || f.path || ''))
          .filter((url) => url && !url.startsWith('blob:'));

        // ⚠️ Comodidades do quarto — enviar como array de IDs
        const comodidadesDoQuarto = Array.isArray(q.comodidades)
          ? q.comodidades.map((c) => (typeof c === 'object' ? c.id : c)).filter((cid) => cid != null)
          : [];

        return {
          // ⚠️ ID REAL DA BD — essencial para o backend fazer UPDATE e associar comodidades
          id: q.id || null,
          tipo_catalogo_id: q.tipo_catalogo_id || q.tipo_quarto_id || q.tipo_id || q.id,
          tipo_quarto_id: q.tipo_quarto_id || q.tipo_catalogo_id || q.tipo_id || q.id,
          quantidade: q.quantidade ?? q.quantidade_disponivel ?? 1,
          quantidade_disponivel: q.quantidade_disponivel || q.quantidade || 1,
          preco_noite: q.preco_noite ?? q.preco_personalizado ?? null,
          preco_personalizado: q.preco_personalizado ?? q.preco_noite ?? null,
          fotos: fotosValidas,
          imagens: fotosValidas,
          comodidades: comodidadesDoQuarto,
        };
      });

      const comodidadesIds = comodidadesSelecionadas.map((c) => c.id || c);
      const regrasIds = regras.map((r) => r.id || r);

      const imagensFormatadas = fotos
        .filter((foto) => !!(foto.url || foto.caminho_url || foto.path))
        .map((foto, index) => {
          const url = foto.url || foto.caminho_url || foto.path || '';
          return {
            url: url,
            caminho_url: url,
            principal: index === 0 ? 1 : 0,
            ordem: index,
            id: foto.id || null,
          };
        });

      const capacidadeQuartos = quartosFormatados.reduce(
        (total, q) => total + ((q.capacidade_efetiva || q.capacidade || 2) * (q.quantidade || 1)),
        0
      );

      const capacidadeFinal = mostraQuartos
        ? capacidadeQuartos || informacoesBasicas.capacidade || 2
        : parseInt(informacoesBasicas.capacidade) || 2;

      // 🔥 Obter com segurança o ID do utilizador autenticado através do token JWT
      const userIdAutenticado = obterUserIdDoToken();

      const dadosParaAPI = {
        proprietario_id: userIdAutenticado,
        titulo: informacoesBasicas.titulo,
        tipo_propriedade: informacoesBasicas.tipo_propriedade,
        tipo: informacoesBasicas.tipo_propriedade,
        descricao: informacoesBasicas.descricao,
        descricao_detalhada: informacoesBasicas.descricao_detalhada || '',
        capacidade: capacidadeFinal,
        preco_noite: parseFloat(informacoesBasicas.preco_noite) || 0,
        estrelas: parseFloat(informacoesBasicas.estrelas) || 4.5,
        tempo_resposta: informacoesBasicas.tempo_resposta || 'Dentro de 1 hora',
        cidade: localizacaoDados.cidade,
        ilha: localizacaoDados.ilha,
        endereco: localizacaoDados.endereco,
        latitude: localizacaoDados.latitude,
        longitude: localizacaoDados.longitude,
        comodidades: comodidadesIds,
        regras_ids: regrasIds,
        regras_adicionais: regrasAdicionais,
        modelo_venda: modeloVenda,
        quartos: mostraQuartos ? quartosFormatados : [],
        checkin_inicio: informacoesBasicas.checkin_flexivel
          ? null
          : informacoesBasicas.checkin_inicio || '14:00',
        checkin_fim: informacoesBasicas.checkin_flexivel
          ? null
          : informacoesBasicas.checkin_fim || '22:00',
        checkout_limite: informacoesBasicas.checkout_limite || '11:00',
        checkin_flexivel: informacoesBasicas.checkin_flexivel ? 1 : 0,
        checkin_flexivel_nota: informacoesBasicas.checkin_flexivel
          ? informacoesBasicas.checkin_flexivel_nota || ''
          : null,
        imagens: imagensFormatadas,
      };

      console.log('📤 Payload enviado para atualizar:', dadosParaAPI);

      const result = await salvarFluxoRegisto(dadosParaAPI, alojamentoId);

      if (result.success) {
        showToast(`✅ ${result.message || 'Alojamento atualizado com sucesso!'}`, 'success');
        setTimeout(() => navigate('/alojamento-registro/meus'), 1500);
      } else {
        showToast(`⚠️ Erro: ${result.message || 'Falha ao atualizar'}`, 'error');
      }
    } catch (error) {
      console.error('Erro ao finalizar:', error);
      showToast('Erro ao atualizar alojamento.', 'error');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleBack = () => {
    if (fase > 1) setFase(fase - 1);
    else navigate('/alojamento-registro/meus');
  };

  const renderProgressBar = () => {
    const fasesLista = ['Informações', 'Localização', 'Comodidades', 'Regras', 'Fotos'];
    return (
      <div className="mb-6">
        <div className="flex items-center justify-between mb-2">
          {fasesLista.map((nome, index) => (
            <div key={index} className="flex-1 text-center">
              <div className={`text-xs font-bold ${fase === index + 1 ? 'text-[#006ce4]' : 'text-gray-400'}`}>
                {nome}
              </div>
            </div>
          ))}
        </div>
        <div className="flex gap-1">
          {fasesLista.map((_, index) => (
            <div
              key={index}
              className={`h-1.5 flex-1 rounded-full ${fase >= index + 1 ? 'bg-[#006ce4]' : 'bg-gray-200'}`}
            />
          ))}
        </div>
      </div>
    );
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <Loader size={36} className="animate-spin text-[#006ce4] mx-auto mb-3" />
          <p className="text-sm font-semibold text-gray-600">A carregar dados do alojamento...</p>
        </div>
      </div>
    );
  }

  return (
    <>
      <header className="bg-[#003580] text-white h-[60px] flex items-center justify-between px-6 shadow-sm">
        <div className="font-bold text-lg tracking-tight"></div>
        <div className="flex items-center gap-6 text-sm">
          <PropMenu
            nomePropriedade={informacoesBasicas.titulo || 'Nova Propriedade'}
            alojamentoId={alojamentoId}
            onEditName={() => setFase(1)}
            onEditLocation={() => setFase(2)}
            onEditComodidades={() => setFase(3)}
            onEditRegras={() => setFase(4)}
          />
          <div className="flex items-center gap-2 cursor-pointer hover:underline">
            <span>Ajuda</span> <HelpCircle size={18} />
          </div>
        </div>
      </header>

      {fase === 1 && (
        <div className="min-h-screen bg-gray-50 py-10">
          <div className="max-w-4xl mx-auto px-4">
            <button onClick={handleBack} className="flex items-center gap-2 text-gray-600 hover:text-gray-900 mb-6">
              <ArrowLeft size={20} /><span>Voltar</span>
            </button>
            {renderProgressBar()}

            <div className="bg-white rounded-2xl shadow-sm p-8 border border-gray-100">
              <h1 className="text-2xl font-bold text-gray-900 mb-2">Editar informações da propriedade</h1>
              <p className="text-sm text-gray-500 mb-8">Atualize os dados e a configuração dos quartos.</p>

              <InformacoesBasicas
                dados={informacoesBasicas}
                onDadosChange={setInformacoesBasicas}
                onQuartosChange={handleQuartosChange}
                quartosIniciais={quartosSelecionados}
                alojamentoId={alojamentoId}
                readOnly={false}
                mostraQuartos={mostraQuartos}
              />

              <div className="flex justify-between gap-4 mt-8 pt-6 border-t border-gray-100">
                <button onClick={handleBack} className="px-6 py-2.5 border border-gray-300 text-gray-700 rounded-xl">
                  Voltar
                </button>
                <button
                  onClick={handleSaveInformacoes}
                  className="px-6 py-2.5 bg-[#006ce4] text-white font-bold rounded-xl flex items-center gap-2"
                >
                  Continuar <ChevronRight size={18} />
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {fase === 2 && (
        <div className="min-h-screen bg-gray-50 py-10">
          <div className="max-w-2xl mx-auto px-4">
            <button onClick={handleBack} className="flex items-center gap-2 text-gray-600 hover:text-gray-900 mb-6">
              <ArrowLeft size={20} /><span>Voltar</span>
            </button>
            {renderProgressBar()}

            <div className="bg-white rounded-2xl shadow-sm p-8 border border-gray-100">
              <h2 className="text-xl font-bold mb-4">📍 Localização do Alojamento</h2>

              <RegistarLocalizacao
                dados={localizacaoDados}
                onChange={handleLocalizacaoChange}
                alojamentoId={alojamentoId}
                readOnly={false}
              />

              <div className="flex justify-between gap-4 mt-8">
                <button onClick={handleBack} className="px-6 py-2.5 border rounded-xl">Voltar</button>
                <button
                  onClick={handleSaveLocalizacao}
                  className="px-6 py-2.5 bg-[#006ce4] text-white font-bold rounded-xl"
                >
                  Continuar
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {fase === 3 && (
        <div className="min-h-screen bg-gray-50 py-10">
          <div className="max-w-4xl mx-auto px-4">
            <button onClick={handleBack} className="flex items-center gap-2 text-gray-600 hover:text-gray-900 mb-6">
              <ArrowLeft size={20} /><span>Voltar</span>
            </button>
            {renderProgressBar()}

            <div className="bg-white rounded-2xl shadow-sm p-8 border border-gray-100">
              <h1 className="text-2xl font-bold text-gray-900 mb-2">Comodidades da propriedade</h1>

              <Comodidades
                alojamentoId={alojamentoId}
                onChange={handleComodidadesChange}
                initialComodidades={comodidadesSelecionadas}
                readOnly={false}
              />

              <div className="flex justify-between gap-4 mt-8 pt-6 border-t border-gray-100">
                <button onClick={handleBack} className="px-6 py-2.5 border rounded-xl">Voltar</button>
                <button
                  onClick={handleSaveComodidades}
                  className="px-6 py-2.5 bg-[#006ce4] text-white font-bold rounded-xl flex items-center gap-2"
                >
                  Continuar <ChevronRight size={18} />
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {fase === 4 && (
        <div className="min-h-screen bg-gray-50 py-10">
          <div className="max-w-3xl mx-auto px-4">
            <button onClick={handleBack} className="flex items-center gap-2 text-gray-600 hover:text-gray-900 mb-6">
              <ArrowLeft size={20} /><span>Voltar</span>
            </button>
            {renderProgressBar()}

            <div className="bg-white rounded-2xl shadow-sm p-8 border border-gray-100">
              <h1 className="text-2xl font-bold text-gray-900 mb-2">Regras da casa</h1>

              <Regras
                alojamentoId={alojamentoId}
                onChange={handleRegrasChange}
                initialRegras={regras}
                initialRegrasAdicionais={regrasAdicionais}
                readOnly={false}
              />

              <div className="flex justify-between gap-4 mt-8 pt-6 border-t border-gray-100">
                <button onClick={handleBack} className="px-6 py-2.5 border rounded-xl">Voltar</button>
                <button
                  onClick={handleSaveRegras}
                  className="px-6 py-2.5 bg-[#006ce4] text-white font-bold rounded-xl flex items-center gap-2"
                >
                  Continuar <ChevronRight size={18} />
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {fase === 5 && (
        <div className="min-h-screen bg-gray-50 py-10">
          <div className="max-w-4xl mx-auto px-4">
            <button onClick={handleBack} className="flex items-center gap-2 text-gray-600 hover:text-gray-900 mb-6">
              <ArrowLeft size={20} /><span>Voltar</span>
            </button>
            {renderProgressBar()}

            <div className="bg-white rounded-2xl shadow-sm p-8 border border-gray-100">
              <h1 className="text-2xl font-bold text-gray-900 mb-2">Fotos da sua propriedade</h1>
              <p className="text-sm text-gray-500 mb-8">Adicione fotos de alta qualidade da propriedade.</p>

              <ImagensUpload
                fotos={fotos}
                onFotosChange={setFotos}
                quartos={quartosSelecionados}
                onQuartosChange={handleQuartosChange}
                maxFotos={20}
                alojamentoId={alojamentoId}
                mostraQuartos={mostraQuartos}
              />

              <div className="flex justify-between gap-4 mt-8 pt-6 border-t border-gray-100">
                <button onClick={handleBack} className="px-6 py-2.5 border rounded-xl">Voltar</button>
                <button
                  onClick={handleFinalizar}
                  disabled={isSubmitting}
                  className="bg-emerald-600 hover:bg-emerald-700 text-white font-bold px-8 py-2.5 rounded-xl flex items-center gap-2 disabled:opacity-50 transition-colors"
                >
                  {isSubmitting ? <Loader size={18} className="animate-spin" /> : <Check size={18} />}
                  Atualizar Registo
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

// Wrapper com Provider
const EditarAlojamento = () => (
  <ToastProviderInterno>
    <EditarAlojamentoContent />
  </ToastProviderInterno>
);

export default EditarAlojamento;

// src/components/AlojamentoRegisto/FluxoRegisto.jsx
import React, { useState, useCallback, useRef, useEffect, createContext, useContext } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { ArrowLeft, Check, HelpCircle, ChevronRight, Loader, CheckCircle, AlertCircle, Info, X, Save, Eye } from 'lucide-react';
import PropMenu from './PropMenu';
import Comodidades from './Comodidades';
import InformacoesBasicas from './InformacoesBasicas';
import Regras from './Regras';
import ImagensUpload from './ImagensUpload';
import RegistarLocalizacao from './RegistarLocalizacao';
import { salvarFluxoRegisto, buscarAlojamentoParaEdicao } from '../../services/apiService';
import 'mapbox-gl/dist/mapbox-gl.css';
import { modeloVendaPorTipo } from '../../utils/tipoAlojamento';

// ==================== TOAST INTERNO (Garante que nunca dá erro de Provider) ====================
const ToastContext = createContext(null);

const ToastProviderInterno = ({ children }) => {
  const [toast, setToast] = useState(null);

  const showToast = useCallback((message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => {
      setToast(null);
    }, 3500);
  }, []);

  return (
    <ToastContext.Provider value={{ showToast }}>
      {children}
      {toast && (
        <div className="fixed bottom-6 right-6 z-50 flex items-center gap-3 px-5 py-3 rounded-xl shadow-2xl text-white bg-gray-900 border border-gray-800 transition-all">
          {toast.type === 'success' && <CheckCircle size={20} className="text-green-400 shrink-0" />}
          {toast.type === 'error' && <AlertCircle size={20} className="text-red-400 shrink-0" />}
          {toast.type === 'info' && <Info size={20} className="text-blue-400 shrink-0" />}
          <span className="text-sm font-medium tracking-wide">{toast.message}</span>
          <button onClick={() => setToast(null)} className="ml-2 text-gray-400 hover:text-white transition-colors">
            <X size={16} />
          </button>
        </div>
      )}
    </ToastContext.Provider>
  );
};

export const useToast = () => {
  const context = useContext(ToastContext);
  if (!context) {
    throw new Error('useToast deve ser usado dentro de um ToastProvider');
  }
  return context;
};

// ==================== CHAVE DO RASCUNHO ====================
const RASCUNHO_KEY = 'morabeza_rascunho_alojamento';

// ==================== COMPONENTE PRINCIPAL ====================
const FluxoRegistoContent = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const { showToast } = useToast();

  // Estados das fases
  const [fase, setFase] = useState(1);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSavingDraft, setIsSavingDraft] = useState(false);
  const [alojamentoId, setAlojamentoId] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [statusAtual, setStatusAtual] = useState('rascunho');
  const [mostrarConfirmacaoRemover, setMostrarConfirmacaoRemover] = useState(false);

  // FASE 1 - Informações Básicas
  const [informacoesBasicas, setInformacoesBasicas] = useState({
    titulo: '',
    tipo_propriedade: 'Apartamento',
    capacidade: 2,
    estrelas: 4.5,
    descricao: '',
    descricao_detalhada: '',
    preco_noite: '',
    tempo_resposta: 'Dentro de 1 hora',
    quartos: 1,
    camas: 1,
    casas_banho: 1,
    checkin_inicio: '14:00',
    checkin_fim: '22:00',
    checkout_limite: '11:00',
    checkin_flexivel: 0,
    checkin_flexivel_nota: ''
  });

  // FASE 2 - Localização
  const [localizacaoDados, setLocalizacaoDados] = useState({
    endereco: '',
    cidade: '',
    ilha: '',
    codigo_postal: '',
    num_apartamento: '',
    morada_completa: '',
    latitude: null,
    longitude: null,
    coordenadas: { lat: null, lng: null }
  });

  // FASE 3 - Comodidades
  const [comodidadesSelecionadas, setComodidadesSelecionadas] = useState([]);

  // FASE 4 - Regras
  const [regrasIds, setRegrasIds] = useState([]);
  const [regrasAdicionais, setRegrasAdicionais] = useState('');
  const [regrasObjetos, setRegrasObjetos] = useState([]);

  // FASE 5 - Fotos e Quartos
  const [fotos, setFotos] = useState([]);
  const [quartosParaEnviar, setQuartosParaEnviar] = useState([]);

  // Refs para controlar carregamento inicial
  const isInitialLoad = useRef(true);
  const isEditing = useRef(false);

  // ==================== MODELO DE VENDA (DERIVADO DO TIPO) ====================
  const modeloVenda = modeloVendaPorTipo(informacoesBasicas.tipo_propriedade);
  const mostraQuartos = modeloVenda === 'por_quarto';

  // Diagnóstico temporário
  useEffect(() => {
    console.log(
      '🔎 tipo:', informacoesBasicas.tipo_propriedade,
      '→ modelo:', modeloVenda,
      '→ mostraQuartos:', mostraQuartos
    );
  }, [informacoesBasicas.tipo_propriedade, modeloVenda, mostraQuartos]);

  // Quando o tipo muda para "inteiro", limpar quartos já selecionados
  useEffect(() => {
    if (!mostraQuartos && quartosParaEnviar.length > 0) {
      console.log('🏠 Tipo inteiro — a limpar quartos selecionados');
      setQuartosParaEnviar([]);
    }
  }, [mostraQuartos, quartosParaEnviar.length]);

  // ==================== GUARDAR RASCUNHO NO LOCALSTORAGE ====================
  const guardarRascunhoLocal = () => {
    const dados = {
      fase,
      informacoesBasicas,
      localizacaoDados,
      comodidadesSelecionadas,
      regrasIds,
      regrasAdicionais,
      regrasObjetos,
      fotos,
      quartosParaEnviar,
      modeloVenda,
      atualizadoEm: new Date().toISOString()
    };

    try {
      localStorage.setItem(RASCUNHO_KEY, JSON.stringify(dados));
      showToast('Rascunho guardado localmente', 'success');
    } catch (err) {
      console.error('Erro ao guardar rascunho:', err);
      showToast('Não foi possível guardar o rascunho', 'error');
    }
  };

  // ==================== ABRIR CAIXA DE CONFIRMAÇÃO ====================
  const pedirConfirmacaoRemoverRascunho = () => {
    setMostrarConfirmacaoRemover(true);
  };

  // ==================== CONFIRMAR E REMOVER RASCUNHO ====================
  const confirmarRemoverRascunho = () => {
    localStorage.removeItem(RASCUNHO_KEY);

    // Limpa o formulário
    setInformacoesBasicas({
      titulo: '',
      tipo_propriedade: 'Apartamento',
      capacidade: 2,
      estrelas: 4.5,
      descricao: '',
      descricao_detalhada: '',
      preco_noite: '',
      tempo_resposta: 'Dentro de 1 hora',
      quartos: 1,
      camas: 1,
      casas_banho: 1,
      checkin_inicio: '14:00',
      checkin_fim: '22:00',
      checkout_limite: '11:00',
      checkin_flexivel: 0,
      checkin_flexivel_nota: ''
    });
    setLocalizacaoDados({
      endereco: '',
      cidade: '',
      ilha: '',
      codigo_postal: '',
      num_apartamento: '',
      morada_completa: '',
      latitude: null,
      longitude: null,
      coordenadas: { lat: null, lng: null }
    });
    setComodidadesSelecionadas([]);
    setRegrasIds([]);
    setRegrasAdicionais('');
    setRegrasObjetos([]);
    setFotos([]);
    setQuartosParaEnviar([]);
    setFase(1);
    setAlojamentoId(null);
    setStatusAtual('rascunho');

    navigate('/alojamento-registro', { replace: true });

    setMostrarConfirmacaoRemover(false);
    showToast('Rascunho removido', 'success');
  };

  // ==================== CARREGAR RASCUNHO DO LOCALSTORAGE (só novo registo) ====================
  useEffect(() => {
    const id = searchParams.get('id');

    // Se tem ID → é edição de anúncio já existente → não usa localStorage
    if (id) return;

    try {
      const raw = localStorage.getItem(RASCUNHO_KEY);
      if (!raw) return;

      const dados = JSON.parse(raw);

      if (dados.informacoesBasicas) setInformacoesBasicas(dados.informacoesBasicas);
      if (dados.localizacaoDados) setLocalizacaoDados(dados.localizacaoDados);
      if (dados.comodidadesSelecionadas) setComodidadesSelecionadas(dados.comodidadesSelecionadas);
      if (dados.regrasIds) setRegrasIds(dados.regrasIds);
      if (dados.regrasAdicionais) setRegrasAdicionais(dados.regrasAdicionais);
      if (dados.regrasObjetos) setRegrasObjetos(dados.regrasObjetos);
      if (dados.fotos) setFotos(dados.fotos);
      if (dados.quartosParaEnviar) setQuartosParaEnviar(dados.quartosParaEnviar);
      if (dados.fase) setFase(dados.fase);

      showToast('Rascunho recuperado', 'info');
    } catch (err) {
      console.warn('Erro ao carregar rascunho:', err);
      localStorage.removeItem(RASCUNHO_KEY);
    }
  }, [searchParams]);

  // ==================== CLEANUP PARA NOVO REGISTO (quando não há rascunho) ====================
  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const id = urlParams.get('id');

    if (!id) {
      // Só limpa storages antigos se NÃO existir rascunho
      const temRascunho = !!localStorage.getItem(RASCUNHO_KEY);
      if (!temRascunho) {
        console.log('🧹 Novo registo - limpando dados antigos...');

        try {
          const storageKeys = [
            'quartos_temporarios', 'quartos_editando', 'quartos_alojamento_id',
            'informacoes_basicas_temp', 'localizacao_temp', 'comodidades_temp',
            'regras_temp', 'fotos_temp'
          ];

          storageKeys.forEach(key => {
            if (localStorage.getItem(key)) localStorage.removeItem(key);
          });

          const sessionKeys = ['quartos_temp', 'alojamento_temp'];
          sessionKeys.forEach(key => {
            if (sessionStorage.getItem(key)) sessionStorage.removeItem(key);
          });

        } catch (error) {
          console.warn('⚠️ Erro ao limpar localStorage:', error);
        }
      }
    }
  }, []);

  // ==================== CARREGAR DADOS PARA EDIÇÃO ====================
  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const id = urlParams.get('id');

    if (id) {
      isEditing.current = true;
      setAlojamentoId(parseInt(id));
      carregarDadosParaEdicao(parseInt(id));
    }
  }, []);

  const carregarDadosParaEdicao = async (id) => {
    setIsLoading(true);
    try {
      const result = await buscarAlojamentoParaEdicao(id);

      if (!result.success || !result.data) {
        showToast('Erro ao carregar dados do alojamento para edição.', 'error');
        return;
      }

      const data = result.data;

      setStatusAtual(data.status || 'rascunho');

      setInformacoesBasicas({
        titulo: data.titulo || '',
        tipo_propriedade: data.tipo_propriedade || data.tipo || 'Apartamento',
        capacidade: data.capacidade || 2,
        estrelas: data.estrelas || 4.5,
        descricao: data.descricao || '',
        descricao_detalhada: data.descricao_detalhada || '',
        preco_noite: data.preco_noite || '',
        tempo_resposta: data.tempo_resposta || 'Dentro de 1 hora',
        quartos: data.quartos || 1,
        camas: data.camas || 1,
        casas_banho: data.casas_banho || 1,
        checkin_inicio: data.checkin_inicio ? String(data.checkin_inicio).substring(0, 5) : '14:00',
        checkin_fim: data.checkin_fim ? String(data.checkin_fim).substring(0, 5) : '22:00',
        checkout_limite: data.checkout_limite ? String(data.checkout_limite).substring(0, 5) : '11:00',
        checkin_flexivel: data.checkin_flexivel ? 1 : 0,
        checkin_flexivel_nota: data.checkin_flexivel_nota || ''
      });

      if (data.morada) {
        const morada = data.morada;
        setLocalizacaoDados({
          endereco: morada.endereco || data.localizacao || '',
          cidade: morada.cidade || data.cidade || '',
          ilha: morada.ilha || data.ilha || '',
          codigo_postal: morada.codigo_postal || morada.codigoPostal || data.codigo_postal || '',
          num_apartamento: morada.num_apartamento || morada.apartamento || data.num_apartamento || '',
          morada_completa: morada.morada_completa || data.morada_completa || '',
          latitude: morada.coordenadas?.lat || morada.lat || data.latitude || null,
          longitude: morada.coordenadas?.lng || morada.lng || data.longitude || null,
          coordenadas: {
            lat: morada.coordenadas?.lat || morada.lat || data.latitude || null,
            lng: morada.coordenadas?.lng || morada.lng || data.longitude || null
          }
        });
      } else {
        setLocalizacaoDados({
          endereco: data.localizacao || '',
          cidade: data.cidade || '',
          ilha: data.ilha || '',
          codigo_postal: data.codigo_postal || '',
          num_apartamento: data.num_apartamento || '',
          morada_completa: data.morada_completa || '',
          latitude: data.latitude || null,
          longitude: data.longitude || null,
          coordenadas: {
            lat: data.latitude || null,
            lng: data.longitude || null
          }
        });
      }

      if (data.comodidades && Array.isArray(data.comodidades)) {
        setComodidadesSelecionadas(data.comodidades);
      }

      if (data.regras) {
        if (data.regras.regras_ids) {
          setRegrasIds(data.regras.regras_ids);
        } else if (Array.isArray(data.regras)) {
          const ids = data.regras.map(r => r.id || r);
          setRegrasIds(ids);
          setRegrasObjetos(data.regras);
        }
        setRegrasAdicionais(data.regras.regras_adicionais || data.regras_adicionais || '');
      }

      if (data.fotos && Array.isArray(data.fotos)) {
        setFotos(data.fotos);
      }

      if (data.quartos && Array.isArray(data.quartos)) {
        // ⚠️ Garantir que as comodidades dos quartos são preservadas
        const quartosComComodidades = data.quartos.map(q => ({
          ...q,
          comodidades: Array.isArray(q.comodidades) ? q.comodidades : []
        }));
        setQuartosParaEnviar(quartosComComodidades);
      }

    } catch (error) {
      console.error('❌ Erro ao carregar dados para edição:', error);
      showToast('Erro ao carregar dados do alojamento para edição.', 'error');
    } finally {
      setIsLoading(false);
    }
  };

  // ==================== HANDLERS ====================
  const handleQuartosChange = useCallback((novosQuartos) => {
    const quartosArray = Array.isArray(novosQuartos) ? novosQuartos : [];
    setQuartosParaEnviar(quartosArray);
  }, []);

  const handleComodidadesChange = useCallback((comodidades) => {
    const comodidadesArray = Array.isArray(comodidades) ? comodidades : [];
    setComodidadesSelecionadas(comodidadesArray);
  }, []);

  const handleRegrasChange = useCallback((dadosRegras) => {
    const ids = dadosRegras.regras_ids || [];
    const texto = dadosRegras.regrasAdicionais || '';

    setRegrasIds(ids);
    setRegrasAdicionais(texto);
    setRegrasObjetos(dadosRegras.regras || []);
  }, []);

  const handleLocalizacaoChange = useCallback((dados) => {
    setLocalizacaoDados(dados);
  }, []);

  // ==================== NAVEGAÇÃO ENTRE FASES ====================
  const handleSaveInformacoes = () => {
    if (!informacoesBasicas.titulo.trim()) {
      showToast('O título da propriedade é obrigatório', 'error');
      return false;
    }
    if (!informacoesBasicas.descricao.trim()) {
      showToast('A descrição curta é obrigatória', 'error');
      return false;
    }
    if (!informacoesBasicas.preco_noite) {
      showToast('O preço por noite é obrigatório', 'error');
      return false;
    }

    setFase(2);
    return true;
  };

  const handleSaveLocalizacao = () => {
    if (!localizacaoDados.endereco?.trim()) {
      showToast('Por favor, insira o endereço', 'error');
      return false;
    }
    if (!localizacaoDados.cidade?.trim()) {
      showToast('Por favor, insira a cidade', 'error');
      return false;
    }
    if (!localizacaoDados.ilha?.trim()) {
      showToast('Por favor, selecione a ilha', 'error');
      return false;
    }

    setFase(3);
    return true;
  };

  const handleSaveComodidades = () => {
    setFase(4);
    return true;
  };

  const handleSaveRegras = () => {
    setFase(5);
    return true;
  };

  // ==================== MONTAR PAYLOAD PARA API ====================
  const montarPayload = (statusDestino) => {
    // ⚠️ Formatar quartos COM comodidades incluídas
    const quartosFormatados = (Array.isArray(quartosParaEnviar) ? quartosParaEnviar : []).map(q => {
      const fotosQuarto = (q.fotos || q.imagens || q.quarto_imagens || [])
        .map(f => (typeof f === 'string' ? f : f.caminho_url || f.url || f.path))
        .filter(Boolean);

      // ⚠️ Comodidades dos quartos — como IDs puros
      const comodidadesQuarto = (q.comodidades || [])
        .map(c => (typeof c === 'object' ? c.id : c))
        .filter(id => id != null && id > 0);

      return {
        id: q.id || q.quarto_id || null,
        tipo_quarto_id: q.tipo_quarto_id || q.tipo_catalogo_id || q.id,
        tipo_catalogo_id: q.tipo_catalogo_id || q.tipo_quarto_id,
        quantidade_disponivel: q.quantidade_disponivel || q.quantidade || 1,
        quantidade: q.quantidade ?? q.quantidade_disponivel ?? 1,
        preco_personalizado: q.preco_personalizado ?? q.preco_noite ?? null,
        preco_noite: q.preco_noite ?? q.preco_personalizado ?? null,
        fotos: fotosQuarto,
        imagens: fotosQuarto,
        // ⚠️ Comodidades dos quartos
        comodidades: comodidadesQuarto
      };
    });

    let fotosComPrincipal = [...fotos];
    const temPrincipal = fotosComPrincipal.some(f => f.principal === 1 || f.principal === true);
    if (!temPrincipal && fotosComPrincipal.length > 0) {
      fotosComPrincipal = fotosComPrincipal.map((f, i) => ({
        ...f,
        principal: i === 0 ? 1 : 0,
        ordem: i
      }));
    } else {
      fotosComPrincipal = fotosComPrincipal.map((f, i) => ({
        ...f,
        principal: (f.principal === 1 || f.principal === true) ? 1 : 0,
        ordem: typeof f.ordem === 'number' ? f.ordem : i
      }));
    }

    const imagensFormatadas = fotosComPrincipal
      .filter(f => f.url || f.caminho_url || f.path || f.src || f.caminho)
      .map((foto, index) => {
        const url = foto.url || foto.caminho_url || foto.path || foto.src || foto.caminho || '';
        return {
          url: url,
          caminho_url: url,
          principal: foto.principal ? 1 : 0,
          ordem: foto.ordem ?? index
        };
      });

    const cidade = localizacaoDados.cidade || '';
    const ilha = localizacaoDados.ilha || '';
    const endereco = localizacaoDados.endereco || '';
    const codigo_postal = localizacaoDados.codigo_postal || '';
    const num_apartamento = localizacaoDados.num_apartamento || '';
    const morada_completa = localizacaoDados.morada_completa || '';
    const latitude = localizacaoDados.coordenadas?.lat || localizacaoDados.latitude || null;
    const longitude = localizacaoDados.coordenadas?.lng || localizacaoDados.longitude || null;

    return {
      // 🔑 Removido o proprietario_id fixo. O backend lê o utilizador diretamente através do Token JWT.
      titulo: informacoesBasicas.titulo,
      tipo_propriedade: informacoesBasicas.tipo_propriedade,
      tipo: informacoesBasicas.tipo_propriedade,
      descricao: informacoesBasicas.descricao,
      descricao_detalhada: informacoesBasicas.descricao_detalhada || '',
      capacidade: parseInt(informacoesBasicas.capacidade) || 2,
      preco_noite: parseFloat(informacoesBasicas.preco_noite) || 0,
      estrelas: parseFloat(informacoesBasicas.estrelas) || 4.0,
      tempo_resposta: informacoesBasicas.tempo_resposta || 'Dentro de 1 hora',
      quartos: parseInt(informacoesBasicas.quartos) || 1,
      camas: parseInt(informacoesBasicas.camas) || 1,
      casas_banho: parseInt(informacoesBasicas.casas_banho) || 1,

      checkin_inicio: informacoesBasicas.checkin_flexivel
        ? null
        : informacoesBasicas.checkin_inicio || '14:00',
      checkin_fim: informacoesBasicas.checkin_flexivel
        ? null
        : informacoesBasicas.checkin_fim || '22:00',
      checkout_limite: informacoesBasicas.checkout_limite || '11:00',
      checkin_flexivel: informacoesBasicas.checkin_flexivel ? 1 : 0,
      checkin_flexivel_nota: informacoesBasicas.checkin_flexivel
        ? informacoesBasicas.checkin_flexivel_nota || ''
        : null,

      cidade: cidade,
      ilha: ilha,
      endereco: endereco,
      localizacao: endereco,
      codigo_postal: codigo_postal,
      num_apartamento: num_apartamento,
      morada_completa: morada_completa,
      latitude: latitude,
      longitude: longitude,

      comodidades: comodidadesSelecionadas.map(c => c.id || c),
      regras_ids: regrasIds,
      regras_adicionais: regrasAdicionais,

      morada: {
        endereco: endereco,
        apartamento: num_apartamento,
        cidade: cidade,
        ilha: ilha,
        codigo_postal: codigo_postal,
        pais: 'Cabo Verde',
        morada_completa: morada_completa,
        lat: latitude,
        lng: longitude,
        coordenadas: { lat: latitude, lng: longitude }
      },

      modelo_venda: modeloVenda,
      quartos: mostraQuartos ? quartosFormatados : [],
      imagens: imagensFormatadas,
      fotos: imagensFormatadas,
      status: statusDestino
    };
  };

  // ==================== ENVIAR PARA ANÁLISE (API) ====================
  const handleEnviarParaAnalise = async () => {
    if (isSubmitting) return;

    // Validações mínimas para enviar para análise
    if (!informacoesBasicas.titulo?.trim()) {
      showToast('O título é obrigatório', 'error');
      setFase(1);
      return;
    }
    if (!informacoesBasicas.descricao?.trim()) {
      showToast('A descrição é obrigatória', 'error');
      setFase(1);
      return;
    }
    if (!informacoesBasicas.preco_noite) {
      showToast('O preço por noite é obrigatório', 'error');
      setFase(1);
      return;
    }
    if (!localizacaoDados.endereco?.trim() || !localizacaoDados.cidade?.trim() || !localizacaoDados.ilha?.trim()) {
      showToast('Complete a localização', 'error');
      setFase(2);
      return;
    }
    if (fotos.length === 0) {
      showToast('Adicione pelo menos uma foto', 'error');
      setFase(5);
      return;
    }

    setIsSubmitting(true);

    try {
      const payload = montarPayload('em_analise');
      const result = await salvarFluxoRegisto(payload, alojamentoId);

      if (result.success) {
        // Limpa o rascunho local depois de enviar com sucesso
        localStorage.removeItem(RASCUNHO_KEY);

        if (result.data?.id && !alojamentoId) {
          setAlojamentoId(result.data.id);
        }
        if (result.data?.alojamento_id && !alojamentoId) {
          setAlojamentoId(result.data.alojamento_id);
        }

        setStatusAtual('em_analise');
        showToast(`✅ ${result.message || 'Anúncio enviado para análise'}`, 'success');
        setTimeout(() => navigate('/alojamento-registro/meus'), 1500);
      } else {
        showToast(`⚠️ Erro: ${result.message}`, 'error');
      }
    } catch (error) {
      console.error('❌ Erro ao finalizar:', error);
      showToast('Erro ao processar o registo. Tente novamente.', 'error');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handlePreVisualizar = () => {
    if (!alojamentoId) {
      showToast('Guarde primeiro como rascunho no servidor para pré-visualizar', 'info');
      return;
    }
    window.open(`/alojamento/${alojamentoId}?preview=1`, '_blank');
  };

  const handleBack = () => {
    if (fase > 1) {
      setFase(fase - 1);
    } else {
      navigate(-1);
    }
  };

  // ==================== BOTÕES DE AÇÃO COMUNS ====================
  const BotoesAcao = ({ mostrarContinuar = true, onContinuar, continuarLabel = 'Continuar' }) => {
    const temRascunho = !!localStorage.getItem(RASCUNHO_KEY);

    return (
      <div className="flex flex-wrap justify-between gap-3 mt-8 pt-6 border-t border-gray-100">
        <button
          onClick={handleBack}
          className="flex items-center gap-2 px-5 py-2.5 border border-gray-300 text-gray-700 rounded-lg font-semibold hover:bg-gray-50"
        >
          <ArrowLeft size={18} /> Voltar
        </button>

        <div className="flex flex-wrap gap-3">
          {/* Guardar rascunho (localStorage) */}
          <button
            onClick={guardarRascunhoLocal}
            className="flex items-center gap-2 px-5 py-2.5 border border-gray-300 text-gray-700 rounded-lg font-semibold hover:bg-gray-50"
          >
            <Save size={18} />
            Guardar rascunho
          </button>

          {/* Remover rascunho */}
          {temRascunho && (
            <button
              onClick={pedirConfirmacaoRemoverRascunho}
              className="flex items-center gap-2 px-5 py-2.5 border border-red-300 text-red-600 rounded-lg font-semibold hover:bg-red-50"
            >
              <X size={18} />
              Remover rascunho
            </button>
          )}

          {/* Pré-visualizar (só se já tiver ID no servidor) */}
          {alojamentoId && (
            <button
              onClick={handlePreVisualizar}
              className="flex items-center gap-2 px-5 py-2.5 border border-blue-300 text-blue-700 rounded-lg font-semibold hover:bg-blue-50"
            >
              <Eye size={18} /> Pré-visualizar
            </button>
          )}

          {mostrarContinuar && (
            <button
              onClick={onContinuar}
              className="flex items-center gap-2 px-5 py-2.5 bg-[#006ce4] text-white rounded-lg font-semibold hover:bg-[#0053b3]"
            >
              {continuarLabel} <ChevronRight size={18} />
            </button>
          )}
        </div>
      </div>
    );
  };

  // ==================== BARRA DE PROGRESSO ====================
  const renderProgressBar = () => {
    const fasesLista = ['Informações', 'Localização', 'Comodidades', 'Regras', 'Fotos'];
    return (
      <div className="mb-6">
        <div className="flex items-center justify-between mb-2">
          {fasesLista.map((nome, index) => (
            <div key={index} className="flex-1 text-center">
              <div className={`text-xs font-medium ${fase > index + 1 ? 'text-[#006ce4]' : fase === index + 1 ? 'text-[#006ce4]' : 'text-gray-400'}`}>
                {nome}
              </div>
            </div>
          ))}
        </div>
        <div className="flex gap-1">
          {fasesLista.map((_, index) => (
            <div
              key={index}
              className={`h-1 flex-1 rounded-full ${
                fase > index + 1 ? 'bg-[#006ce4]' :
                fase === index + 1 ? 'bg-[#006ce4] bg-opacity-50' : 'bg-gray-200'
              }`}
            />
          ))}
        </div>
      </div>
    );
  };

  // ==================== FASES ====================
  const renderFaseInformacoes = () => (
    <div className="min-h-screen bg-gray-50">
      <div className="max-w-4xl mx-auto px-4 py-12">
        <div className="bg-white rounded-lg shadow-md p-8">
          <h1 className="text-2xl font-bold text-gray-900 mb-2">Informações básicas da propriedade</h1>
          <p className="text-gray-600 mb-8">Preencha os dados principais do seu alojamento.</p>

          <InformacoesBasicas
            dados={informacoesBasicas}
            onDadosChange={setInformacoesBasicas}
            onQuartosChange={handleQuartosChange}
            quartosIniciais={quartosParaEnviar}
            alojamentoId={alojamentoId}
            readOnly={false}
            mostraQuartos={mostraQuartos}
          />

          <BotoesAcao onContinuar={handleSaveInformacoes} />
        </div>
      </div>
    </div>
  );

  const renderFaseLocalizacao = () => (
    <div className="min-h-screen bg-gray-50 py-12">
      <div className="max-w-2xl mx-auto px-4">
        <div className="bg-white rounded-lg shadow-md p-6">
          <h2 className="text-xl font-bold mb-4">📍 Localização do Alojamento</h2>
          <p className="text-gray-600 mb-6">Onde fica a sua propriedade?</p>

          <RegistarLocalizacao
            dados={localizacaoDados}
            onChange={handleLocalizacaoChange}
            alojamentoId={alojamentoId}
            readOnly={false}
          />

          <BotoesAcao onContinuar={handleSaveLocalizacao} />
        </div>
      </div>
    </div>
  );

  const renderFaseComodidades = () => (
    <div className="min-h-screen bg-gray-50">
      <div className="max-w-4xl mx-auto px-4 py-12">
        <div className="bg-white rounded-lg shadow-md p-8">
          <h1 className="text-2xl font-bold text-gray-900 mb-2">Comodidades</h1>
          <p className="text-gray-600 mb-6">Selecione as comodidades oferecidas pela propriedade</p>

          <Comodidades
            alojamentoId={alojamentoId}
            onChange={handleComodidadesChange}
            initialComodidades={comodidadesSelecionadas}
            readOnly={false}
          />

          <BotoesAcao onContinuar={handleSaveComodidades} />
        </div>
      </div>
    </div>
  );

  const renderFaseRegras = () => (
    <div className="min-h-screen bg-gray-50">
      <div className="max-w-4xl mx-auto px-4 py-12">
        <div className="bg-white rounded-lg shadow-md p-8">
          <h1 className="text-2xl font-bold text-gray-900 mb-2">Regras da Casa</h1>
          <p className="text-gray-600 mb-6">Defina as regras para os hóspedes</p>

          <Regras
            alojamentoId={alojamentoId}
            onChange={handleRegrasChange}
            initialRegras={regrasObjetos}
            initialRegrasAdicionais={regrasAdicionais}
            readOnly={false}
          />

          <BotoesAcao onContinuar={handleSaveRegras} />
        </div>
      </div>
    </div>
  );

  const renderFaseFotos = () => {
    const temRascunho = !!localStorage.getItem(RASCUNHO_KEY);

    return (
      <div className="min-h-screen bg-gray-50">
        <div className="max-w-4xl mx-auto px-4 py-12">
          <div className="bg-white rounded-lg shadow-md p-8">
            <h1 className="text-2xl font-bold text-gray-900 mb-2">Fotos do Alojamento</h1>
            <p className="text-gray-600 mb-6">
              Adicione fotos e escolha manualmente a fotografia principal (clique na estrela ou no botão "Principal").
            </p>

            <ImagensUpload
              fotos={fotos}
              onFotosChange={setFotos}
              quartos={quartosParaEnviar}
              onQuartosChange={handleQuartosChange}
              maxFotos={20}
              alojamentoId={alojamentoId}
              mostraQuartos={mostraQuartos}
            />

            <div className="flex flex-wrap justify-between gap-3 mt-8 pt-6 border-t border-gray-100">
              <button
                onClick={handleBack}
                className="flex items-center gap-2 px-5 py-2.5 border border-gray-300 text-gray-700 rounded-lg font-semibold hover:bg-gray-50"
              >
                <ArrowLeft size={18} /> Voltar
              </button>

              <div className="flex flex-wrap gap-3">
                <button
                  onClick={guardarRascunhoLocal}
                  className="flex items-center gap-2 px-5 py-2.5 border border-gray-300 text-gray-700 rounded-lg font-semibold hover:bg-gray-50"
                >
                  <Save size={18} />
                  Guardar rascunho
                </button>

                {temRascunho && (
                  <button
                    onClick={pedirConfirmacaoRemoverRascunho}
                    className="flex items-center gap-2 px-5 py-2.5 border border-red-300 text-red-600 rounded-lg font-semibold hover:bg-red-50"
                  >
                    <X size={18} />
                    Remover rascunho
                  </button>
                )}

                {alojamentoId && (
                  <button
                    onClick={handlePreVisualizar}
                    className="flex items-center gap-2 px-5 py-2.5 border border-blue-300 text-blue-700 rounded-lg font-semibold hover:bg-blue-50"
                  >
                    <Eye size={18} /> Pré-visualizar
                  </button>
                )}

                <button
                  onClick={handleEnviarParaAnalise}
                  disabled={isSubmitting}
                  className="flex items-center gap-2 px-5 py-2.5 bg-green-600 text-white rounded-lg font-semibold hover:bg-green-700 disabled:opacity-50"
                >
                  {isSubmitting ? (
                    <>
                      <Loader size={18} className="animate-spin" />
                      A enviar...
                    </>
                  ) : (
                    <>
                      <Check size={18} />
                      Enviar para análise
                    </>
                  )}
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <Loader className="animate-spin mx-auto text-[#006ce4]" size={48} />
          <p className="mt-4 text-gray-600">Carregando dados do alojamento...</p>
        </div>
      </div>
    );
  }

  return (
    <>
      <header className="bg-[#003580] text-white px-4 py-2 flex items-center justify-between shadow-sm">
        <div className="flex items-center gap-3">
          <div className="font-bold text-lg tracking-tight truncate max-w-[200px]">
            {informacoesBasicas.titulo || 'Nova Propriedade'}
          </div>
          <span className="text-xs bg-white/20 px-2 py-0.5 rounded">
