import React, { useState, useEffect } from 'react';
import { Bed, Plus, Trash2, Camera, Save, Loader, AlertCircle, CheckCircle } from 'lucide-react';

const GerenciarQuartosAlojamento = ({ alojamentoId, precoBaseAlojamento }) => {
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [mensagem, setMensagem] = useState(null);

  const tiposQuartoPadrao = [
    { tipo_quarto_id: 1, nome: 'Quarto Casal', quantidade_disponivel: 1, preco_personalizado: '', ativo: 1, fotos: [''] },
    { tipo_quarto_id: 2, nome: 'Quarto Twin', quantidade_disponivel: 0, preco_personalizado: '', ativo: 0, fotos: [''] },
    { tipo_quarto_id: 3, nome: 'Quarto Solteiro', quantidade_disponivel: 0, preco_personalizado: '', ativo: 0, fotos: [''] },
    { tipo_quarto_id: 4, nome: 'Suíte Luxo', quantidade_disponivel: 0, preco_personalizado: '', ativo: 0, fotos: [''] }
  ];

  const [quartos, setQuartos] = useState(tiposQuartoPadrao);

  useEffect(() => {
    const carregarQuartos = async () => {
      try {
        setLoading(true);
        const res = await fetch(`https://welovepalop.com/api/meus_alojamentos.php?id=${alojamentoId}`);
        const data = await res.json();

        if (data.success && data.data && data.data.quartos && data.data.quartos.length > 0) {
          const carregados = tiposQuartoPadrao.map(padrao => {
            const encontrado = data.data.quartos.find(q => q.tipo_quarto_id === padrao.tipo_quarto_id);
            if (encontrado) {
              return {
                ...padrao,
                quantidade_disponivel: encontrado.quantidade_disponivel || 0,
                preco_personalizado: encontrado.preco || '',
                ativo: 1,
                fotos: encontrado.fotos && encontrado.fotos.length > 0 ? encontrado.fotos : ['']
              };
            }
            return padrao;
          });
          setQuartos(carregados);
        }
      } catch (err) {
        console.error('Erro ao carregar quartos:', err);
      } finally {
        setLoading(false);
      }
    };

    if (alojamentoId) carregarQuartos();
  }, [alojamentoId]);

  const handleCampoChange = (index, campo, valor) => {
    setQuartos(prev => {
      const novos = [...prev];
      novos[index][campo] = valor;
      return novos;
    });
  };

  const handleFotoChange = (quartoIdx, fotoIdx, valor) => {
    setQuartos(prev => {
      const novos = [...prev];
      novos[quartoIdx].fotos[fotoIdx] = valor;
      return novos;
    });
  };

  const AdicionarCampoFoto = (quartoIdx) => {
    setQuartos(prev => {
      const novos = [...prev];
      novos[quartoIdx].fotos.push('');
      return novos;
    });
  };

  const RemoverFoto = (quartoIdx, fotoIdx) => {
    setQuartos(prev => {
      const novos = [...prev];
      novos[quartoIdx].fotos = novos[quartoIdx].fotos.filter((_, i) => i !== fotoIdx);
      if (novos[quartoIdx].fotos.length === 0) novos[quartoIdx].fotos = [''];
      return novos;
    });
  };

  const handleSalvar = async () => {
    try {
      setSaving(true);
      setMensagem(null);

      const payload = {
        alojamento_id: alojamentoId,
        quartos: quartos.map(q => ({
          tipo_quarto_id: q.tipo_quarto_id,
          quantidade_disponivel: q.ativo ? Number(q.quantidade_disponivel) : 0,
          preco_personalizado: q.preco_personalizado !== '' ? Number(q.preco_personalizado) : null,
          ativo: q.ativo ? 1 : 0,
          fotos: q.fotos.filter(f => f.trim() !== '')
        }))
      };

      const res = await fetch('https://welovepalop.com/api/alojamento/salvar_quartos_alojamento.php', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });

      const data = await res.json();
      if (data.success) {
        setMensagem({ tipo: 'sucesso', texto: 'Configuração dos quartos guardada com sucesso!' });
      } else {
        throw new Error(data.message || 'Erro ao guardar quartos.');
      }
    } catch (err) {
      setMensagem({ tipo: 'erro', texto: err.message });
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="flex justify-center items-center py-12">
        <Loader className="animate-spin text-blue-600" size={32} />
      </div>
    );
  }

  return (
    <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-200 max-w-4xl mx-auto">
      <div className="flex items-center justify-between mb-6 pb-4 border-b border-slate-100">
        <div>
          <h2 className="text-lg font-bold text-slate-900 flex items-center gap-2">
            <Bed className="text-blue-600" size={20} /> Gestão de Tipos de Quartos & Inventário
          </h2>
          <p className="text-xs text-slate-500 mt-1">
            Defina o número de unidades disponíveis, o preço por noite (ou use o preço base de {precoBaseAlojamento || 1880} CVE) e fotos de cada tipo.
          </p>
        </div>

        <button
          onClick={handleSalvar}
          disabled={saving}
          className="bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs px-4 py-2.5 rounded-xl flex items-center gap-2 transition-colors disabled:opacity-50"
        >
          {saving ? <Loader className="animate-spin" size={16} /> : <Save size={16} />}
          Guardar Quartos
        </button>
      </div>

      {mensagem && (
        <div className={`p-4 rounded-xl mb-6 flex items-center gap-2 text-xs font-bold ${
          mensagem.tipo === 'sucesso' ? 'bg-emerald-50 text-emerald-700 border border-emerald-200' : 'bg-red-50 text-red-700 border border-red-200'
        }`}>
          {mensagem.tipo === 'sucesso' ? <CheckCircle size={16} /> : <AlertCircle size={16} />}
          {mensagem.texto}
        </div>
      )}

      <div className="space-y-6">
        {quartos.map((quarto, idx) => (
          <div 
            key={quarto.tipo_quarto_id}
            className={`p-5 rounded-2xl border transition-all ${
              quarto.ativo ? 'border-slate-200 bg-white' : 'border-slate-100 bg-slate-50/50 opacity-75'
            }`}
          >
            <div className="flex items-center justify-between mb-4">
              <label className="flex items-center gap-3 cursor-pointer">
                <input
                  type="checkbox"
                  checked={quarto.ativo === 1}
                  onChange={(e) => handleCampoChange(idx, 'ativo', e.target.checked ? 1 : 0)}
                  className="w-4 h-4 rounded text-blue-600 focus:ring-blue-500"
                />
                <span className="font-bold text-sm text-slate-900">{quarto.nome}</span>
              </label>

              {quarto.ativo === 1 && (
                <span className="text-[10px] font-bold bg-blue-50 text-blue-700 px-2 py-0.5 rounded-md uppercase">
                  Ativo no anúncio
                </span>
              )}
            </div>

            {quarto.ativo === 1 && (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 pt-2">
                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1">
                    Quantidade de quartos disponíveis (Stock)
                  </label>
                  <input
                    type="number"
                    min="0"
                    value={quarto.quantidade_disponivel}
                    onChange={(e) => handleCampoChange(idx, 'quantidade_disponivel', e.target.value)}
                    className="w-full text-xs p-2.5 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:outline-none"
                  />
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1">
                    Preço personalizado (CVE / noite)
                  </label>
                  <input
                    type="number"
                    placeholder={`Padrão: ${precoBaseAlojamento || 1880} CVE`}
                    value={quarto.preco_personalizado}
                    onChange={(e) => handleCampoChange(idx, 'preco_personalizado', e.target.value)}
                    className="w-full text-xs p-2.5 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:outline-none"
                  />
                </div>

                {/* Secção de Fotografias do Quarto */}
                <div className="md:col-span-2 pt-2 border-t border-slate-100 mt-2">
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-xs font-bold text-slate-700 flex items-center gap-1">
                      <Camera size={14} /> URLs das Fotos deste Quarto
                    </span>
                    <button
                      type="button"
                      onClick={() => AdicionarCampoFoto(idx)}
                      className="text-xs text-blue-600 hover:underline font-bold flex items-center gap-1"
                    >
                      <Plus size={12} /> Adicionar Foto
                    </button>
                  </div>

                  <div className="space-y-2">
                    {quarto.fotos.map((urlFoto, fotoIdx) => (
                      <div key={fotoIdx} className="flex gap-2 items-center">
                        <input
                          type="text"
                          placeholder="https://welovepalop.com/uploads/quarto.jpg"
                          value={urlFoto}
                          onChange={(e) => handleFotoChange(idx, fotoIdx, e.target.value)}
                          className="flex-1 text-xs p-2 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:outline-none"
                        />
                        {quarto.fotos.length > 1 && (
                          <button
                            type="button"
                            onClick={() => RemoverFoto(idx, fotoIdx)}
                            className="p-2 text-red-500 hover:bg-red-50 rounded-lg"
                          >
                            <Trash2 size={14} />
                          </button>
                        )}
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

export default GerenciarQuartosAlojamento;

// src/components/AlojamentoRegisto/ImagensUpload.jsx
import React, { useState, useRef } from 'react';
import { Upload, X, Image, Star, Trash2, Move, AlertCircle, Check, Plus, Loader } from 'lucide-react';

const API_URL = 'https://welovepalop.com';

const ImagensUpload = ({ 
  fotos = [], 
  onFotosChange, 
  onFotoPrincipalChange,
  maxFotos = 20,
  readOnly = false,
  alojamentoId = null
}) => {
  const [isDragging, setIsDragging] = useState(false);
  const [erro, setErro] = useState('');
  const [uploading, setUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState({});
  const fileInputRef = useRef(null);
  
  const fotoPrincipalId = fotos.find(f => f.principal)?.id || fotos[0]?.id;
  
  // Função para fazer upload de uma imagem para o servidor
  const uploadImagemParaServidor = async (file, ordem) => {
    const formData = new FormData();
    formData.append('imagem', file);
    formData.append('ordem', ordem);
    
    if (alojamentoId && alojamentoId !== 'temp' && alojamentoId !== null) {
      formData.append('alojamento_id', alojamentoId);
    }
    
    const fileId = Date.now() + Math.random();
    setUploadProgress(prev => ({ ...prev, [fileId]: 0 }));
    
    return new Promise((resolve, reject) => {
      const xhr = new XMLHttpRequest();
      
      xhr.upload.addEventListener('progress', (e) => {
        if (e.lengthComputable) {
          const percent = Math.round((e.loaded / e.total) * 100);
          setUploadProgress(prev => ({ ...prev, [fileId]: percent }));
        }
      });
      
      xhr.onload = () => {
        if (xhr.status === 200) {
          try {
            const response = JSON.parse(xhr.responseText);
            if (response.success) {
              resolve(response.data);
            } else {
              reject(new Error(response.message));
            }
          } catch (e) {
            reject(new Error('Erro ao processar resposta do servidor'));
          }
        } else {
          reject(new Error(`Erro ${xhr.status}: ${xhr.statusText}`));
        }
        setUploadProgress(prev => {
          const newProgress = { ...prev };
          delete newProgress[fileId];
          return newProgress;
        });
      };
      
      xhr.onerror = () => {
        reject(new Error('Erro de conexão com o servidor'));
        setUploadProgress(prev => {
          const newProgress = { ...prev };
          delete newProgress[fileId];
          return newProgress;
        });
      };
      
      xhr.open('POST', `${API_URL}/api/alojamento/upload_imagem.php`);
      xhr.send(formData);
    });
  };
  
  // Handler para selecionar arquivos
  const handleFileSelect = async (files) => {
    setErro('');
    const filesArray = Array.from(files);
    
    if (fotos.length + filesArray.length > maxFotos) {
      setErro(`Máximo de ${maxFotos} fotos permitidas. Você já tem ${fotos.length} fotos.`);
      return;
    }
    
    const arquivosInvalidos = filesArray.filter(file => {
      if (!file.type.startsWith('image/')) return true;
      if (file.size > 10 * 1024 * 1024) return true;
      return false;
    });
    
    if (arquivosInvalidos.length > 0) {
      setErro('Apenas imagens até 10MB são permitidas');
      return;
    }
    
    setUploading(true);
    
    try {
      const novasFotos = [];
      
      for (let i = 0; i < filesArray.length; i++) {
        const file = filesArray[i];
        const ordem = fotos.length + i;
        
        try {
          // Upload para o servidor
          const resultadoUpload = await uploadImagemParaServidor(file, ordem);
          
          const novaFoto = {
            id: resultadoUpload.id || Date.now() + Math.random(),
            url: resultadoUpload.url, // Caminho da imagem (ex: /uploads/alojamentos/xxx.jpg)
            path: resultadoUpload.path,
            nome: file.name,
            tamanho: file.size,
            principal: fotos.length === 0 && novasFotos.length === 0,
            ordem: ordem,
            uploadCompleto: true
          };
          
          novasFotos.push(novaFoto);
          
        } catch (uploadError) {
          console.error('Erro no upload da imagem:', uploadError);
          setErro(`Erro ao fazer upload de ${file.name}: ${uploadError.message}`);
        }
      }
      
      if (novasFotos.length > 0) {
        const fotosAtualizadas = [...fotos, ...novasFotos];
        onFotosChange(fotosAtualizadas);
        
        if (!fotoPrincipalId && fotosAtualizadas.length > 0) {
          onFotoPrincipalChange?.(fotosAtualizadas[0].id);
        }
      }
      
    } catch (error) {
      console.error('Erro no processo de upload:', error);
      setErro(`Erro ao fazer upload: ${error.message}`);
    } finally {
      setUploading(false);
    }
  };
  
  // Drag & Drop handlers
  const handleDragOver = (e) => {
    e.preventDefault();
    setIsDragging(true);
  };
  
  const handleDragLeave = (e) => {
    e.preventDefault();
    setIsDragging(false);
  };
  
  const handleDrop = (e) => {
    e.preventDefault();
    setIsDragging(false);
    const files = e.dataTransfer.files;
    if (files.length > 0) {
      handleFileSelect(files);
    }
  };
  
  // Remover foto
  const handleRemoverFoto = async (id) => {
    const fotoRemover = fotos.find(f => f.id === id);
    
    if (fotoRemover?.id && !readOnly) {
      try {
        await fetch(`${API_URL}/api/alojamento/remover_imagem.php?id=${fotoRemover.id}`, {
          method: 'DELETE'
        });
      } catch (error) {
        console.error('Erro ao remover imagem do servidor:', error);
      }
    }
    
    const fotosAtualizadas = fotos.filter(foto => foto.id !== id);
    
    if (fotoPrincipalId === id && fotosAtualizadas.length > 0) {
      const novaPrincipal = fotosAtualizadas[0];
      onFotoPrincipalChange?.(novaPrincipal.id);
      fotosAtualizadas[0].principal = true;
    }
    
    onFotosChange(fotosAtualizadas);
  };
  
  // Definir foto principal
  const handleDefinirPrincipal = async (id) => {
    const fotosAtualizadas = fotos.map(foto => ({
      ...foto,
      principal: foto.id === id
    }));
    onFotosChange(fotosAtualizadas);
    onFotoPrincipalChange?.(id);
    
    if (alojamentoId) {
      try {
        await fetch(`${API_URL}/api/alojamento/definir_principal.php`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            alojamento_id: alojamentoId,
            imagem_id: id
          })
        });
      } catch (error) {
        console.error('Erro ao definir principal:', error);
      }
    }
  };
  
  // Reordenar fotos
  const [dragIndex, setDragIndex] = useState(null);
  
  const handleDragStart = (e, index) => {
    e.dataTransfer.effectAllowed = 'move';
    setDragIndex(index);
  };
  
  const handleDragOverItem = (e, index) => {
    e.preventDefault();
    if (dragIndex === null) return;
    
    if (dragIndex !== index) {
      const fotosReordenadas = [...fotos];
      const [item] = fotosReordenadas.splice(dragIndex, 1);
      fotosReordenadas.splice(index, 0, item);
      
      fotosReordenadas.forEach((foto, idx) => {
        foto.ordem = idx;
      });
      
      onFotosChange(fotosReordenadas);
      setDragIndex(index);
    }
  };
  
  const handleDragEnd = () => {
    setDragIndex(null);
  };
  
  const formatFileSize = (bytes) => {
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  };
  
  const hasUploading = Object.keys(uploadProgress).length > 0;
  
  return (
    <div className="space-y-6">
      {/* Área de upload */}
      {!readOnly && !uploading && (
        <div
          onDragOver={handleDragOver}
          onDragLeave={handleDragLeave}
          onDrop={handleDrop}
          onClick={() => fileInputRef.current?.click()}
          className={`border-2 border-dashed rounded-xl p-8 text-center cursor-pointer transition-all ${
            isDragging 
              ? 'border-[#006ce4] bg-blue-50' 
              : 'border-gray-300 hover:border-[#006ce4] hover:bg-gray-50'
          }`}
        >
          <input
            type="file"
            ref={fileInputRef}
            onChange={(e) => handleFileSelect(e.target.files)}
            accept="image/jpeg,image/png,image/webp,image/gif"
            multiple
            className="hidden"
          />
          
          <Upload className={`w-12 h-12 mx-auto mb-3 ${isDragging ? 'text-[#006ce4]' : 'text-gray-400'}`} />
          
          <p className="text-gray-600 mb-1">
            {isDragging ? 'Solte para adicionar as fotos' : 'Arraste e solte as suas fotos aqui'}
          </p>
          <p className="text-sm text-gray-400">
            ou clique para selecionar do computador
          </p>
          <p className="text-xs text-gray-400 mt-3">
            Formatos: JPG, PNG, WEBP, GIF | Máx 10MB por foto | Máx {maxFotos} fotos
          </p>
        </div>
      )}
      
      {/* Indicador de upload */}
      {uploading && (
        <div className="border-2 border-[#006ce4] bg-blue-50 rounded-xl p-6 text-center">
          <Loader className="w-8 h-8 mx-auto mb-3 text-[#006ce4] animate-spin" />
          <p className="text-gray-600">Fazendo upload das imagens...</p>
          {hasUploading && (
            <div className="mt-3 w-full bg-gray-200 rounded-full h-2">
              <div 
                className="bg-[#006ce4] h-2 rounded-full transition-all duration-300"
                style={{ width: `${Object.values(uploadProgress)[0] || 0}%` }}
              />
            </div>
          )}
        </div>
      )}
      
      {/* Mensagem de erro */}
      {erro && (
        <div className="bg-red-50 border border-red-200 rounded-lg p-3 flex items-center gap-2">
          <AlertCircle size={18} className="text-red-500" />
          <p className="text-sm text-red-600">{erro}</p>
          <button onClick={() => setErro('')} className="ml-auto text-red-400 hover:text-red-600">
            <X size={16} />
          </button>
        </div>
      )}
      
      {/* Galeria de fotos */}
      {fotos.length > 0 && (
        <div>
          <div className="flex justify-between items-center mb-4">
            <h3 className="font-semibold text-gray-900 flex items-center gap-2">
              <Image size={18} />
              Suas fotos ({fotos.length}/{maxFotos})
            </h3>
            {!readOnly && !uploading && fotos.length < maxFotos && (
              <button
                onClick={() => fileInputRef.current?.click()}
                className="text-sm text-[#006ce4] hover:underline flex items-center gap-1"
              >
                <Plus size={14} /> Adicionar mais
              </button>
            )}
          </div>
          
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
            {fotos.map((foto, index) => {
              // Construir URL completa da imagem
              const imageUrl = foto.url?.startsWith('http') || foto.url?.startsWith('data:') 
                ? foto.url 
                : `${API_URL}${foto.url}`
              
              return (
                <div
                  key={foto.id}
                  draggable={!readOnly && !uploading}
                  onDragStart={(e) => handleDragStart(e, index)}
                  onDragOver={(e) => handleDragOverItem(e, index)}
                  onDragEnd={handleDragEnd}
                  className={`relative group rounded-lg overflow-hidden border-2 transition-all ${
                    fotoPrincipalId === foto.id 
                      ? 'border-[#006ce4] shadow-lg' 
                      : 'border-gray-200 hover:border-gray-300'
                  } ${!readOnly && 'cursor-move'}`}
                >
                  {fotoPrincipalId === foto.id && (
                    <div className="absolute top-2 left-2 bg-[#006ce4] text-white text-xs px-2 py-0.5 rounded-full flex items-center gap-1 z-10">
                      <Star size={10} fill="white" /> Principal
                    </div>
                  )}
                  
                  <img
                    src={imageUrl}
                    alt={foto.nome}
                    className="w-full h-40 object-cover"
                    onError={(e) => {
                      console.error('Erro ao carregar imagem:', imageUrl);
                      e.target.src = 'https://via.placeholder.com/400x300?text=Erro+ao+carregar';
                    }}
                  />
                  
                  <div className="absolute inset-0 bg-black bg-opacity-50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-2">
                    {!readOnly && !uploading && fotoPrincipalId !== foto.id && (
                      <button
                        onClick={() => handleDefinirPrincipal(foto.id)}
                        className="p-2 bg-white rounded-full text-gray-700 hover:bg-[#006ce4] hover:text-white transition-colors"
                        title="Definir como principal"
                      >
                        <Star size={16} />
                      </button>
                    )}
                    
                    {!readOnly && !uploading && (
                      <button
                        onClick={() => handleRemoverFoto(foto.id)}
                        className="p-2 bg-white rounded-full text-red-500 hover:bg-red-500 hover:text-white transition-colors"
                        title="Remover foto"
                      >
                        <Trash2 size={16} />
                      </button>
                    )}
                    
                    {!readOnly && !uploading && (
                      <div className="p-2 bg-white rounded-full text-gray-400 cursor-move" title="Arrastar para reordenar">
                        <Move size={16} />
                      </div>
                    )}
                  </div>
                  
                  <div className="absolute bottom-0 left-0 right-0 bg-black bg-opacity-60 text-white text-xs p-1 px-2">
                    <span className="truncate block">{foto.nome}</span>
                    <span className="text-gray-300 text-[10px]">{formatFileSize(foto.tamanho)}</span>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}
      
      {/* Dicas para boas fotos */}
      {!readOnly && fotos.length === 0 && !uploading && (
        <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4">
          <h4 className="font-semibold text-yellow-800 mb-2 text-sm flex items-center gap-2">
            <Image size={16} /> Dicas para fotos de sucesso:
          </h4>
          <ul className="text-yellow-700 text-sm space-y-1">
            <li>• 📸 Tire fotos com boa iluminação natural</li>
            <li>• 🛏️ Mostre todos os cômodos (sala, quartos, cozinha, banheiro)</li>
            <li>• 🌅 Inclua fotos da área externa e vista</li>
            <li>• 🚫 Evite fotos com pessoas ou objetos pessoais</li>
            <li>• 📱 Use a câmera na horizontal para melhores resultados</li>
          </ul>
        </div>
      )}
      
      {/* Resumo das fotos */}
      {fotos.length > 0 && (
        <div className="bg-gray-50 rounded-lg p-4">
          <h4 className="font-semibold text-gray-700 mb-2 flex items-center gap-2">
            <Check size={16} className="text-green-500" />
            Resumo das fotos
          </h4>
          <div className="grid grid-cols-2 gap-3 text-sm">
            <div>
              <span className="text-gray-500">Total de fotos:</span>{' '}
              <span className="font-medium">{fotos.length}</span>
            </div>
            <div>
              <span className="text-gray-500">Foto principal:</span>{' '}
              <span className="font-medium text-[#006ce4]">
                {fotos.find(f => f.id === fotoPrincipalId)?.nome || 'Definida'}
              </span>
            </div>
            <div>
              <span className="text-gray-500">Tamanho total:</span>{' '}
              <span className="font-medium">
                {formatFileSize(fotos.reduce((acc, f) => acc + (f.tamanho || 0), 0))}
              </span>
            </div>
            <div>
              <span className="text-gray-500">Ordem:</span>{' '}
              <span className="font-medium">
                Arraste para reordenar
              </span>
            </div>
          </div>
        </div>
      )}
      
      {/* Aviso de fotos insuficientes */}
      {!readOnly && fotos.length < 3 && !uploading && (
        <div className="bg-blue-50 border border-blue-200 rounded-lg p-3 flex items-start gap-2">
          <AlertCircle size={18} className="text-blue-500 shrink-0 mt-0.5" />
          <p className="text-sm text-blue-700">
            Recomendamos pelo menos <strong>3 fotos</strong> para atrair mais hóspedes. 
            Propriedades com mais fotos recebem até 40% mais reservas!
          </p>
        </div>
      )}
      
      {/* Modo leitura */}
      {readOnly && fotos.length === 0 && (
        <p className="text-gray-400 text-center py-8">Nenhuma foto adicionada</p>
      )}
    </div>
  );
};

