                    ? 'bg-[#006ce4] text-white'
                    : 'bg-white text-gray-600 border border-gray-300 hover:bg-gray-50'
                }`}
              >
                {status === 'todos' ? 'Todos' :
                 status === 'aprovado' ? 'Aprovados' :
                 status === 'pendente' ? 'Pendentes' : 'Inativos'}
