// src/components/AlojamentoRegisto/NomePropriedade.js
import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { ArrowLeft, Check, HelpCircle, User } from 'lucide-react';
import PropMenu from './PropMenu';

const NomePropriedade = () => {
  const navigate = useNavigate();
  const location = useLocation();
  
  const [propertyName, setPropertyName] = useState(location.state?.propertyName || '');
  const [newName, setNewName] = useState(propertyName);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);
  
  // Carregar nome salvo
  useEffect(() => {
    const savedName = localStorage.getItem('propertyName');
    if (savedName && !location.state?.propertyName) {
      setPropertyName(savedName);
      setNewName(savedName);
    }
  }, [location.state?.propertyName]);

  const handleSave = () => {
    if (!newName.trim()) {
      setError('O nome da propriedade é obrigatório');
      return;
    }
    
    localStorage.setItem('propertyName', newName.trim());
    setSuccess(true);
    
    setTimeout(() => {
      navigate(-1);
    }, 1000);
  };

  const handleBack = () => {
    navigate(-1);
  };

  const handleEditLocation = () => {
    navigate('/alojamento/localizacao', { state: { propertyName: newName, action: 'edit' } });
  };

  const handleEditName = () => {
    console.log('Editando nome');
  };

  return (
    <div className="w-screen min-h-screen bg-gray-50 font-sans antialiased text-gray-900">
      
      <header className="bg-[#003580] text-white h-[60px] flex items-center justify-between px-6 shadow-sm">
        <div className="font-bold text-2xl tracking-tight">morabezastay.cv</div>
        <div className="flex items-center gap-6 text-sm">
          <div className="text-right">
            <PropMenu 
              nomePropriedade={newName || propertyName || 'Nova Propriedade'}
              onEditName={handleEditName}
              onEditLocation={handleEditLocation}
            />
            <div className="text-[10px] opacity-80">
              Editar nome da propriedade
            </div>
          </div>
          <div className="w-[1px] h-8 bg-blue-900"></div>

          <div className="flex items-center gap-2 cursor-pointer hover:underline">
            <span>Ajuda</span> <HelpCircle size={18} />
          </div>
    
        </div>
      </header>

      <div className="max-w-2xl mx-auto px-4 py-12">
        <div className="bg-white rounded-lg shadow-md p-8">
          
          <button
            onClick={handleBack}
            className="flex items-center gap-2 text-gray-600 hover:text-gray-900 mb-6 transition-colors"
          >
            <ArrowLeft size={20} />
            <span>Voltar</span>
          </button>

          <h1 className="text-2xl font-bold text-gray-900 mb-2">
            Editar nome da propriedade
          </h1>
          <p className="text-gray-600 mb-8">
            Altere o nome da sua propriedade como será exibido na plataforma.
          </p>

          {success ? (
            <div className="bg-green-50 border border-green-200 rounded-lg p-4 mb-6">
              <div className="flex items-center gap-3">
                <Check className="text-green-600" size={24} />
                <div>
                  <h3 className="font-semibold text-green-800">Nome atualizado com sucesso!</h3>
                  <p className="text-green-700 text-sm">Redirecionando...</p>
                </div>
              </div>
            </div>
          ) : (
            <form onSubmit={(e) => { e.preventDefault(); handleSave(); }}>
              <div className="mb-6">
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Nome da propriedade *
                </label>
                <input
                  type="text"
                  value={newName}
                  onChange={(e) => {
                    setNewName(e.target.value);
                    setError('');
                  }}
                  placeholder="Ex: Villa Sol, Mar Azul Apartments, Casa da Praia..."
                  className={`w-full px-4 py-3 border ${error ? 'border-red-500' : 'border-gray-300'} rounded-lg focus:outline-none focus:border-[#006ce4] focus:ring-1 focus:ring-[#006ce4] transition-colors`}
                  autoFocus
                />
                {error && (
                  <p className="mt-2 text-sm text-red-600">{error}</p>
                )}
              </div>

              <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 mb-8">
                <h4 className="font-semibold text-blue-900 mb-2 text-sm">💡 Dica:</h4>
                <p className="text-blue-800 text-sm">
                  Escolha um nome claro e fácil de lembrar. Os hóspedes vão identificar sua propriedade por este nome.
                </p>
              </div>

              <div className="flex gap-3">
                <button
                  type="button"
                  onClick={handleBack}
                  className="px-6 py-2.5 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition-colors font-medium"
                >
                  Cancelar
                </button>
                <button
                  type="submit"
                  className="flex-1 bg-[#006ce4] text-white py-2.5 rounded-lg hover:bg-[#0053b3] transition-colors font-medium flex items-center justify-center gap-2"
                >
                  <Check size={18} />
                  Salvar alterações
                </button>
              </div>
            </form>
          )}

          <div className="mt-8 pt-6 border-t border-gray-200">
            <p className="text-sm text-gray-500 mb-2">Preview:</p>
            <div className="bg-gray-50 rounded-lg p-4">
              <p className="text-gray-700">
                <span className="font-semibold">Nome atual:</span>{' '}
                <span className="text-gray-500">{propertyName || 'Não definido'}</span>
              </p>
              <p className="text-gray-700 mt-2">
                <span className="font-semibold">Novo nome:</span>{' '}
                <span className="text-[#006ce4] font-medium">{newName || '___'}</span>
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default NomePropriedade;

// src/components/AlojamentoRegisto/Regras.jsx
import React, { useState, useEffect, useCallback, useRef } from 'react';
import {
  Check, Clock, Ban, Moon, Baby, Volume2, Users, Car,
  AlertCircle, Search, Loader, Shield, DoorOpen, Calendar,
  XCircle, RefreshCw,
} from 'lucide-react';

const API_URL = 'https://welovepalop.com';

// ==================== SANITIZAÇÃO DEFENSIVA ====================
// Rejeita regras com lixo no título: "ddd", "0", string vazia, etc.
const regraValida = (r) => {
  if (!r || typeof r !== 'object') return false;
  const titulo = String(r.titulo ?? '').trim();
  if (!titulo) return false;
  if (/\bddd\b/i.test(titulo)) return false;   // "ddd" em qualquer posição
  if (/^0+$/.test(titulo)) return false;        // apenas "0", "00", ...
  return true;
};

// Normaliza uma regra vinda do backend (removendo qualquer ruído no título)
const normalizarRegra = (r) => {
  if (!r) return null;
  const tituloLimpo = String(r.titulo ?? '')
    .replace(/\bddd\b/gi, '')   // remove "ddd"
    .replace(/\s{2,}/g, ' ')     // colapsa espaços duplos
    .trim();
  return { ...r, titulo: tituloLimpo };
};

const getIcone = (iconeNome) => {
  const icons = {
    clock:    <Clock size={20} />,
    ban:      <Ban size={20} />,
    moon:     <Moon size={20} />,
    baby:     <Baby size={20} />,
    volume2:  <Volume2 size={20} />,
    users:    <Users size={20} />,
    car:      <Car size={20} />,
    calendar: <Calendar size={20} />,
    shield:   <Shield size={20} />,
    dooropen: <DoorOpen size={20} />,
  };
  return icons[String(iconeNome || '').toLowerCase()] || <AlertCircle size={20} />;
};

// ==================== API ====================

export async function buscarRegrasDisponiveis() {
  try {
    const response = await fetch(`${API_URL}/api/alojamento/regras.php`);
    const data = await response.json();
    const lista = data.success ? (data.data || []) : [];
    return lista
      .map(normalizarRegra)
      .filter(regraValida);
  } catch (error) {
    console.error('Erro ao buscar regras:', error);
    return [];
  }
}

export async function buscarRegrasDoAlojamento(id) {
  try {
    const response = await fetch(`${API_URL}/api/alojamento/regras.php?id=${id}`);
    const data = await response.json();
    if (data.success && data.data) {
      const regras = (data.data.regras || [])
        .map(normalizarRegra)
        .filter(regraValida);
      return {
        success: true,
        data: {
          regras,
          regras_adicionais: data.data.regras_adicionais || '',
        },
      };
    }
    return { success: false, data: { regras: [], regras_adicionais: '' } };
  } catch (error) {
    console.error('Erro ao buscar regras do alojamento:', error);
    return { success: false, data: { regras: [], regras_adicionais: '' } };
  }
}

export async function salvarRegras(alojamentoId, regrasIds, regrasAdicionais = '') {
  try {
    const response = await fetch(`${API_URL}/api/alojamento/regras.php`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        alojamento_id: alojamentoId,
        regras_ids: regrasIds,
        regras_adicionais: regrasAdicionais,
      }),
    });
    return await response.json();
  } catch (error) {
    console.error('Erro ao salvar regras:', error);
    return { success: false, message: 'Erro de conexão' };
  }
}

export async function alternarStatusRegra(alojamentoId, regraId, ativar) {
  try {
    const response = await fetch(`${API_URL}/api/alojamento/alternar_status_regra.php`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        alojamento_id: alojamentoId,
        regra_id: regraId,
        ativar: ativar ? 1 : 0,
      }),
    });
    return await response.json();
  } catch (error) {
    console.error('Erro ao alternar status:', error);
    return { success: false, message: 'Erro de conexão' };
  }
}

// ==================== COMPONENTE PRINCIPAL ====================

const Regras = ({
  alojamentoId,
  onChange,
  readOnly = false,
  initialRegras = [],
  initialRegrasAdicionais = '',
}) => {
  const [categoriaAtiva, setCategoriaAtiva] = useState('todas');
  const [busca, setBusca]                   = useState('');
  const [regras, setRegras]                 = useState([]);
  const [loading, setLoading]               = useState(true);
  const [error, setError]                   = useState(null);
  const [successMessage, setSuccessMessage] = useState(null);
  const [regrasAdicionais, setRegrasAdicionais] = useState(initialRegrasAdicionais || '');
  const [isSaving, setIsSaving]             = useState(false);
  const [togglingId, setTogglingId]         = useState(null);

  const isInitialMount    = useRef(true);
  const prevAlojamentoId  = useRef(alojamentoId);
  const notifyingParent   = useRef(false);
  const prevRegrasRef     = useRef(regras);
  const prevAdicionaisRef = useRef(regrasAdicionais);

  const notificarPai = useCallback((novasRegras, novoTextoAdicional) => {
    if (!onChange) return;
    if (notifyingParent.current) return;

    const selecionadas = novasRegras.filter(r => r.selecionada === true);
    const regrasIds    = selecionadas.map(r => r.id);

    console.log('📤 Notificando pai - Regras IDs:', regrasIds);
    console.log('📤 Notificando pai - Regras adicionais:', novoTextoAdicional);

    notifyingParent.current = true;
    onChange({
      regras: selecionadas,
      regras_ids: regrasIds,
      regrasAdicionais: novoTextoAdicional,
    });
    setTimeout(() => { notifyingParent.current = false; }, 100);
  }, [onChange]);

  // ==================== CARREGAR REGRAS ====================
  const carregarRegras = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);

      console.log('🔄 Carregando regras - alojamentoId:', alojamentoId);

      let regrasLista = [];
      let regrasAdicionaisTexto = '';

      if (alojamentoId) {
        // Modo EDIÇÃO
        const resultado = await buscarRegrasDoAlojamento(alojamentoId);
        if (resultado.success && resultado.data) {
          regrasLista = resultado.data.regras || [];
          regrasAdicionaisTexto = resultado.data.regras_adicionais || '';
          console.log('✏️ Modo EDIÇÃO - regras carregadas:', regrasLista.length);
        }
      } else {
        // Modo REGISTO
        const regrasDisponiveis = await buscarRegrasDisponiveis();

        const savedRegrasIds       = localStorage.getItem('propertyRegrasSelecionadas');
        const savedRegrasAdicionais = localStorage.getItem('propertyRegrasAdicionais');

        if (savedRegrasIds) {
          let savedIds = [];
          try { savedIds = JSON.parse(savedRegrasIds); } catch { savedIds = []; }
          regrasLista = (regrasDisponiveis || []).map(r => ({
            ...r,
            selecionada: Array.isArray(savedIds) && savedIds.includes(r.id),
          }));
          console.log('🆕 Modo REGISTO - regras do localStorage IDs:', savedIds);
        } else {
          regrasLista = (regrasDisponiveis || []).map(r => ({ ...r, selecionada: false }));
        }

        if (savedRegrasAdicionais) {
          regrasAdicionaisTexto = savedRegrasAdicionais;
        }

        console.log('🆕 Modo REGISTO - total regras carregadas:', regrasLista.length);
      }

      setRegras(regrasLista);
      setRegrasAdicionais(regrasAdicionaisTexto);

      setTimeout(() => {
        notificarPai(regrasLista, regrasAdicionaisTexto);
      }, 50);
    } catch (err) {
      console.error('❌ Erro:', err);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }, [alojamentoId, notificarPai]);

  useEffect(() => {
    if (prevAlojamentoId.current !== alojamentoId) {
      prevAlojamentoId.current = alojamentoId;
      carregarRegras();
    } else if (isInitialMount.current) {
      isInitialMount.current = false;
      carregarRegras();
    }
  }, [alojamentoId, carregarRegras]);

  // ==================== NOTIFICAR PAI QUANDO MUDA ====================
  useEffect(() => {
    if (isInitialMount.current) return;

    const regrasChanged    = JSON.stringify(prevRegrasRef.current) !== JSON.stringify(regras);
    const adicionaisChanged = prevAdicionaisRef.current !== regrasAdicionais;

    if ((regrasChanged || adicionaisChanged) && !loading) {
      console.log('🔄 Mudança nas regras detectada, notificando pai...');
      notificarPai(regras, regrasAdicionais);
    }

    prevRegrasRef.current    = regras;
    prevAdicionaisRef.current = regrasAdicionais;
  }, [regras, regrasAdicionais, loading, notificarPai]);

  // ==================== TOGGLE REGRA ====================
  const toggleRegra = async (regraId, currentStatus) => {
    if (readOnly) return;

    const novoStatus = !currentStatus;
    console.log(`🔄 Toggle regra ${regraId}: ${currentStatus} -> ${novoStatus}`);

    setRegras(prev => {
      const novas = prev.map(r =>
        r.id === regraId ? { ...r, selecionada: novoStatus } : r
      );

      if (!alojamentoId) {
        const selecionadasIds = novas.filter(r => r.selecionada).map(r => r.id);
        localStorage.setItem('propertyRegrasSelecionadas', JSON.stringify(selecionadasIds));
        localStorage.setItem('propertyRegrasAdicionais', regrasAdicionais);
        console.log('💾 Modo REGISTO - Regras salvas no localStorage:', selecionadasIds);
      }

      return novas;
    });

    if (alojamentoId) {
      setTogglingId(regraId);
      setError(null);

      try {
        const result = await alternarStatusRegra(alojamentoId, regraId, novoStatus);
        if (result.success) {
          setSuccessMessage(novoStatus ? 'Regra ativada!' : 'Regra desativada!');
          setTimeout(() => setSuccessMessage(null), 2000);
          console.log(`✅ Regra ${regraId} ${novoStatus ? 'ativada' : 'desativada'} no backend`);
        } else {
          throw new Error(result.message || 'Erro ao alterar status');
        }
      } catch (err) {
        console.error('❌ Erro ao alternar:', err);
        setError(err.message);
        setTimeout(() => setError(null), 3000);
      } finally {
        setTogglingId(null);
      }
    }
  };

  // ==================== REGRAS ADICIONAIS ====================
  const handleRegrasAdicionaisChange = (e) => {
    const novoTexto = e.target.value;
    setRegrasAdicionais(novoTexto);

    if (!alojamentoId) {
      localStorage.setItem('propertyRegrasAdicionais', novoTexto);
      console.log('💾 Regras adicionais salvas no localStorage:', novoTexto);
    }
  };

  const handleSalvarRegrasAdicionais = async () => {
    if (!alojamentoId) {
      setSuccessMessage('Regras adicionais guardadas!');
      setTimeout(() => setSuccessMessage(null), 2000);
      return;
    }

    setIsSaving(true);
    setError(null);
    setSuccessMessage(null);

    try {
      const regrasIds = regras.filter(r => r.selecionada).map(r => r.id);
      const result = await salvarRegras(alojamentoId, regrasIds, regrasAdicionais);

      if (result.success) {
        setSuccessMessage('Regras adicionais salvas!');
        setTimeout(() => setSuccessMessage(null), 3000);
      } else {
        throw new Error(result.message || 'Erro ao salvar');
      }
    } catch (err) {
      console.error('❌ Erro:', err);
      setError(err.message);
      setTimeout(() => setError(null), 3000);
    } finally {
      setIsSaving(false);
    }
  };

  // ==================== CATEGORIAS + FILTRO ====================
  const categorias = [
    'todas',
    ...new Set(
      regras
        .map(r => r.categoria || 'Gerais')
        .filter(c => c && String(c).trim() !== '')
    ),
  ];

  const regrasFiltradas = regras.filter(regra => {
    if (categoriaAtiva !== 'todas' && (regra.categoria || 'Gerais') !== categoriaAtiva) {
      return false;
    }
    if (busca && !String(regra.titulo || '').toLowerCase().includes(busca.toLowerCase())) {
      return false;
    }
    return true;
  });

  const totalSelecionadas = regras.filter(r => r.selecionada === true).length;

  // ==================== RENDER: LOADING ====================
  if (loading) {
    return (
      <div className="text-center py-12">
        <Loader className="animate-spin mx-auto text-[#006ce4]" size={40} />
        <p className="mt-3 text-gray-600">Carregando regras...</p>
      </div>
    );
  }

  // ==================== RENDER: ERRO ====================
  if (error) {
    return (
      <div className="bg-red-50 border border-red-200 rounded-lg p-6 text-center">
        <XCircle className="mx-auto text-red-500 mb-3" size={48} />
        <p className="text-red-700 font-medium">Erro</p>
        <p className="text-red-600 text-sm mt-1">{error}</p>
        <button
          onClick={() => carregarRegras()}
          className="mt-4 px-4 py-2 bg-[#006ce4] text-white rounded-lg hover:bg-[#0053b3] transition-colors flex items-center gap-2 mx-auto"
        >
          <RefreshCw size={16} /> Tentar novamente
        </button>
      </div>
    );
  }

  // ==================== RENDER: SEM REGRAS ====================
  if (regras.length === 0) {
    return (
      <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-6 text-center">
        <Shield className="mx-auto text-yellow-500 mb-3" size={48} />
        <p className="text-yellow-700">⚠️ Nenhuma regra encontrada</p>
        <button
          onClick={carregarRegras}
          className="mt-4 px-4 py-2 bg-[#006ce4] text-white rounded-lg"
        >
          Recarregar
        </button>
      </div>
    );
  }

  // ==================== RENDER: PRINCIPAL ====================
  return (
    <div className="space-y-6">
      <div className="text-xs text-gray-400 text-right">
        {alojamentoId ? (
          <span className="flex items-center justify-end gap-2">
            <span className="inline-block w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
            ✏️ Modo edição — {totalSelecionadas} regra(s) ativa(s)
          </span>
        ) : (
          <span className="flex items-center justify-end gap-2">
            <span className="inline-block w-2 h-2 bg-blue-500 rounded-full animate-pulse"></span>
            📝 Modo registo — {totalSelecionadas} regra(s) selecionada(s)
          </span>
        )}
      </div>

      {successMessage && (
        <div className="bg-green-50 border border-green-200 rounded-lg p-3 flex items-center gap-2">
          <Check size={18} className="text-green-500" />
          <p className="text-green-700 text-sm">{successMessage}</p>
        </div>
      )}

      {/* Pesquisa */}
      <div className="relative">
        <input
          type="text"
          value={busca}
          onChange={(e) => setBusca(e.target.value)}
          placeholder="Pesquisar regras..."
          className="w-full px-4 py-3 pl-10 border border-gray-300 rounded-lg focus:ring-2 focus:ring-[#006ce4] focus:border-transparent"
          disabled={readOnly}
        />
        <Search size={18} className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 pointer-events-none" />
      </div>

      {/* Categorias */}
      {categorias.length > 1 && (
        <div className="flex flex-wrap gap-2 overflow-x-auto pb-2">
          {categorias.map(cat => (
            <button
              key={cat}
              type="button"
              onClick={() => setCategoriaAtiva(cat)}
              className={`px-4 py-2 rounded-full text-sm font-medium transition-all whitespace-nowrap ${
                categoriaAtiva === cat
                  ? 'bg-[#006ce4] text-white'
                  : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
              }`}
            >
              {cat === 'todas' ? 'Todas' : cat}
            </button>
          ))}
        </div>
      )}

      {/* Lista de regras */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
        {regrasFiltradas.length === 0 && (
          <div className="col-span-full text-center py-8 text-gray-400">
            {busca ? 'Nenhuma regra encontrada' : 'Nenhuma regra disponível'}
          </div>
        )}

        {regrasFiltradas.map(regra => {
          const isAtiva   = regra.selecionada === true;
          const isLoading = togglingId === regra.id;

          return (
            <button
              key={regra.id}
              type="button"
              onClick={() => toggleRegra(regra.id, isAtiva)}
              disabled={readOnly || regra.obrigatorio || isLoading}
              className={`flex items-center gap-3 p-3 rounded-lg border transition-all duration-200 ${
                isAtiva
                  ? 'border-[#006ce4] bg-blue-50 shadow-sm'
                  : 'border-gray-200 hover:border-gray-300 hover:bg-gray-50'
              } ${(readOnly || regra.obrigatorio) ? 'cursor-default' : 'cursor-pointer'}
              ${isLoading ? 'opacity-70' : 'opacity-100'}`}
            >
              <div
                className={`transition-transform duration-200 ${
                  isAtiva ? 'scale-110 text-[#006ce4]' : 'scale-100 text-gray-500'
                }`}
              >
                {isLoading ? <Loader size={20} className="animate-spin" /> : getIcone(regra.icone)}
              </div>

              <div className="flex-1 text-left">
                <div className="flex items-center gap-2 flex-wrap">
                  <span className={`text-sm font-medium ${isAtiva ? 'text-[#006ce4]' : 'text-gray-700'}`}>
                    {regra.titulo}
                  </span>
                  {regra.obrigatorio && (
                    <span className="text-xs bg-gray-200 text-gray-600 px-2 py-0.5 rounded-full">
                      Obrigatório
                    </span>
                  )}
                </div>
                {regra.descricao && (
                  <p className="text-xs text-gray-500 mt-0.5">{regra.descricao}</p>
                )}
              </div>

              {!regra.obrigatorio && (
                <div
                  className={`w-5 h-5 rounded border-2 flex items-center justify-center transition-all ${
                    isAtiva ? 'bg-[#006ce4] border-[#006ce4]' : 'border-gray-300 bg-white'
                  }`}
                >
                  {isAtiva && <Check size={12} className="text-white" />}
                </div>
              )}
            </button>
          );
        })}
      </div>

      {/* Regras adicionais */}
      {!readOnly && (
        <div className="mt-6 border-t pt-4">
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Regras adicionais personalizadas
          </label>
          <textarea
            value={regrasAdicionais}
            onChange={handleRegrasAdicionaisChange}
            rows={4}
            placeholder="Adicione regras específicas da sua propriedade (ex: Horário de silêncio, Proibido fumar, etc.)"
            className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-[#006ce4] focus:border-transparent"
          />

          <div className="flex justify-end mt-3">
            <button
              onClick={handleSalvarRegrasAdicionais}
              disabled={isSaving}
              className="flex items-center gap-2 px-4 py-2 bg-[#006ce4] text-white rounded-lg text-sm font-medium hover:bg-[#0053b3] transition-colors disabled:opacity-50"
            >
              {isSaving ? (
                <>
                  <Loader size={16} className="animate-spin" />
                  Salvando...
                </>
              ) : (
                <>
                  <Check size={16} />
                  {alojamentoId ? 'Salvar regras' : 'Guardar regras'}
                </>
              )}
            </button>
          </div>
        </div>
      )}

      {/* Resumo das selecionadas */}
      {totalSelecionadas > 0 && (
        <div className="bg-gray-50 rounded-lg p-4 mt-4 border border-gray-200">
          <h4 className="font-semibold text-gray-700 mb-2 flex items-center gap-2">
            <Check size={16} className="text-green-500" />
            Regras selecionadas ({totalSelecionadas})
          </h4>
          <div className="flex flex-wrap gap-2">
            {regras.filter(r => r.selecionada).map(regra => (
              <span
                key={regra.id}
                className="px-3 py-1 bg-white border border-[#006ce4] rounded-full text-sm flex items-center gap-1 text-[#006ce4]"
              >
                {getIcone(regra.icone)}
                {regra.titulo}
              </span>
            ))}
          </div>
          {regrasAdicionais && (
            <div className="mt-3 pt-2 border-t border-gray-200">
              <p className="text-xs text-gray-500">Regras adicionais:</p>
              <p className="text-sm text-gray-700 mt-1 whitespace-pre-line">{regrasAdicionais}</p>
            </div>
          )}
        </div>
      )}

      {totalSelecionadas === 0 && !readOnly && (
        <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4 text-center">
          <AlertCircle size={18} className="inline-block mr-2 text-yellow-500" />
          <p className="text-yellow-700 text-sm inline">
            Nenhuma regra selecionada. Clique nas regras acima para selecionar.
          </p>
        </div>
      )}
    </div>
  );
};

// ==================== RESUMO (usado noutros ecrãs) ====================
export const RegrasResumo = ({ regras, regrasAdicionais, className = '' }) => {
  const regrasAtivas = (regras || [])
    .map(normalizarRegra)
    .filter(regraValida)
    .filter(r => r && (r.selecionada === true || r.id));

  if (regrasAtivas.length === 0 && !regrasAdicionais) {
    return <p className="text-gray-400 text-sm">Nenhuma regra definida</p>;
  }

  return (
    <div className={`space-y-3 ${className}`}>
      {regrasAtivas.map(regra => (
        <div key={regra.id} className="flex items-start gap-3">
          <div className="text-gray-500 mt-0.5">{getIcone(regra.icone)}</div>
          <div>
            <p className="font-medium text-gray-800 text-sm">{regra.titulo}</p>
            {regra.descricao && (
              <p className="text-xs text-gray-500">{regra.descricao}</p>
            )}
          </div>
        </div>
      ))}

      {regrasAdicionais && (
        <div className="flex items-start gap-3">
          <div className="text-gray-500 mt-0.5"><AlertCircle size={16} /></div>
          <div>
            <p className="font-medium text-gray-800 text-sm">Regras adicionais</p>
            <p className="text-xs text-gray-500 whitespace-pre-line">{regrasAdicionais}</p>
          </div>
        </div>
      )}
    </div>
  );
};

export default Regras;

// src/components/CarroRegisto/Caracteristicas.jsx
// CORRIGIDO - Sem setState durante renderização

import React, { useState, useEffect } from 'react';
import { 
  Check, Loader, Search, Wifi, Snowflake, Tv, Coffee, 
  Utensils, Car, Map, Camera, Bluetooth, Shield, 
  Armchair, Sun, Smartphone, Wind, Volume2, Fan, 
  Thermometer, Video, Music, Battery, Key, Lock, 
  Flower2, Sparkles, Airplay, Radio 
} from 'lucide-react';
import { buscarCaracteristicas } from '../../services/carroApiService';

const getIcone = (iconeNome) => {
  const icons = {
    snowflake: <Snowflake size={18} />,
    map: <Map size={18} />,
    camera: <Camera size={18} />,
    bluetooth: <Bluetooth size={18} />,
    steering: <Car size={18} />,
    window: <Wind size={18} />,
    shield: <Shield size={18} />,
    brake: <Shield size={18} />,
    seat: <Armchair size={18} />,
    sun: <Sun size={18} />,
    smartphone: <Smartphone size={18} />,
    wifi: <Wifi size={18} />,
    tv: <Tv size={18} />,
    coffee: <Coffee size={18} />,
    utensils: <Utensils size={18} />,
    volume2: <Volume2 size={18} />,
    fan: <Fan size={18} />,
    thermomether: <Thermometer size={18} />,
    video: <Video size={18} />,
    music: <Music size={18} />,
    battery: <Battery size={18} />,
    key: <Key size={18} />,
    lock: <Lock size={18} />,
    flower: <Flower2 size={18} />,
    sparkles: <Sparkles size={18} />,
    airplay: <Airplay size={18} />,
    radio: <Radio size={18} />
  };
  return icons[iconeNome?.toLowerCase()] || <Check size={18} />;
};

const Caracteristicas = ({ items = [], onChange, readOnly = false }) => {
  const [caracteristicas, setCaracteristicas] = useState([]);
  const [loading, setLoading] = useState(true);
  const [busca, setBusca] = useState('');
  const [categoriaAtiva, setCategoriaAtiva] = useState('todas');

  // Carregar características apenas uma vez
  useEffect(() => {
    const carregar = async () => {
      try {
        const result = await buscarCaracteristicas();
        if (result.success && result.data) {
          // Mapear com selecionada baseado nos items recebidos
          const lista = result.data.map(c => ({
            ...c,
            selecionada: items.includes(c.id)
          }));
          setCaracteristicas(lista);
        } else {
          // Fallback
          const fallback = [
            { id: 1, nome: 'Ar Condicionado', icone: 'snowflake', tipo: 'Conforto', selecionada: items.includes(1) },
            { id: 2, nome: 'GPS', icone: 'map', tipo: 'Tecnologia', selecionada: items.includes(2) },
            { id: 3, nome: 'Câmera de Ré', icone: 'camera', tipo: 'Segurança', selecionada: items.includes(3) },
            { id: 4, nome: 'Bluetooth', icone: 'bluetooth', tipo: 'Tecnologia', selecionada: items.includes(4) },
            { id: 5, nome: 'Direção Assistida', icone: 'steering', tipo: 'Conforto', selecionada: items.includes(5) },
            { id: 6, nome: 'Vidros Elétricos', icone: 'window', tipo: 'Conforto', selecionada: items.includes(6) },
            { id: 7, nome: 'Airbags', icone: 'shield', tipo: 'Segurança', selecionada: items.includes(7) },
            { id: 8, nome: 'ABS', icone: 'brake', tipo: 'Segurança', selecionada: items.includes(8) },
            { id: 9, nome: 'Bancos de Couro', icone: 'seat', tipo: 'Luxo', selecionada: items.includes(9) },
            { id: 10, nome: 'Teto Solar', icone: 'sun', tipo: 'Luxo', selecionada: items.includes(10) }
          ];
          setCaracteristicas(fallback);
        }
      } catch (error) {
        console.error('Erro ao carregar características:', error);
      } finally {
        setLoading(false);
      }
    };
    
    carregar();
  }, []); // Executa apenas uma vez

  // 🔥 CORREÇÃO: Não chamar onChange durante renderização
  const toggleCaracteristica = (id) => {
    if (readOnly) return;
    
    const novasCaracteristicas = caracteristicas.map(c => 
      c.id === id ? { ...c, selecionada: !c.selecionada } : c
    );
    
    setCaracteristicas(novasCaracteristicas);
    
    const selecionadasIds = novasCaracteristicas.filter(c => c.selecionada).map(c => c.id);
    onChange(selecionadasIds);
  };

  const caracteristicasFiltradas = caracteristicas.filter(c => 
    c.nome.toLowerCase().includes(busca.toLowerCase())
  );

  const categorias = [...new Set(caracteristicas.map(c => c.tipo || 'Geral').filter(Boolean))];
  
  const caracteristicasPorCategoria = categoriaAtiva === 'todas' 
    ? caracteristicasFiltradas 
    : caracteristicasFiltradas.filter(c => (c.tipo || 'Geral') === categoriaAtiva);

  const totalSelecionadas = caracteristicas.filter(c => c.selecionada).length;

  if (loading) {
    return (
      <div className="text-center py-8">
        <Loader className="animate-spin mx-auto text-[#006ce4]" size={32} />
        <p className="mt-2 text-gray-500">Carregando características...</p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div className="relative flex-1 max-w-xs">
          <Search size={16} className="absolute left-2.5 top-1/2 transform -translate-y-1/2 text-gray-400" />
          <input
            type="text"
            value={busca}
            onChange={(e) => setBusca(e.target.value)}
            placeholder="Buscar características..."
            className="w-full pl-9 pr-4 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:border-[#006ce4]"
          />
        </div>
        <span className="text-sm text-gray-500">
          {totalSelecionadas} selecionada(s)
        </span>
      </div>

      {categorias.length > 0 && (
        <div className="flex flex-wrap gap-2">
          <button
            onClick={() => setCategoriaAtiva('todas')}
            className={`px-3 py-1.5 rounded-full text-xs font-medium transition-colors ${
              categoriaAtiva === 'todas' 
                ? 'bg-[#006ce4] text-white' 
                : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
            }`}
          >
            Todas
          </button>
          {categorias.map(cat => (
            <button
              key={cat}
              onClick={() => setCategoriaAtiva(cat)}
              className={`px-3 py-1.5 rounded-full text-xs font-medium transition-colors ${
                categoriaAtiva === cat 
                  ? 'bg-[#006ce4] text-white' 
                  : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
              }`}
            >
              {cat}
            </button>
          ))}
        </div>
      )}

      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3">
        {caracteristicasPorCategoria.map(carac => (
          <button
            key={carac.id}
            type="button"
            onClick={() => toggleCaracteristica(carac.id)}
            disabled={readOnly}
            className={`flex items-center gap-3 p-3 rounded-lg border transition-all ${
              carac.selecionada
                ? 'border-[#006ce4] bg-blue-50 text-[#006ce4]'
                : 'border-gray-200 hover:border-gray-300 hover:bg-gray-50'
            }`}
          >
            <div className={carac.selecionada ? 'text-[#006ce4]' : 'text-gray-500'}>
              {getIcone(carac.icone)}
            </div>
            <span className="text-sm flex-1 text-left">{carac.nome}</span>
            {carac.selecionada && <Check size={16} />}
          </button>
        ))}
      </div>

      {caracteristicasPorCategoria.length === 0 && (
        <div className="text-center py-8 text-gray-400">
          Nenhuma característica encontrada
        </div>
      )}
    </div>
  );
};

export default Caracteristicas;

// src/components/CarroRegisto/EditarCarro.jsx
// CORRIGIDO - Localização funcionando corretamente + Toast padrão do projeto

import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { ArrowLeft, Check, ChevronRight, HelpCircle, User, Loader } from 'lucide-react';
import InformacoesBasicas from './InformacoesBasicas';
import Especificacoes from './Especificacoes';
import Localizacao from './Localizacao';
import Caracteristicas from './Caracteristicas';
import ImagensUpload from './ImagensUpload';
import { buscarCarro, salvarFluxoCarro } from '../../services/carroApiService';
import { useToast } from '../../Toast';

const EditarCarro = () => {
  const navigate = useNavigate();
  const { id } = useParams();
  const { showToast } = useToast();

  const [fase, setFase] = useState(1);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [loading, setLoading] = useState(true);
  const [carroId, setCarroId] = useState(id ? parseInt(id) : null);

  const [informacoes, setInformacoes] = useState({});
  const [especificacoes, setEspecificacoes] = useState({});

  // 🔥 CORRIGIDO: Estado da localização com todos os campos
  const [localizacao, setLocalizacao] = useState({
    local: '',
    cidade: '',
    ilha: ''
  });

  const [caracteristicas, setCaracteristicas] = useState([]);
  const [imagens, setImagens] = useState([]);

  useEffect(() => {
    const carregarCarro = async () => {
      if (!carroId) return;

      setLoading(true);
      try {
        console.log(`🚗 Buscando carro ID: ${carroId}`);
        const result = await buscarCarro(carroId);

        console.log('📦 Dados recebidos:', result);

        if (result.success && result.data) {
          const data = result.data;

          setInformacoes({
            titulo: data.titulo || '',
            marca: data.marca || '',
            modelo: data.modelo || '',
            categoria_id: data.categoria_id || '',
            preco_dia: data.preco_dia || '',
            descricao: data.descricao || '',
            descricao_detalhada: data.descricao_detalhada || ''
          });

          setEspecificacoes({
            ano: data.ano || '',
            passageiros: data.passageiros || 5,
            portas: data.portas || 4,
            transmissao: data.transmissao || 'Manual',
            combustivel: data.combustivel || 'Gasolina',
            consumo: data.consumo || '',
            cor: data.cor || '',
            quilometragem: data.quilometragem || 0
          });

          // 🔥 CORRIGIDO: Carregar localização com todos os campos
          setLocalizacao({
            local: data.localizacao || data.cidade || '',
            cidade: data.cidade || data.localizacao || '',
            ilha: data.ilha || ''
          });

          console.log('📍 Localização carregada:', {
            local: data.localizacao,
            cidade: data.cidade,
            ilha: data.ilha
          });

          setCaracteristicas(data.caracteristicas || []);
          setImagens(data.imagens || []);
        } else {
          showToast('Erro ao carregar dados do veículo: ' + (result.message || ''), 'error');
          navigate('/carro-registo/meus');
        }
      } catch (error) {
        console.error('❌ Erro ao carregar:', error);
        showToast('Erro ao carregar dados: ' + error.message, 'error');
        navigate('/carro-registo/meus');
      } finally {
        setLoading(false);
      }
    };

    carregarCarro();
  }, [carroId, navigate, showToast]);

  const handleNext = () => {
    setFase(fase + 1);
    window.scrollTo(0, 0);
  };

  const handleBack = () => {
    if (fase > 1) {
      setFase(fase - 1);
      window.scrollTo(0, 0);
    } else {
      navigate(-1);
    }
  };

  const handleFinalizar = async () => {
    if (isSubmitting) return;
    setIsSubmitting(true);

    try {
      // 🔥 CORRIGIDO: Montar dados completos corretamente
      const dadosCompletos = {
        ...informacoes,
        ...especificacoes,
        localizacao: localizacao.local || localizacao.cidade || '',
        cidade: localizacao.cidade || localizacao.local || '',
        ilha: localizacao.ilha || '',
        caracteristicas: caracteristicas,
        imagens: imagens
      };

      console.log('📤 Enviando dados para atualização:', dadosCompletos);

      const result = await salvarFluxoCarro(dadosCompletos, carroId);

      if (result.success) {
        showToast(result.message || 'Alterações guardadas com sucesso!', 'success');
        navigate('/carro-registo/meus');
      } else {
        showToast(result.message || 'Erro ao guardar alterações', 'error');
      }
    } catch (error) {
      console.error('❌ Erro ao salvar:', error);
      showToast('Erro ao salvar as alterações. Tente novamente.', 'error');
    } finally {
      setIsSubmitting(false);
    }
  };

  const renderProgressBar = () => {
    const fasesLista = ['Info', 'Especificações', 'Localização', 'Características', 'Fotos'];
    return (
      <div className="mb-6">
        <div className="flex items-center justify-between mb-2">
          {fasesLista.map((nome, index) => (
            <div key={index} className="flex-1 text-center">
              <div className={`text-xs font-medium ${fase > index + 1 ? 'text-[#006ce4]' : fase === index + 1 ? 'text-[#006ce4]' : 'text-gray-400'}`}>
                {nome}
              </div>
            </div>
          ))}
        </div>
        <div className="flex gap-1">
          {fasesLista.map((_, index) => (
            <div key={index} className={`h-1 flex-1 rounded-full ${fase > index + 1 ? 'bg-[#006ce4]' : fase === index + 1 ? 'bg-[#006ce4]' : 'bg-gray-200'}`} />
          ))}
        </div>
      </div>
    );
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <Loader className="animate-spin mx-auto text-[#006ce4]" size={48} />
        <p className="mt-4 text-gray-600">Carregando veículo...</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <header className="bg-[#003580] text-white h-[60px] flex items-center justify-between px-6 shadow-sm">
        <div className="font-bold text-2xl tracking-tight"></div>
        <div className="flex items-center gap-6 text-sm">
          <div className="text-right">
            <div className="font-medium">{informacoes.titulo || 'Editar Veículo'}</div>
            <div className="text-[10px] opacity-80">
              {fase === 1 && 'Informações básicas'}
              {fase === 2 && 'Especificações'}
              {fase === 3 && 'Localização'}
              {fase === 4 && `${caracteristicas.length} característica(s)`}
              {fase === 5 && `${imagens.length} foto(s)`}
            </div>
          </div>
          <div className="w-[1px] h-8 bg-blue-900"></div>

          <div className="flex items-center gap-2 cursor-pointer hover:underline">
            <span>Ajuda</span> <HelpCircle size={18} />
          </div>

        </div>
      </header>

      <div className="max-w-4xl mx-auto px-4 py-8">
        {renderProgressBar()}

        <div className="bg-white rounded-lg shadow-md p-8">
          {fase === 1 && (
            <>
              <h1 className="text-2xl font-bold text-gray-900 mb-2">Editar Informações</h1>
              <p className="text-gray-600 mb-6">Atualize os dados do veículo.</p>
              <InformacoesBasicas
                dados={informacoes}
                onChange={setInformacoes}
                readOnly={false}
              />
            </>
          )}

          {fase === 2 && (
            <>
              <h1 className="text-2xl font-bold text-gray-900 mb-2">Editar Especificações</h1>
              <p className="text-gray-600 mb-6">Atualize os detalhes técnicos.</p>
              <Especificacoes
                dados={especificacoes}
                onChange={setEspecificacoes}
                readOnly={false}
              />
            </>
          )}

          {fase === 3 && (
            <>
              <h1 className="text-2xl font-bold text-gray-900 mb-2">Editar Localização</h1>
              <p className="text-gray-600 mb-6">Atualize onde o veículo está disponível.</p>
              <Localizacao
                dados={localizacao}
                onChange={setLocalizacao}
                readOnly={false}
                carroId={carroId}
              />
            </>
          )}

          {fase === 4 && (
            <>
              <h1 className="text-2xl font-bold text-gray-900 mb-2">Editar Características</h1>
              <p className="text-gray-600 mb-6">Atualize os equipamentos do veículo.</p>
              <Caracteristicas
                items={caracteristicas}
                onChange={setCaracteristicas}
                readOnly={false}
              />
            </>
          )}

          {fase === 5 && (
            <>
              <h1 className="text-2xl font-bold text-gray-900 mb-2">Editar Fotos</h1>
              <p className="text-gray-600 mb-6">Atualize as fotos do veículo.</p>
              <ImagensUpload
                imagens={imagens}
                onChange={setImagens}
                veiculoId={carroId}
                readOnly={false}
              />
            </>
          )}

          <div className="flex justify-between gap-4 mt-8 pt-6 border-t border-gray-100">
            <button
              onClick={handleBack}
              className="flex items-center gap-2 px-6 py-2.5 border border-gray-300 text-gray-700 rounded-lg font-semibold hover:bg-gray-50"
            >
              <ArrowLeft size={18} /> Voltar
            </button>

            {fase < 5 && (
              <button
                onClick={handleNext}
                className="flex items-center gap-2 px-6 py-2.5 bg-[#006ce4] text-white rounded-lg font-semibold hover:bg-[#0053b3]"
              >
                Continuar <ChevronRight size={18} />
              </button>
            )}

            {fase === 5 && (
              <button
                onClick={handleFinalizar}
                disabled={isSubmitting}
                className="flex items-center gap-2 px-6 py-2.5 bg-green-600 text-white rounded-lg font-semibold hover:bg-green-700 disabled:opacity-50"
              >
                {isSubmitting ? (
                  <><Loader size={18} className="animate-spin" /> Salvando...</>
                ) : (
                  <><Check size={18} /> Salvar Alterações</>
                )}
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default EditarCarro;

// src/components/CarroRegisto/FluxoRegisto.jsx
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Check, ChevronRight, HelpCircle, Loader, Save, X, AlertCircle } from 'lucide-react';
import InformacoesBasicas from './InformacoesBasicas';
import Especificacoes from './Especificacoes';
import Localizacao from './Localizacao';
import Caracteristicas from './Caracteristicas';
import ImagensUpload from './ImagensUpload';
import { salvarFluxoCarro } from '../../services/carroApiService';
import { useToast } from '../../Toast';

// ==================== CHAVE DO RASCUNHO ====================
const RASCUNHO_KEY = 'morabeza_rascunho_carro';

const FluxoRegisto = () => {
  const navigate = useNavigate();
  const { showToast } = useToast();

  const [fase, setFase] = useState(1);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [carroId, setCarroId] = useState(null);
  const [loading, setLoading] = useState(false);
  const [mostrarConfirmacaoRemover, setMostrarConfirmacaoRemover] = useState(false);
  const [usuarioId, setUsuarioId] = useState(null);

  const [informacoes, setInformacoes] = useState({
    titulo: '',
    marca: '',
    modelo: '',
    categoria_id: '',
    preco_dia: '',
    descricao: '',
    descricao_detalhada: ''
  });

  const [especificacoes, setEspecificacoes] = useState({
    ano: '',
    passageiros: 5,
    portas: 4,
    transmissao: 'Manual',
    combustivel: 'Gasolina',
    consumo: '',
    cor: '',
    quilometragem: 0
  });

  const [localizacao, setLocalizacao] = useState({
    local: '',
    cidade: '',
    ilha: ''
  });

  const [caracteristicas, setCaracteristicas] = useState([]);
  const [imagens, setImagens] = useState([]);

  // ==================== OBTER ID DO UTILIZADOR (JWT) ====================
  useEffect(() => {
    try {
      const token = localStorage.getItem('token') || localStorage.getItem('morabeza_token');
      if (token) {
        const base64Url = token.split('.')[1];
        const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
        const jsonPayload = decodeURIComponent(atob(base64).split('').map(c => {
          return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
        }).join(''));
        const parsed = JSON.parse(jsonPayload);
        const userData = parsed.data || parsed;
        if (userData?.id) {
          setUsuarioId(userData.id);
          return;
        }
      }

      // Fallback para as chaves tradicionais no LocalStorage
      const chaves = ['user', 'morabeza_user', 'morabeza_admin'];
      for (const chave of chaves) {
        const savedUser = localStorage.getItem(chave);
        if (savedUser) {
          const user = JSON.parse(savedUser);
          if (user?.id) {
            setUsuarioId(user.id);
            break;
          }
        }
      }
    } catch (e) {
      console.error('Erro ao obter ID do utilizador:', e);
    }
  }, []);

  // ==================== GUARDAR RASCUNHO ====================
  const guardarRascunhoLocal = () => {
    const dados = {
      fase,
      informacoes,
      especificacoes,
      localizacao,
      caracteristicas,
      imagens,
      carroId,
      atualizadoEm: new Date().toISOString()
    };

    try {
      localStorage.setItem(RASCUNHO_KEY, JSON.stringify(dados));
      showToast('Rascunho guardado localmente', 'success');
    } catch (err) {
      console.error('Erro ao guardar rascunho:', err);
      showToast('Não foi possível guardar o rascunho', 'error');
    }
  };

  // ==================== ABRIR CONFIRMAÇÃO ====================
  const pedirConfirmacaoRemoverRascunho = () => {
    setMostrarConfirmacaoRemover(true);
  };

  // ==================== CONFIRMAR E REMOVER ====================
  const confirmarRemoverRascunho = () => {
    localStorage.removeItem(RASCUNHO_KEY);

    setInformacoes({
      titulo: '',
      marca: '',
      modelo: '',
      categoria_id: '',
      preco_dia: '',
      descricao: '',
      descricao_detalhada: ''
    });
    setEspecificacoes({
      ano: '',
      passageiros: 5,
      portas: 4,
      transmissao: 'Manual',
      combustivel: 'Gasolina',
      consumo: '',
      cor: '',
      quilometragem: 0
    });
    setLocalizacao({
      local: '',
      cidade: '',
      ilha: ''
    });
    setCaracteristicas([]);
    setImagens([]);
    setFase(1);
    setCarroId(null);

    setMostrarConfirmacaoRemover(false);
    showToast('Rascunho removido', 'success');
  };

  // ==================== CARREGAR RASCUNHO ====================
  useEffect(() => {
    const carregarDados = async () => {
      setLoading(true);
      try {
        const raw = localStorage.getItem(RASCUNHO_KEY);
        if (raw) {
          const dados = JSON.parse(raw);

          if (dados.informacoes) setInformacoes(dados.informacoes);
          if (dados.especificacoes) setEspecificacoes(dados.especificacoes);
          if (dados.localizacao) setLocalizacao(dados.localizacao);
          if (dados.caracteristicas) setCaracteristicas(dados.caracteristicas);
          if (dados.imagens) setImagens(dados.imagens);
          if (dados.fase) setFase(dados.fase);
          if (dados.carroId) setCarroId(dados.carroId);

          showToast('Rascunho recuperado', 'info');
        }
      } catch (e) {
        console.warn('Erro ao carregar rascunho:', e);
        localStorage.removeItem(RASCUNHO_KEY);
      } finally {
        setLoading(false);
      }
    };
    carregarDados();
  }, []);

  // ==================== NAVEGAÇÃO ====================
  const handleNext = () => {
    if (fase === 1) {
      if (!informacoes.titulo) {
        showToast('O título do veículo é obrigatório', 'error');
        return;
      }
      if (!informacoes.preco_dia) {
        showToast('O preço por dia é obrigatório', 'error');
        return;
      }
    }

    if (fase === 3) {
      if (!localizacao.ilha) {
        showToast('A ilha é obrigatória', 'error');
        return;
      }
      if (!localizacao.local && !localizacao.cidade) {
        showToast('A localização/cidade é obrigatória', 'error');
        return;
      }
    }

    setFase(fase + 1);
    window.scrollTo(0, 0);
  };

  const handleBack = () => {
    if (fase > 1) {
      setFase(fase - 1);
      window.scrollTo(0, 0);
    } else {
      navigate(-1);
    }
  };

  // ==================== FINALIZAR ====================
  const handleFinalizar = async () => {
    if (isSubmitting) return;

    if (!usuarioId) {
      showToast('Utilizador não autenticado. Faça login novamente.', 'error');
      return;
    }

    setIsSubmitting(true);

    try {
      const dadosCompletos = {
        ...informacoes,
        ...especificacoes,
        usuario_id: usuarioId,
        localizacao: localizacao.local || localizacao.cidade || '',
        cidade: localizacao.cidade || localizacao.local || '',
        ilha: localizacao.ilha || '',
        caracteristicas: caracteristicas,
        imagens: imagens
      };

      console.log('📤 Enviando dados para criação:', dadosCompletos);

      const result = await salvarFluxoCarro(dadosCompletos, carroId);

      if (result.success) {
        localStorage.removeItem(RASCUNHO_KEY);
        showToast(result.message || 'Veículo registado com sucesso!', 'success');
        navigate('/carro-registo/meus');
      } else {
        showToast(result.message || 'Erro ao registar veículo', 'error');
      }
    } catch (error) {
      console.error('Erro:', error);
      showToast('Erro ao processar o registo. Tente novamente.', 'error');
    } finally {
      setIsSubmitting(false);
    }
  };

  // ==================== BARRA DE PROGRESSO ====================
  const renderProgressBar = () => {
    const fasesLista = ['Info', 'Especificações', 'Localização', 'Características', 'Fotos'];
    return (
      <div className="mb-6">
        <div className="flex items-center justify-between mb-2">
          {fasesLista.map((nome, index) => (
            <div key={index} className="flex-1 text-center">
              <div className={`text-xs font-medium ${fase > index + 1 ? 'text-[#006ce4]' : fase === index + 1 ? 'text-[#006ce4]' : 'text-gray-400'}`}>
                {nome}
              </div>
            </div>
          ))}
        </div>
        <div className="flex gap-1">
          {fasesLista.map((_, index) => (
            <div
              key={index}
              className={`h-1 flex-1 rounded-full ${
                fase > index + 1 ? 'bg-[#006ce4]' :
                fase === index + 1 ? 'bg-[#006ce4]' : 'bg-gray-200'
              }`}
            />
          ))}
        </div>
      </div>
    );
  };

  const temRascunho = !!localStorage.getItem(RASCUNHO_KEY);

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <Loader className="animate-spin mx-auto text-[#006ce4]" size={48} />
          <p className="mt-4 text-gray-600">Carregando dados...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <header className="bg-[#003580] text-white px-4 py-2 flex items-center justify-between shadow-sm">
        <div className="flex items-center">
          <div className="font-bold text-lg tracking-tight truncate max-w-[140px]"></div>
        </div>

        <div className="flex items-center gap-3">
          <div className="flex flex-col items-end">
            <div className="font-medium text-sm truncate max-w-[120px]">
              {informacoes.titulo || 'Novo Carro'}
            </div>
            <div className="text-[8px] opacity-80 mt-0.5">
              {fase === 1 && 'Básicas'}
              {fase === 2 && 'Especificações'}
              {fase === 3 && 'Localização'}
              {fase === 4 && `${caracteristicas.length} carac.`}
              {fase === 5 && `${imagens.length} fotos`}
            </div>
          </div>

          <div className="w-[1px] h-6 bg-blue-900"></div>

          <div className="flex items-center gap-1 cursor-pointer hover:underline">
            <HelpCircle size={16} />
          </div>
        </div>
      </header>

      <div className="max-w-4xl mx-auto px-4 py-8">
        {renderProgressBar()}

        <div className="bg-white rounded-lg shadow-md p-8">
          {fase === 1 && (
            <>
              <h1 className="text-2xl font-bold text-gray-900 mb-2">Informações do Veículo</h1>
              <p className="text-gray-600 mb-6">Preencha os dados básicos do carro.</p>
              <InformacoesBasicas
                dados={informacoes}
                onChange={setInformacoes}
                readOnly={false}
              />
            </>
          )}

          {fase === 2 && (
            <>
              <h1 className="text-2xl font-bold text-gray-900 mb-2">Especificações Técnicas</h1>
              <p className="text-gray-600 mb-6">Detalhes técnicos do veículo.</p>
              <Especificacoes
                dados={especificacoes}
                onChange={setEspecificacoes}
                readOnly={false}
              />
            </>
          )}

          {fase === 3 && (
            <>
              <h1 className="text-2xl font-bold text-gray-900 mb-2">Localização</h1>
              <p className="text-gray-600 mb-6">Onde o veículo está disponível?</p>
              <Localizacao
                dados={localizacao}
                onChange={setLocalizacao}
                readOnly={false}
              />
            </>
          )}

          {fase === 4 && (
            <>
              <h1 className="text-2xl font-bold text-gray-900 mb-2">Características</h1>
              <p className="text-gray-600 mb-6">Selecione os equipamentos do veículo.</p>
              <Caracteristicas
                items={caracteristicas}
                onChange={setCaracteristicas}
                readOnly={false}
              />
            </>
          )}

          {fase === 5 && (
            <>
              <h1 className="text-2xl font-bold text-gray-900 mb-2">Fotos do Veículo</h1>
              <p className="text-gray-600 mb-6">Adicione fotos para mostrar o carro.</p>
              <ImagensUpload
                imagens={imagens}
                onChange={setImagens}
                veiculoId={carroId}
                tipo="carro"
                readOnly={false}
              />
            </>
          )}

          {/* ==================== BOTÕES ==================== */}
          <div className="flex flex-wrap justify-between gap-3 mt-8 pt-6 border-t border-gray-100">
            <button
              onClick={handleBack}
              className="flex items-center gap-2 px-5 py-2.5 border border-gray-300 text-gray-700 rounded-lg font-semibold hover:bg-gray-50"
            >
              <ArrowLeft size={18} /> Voltar
            </button>

            <div className="flex flex-wrap gap-3">
              <button
                onClick={guardarRascunhoLocal}
                className="flex items-center gap-2 px-5 py-2.5 border border-gray-300 text-gray-700 rounded-lg font-semibold hover:bg-gray-50"
              >
                <Save size={18} />
                Guardar rascunho
              </button>

              {temRascunho && (
                <button
                  onClick={pedirConfirmacaoRemoverRascunho}
                  className="flex items-center gap-2 px-5 py-2.5 border border-red-300 text-red-600 rounded-lg font-semibold hover:bg-red-50"
                >
                  <X size={18} />
                  Remover rascunho
                </button>
              )}

              {fase < 5 && (
                <button
                  onClick={handleNext}
                  className="flex items-center gap-2 px-5 py-2.5 bg-[#006ce4] text-white rounded-lg font-semibold hover:bg-[#0053b3]"
                >
                  Continuar <ChevronRight size={18} />
                </button>
              )}

              {fase === 5 && (
                <button
                  onClick={handleFinalizar}
                  disabled={isSubmitting}
                  className="flex items-center gap-2 px-5 py-2.5 bg-green-600 text-white rounded-lg font-semibold hover:bg-green-700 disabled:opacity-50"
                >
                  {isSubmitting ? (
                    <>
                      <Loader size={18} className="animate-spin" />
                      A enviar...
                    </>
                  ) : (
                    <>
                      <Check size={18} />
                      Finalizar Registo
                    </>
                  )}
                </button>
              )}
            </div>
          </div>
        </div>
      </div>

      {mostrarConfirmacaoRemover && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/50">
          <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full p-6">
            <div className="flex items-start gap-4">
              <div className="flex-shrink-0 w-12 h-12 rounded-full bg-red-100 flex items-center justify-center">
                <AlertCircle className="text-red-600" size={24} />
              </div>
              <div className="flex-1">
                <h3 className="text-lg font-bold text-gray-900 mb-1">
                  Remover rascunho?
                </h3>
                <p className="text-gray-600 text-sm leading-relaxed">
                  Tens a certeza que queres apagar o rascunho? Esta ação não pode ser desfeita.
                </p>
              </div>
            </div>

            <div className="flex gap-3 mt-6">
              <button
                onClick={() => setMostrarConfirmacaoRemover(false)}
                className="flex-1 px-4 py-2.5 border border-gray-300 text-gray-700 rounded-xl font-semibold hover:bg-gray-50 transition-colors"
              >
                Cancelar
              </button>
              <button
                onClick={confirmarRemoverRascunho}
                className="flex-1 px-4 py-2.5 bg-red-600 text-white rounded-xl font-semibold hover:bg-red-700 transition-colors"
              >
                Sim, apagar
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default FluxoRegisto;

// src/components/CarroRegisto/ImagensUpload.jsx
// Mesma lógica do alojamento: upload direto via XHR + progresso + reordenar + foto principal

import React, { useState, useRef } from 'react';
import { Upload, X, Image, Star, Trash2, Move, AlertCircle, Check, Plus, Loader } from 'lucide-react';

const API_URL = 'https://welovepalop.com';

const ImagensUpload = ({
  // Nomes usados no alojamento:
  fotos,
  onFotosChange,
  onFotoPrincipalChange,
  // Compatibilidade com o FluxoRegisto de carros:
  imagens,
  onChange,
  veiculoId = null,

  maxFotos = 20,
  readOnly = false,
}) => {
  // Aceita ambos os nomes (fotos/onFotosChange OU imagens/onChange)
  const list = fotos ?? imagens ?? [];
  const setList = onFotosChange ?? onChange ?? (() => {});
  const isCarro = veiculoId !== undefined;

  const [isDragging, setIsDragging] = useState(false);
  const [erro, setErro] = useState('');
  const [uploading, setUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState({});
  const fileInputRef = useRef(null);
  const [dragIndex, setDragIndex] = useState(null);

  const fotoPrincipalId = list.find((f) => f.principal)?.id || list[0]?.id;

  // ---------------------------------------------------------------------
  // Upload (XHR para mostrar progresso)
  // ---------------------------------------------------------------------
  const uploadImagemParaServidor = (file, ordem) => {
    const formData = new FormData();
    formData.append('imagem', file);
    formData.append('ordem', ordem);

    // Backend do carro espera "carro_id"
    if (isCarro && veiculoId && veiculoId !== 'temp' && veiculoId !== null) {
      formData.append('carro_id', veiculoId);
    }

    const fileId = Date.now() + Math.random();
    setUploadProgress((prev) => ({ ...prev, [fileId]: 0 }));

    return new Promise((resolve, reject) => {
      const xhr = new XMLHttpRequest();

      xhr.upload.addEventListener('progress', (e) => {
        if (e.lengthComputable) {
          const percent = Math.round((e.loaded / e.total) * 100);
          setUploadProgress((prev) => ({ ...prev, [fileId]: percent }));
        }
      });

      xhr.onload = () => {
        setUploadProgress((prev) => {
          const next = { ...prev };
          delete next[fileId];
          return next;
        });

        if (xhr.status === 200) {
          try {
            const response = JSON.parse(xhr.responseText);
            if (response.success) {
              resolve(response.data);
            } else {
              reject(new Error(response.message || 'Erro no upload'));
            }
          } catch (e) {
            reject(new Error('Erro ao processar resposta do servidor'));
          }
        } else {
          reject(new Error(`Erro ${xhr.status}: ${xhr.statusText}`));
        }
      };

      xhr.onerror = () => {
        setUploadProgress((prev) => {
          const next = { ...prev };
          delete next[fileId];
          return next;
        });
        reject(new Error('Erro de conexão com o servidor'));
      };

      // Endpoint do CARRO
      xhr.open('POST', `${API_URL}/api/carro/upload_imagem.php`);
      xhr.send(formData);
    });
  };

  // ---------------------------------------------------------------------
  // Seleção de ficheiros
  // ---------------------------------------------------------------------
  const handleFileSelect = async (files) => {
    setErro('');
    const filesArray = Array.from(files);

    if (list.length + filesArray.length > maxFotos) {
      setErro(`Máximo de ${maxFotos} fotos permitidas. Já tens ${list.length}.`);
      return;
    }

    const invalidos = filesArray.filter((f) => {
      if (!f.type.startsWith('image/')) return true;
      if (f.size > 10 * 1024 * 1024) return true;
      return false;
    });

    if (invalidos.length > 0) {
      setErro('Apenas imagens até 10MB são permitidas');
      return;
    }

    setUploading(true);

    try {
      const novasFotos = [];

      for (let i = 0; i < filesArray.length; i++) {
        const file = filesArray[i];
        const ordem = list.length + i;

        try {
          const resultado = await uploadImagemParaServidor(file, ordem);

          novasFotos.push({
            id: resultado.id || Date.now() + Math.random(),
            url: resultado.url || resultado.caminho_url,
            caminho_url: resultado.caminho_url || resultado.url,
            path: resultado.path || resultado.caminho_url,
            nome: file.name,
            tamanho: file.size,
            principal: list.length === 0 && novasFotos.length === 0,
            ordem,
            uploadCompleto: true,
          });
        } catch (uploadError) {
          console.error('Erro no upload da imagem:', uploadError);
          setErro(`Erro ao fazer upload de ${file.name}: ${uploadError.message}`);
        }
      }

      if (novasFotos.length > 0) {
        const atualizadas = [...list, ...novasFotos];
        setList(atualizadas);

        if (!fotoPrincipalId && atualizadas.length > 0) {
          onFotoPrincipalChange?.(atualizadas[0].id);
        }
      }
    } catch (error) {
      console.error('Erro no processo de upload:', error);
      setErro(`Erro ao fazer upload: ${error.message}`);
    } finally {
      setUploading(false);
    }
  };

  // ---------------------------------------------------------------------
  // Drag & drop
  // ---------------------------------------------------------------------
  const handleDragOver = (e) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = (e) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const handleDrop = (e) => {
    e.preventDefault();
    setIsDragging(false);
    const files = e.dataTransfer.files;
    if (files.length > 0) handleFileSelect(files);
  };

  // ---------------------------------------------------------------------
  // Remover
  // ---------------------------------------------------------------------
  const handleRemoverFoto = async (id) => {
    const fotoRemover = list.find((f) => f.id === id);

    if (fotoRemover?.id && !readOnly && !fotoRemover.pendingUpload) {
      try {
        await fetch(`${API_URL}/api/carro/remover_imagem.php?id=${fotoRemover.id}`, {
          method: 'DELETE',
        });
      } catch (error) {
        console.error('Erro ao remover imagem do servidor:', error);
      }
    }

    const atualizadas = list.filter((f) => f.id !== id);

    if (fotoPrincipalId === id && atualizadas.length > 0) {
      const novaPrincipal = atualizadas[0];
      onFotoPrincipalChange?.(novaPrincipal.id);
      atualizadas[0].principal = true;
    }

    setList(atualizadas);
  };

  // ---------------------------------------------------------------------
  // Definir principal
  // ---------------------------------------------------------------------
  const handleDefinirPrincipal = async (id) => {
    const atualizadas = list.map((f) => ({
      ...f,
      principal: f.id === id,
    }));
    setList(atualizadas);
    onFotoPrincipalChange?.(id);

    // Se o backend tiver endpoint (opcional), tenta atualizar
    if (veiculoId && veiculoId !== 'temp') {
      try {
        await fetch(`${API_URL}/api/carro/definir_principal.php`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            carro_id: veiculoId,
            imagem_id: id,
          }),
        });
      } catch {
        // silencioso — nem todos os projetos têm este endpoint
      }
    }
  };

  // ---------------------------------------------------------------------
  // Reordenar (drag)
  // ---------------------------------------------------------------------
  const handleDragStart = (e, index) => {
    e.dataTransfer.effectAllowed = 'move';
    setDragIndex(index);
  };

  const handleDragOverItem = (e, index) => {
    e.preventDefault();
    if (dragIndex === null) return;

    if (dragIndex !== index) {
      const reordenadas = [...list];
      const [item] = reordenadas.splice(dragIndex, 1);
      reordenadas.splice(index, 0, item);

      reordenadas.forEach((foto, idx) => {
        foto.ordem = idx;
      });

      setList(reordenadas);
      setDragIndex(index);
    }
  };

  const handleDragEnd = () => {
    setDragIndex(null);
  };

  // ---------------------------------------------------------------------
  // Utilidades
  // ---------------------------------------------------------------------
  const formatFileSize = (bytes) => {
    if (!bytes) return '0 B';
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  };

  const hasUploading = Object.keys(uploadProgress).length > 0;

  return (
    <div className="space-y-6">
      {/* Área de upload */}
      {!readOnly && !uploading && (
        <div
          onDragOver={handleDragOver}
          onDragLeave={handleDragLeave}
          onDrop={handleDrop}
          onClick={() => fileInputRef.current?.click()}
          className={`border-2 border-dashed rounded-xl p-8 text-center cursor-pointer transition-all ${
            isDragging
              ? 'border-[#006ce4] bg-blue-50'
              : 'border-gray-300 hover:border-[#006ce4] hover:bg-gray-50'
          }`}
        >
          <input
            type="file"
            ref={fileInputRef}
            onChange={(e) => handleFileSelect(e.target.files)}
            accept="image/jpeg,image/png,image/webp,image/gif"
            multiple
            className="hidden"
          />

          <Upload className={`w-12 h-12 mx-auto mb-3 ${isDragging ? 'text-[#006ce4]' : 'text-gray-400'}`} />

          <p className="text-gray-600 mb-1">
            {isDragging ? 'Solte para adicionar as fotos' : 'Arraste e solte as suas fotos aqui'}
          </p>
          <p className="text-sm text-gray-400">ou clique para selecionar do computador</p>
          <p className="text-xs text-gray-400 mt-3">
            Formatos: JPG, PNG, WEBP, GIF | Máx 10MB por foto | Máx {maxFotos} fotos
          </p>
        </div>
      )}

      {/* Indicador de upload */}
      {uploading && (
        <div className="border-2 border-[#006ce4] bg-blue-50 rounded-xl p-6 text-center">
          <Loader className="w-8 h-8 mx-auto mb-3 text-[#006ce4] animate-spin" />
          <p className="text-gray-600">Fazendo upload das imagens...</p>
          {hasUploading && (
            <div className="mt-3 w-full bg-gray-200 rounded-full h-2">
              <div
                className="bg-[#006ce4] h-2 rounded-full transition-all duration-300"
                style={{ width: `${Object.values(uploadProgress)[0] || 0}%` }}
              />
            </div>
          )}
        </div>
      )}

      {/* Erro */}
      {erro && (
        <div className="bg-red-50 border border-red-200 rounded-lg p-3 flex items-center gap-2">
          <AlertCircle size={18} className="text-red-500" />
          <p className="text-sm text-red-600">{erro}</p>
          <button onClick={() => setErro('')} className="ml-auto text-red-400 hover:text-red-600">
            <X size={16} />
          </button>
        </div>
      )}

      {/* Galeria */}
      {list.length > 0 && (
        <div>
          <div className="flex justify-between items-center mb-4">
            <h3 className="font-semibold text-gray-900 flex items-center gap-2">
              <Image size={18} />
              Fotos do veículo ({list.length}/{maxFotos})
            </h3>
            {!readOnly && !uploading && list.length < maxFotos && (
              <button
                onClick={() => fileInputRef.current?.click()}
                className="text-sm text-[#006ce4] hover:underline flex items-center gap-1"
              >
                <Plus size={14} /> Adicionar mais
              </button>
            )}
          </div>

          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
            {list.map((foto, index) => {
              const imageUrl =
                foto.caminho_url || foto.url || foto.path || '';
              const fullUrl =
                imageUrl.startsWith('http') || imageUrl.startsWith('data:')
                  ? imageUrl
                  : `${API_URL}${imageUrl}`;

              return (
                <div
                  key={foto.id}
                  draggable={!readOnly && !uploading}
                  onDragStart={(e) => handleDragStart(e, index)}
                  onDragOver={(e) => handleDragOverItem(e, index)}
                  onDragEnd={handleDragEnd}
                  className={`relative group rounded-lg overflow-hidden border-2 transition-all ${
                    fotoPrincipalId === foto.id
                      ? 'border-[#006ce4] shadow-lg'
                      : 'border-gray-200 hover:border-gray-300'
                  } ${!readOnly ? 'cursor-move' : ''}`}
                >
                  {fotoPrincipalId === foto.id && (
                    <div className="absolute top-2 left-2 bg-[#006ce4] text-white text-xs px-2 py-0.5 rounded-full flex items-center gap-1 z-10">
                      <Star size={10} fill="white" /> Principal
                    </div>
                  )}

                  {foto.pendingUpload && (
                    <div className="absolute top-2 right-2 bg-yellow-500 text-white text-xs px-2 py-0.5 rounded-full z-10">
                      Pendente
                    </div>
                  )}

                  <img
                    src={fullUrl}
                    alt={foto.nome || 'Foto'}
                    className="w-full h-40 object-cover"
                    onError={(e) => {
                      e.target.src = 'https://via.placeholder.com/400x300?text=Erro+ao+carregar';
                    }}
                  />

                  <div className="absolute inset-0 bg-black bg-opacity-50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-2">
                    {!readOnly && !uploading && fotoPrincipalId !== foto.id && (
                      <button
                        onClick={() => handleDefinirPrincipal(foto.id)}
                        className="p-2 bg-white rounded-full text-gray-700 hover:bg-[#006ce4] hover:text-white transition-colors"
                        title="Definir como principal"
                      >
                        <Star size={16} />
                      </button>
                    )}

                    {!readOnly && !uploading && (
                      <button
                        onClick={() => handleRemoverFoto(foto.id)}
                        className="p-2 bg-white rounded-full text-red-500 hover:bg-red-500 hover:text-white transition-colors"
                        title="Remover foto"
                      >
                        <Trash2 size={16} />
                      </button>
                    )}

                    {!readOnly && !uploading && (
                      <div
                        className="p-2 bg-white rounded-full text-gray-400 cursor-move"
                        title="Arrastar para reordenar"
                      >
                        <Move size={16} />
                      </div>
                    )}
                  </div>

                  <div className="absolute bottom-0 left-0 right-0 bg-black bg-opacity-60 text-white text-xs p-1 px-2">
                    <span className="truncate block">{foto.nome || 'imagem'}</span>
                    <span className="text-gray-300 text-[10px]">
                      {formatFileSize(foto.tamanho)}
                    </span>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Dicas */}
      {!readOnly && list.length === 0 && !uploading && (
        <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4">
          <h4 className="font-semibold text-yellow-800 mb-2 text-sm flex items-center gap-2">
            <Image size={16} /> Dicas para fotos de sucesso:
          </h4>
          <ul className="text-yellow-700 text-sm space-y-1">
            <li>• 📸 Tire fotos com boa iluminação natural</li>
            <li>• 🚗 Mostre o exterior por vários ângulos</li>
            <li>• 🪑 Inclua fotos do interior e do painel</li>
            <li>• 🧳 Mostre a bagageira se for relevante</li>
            <li>• 📱 Use a câmara na horizontal para melhores resultados</li>
          </ul>
        </div>
      )}

      {/* Resumo */}
      {list.length > 0 && (
        <div className="bg-gray-50 rounded-lg p-4">
          <h4 className="font-semibold text-gray-700 mb-2 flex items-center gap-2">
            <Check size={16} className="text-green-500" />
            Resumo das fotos
          </h4>
          <div className="grid grid-cols-2 gap-3 text-sm">
            <div>
              <span className="text-gray-500">Total de fotos:</span>{' '}
              <span className="font-medium">{list.length}</span>
            </div>
            <div>
              <span className="text-gray-500">Foto principal:</span>{' '}
              <span className="font-medium text-[#006ce4]">
                {list.find((f) => f.id === fotoPrincipalId)?.nome || 'Definida'}
              </span>
            </div>
            <div>
              <span className="text-gray-500">Tamanho total:</span>{' '}
              <span className="font-medium">
                {formatFileSize(list.reduce((acc, f) => acc + (f.tamanho || 0), 0))}
              </span>
            </div>
            <div>
              <span className="text-gray-500">Ordem:</span>{' '}
              <span className="font-medium">Arraste para reordenar</span>
            </div>
          </div>
        </div>
      )}

      {/* Aviso de fotos insuficientes */}
      {!readOnly && list.length < 3 && !uploading && (
        <div className="bg-blue-50 border border-blue-200 rounded-lg p-3 flex items-start gap-2">
          <AlertCircle size={18} className="text-blue-500 shrink-0 mt-0.5" />
          <p className="text-sm text-blue-700">
            Recomendamos pelo menos <strong>3 fotos</strong> para atrair mais clientes.
            Anúncios com mais fotos recebem até 40% mais reservas!
          </p>
        </div>
      )}

      {/* Modo leitura vazio */}
      {readOnly && list.length === 0 && (
        <p className="text-gray-400 text-center py-8">Nenhuma foto adicionada</p>
      )}
    </div>
  );
};

export default ImagensUpload;

// src/components/ExperienciaRegisto/EditarExperiencia.jsx

import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { ArrowLeft, Check, ChevronRight, HelpCircle, User, Loader } from 'lucide-react';
import InformacoesBasicas from './InformacoesBasicas';
import Localizacao from './Localizacao';
import Categoria from './Categoria';
import Inclusoes from './Inclusoes';
import Requisitos from './Requisitos';
import Idiomas from './Idiomas';
import ImagensUpload from './ImagensUpload';
import Disponibilidade from './Disponibilidade';
import { buscarExperienciaParaEdicao, salvarFluxoExperiencia } from '../../services/experienciaApiService';
import { useToast } from '../../Toast';

const EditarExperiencia = () => {
  const navigate = useNavigate();
  const { id } = useParams();
  const { showToast } = useToast();

  const [fase, setFase] = useState(1);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [loading, setLoading] = useState(true);
  const [experienciaId, setExperienciaId] = useState(id ? parseInt(id) : null);
  const [usuarioId, setUsuarioId] = useState(null);

  const [informacoes, setInformacoes] = useState({});
  const [endereco, setEndereco] = useState({});
  const [categoria, setCategoria] = useState('aventura');
  const [inclusoes, setInclusoes] = useState([]);
  const [requisitos, setRequisitos] = useState([]);
  const [idiomas, setIdiomas] = useState([]);
  const [imagens, setImagens] = useState([]);
  const [disponibilidade, setDisponibilidade] = useState({ dias_disponiveis: [], horarios: [] });

  // ==================== OBTER ID DO UTILIZADOR (JWT) ====================
  useEffect(() => {
    try {
      const token = localStorage.getItem('token') || localStorage.getItem('morabeza_token');
      if (token) {
        const base64Url = token.split('.')[1];
        const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
        const jsonPayload = decodeURIComponent(atob(base64).split('').map(c => {
          return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
        }).join(''));
        const parsed = JSON.parse(jsonPayload);
        const userData = parsed.data || parsed;
        if (userData?.id) {
          setUsuarioId(userData.id);
          return;
        }
      }

      const chaves = ['user', 'morabeza_user', 'morabeza_admin'];
      for (const chave of chaves) {
        const raw = localStorage.getItem(chave);
        if (raw) {
          const user = JSON.parse(raw);
          const uid = user?.id || user?.sub || user?.user_id;
          if (uid) {
            setUsuarioId(uid);
            break;
          }
        }
      }
    } catch (e) {
      console.error('Erro ao obter ID do utilizador:', e);
    }
  }, []);

  // Carregar dados da experiência
  useEffect(() => {
    const carregarExperiencia = async () => {
      if (!experienciaId) return;

      setLoading(true);
      try {
        const result = await buscarExperienciaParaEdicao(experienciaId);

        if (result.success && result.data) {
          const data = result.data;

          setInformacoes({
            titulo: data.titulo || '',
            descricao_curta: data.descricao_curta || '',
            descricao_longa: data.descricao_longa || '',
            descricao_completa: data.descricao_completa || '',
            preco: data.preco || '',
            preco_crianca: data.preco_crianca || '',
            preco_bebe: data.preco_bebe || '',
            duracao: data.duracao || '2 horas',
            max_pessoas: data.max_pessoas || 10,
            min_pessoas: data.min_pessoas || 1,
            inclui_guia: data.inclui_guia == 1,
            inclui_transporte: data.inclui_transporte == 1,
            inclui_refeicao: data.inclui_refeicao == 1,
            ponto_encontro: data.ponto_encontro || ''
          });

          setEndereco({
            morada: data.endereco || '',
            cidade: data.localizacao || '',
            ilha: data.ilha || '',
            lat: data.latitude || null,
            lng: data.longitude || null
          });

          setCategoria(data.categoria || 'aventura');
          setInclusoes(data.inclusoes || []);
          setRequisitos(data.requisitos || []);
          setIdiomas(data.idiomas || []);
          setImagens(data.imagens || []);
          setDisponibilidade({
            dias_disponiveis: data.dias_disponiveis || [],
            horarios: data.horarios || []
          });
        } else {
          showToast('Erro ao carregar experiência', 'error');
          navigate('/experiencia-registo/meus');
        }
      } catch (error) {
        console.error('Erro:', error);
        showToast('Erro ao carregar dados da experiência', 'error');
        navigate('/experiencia-registo/meus');
      } finally {
        setLoading(false);
      }
    };

    carregarExperiencia();
  }, [experienciaId, navigate, showToast]);

  const handleNext = () => {
    setFase(fase + 1);
    window.scrollTo(0, 0);
  };

  const handleBack = () => {
    if (fase > 1) {
      setFase(fase - 1);
      window.scrollTo(0, 0);
    } else {
      navigate(-1);
    }
  };

  const handleFinalizar = async () => {
    if (isSubmitting) return;

    if (!usuarioId) {
      showToast('Utilizador não autenticado. Faça login novamente.', 'error');
      return;
    }

    setIsSubmitting(true);

    try {
      const dadosCompletos = {
        usuario_id: usuarioId,
        ...informacoes,
        endereco,
        categoria,
        inclusoes,
        requisitos,
        idiomas,
        imagens,
        ...disponibilidade
      };

      const result = await salvarFluxoExperiencia(dadosCompletos, experienciaId);

      if (result.success) {
        showToast(result.message || 'Alterações guardadas com sucesso!', 'success');
        navigate('/experiencia-registo/meus');
      } else {
        showToast(result.message || 'Erro ao guardar alterações', 'error');
      }
    } catch (error) {
      console.error('Erro:', error);
      showToast('Erro ao salvar as alterações. Tente novamente.', 'error');
    } finally {
      setIsSubmitting(false);
    }
  };

  const renderProgressBar = () => {
    const fasesLista = ['Info', 'Local', 'Categoria', 'Inclusões', 'Requisitos', 'Idiomas', 'Fotos', 'Disponibilidade'];
    return (
      <div className="mb-6">
        <div className="flex items-center justify-between mb-2">
          {fasesLista.map((nome, index) => (
            <div key={index} className="flex-1 text-center">
              <div className={`text-xs font-medium ${fase > index + 1 ? 'text-[#006ce4]' : fase === index + 1 ? 'text-[#006ce4]' : 'text-gray-400'}`}>
                {nome}
              </div>
            </div>
          ))}
        </div>
        <div className="flex gap-1">
          {fasesLista.map((_, index) => (
            <div key={index} className={`h-1 flex-1 rounded-full ${fase > index + 1 ? 'bg-[#006ce4]' : fase === index + 1 ? 'bg-[#006ce4]' : 'bg-gray-200'}`} />
          ))}
        </div>
      </div>
    );
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <Loader className="animate-spin mx-auto text-[#006ce4]" size={48} />
          <p className="mt-4 text-gray-600">Carregando experiência...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <header className="bg-[#003580] text-white h-[60px] flex items-center justify-between px-6 shadow-sm">
        <div className="font-bold text-2xl tracking-tight"></div>
        <div className="flex items-center gap-6 text-sm">
          <div className="text-right">
            <div className="font-medium">{informacoes.titulo || 'Editar Experiência'}</div>
            <div className="text-[10px] opacity-80">
              {fase === 1 && 'Informações básicas'}
              {fase === 2 && 'Localização'}
              {fase === 3 && 'Categoria'}
              {fase === 4 && `${inclusoes.length} inclusão(ões)`}
              {fase === 5 && `${requisitos.length} requisito(s)`}
              {fase === 6 && `${idiomas.length} idioma(s)`}
              {fase === 7 && `${imagens.length} foto(s)`}
              {fase === 8 && 'Disponibilidade'}
            </div>
          </div>
          <div className="w-[1px] h-8 bg-blue-900"></div>

          <div className="flex items-center gap-2 cursor-pointer hover:underline">
            <span>Ajuda</span> <HelpCircle size={18} />
          </div>

        </div>
      </header>

      <div className="max-w-4xl mx-auto px-4 py-8">
        {renderProgressBar()}

        <div className="bg-white rounded-lg shadow-md p-8">
          {fase === 1 && (
            <>
              <h1 className="text-2xl font-bold text-gray-900 mb-2">Editar Informações</h1>
              <p className="text-gray-600 mb-6">Atualize os dados da sua experiência.</p>
              <InformacoesBasicas
                dados={informacoes}
                onChange={setInformacoes}
                readOnly={false}
              />
            </>
          )}

          {fase === 2 && (
            <>
              <h1 className="text-2xl font-bold text-gray-900 mb-2">Editar Localização</h1>
              <p className="text-gray-600 mb-6">Atualize o local da experiência.</p>
              <Localizacao
                dados={endereco}
                onChange={setEndereco}
                readOnly={false}
                experienciaId={experienciaId}
              />
            </>
          )}

          {fase === 3 && (
            <>
              <h1 className="text-2xl font-bold text-gray-900 mb-2">Editar Categoria</h1>
              <p className="text-gray-600 mb-6">Atualize a categoria da experiência.</p>
              <Categoria
                value={categoria}
                onChange={setCategoria}
                readOnly={false}
              />
            </>
          )}

          {fase === 4 && (
            <>
              <h1 className="text-2xl font-bold text-gray-900 mb-2">Editar Inclusões</h1>
              <p className="text-gray-600 mb-6">Atualize os itens inclusos na experiência.</p>
              <Inclusoes
                items={inclusoes}
                onChange={setInclusoes}
                readOnly={false}
              />
            </>
          )}

          {fase === 5 && (
            <>
              <h1 className="text-2xl font-bold text-gray-900 mb-2">Editar Requisitos</h1>
              <p className="text-gray-600 mb-6">Atualize os requisitos da experiência.</p>
              <Requisitos
                items={requisitos}
                onChange={setRequisitos}
                readOnly={false}
              />
            </>
          )}

          {fase === 6 && (
            <>
              <h1 className="text-2xl font-bold text-gray-900 mb-2">Editar Idiomas</h1>
              <p className="text-gray-600 mb-6">Atualize os idiomas falados.</p>
              <Idiomas
                items={idiomas}
                onChange={setIdiomas}
                readOnly={false}
              />
            </>
          )}

          {fase === 7 && (
            <>
              <h1 className="text-2xl font-bold text-gray-900 mb-2">Editar Fotos</h1>
              <p className="text-gray-600 mb-6">Atualize as fotos da experiência.</p>
              <ImagensUpload
                imagens={imagens}
                onChange={setImagens}
                experienciaId={experienciaId}
                readOnly={false}
              />
            </>
          )}

          {fase === 8 && (
            <>
              <h1 className="text-2xl font-bold text-gray-900 mb-2">Editar Disponibilidade</h1>
              <p className="text-gray-600 mb-6">Atualize os dias e horários da experiência.</p>
              <Disponibilidade
                dados={disponibilidade}
                onChange={setDisponibilidade}
                readOnly={false}
              />
            </>
          )}

          <div className="flex justify-between gap-4 mt-8 pt-6 border-t border-gray-100">
            <button
              onClick={handleBack}
              className="flex items-center gap-2 px-6 py-2.5 border border-gray-300 text-gray-700 rounded-lg font-semibold hover:bg-gray-50"
            >
              <ArrowLeft size={18} /> Voltar
            </button>

            {fase < 8 && (
              <button
                onClick={handleNext}
                className="flex items-center gap-2 px-6 py-2.5 bg-[#006ce4] text-white rounded-lg font-semibold hover:bg-[#0053b3]"
              >
                Continuar <ChevronRight size={18} />
              </button>
            )}

            {fase === 8 && (
              <button
                onClick={handleFinalizar}
                disabled={isSubmitting}
                className="flex items-center gap-2 px-6 py-2.5 bg-green-600 text-white rounded-lg font-semibold hover:bg-green-700 disabled:opacity-50"
              >
                {isSubmitting ? (
                  <>
                    <Loader size={18} className="animate-spin" />
                    Salvando...
                  </>
                ) : (
                  <>
                    <Check size={18} />
                    Salvar Alterações
                  </>
                )}
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default EditarExperiencia;

// src/components/ExperienciaRegisto/FluxoRegisto.jsx
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Check, ChevronRight, HelpCircle, Loader, Save, X, AlertCircle } from 'lucide-react';
import InformacoesBasicas from './InformacoesBasicas';
import Localizacao from './Localizacao';
import Categoria from './Categoria';
import Inclusoes from './Inclusoes';
import Requisitos from './Requisitos';
import Idiomas from './Idiomas';
import ImagensUpload from './ImagensUpload';
import Disponibilidade from './Disponibilidade';
import { salvarFluxoExperiencia } from '../../services/experienciaApiService';
import { useToast } from '../../Toast';

// ==================== CHAVE DO RASCUNHO ====================
const RASCUNHO_KEY = 'morabeza_rascunho_experiencia';

const FluxoRegisto = () => {
  const navigate = useNavigate();
  const { showToast } = useToast();

  const [fase, setFase] = useState(1);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [experienciaId, setExperienciaId] = useState(null);
  const [loading, setLoading] = useState(false);
  const [mostrarConfirmacaoRemover, setMostrarConfirmacaoRemover] = useState(false);
  const [usuarioId, setUsuarioId] = useState(null);

  // Estados do formulário
  const [informacoes, setInformacoes] = useState({
    titulo: '',
    descricao_curta: '',
    descricao_longa: '',
    descricao_completa: '',
    preco: '',
    preco_crianca: '',
    preco_bebe: '',
    duracao: '2 horas',
    max_pessoas: 10,
    min_pessoas: 1,
    inclui_guia: true,
    inclui_transporte: false,
    inclui_refeicao: false,
    ponto_encontro: ''
  });

  const [endereco, setEndereco] = useState({
    morada: '',
    cidade: '',
    ilha: '',
    lat: null,
    lng: null
  });

  const [categoria, setCategoria] = useState('aventura');
  const [inclusoes, setInclusoes] = useState([]);
  const [requisitos, setRequisitos] = useState([]);
  const [idiomas, setIdiomas] = useState([]);
  const [imagens, setImagens] = useState([]);
  const [disponibilidade, setDisponibilidade] = useState({
    dias_disponiveis: [],
    horarios: []
  });

  // ==================== OBTER ID DO UTILIZADOR (JWT) ====================
  useEffect(() => {
    try {
      const token = localStorage.getItem('token') || localStorage.getItem('morabeza_token');
      if (token) {
        const base64Url = token.split('.')[1];
        const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
        const jsonPayload = decodeURIComponent(atob(base64).split('').map(c => {
          return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
        }).join(''));
        const parsed = JSON.parse(jsonPayload);
        const userData = parsed.data || parsed;
        if (userData?.id) {
          setUsuarioId(userData.id);
          return;
        }
      }

      const chaves = ['user', 'morabeza_user', 'morabeza_admin'];
      for (const chave of chaves) {
        const raw = localStorage.getItem(chave);
        if (raw) {
          const user = JSON.parse(raw);
          const uid = user?.id || user?.sub || user?.user_id;
          if (uid) {
            setUsuarioId(uid);
            break;
          }
        }
      }
    } catch (e) {
      console.error('Erro ao obter ID do utilizador:', e);
    }
  }, []);

  // ==================== GUARDAR RASCUNHO ====================
  const guardarRascunhoLocal = () => {
    const dados = {
      fase,
      informacoes,
      endereco,
      categoria,
      inclusoes,
      requisitos,
      idiomas,
      imagens,
      disponibilidade,
      experienciaId,
      atualizadoEm: new Date().toISOString()
    };

    try {
      localStorage.setItem(RASCUNHO_KEY, JSON.stringify(dados));
      showToast('Rascunho guardado localmente', 'success');
    } catch (err) {
      console.error('Erro ao guardar rascunho:', err);
      showToast('Não foi possível guardar o rascunho', 'error');
    }
  };

  // ==================== ABRIR CONFIRMAÇÃO ====================
  const pedirConfirmacaoRemoverRascunho = () => {
    setMostrarConfirmacaoRemover(true);
  };

  // ==================== CONFIRMAR E REMOVER ====================
  const confirmarRemoverRascunho = () => {
    localStorage.removeItem(RASCUNHO_KEY);

    setInformacoes({
      titulo: '',
      descricao_curta: '',
      descricao_longa: '',
      descricao_completa: '',
      preco: '',
      preco_crianca: '',
      preco_bebe: '',
      duracao: '2 horas',
      max_pessoas: 10,
      min_pessoas: 1,
      inclui_guia: true,
      inclui_transporte: false,
      inclui_refeicao: false,
      ponto_encontro: ''
    });
    setEndereco({
      morada: '',
      cidade: '',
      ilha: '',
      lat: null,
      lng: null
    });
    setCategoria('aventura');
    setInclusoes([]);
    setRequisitos([]);
    setIdiomas([]);
    setImagens([]);
    setDisponibilidade({
      dias_disponiveis: [],
      horarios: []
    });
    setFase(1);
    setExperienciaId(null);

    setMostrarConfirmacaoRemover(false);
    showToast('Rascunho removido', 'success');
  };

  // ==================== CARREGAR RASCUNHO ====================
  useEffect(() => {
    const carregarDados = async () => {
      setLoading(true);
      try {
        const raw = localStorage.getItem(RASCUNHO_KEY);
        if (raw) {
          const dados = JSON.parse(raw);

          if (dados.informacoes) setInformacoes(dados.informacoes);
          if (dados.endereco) setEndereco(dados.endereco);
          if (dados.categoria) setCategoria(dados.categoria);
          if (dados.inclusoes) setInclusoes(dados.inclusoes);
          if (dados.requisitos) setRequisitos(dados.requisitos);
          if (dados.idiomas) setIdiomas(dados.idiomas);
          if (dados.imagens) setImagens(dados.imagens);
          if (dados.disponibilidade) setDisponibilidade(dados.disponibilidade);
          if (dados.fase) setFase(dados.fase);
          if (dados.experienciaId) setExperienciaId(dados.experienciaId);

          showToast('Rascunho recuperado', 'info');
        }
      } catch (e) {
        console.warn('Erro ao carregar rascunho:', e);
        localStorage.removeItem(RASCUNHO_KEY);
      } finally {
        setLoading(false);
      }
    };

    carregarDados();
  }, []);

  // ==================== NAVEGAÇÃO ====================
  const handleNext = () => {
    if (fase === 1) {
      if (!informacoes.titulo || !informacoes.titulo.trim()) {
        showToast('O título da experiência é obrigatório', 'error');
        return;
      }
      if (!informacoes.preco || Number(informacoes.preco) <= 0) {
        showToast('O preço é obrigatório', 'error');
        return;
      }
    }

    if (fase === 2) {
      if (!endereco.ilha) {
        showToast('A ilha é obrigatória', 'error');
        return;
      }
    }

    setFase(fase + 1);
    window.scrollTo(0, 0);
  };

  const handleBack = () => {
    if (fase > 1) {
      setFase(fase - 1);
      window.scrollTo(0, 0);
    } else {
      navigate(-1);
    }
  };

  // ==================== FINALIZAR ====================
  const handleFinalizar = async () => {
    if (isSubmitting) return;

    if (!usuarioId) {
      showToast('Utilizador não autenticado. Faça login novamente.', 'error');
      return;
    }

    setIsSubmitting(true);

    try {
      const dadosCompletos = {
        usuario_id: usuarioId,
        ...informacoes,
        endereco,
        categoria,
        inclusoes,
        requisitos,
        idiomas,
        imagens: imagens.map(img => ({
          url: img.caminho_url || img.url,
          principal: img.principal || false
        })),
        ...disponibilidade
      };

      console.log('📤 Enviando dados:', dadosCompletos);

      const result = await salvarFluxoExperiencia(dadosCompletos, experienciaId);

      if (result.success) {
        localStorage.removeItem(RASCUNHO_KEY);
        showToast(result.message || 'Experiência registada com sucesso!', 'success');
        navigate('/experiencia-registo/meus');
      } else {
        showToast(result.message || 'Erro ao registar experiência', 'error');
      }
    } catch (error) {
      console.error('Erro:', error);
      showToast('Erro ao processar o registo. Tente novamente.', 'error');
    } finally {
      setIsSubmitting(false);
    }
  };

  // ==================== BARRA DE PROGRESSO ====================
  const renderProgressBar = () => {
    const fasesLista = ['Info', 'Local', 'Categoria', 'Inclusões', 'Requisitos', 'Idiomas', 'Fotos', 'Disponibilidade'];
    return (
      <div className="mb-6">
        <div className="flex items-center justify-between mb-2">
          {fasesLista.map((nome, index) => (
            <div key={index} className="flex-1 text-center">
              <div className={`text-xs font-medium ${fase > index + 1 ? 'text-[#006ce4]' : fase === index + 1 ? 'text-[#006ce4]' : 'text-gray-400'}`}>
                {nome}
              </div>
            </div>
          ))}
        </div>
        <div className="flex gap-1">
          {fasesLista.map((_, index) => (
            <div
              key={index}
              className={`h-1 flex-1 rounded-full ${
                fase > index + 1 ? 'bg-[#006ce4]' :
                fase === index + 1 ? 'bg-[#006ce4]' : 'bg-gray-200'
              }`}
            />
          ))}
        </div>
      </div>
    );
  };

  const temRascunho = !!localStorage.getItem(RASCUNHO_KEY);

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <Loader className="animate-spin mx-auto text-[#006ce4]" size={48} />
          <p className="mt-4 text-gray-600">Carregando dados da experiência...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <header className="bg-[#003580] text-white px-3 py-2 flex items-center justify-between shadow-sm">
        <div className="flex items-center">
          <div className="font-bold text-base tracking-tight truncate max-w-[130px]"></div>
        </div>

        <div className="flex items-center gap-2">
          <div className="flex flex-col items-end">
            <div className="font-medium text-xs truncate max-w-[90px]">
              {informacoes.titulo || 'Nova Exp.'}
            </div>
            <div className="text-[7px] opacity-80 mt-0.5">
              {fase === 1 && 'Básicas'}
              {fase === 2 && 'Localização'}
              {fase === 3 && 'Categoria'}
              {fase === 4 && `${inclusoes.length} incl.`}
              {fase === 5 && `${requisitos.length} req.`}
              {fase === 6 && `${idiomas.length} idiomas`}
              {fase === 7 && `${imagens.length} fotos`}
              {fase === 8 && 'Disponib.'}
            </div>
          </div>

          <div className="w-[1px] h-5 bg-blue-900"></div>

          <div className="flex items-center cursor-pointer hover:opacity-80">
            <HelpCircle size={15} />
          </div>
        </div>
      </header>

      <div className="max-w-4xl mx-auto px-4 py-8">
        {renderProgressBar()}

        <div className="bg-white rounded-lg shadow-md p-8">
          {/* FASE 1 - Informações Básicas */}
          {fase === 1 && (
            <>
              <h1 className="text-2xl font-bold text-gray-900 mb-2">Informações da Experiência</h1>
              <p className="text-gray-600 mb-6">Preencha os dados principais da sua experiência.</p>
              <InformacoesBasicas
                dados={informacoes}
                onChange={setInformacoes}
                readOnly={false}
              />
            </>
          )}

          {/* FASE 2 - Localização */}
          {fase === 2 && (
            <>
              <h1 className="text-2xl font-bold text-gray-900 mb-2">Onde acontece?</h1>
              <p className="text-gray-600 mb-6">Informe o local da experiência.</p>
              <Localizacao
                dados={endereco}
                onChange={setEndereco}
                readOnly={false}
                experienciaId={experienciaId}
              />
            </>
          )}

          {/* FASE 3 - Categoria */}
          {fase === 3 && (
            <>
              <h1 className="text-2xl font-bold text-gray-900 mb-2">Categoria</h1>
              <p className="text-gray-600 mb-6">Selecione a categoria da experiência.</p>
              <Categoria
                value={categoria}
                onChange={setCategoria}
                readOnly={false}
              />
            </>
          )}

          {/* FASE 4 - Inclusões */}
          {fase === 4 && (
            <>
              <h1 className="text-2xl font-bold text-gray-900 mb-2">O que está incluído?</h1>
              <p className="text-gray-600 mb-6">Liste os itens inclusos na experiência.</p>
              <Inclusoes
                items={inclusoes}
                onChange={setInclusoes}
                readOnly={false}
              />
            </>
          )}

          {/* FASE 5 - Requisitos */}
          {fase === 5 && (
            <>
              <h1 className="text-2xl font-bold text-gray-900 mb-2">Requisitos</h1>
              <p className="text-gray-600 mb-6">O que os participantes precisam saber?</p>
              <Requisitos
                items={requisitos}
                onChange={setRequisitos}
                readOnly={false}
              />
            </>
          )}

          {/* FASE 6 - Idiomas */}
          {fase === 6 && (
            <>
              <h1 className="text-2xl font-bold text-gray-900 mb-2">Idiomas</h1>
              <p className="text-gray-600 mb-6">Quais idiomas são falados?</p>
              <Idiomas
                items={idiomas}
                onChange={setIdiomas}
                readOnly={false}
              />
            </>
          )}

          {/* FASE 7 - Fotos */}
          {fase === 7 && (
            <>
              <h1 className="text-2xl font-bold text-gray-900 mb-2">Fotos da Experiência</h1>
              <p className="text-gray-600 mb-6">Adicione fotos para mostrar sua experiência.</p>
              <ImagensUpload
                imagens={imagens}
                onChange={setImagens}
                experienciaId={experienciaId}
                readOnly={false}
              />
            </>
          )}

          {/* FASE 8 - Disponibilidade */}
          {fase === 8 && (
            <>
              <h1 className="text-2xl font-bold text-gray-900 mb-2">Disponibilidade</h1>
              <p className="text-gray-600 mb-6">Defina os dias e horários da experiência.</p>
              <Disponibilidade
                dados={disponibilidade}
                onChange={setDisponibilidade}
                readOnly={false}
              />
            </>
          )}

          {/* ==================== BOTÕES ==================== */}
          <div className="flex flex-wrap justify-between gap-3 mt-8 pt-6 border-t border-gray-100">
            <button
              onClick={handleBack}
              className="flex items-center gap-2 px-5 py-2.5 border border-gray-300 text-gray-700 rounded-lg font-semibold hover:bg-gray-50"
            >
              <ArrowLeft size={18} /> Voltar
            </button>

            <div className="flex flex-wrap gap-3">
              {/* Guardar rascunho */}
              <button
                onClick={guardarRascunhoLocal}
                className="flex items-center gap-2 px-5 py-2.5 border border-gray-300 text-gray-700 rounded-lg font-semibold hover:bg-gray-50"
              >
                <Save size={18} />
                Guardar rascunho
              </button>

              {/* Remover rascunho */}
              {temRascunho && (
                <button
                  onClick={pedirConfirmacaoRemoverRascunho}
                  className="flex items-center gap-2 px-5 py-2.5 border border-red-300 text-red-600 rounded-lg font-semibold hover:bg-red-50"
                >
                  <X size={18} />
                  Remover rascunho
                </button>
              )}

              {fase < 8 && (
                <button
                  onClick={handleNext}
                  className="flex items-center gap-2 px-5 py-2.5 bg-[#006ce4] text-white rounded-lg font-semibold hover:bg-[#0053b3]"
                >
                  Continuar <ChevronRight size={18} />
                </button>
              )}

              {fase === 8 && (
                <button
                  onClick={handleFinalizar}
                  disabled={isSubmitting}
                  className="flex items-center gap-2 px-5 py-2.5 bg-green-600 text-white rounded-lg font-semibold hover:bg-green-700 disabled:opacity-50"
                >
                  {isSubmitting ? (
                    <>
                      <Loader size={18} className="animate-spin" />
                      A enviar...
                    </>
                  ) : (
                    <>
                      <Check size={18} />
                      Enviar para análise
                    </>
                  )}
                </button>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* ========== CAIXA DE CONFIRMAÇÃO REMOVER RASCUNHO ========== */}
      {mostrarConfirmacaoRemover && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/50">
          <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full p-6">
