              <AlertCircle size={16} className="text-orange-500" />
              <span className="flex-1 text-sm text-gray-700">{item.requisito}</span>
              {!readOnly && (
                <button
                  type="button"
                  onClick={() => removerRequisito(item.id)}
                  className="p-1 text-red-500 hover:bg-red-100 rounded"
                >
                  <Trash2 size={16} />
                </button>
              )}
            </div>
          ))}
        </div>
      )}
      
      {/* Botão adicionar */}
      {!readOnly && (
