// src/components/Navbar.jsx
import React, { useState, useEffect, useRef } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { Menu, X, Home, Car, Palmtree, Globe, ChevronDown, Info } from 'lucide-react';
import UserDropdown from './UserDropdown';
import { useTranslation } from 'react-i18next';

const Navbar = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [user, setUser] = useState(null);
  const [userDropdownOpen, setUserDropdownOpen] = useState(false);
  const [langDropdownOpen, setLangDropdownOpen] = useState(false);
  
  const { i18n, t } = useTranslation();
  const location = useLocation();
  const langRef = useRef(null);

  const paginasComHero = ['/', '/experiencias', '/alojamentos', '/carros', '/sobre'];
  const isHeroPage = paginasComHero.includes(location.pathname);

  // 🔑 Função segura para verificar se existe um token JWT válido
  const verificarUtilizadorLogado = () => {
    const token = localStorage.getItem('token') || localStorage.getItem('morabeza_token');
    if (!token) return null;
    try {
      const base64Url = token.split('.')[1];
      const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
      const jsonPayload = decodeURIComponent(atob(base64).split('').map(c => {
        return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
      }).join(''));
      return JSON.parse(jsonPayload).data || { logged: true };
    } catch (e) {
      return null;
    }
  };

  useEffect(() => {
    setUser(verificarUtilizadorLogado());

    const handleClickOutside = (event) => {
      if (langRef.current && !langRef.current.contains(event.target)) {
        setLangDropdownOpen(false);
      }
    };
    
    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);

  // Ouvir eventos de atualização do utilizador/token
  useEffect(() => {
    const atualizarUser = () => {
      setUser(verificarUtilizadorLogado());
    };

    window.addEventListener('userUpdated', atualizarUser);
    window.addEventListener('storage', atualizarUser);
    return () => {
      window.removeEventListener('userUpdated', atualizarUser);
      window.removeEventListener('storage', atualizarUser);
    };
  }, []);

  const handleLogout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('morabeza_token');
    setUser(null);
    setUserDropdownOpen(false);
    window.location.replace('/');
  };

  const changeLanguage = (lng) => {
    i18n.changeLanguage(lng);
    setLangDropdownOpen(false);
  };

  const navLinks = [
    { name: t('menu_inicio'), icon: <Home size={18} />, path: '/' },
    { name: t('menu_sobre', 'Sobre Nós'), icon: <Info size={18} />, path: '/sobre' },
    { name: t('menu_alojamentos'), icon: <Globe size={18} />, path: '/alojamentos' },
    { name: t('menu_carros'), icon: <Car size={18} />, path: '/carros' },
    { name: t('menu_experiencias'), icon: <Palmtree size={18} />, path: '/experiencias' },
  ];

  const languages = [
    { code: 'pt', label: 'Português' },
    { code: 'en', label: 'English' },
    { code: 'fr', label: 'Français' },
    { code: 'es', label: 'Español' },
    { code: 'de', label: 'Deutsch' },
    { code: 'ir', label: 'Italiano' },
    { code: 'cv', label: 'Cabo-verdiano' },
  ];

  const getNavbarClasses = () => {
    if (isHeroPage) {
      return "absolute top-0 left-0 bg-transparent text-white";
    } else {
      return "relative bg-white shadow-md text-gray-900 border-b border-gray-100";
    }
  };

  return (
    <>
      <nav className={`w-full z-[100] px-6 md:px-12 py-5 flex justify-between items-center transition-all duration-300 ${getNavbarClasses()}`}>
        
        <Link to="/" className="flex items-center min-w-[150px]">
          <img 
            src="https://res.cloudinary.com/dpsrmzvsl/image/upload/v1781877448/logo_morabeza_r1s2ne.png" 
            alt="Morabeza Stay Logo" 
            className="h-10 w-auto object-contain"
          />
        </Link>

        {/* MENU DESKTOP */}
        <div className={`hidden lg:flex items-center gap-8 text-[10px] font-black uppercase tracking-[0.2em] absolute left-1/2 -translate-x-1/2 transition-colors ${
          isHeroPage ? "text-white" : "text-gray-600"
        }`}>
          {navLinks.map((link, idx) => (
            <Link 
              key={idx} 
              to={link.path} 
              className="hover:text-blue-400 transition-all opacity-80 hover:opacity-100 relative group"
            >
              {link.name}
              <span className="absolute -bottom-1 left-0 w-0 h-0.5 bg-blue-400 transition-all group-hover:w-full"></span>
            </Link>
          ))}
        </div>

        <div className="flex items-center gap-4 min-w-[150px] justify-end">
          
          <div className="relative hidden sm:block" ref={langRef}>
            <button 
              onClick={() => setLangDropdownOpen(!langDropdownOpen)}
              className={`flex items-center gap-1 text-[10px] font-black uppercase tracking-widest hover:opacity-100 opacity-80 transition-all ${
                isHeroPage ? "text-white" : "text-gray-700"
              }`}
            >
              {i18n.language.substring(0, 2)}
              <ChevronDown size={12} className={`transition-transform ${langDropdownOpen ? 'rotate-180' : ''}`} />
            </button>

            {langDropdownOpen && (
              <div className="absolute right-0 mt-3 w-40 bg-white rounded-xl shadow-xl border border-gray-100 py-2 overflow-hidden z-50">
                {languages.map((lng) => (
                  <button
                    key={lng.code}
                    onClick={() => changeLanguage(lng.code)}
                    className={`w-full text-left px-4 py-2 text-[10px] font-bold uppercase tracking-widest hover:bg-blue-50 transition-colors ${
                      i18n.language === lng.code ? "text-blue-600 bg-blue-50/50" : "text-gray-600"
                    }`}
                  >
                    {lng.label}
                  </button>
                ))}
              </div>
            )}
          </div>

          {/* BOTÃO DE REGISTAR PROPRIEDADE OU USER DROPDOWN */}
          {!user ? (
            <Link 
              to="/login"
              className={`px-4 py-2 text-[11px] md:text-sm font-bold rounded-lg transition-all shadow-sm whitespace-nowrap ${
                isHeroPage 
                  ? "bg-white text-[#003580] hover:bg-gray-100" 
                  : "bg-[#003580] text-white hover:bg-[#002560]"
              }`}
            >
              {t('registe_sua_propriedade')}
            </Link>
          ) : (
            <UserDropdown 
              user={user} 
              onLogout={handleLogout} 
              isOpen={userDropdownOpen} 
              setIsOpen={setUserDropdownOpen} 
            />
          )}

          <button 
            onClick={() => setIsOpen(true)} 
            className={`flex items-center gap-2 border p-2 rounded-full transition-all ${
              isHeroPage 
                ? "bg-white/10 border-white/30 text-white hover:bg-white/20" 
                : "bg-gray-100 border-gray-200 text-gray-900 hover:bg-gray-200"
            }`}
          >
            <Menu size={20} />
          </button>
        </div>
      </nav>

      {/* Sidebar de navegação móvel */}
      <div className={`fixed top-0 right-0 h-full w-[300px] bg-white z-[110] shadow-2xl transform transition-transform duration-500 ease-in-out ${isOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="p-8 flex justify-between items-center border-b border-gray-50">
          <span className="text-xl font-bold uppercase text-gray-800 tracking-tighter">Menu</span>
          <button onClick={() => setIsOpen(false)} className="p-2 hover:bg-gray-100 rounded-full text-gray-400">
            <X size={24} />
          </button>
        </div>

        <div className="p-6 space-y-2 text-left">
          {navLinks.map((link, index) => (
            <Link 
              key={index} 
              to={link.path} 
              onClick={() => setIsOpen(false)} 
              className="flex items-center gap-4 p-4 hover:bg-blue-50 text-gray-700 rounded-2xl transition-all group"
            >
              <span className="text-gray-400 group-hover:text-blue-500 transition-colors">{link.icon}</span>
              <span className="font-bold text-sm uppercase tracking-wider">{link.name}</span>
            </Link>
          ))}
          
          <div className="pt-6 mt-6 border-t border-gray-100">
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] mb-4 px-4">Idioma</p>
            <div className="grid grid-cols-2 gap-2 px-2">
              {languages.map((lng) => (
                <button 
                  key={lng.code}
                  onClick={() => { changeLanguage(lng.code); setIsOpen(false); }}
                  className={`py-3 text-[10px] font-bold rounded-xl border transition-all ${
                    i18n.language === lng.code ? "bg-blue-600 text-white border-blue-600" : "bg-gray-50 text-gray-500 border-gray-100 hover:bg-gray-100"
                  }`}
                >
                  {lng.label}
                </button>
              ))}
            </div>
          </div>
        </div>
      </div>
    </>
  );
};

export default Navbar;

// src/components/UserDropdown.jsx
import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { Home, Car, Compass, Heart, User, LogOut, LayoutDashboard, Calendar } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { useFavoritos } from '../hooks/useFavoritos';

const UserDropdown = ({ user, onLogout, isOpen, setIsOpen }) => {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const { totalFavoritos: totalFromHook, recarregar } = useFavoritos();
  const [totalFavoritos, setTotalFavoritos] = useState(0);
  const [sessionUser, setSessionUser] = useState(user);

  // 🔑 Função ultra-abrangente para extrair dados e procurar a foto em qualquer lugar possível
  const obterDadosSessao = useCallback(() => {
    try {
      // 1. Verificar se foi passado via props diretamente e tem foto
      if (user) {
        const f = user.foto || user.picture || user.avatar || user.image || user.user_metadata?.avatar_url || user.data?.picture;
        if (f) return user;
      }

      // 2. Tenta extrair do token JWT no localStorage
      const token = localStorage.getItem('token') || localStorage.getItem('morabeza_token');
      let tokenData = null;
      if (token) {
        const base64Url = token.split('.')[1];
        const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
        const jsonPayload = decodeURIComponent(atob(base64).split('').map(c => {
          return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
        }).join(''));
        const parsed = JSON.parse(jsonPayload);
        tokenData = parsed.data || parsed;
      }

      // 3. Procura nas chaves de utilizador do localStorage
      let localData = null;
      const chaves = ['user', 'morabeza_user', 'morabeza_admin', 'usuario', 'dados_utilizador'];
      for (const chave of chaves) {
        const raw = localStorage.getItem(chave);
        if (raw) {
          try {
            const parsedUser = JSON.parse(raw);
            if (parsedUser) {
              localData = parsedUser.data || parsedUser;
              break;
            }
          } catch (err) {
            // Ignorar erros de parse se não for JSON válido
          }
        }
      }

      // Funde tudo priorizando quem tem uma foto válida guardada
      const merged = { ...(tokenData || {}), ...(localData || {}), ...(user || {}) };
      return merged;
    } catch (e) {
      console.error('Erro ao ler dados da sessão:', e);
    }
    return user || null;
  }, [user]);

  // Sincronizar sessão em tempo real
  useEffect(() => {
    setSessionUser(obterDadosSessao());

    const atualizarSessaoEmTempoReal = () => {
      setSessionUser(obterDadosSessao());
    };

    window.addEventListener('storage', atualizarSessaoEmTempoReal);
    window.addEventListener('userUpdated', atualizarSessaoEmTempoReal);
    window.addEventListener('utilizadorAtualizado', atualizarSessaoEmTempoReal);

    return () => {
      window.removeEventListener('storage', atualizarSessaoEmTempoReal);
      window.removeEventListener('userUpdated', atualizarSessaoEmTempoReal);
      window.removeEventListener('utilizadorAtualizado', atualizarSessaoEmTempoReal);
    };
  }, [user, obterDadosSessao]);

  const usuarioAtual = sessionUser || obterDadosSessao();

  // Estados das roles
  const [canManageAlojamento, setCanManageAlojamento] = useState(false);
  const [canManageCarros, setCanManageCarros] = useState(false);
  const [canManageExperiencias, setCanManageExperiencias] = useState(false);
  const [canAccessDashboard, setCanAccessDashboard] = useState(false);

  // Buscar roles do utilizador de forma segura
  useEffect(() => {
    const fetchUserRoles = async () => {
      const userId = usuarioAtual?.id;
      if (!userId) return;
      
      try {
        const response = await fetch(`https://welovepalop.com/api/usuarios/listar_roles.php?usuario_id=${userId}`);
        const data = await response.json();
        
        if (data.success && data.roles) {
          const isAnfitrionApproved = data.roles.some(r => r.name === 'anfitrion' && r.status === 'approved');
          const isGuiaApproved = data.roles.some(r => r.name === 'guia_experiencias' && r.status === 'approved');
          const isProprietarioVeiculosApproved = data.roles.some(r => r.name === 'proprietario_veiculos' && r.status === 'approved');
          
          const hasAnyRole = isAnfitrionApproved || isGuiaApproved || isProprietarioVeiculosApproved;
          
          setCanManageAlojamento(isAnfitrionApproved);
          setCanManageCarros(isProprietarioVeiculosApproved);
          setCanManageExperiencias(isGuiaApproved);
          setCanAccessDashboard(hasAnyRole);
        }
      } catch (error) {
        console.error('Erro ao buscar roles do usuário:', error);
      }
    };

    fetchUserRoles();
  }, [usuarioAtual?.id]);

  useEffect(() => {
    setTotalFavoritos(totalFromHook);
  }, [totalFromHook]);

  useEffect(() => {
    const handleUpdate = (event) => {
      if (event.detail?.total !== undefined) {
        setTotalFavoritos(event.detail.total);
      } else {
        recarregar();
      }
    };
    
    window.addEventListener('favoritosAtualizados', handleUpdate);
    return () => {
      window.removeEventListener('favoritosAtualizados', handleUpdate);
    };
  }, [recarregar]);

  const handleNavigation = (path) => {
    setIsOpen(false);
    navigate(path);
  };

  // Se NÃO HOUVER UTILIZADOR nem TOKEN VÁLIDO
  if (!usuarioAtual || (!usuarioAtual.id && !usuarioAtual.email)) {
    return (
      <button 
        onClick={() => navigate('/login')}
        className="flex items-center justify-center bg-white/10 hover:bg-white/20 backdrop-blur-md border border-white/30 px-4 py-2 rounded-lg transition-all shadow-sm text-white font-medium text-sm"
      >
        Regista a sua Propriedade
      </button>
    );
  }

  const emailExibicao = usuarioAtual.email || usuarioAtual.correo || 'utilizador@morabezastay.com';
  
  // 🌟 Captação exaustiva da foto em qualquer nivel ou chave possível (Google, Gmail, Local, etc.)
  const fotoPerfil = 
    usuarioAtual.foto || 
    usuarioAtual.picture || 
    usuarioAtual.avatar || 
    usuarioAtual.image || 
    usuarioAtual.user_metadata?.avatar_url || 
    usuarioAtual.data?.picture || 
    usuarioAtual.data?.foto ||
    null;

  return (
    <div className="relative">
      <button 
        onClick={(e) => {
          e.stopPropagation();
          setIsOpen(!isOpen);
        }}
        className="flex items-center justify-center bg-white/10 hover:bg-white/20 backdrop-blur-md border border-white/30 p-1.5 rounded-full transition-all z-50 shadow-sm"
      >
        {fotoPerfil ? (
          <img 
            src={fotoPerfil} 
            alt="Perfil" 
            className="w-8 h-8 rounded-full object-cover"
            onError={(e) => {
              // Se a imagem falhar ao carregar por algum motivo de CORS ou URL expirada, esconde e mostra a letra
              e.target.style.display = 'none';
            }}
          />
        ) : (
          <div className="w-8 h-8 rounded-full bg-blue-600 text-white flex items-center justify-center font-bold text-sm">
            {emailExibicao ? emailExibicao.charAt(0).toUpperCase() : 'U'}
          </div>
        )}
      </button>

      {isOpen && (
        <>
          <div 
            className="fixed inset-0 z-40 cursor-default" 
            onClick={() => setIsOpen(false)}
          ></div>
          
          <div className="absolute right-0 mt-3 w-64 bg-white rounded-2xl shadow-2xl py-3 z-50 border border-gray-100 animate-in fade-in zoom-in duration-200 text-left">
            
            <div className="px-6 py-3 border-b border-gray-50 mb-2 bg-gradient-to-r from-[#003580] to-[#1a4d8c] mx-2 rounded-xl">
              <p className="text-[10px] font-black text-white/70 uppercase tracking-widest">
                {t('minha_conta')}
              </p>
              <p className="text-sm font-bold text-white truncate">{emailExibicao}</p>
            </div>
            
            <div className="px-2 space-y-1">
              {canManageAlojamento && (
                <button 
                  onClick={() => handleNavigation('/alojamento-registro/meus')}
                  className="w-full flex items-center gap-3 px-4 py-2.5 rounded-xl text-gray-700 hover:bg-blue-50 hover:text-blue-600 transition-all font-semibold text-sm"
                >
                  <Home size={16} /> Anuncie Alojamento
                </button>
              )}

              {canManageCarros && (
                <button 
                  onClick={() => handleNavigation('/carro-registo/meus')}
                  className="w-full flex items-center gap-3 px-4 py-2.5 rounded-xl text-gray-700 hover:bg-blue-50 hover:text-blue-600 transition-all font-semibold text-sm"
                >
                  <Car size={16} /> Anuncie Carros
                </button>
              )}

              {canManageExperiencias && (
                <button 
                  onClick={() => handleNavigation('/experiencia-registo/meus')}
                  className="w-full flex items-center gap-3 px-4 py-2.5 rounded-xl text-gray-700 hover:bg-blue-50 hover:text-blue-600 transition-all font-semibold text-sm"
                >
                  <Compass size={16} /> Anuncie Experiência
                </button>
              )}

              {(canManageAlojamento || canManageCarros || canManageExperiencias) && (
                <div className="border-t border-gray-100 my-2"></div>
              )}

              <button 
                onClick={() => handleNavigation('/favoritos')}
                className="w-full flex items-center gap-3 px-4 py-2.5 rounded-xl text-gray-700 hover:bg-blue-50 hover:text-blue-600 transition-all font-semibold text-sm"
              >
                <Heart size={16} /> {t('favoritos')}
                {totalFavoritos > 0 && (
                  <span className="ml-auto bg-red-500 text-white text-[10px] font-bold px-2 py-0.5 rounded-full min-w-[20px] text-center">
                    {totalFavoritos}
                  </span>
                )}
              </button>

              <button 
                onClick={() => handleNavigation('/gest/minhas-reservas')}
                className="w-full flex items-center gap-3 px-4 py-2.5 rounded-xl text-gray-700 hover:bg-blue-50 hover:text-blue-600 transition-all font-semibold text-sm"
              >
                <Calendar size={16} /> Minhas Reservas
              </button>

              <button 
                onClick={() => handleNavigation('/gest/configuracoes')}
                className="w-full flex items-center gap-3 px-4 py-2.5 rounded-xl text-gray-700 hover:bg-blue-50 hover:text-blue-600 transition-all font-semibold text-sm"
              >
                <User size={16} /> Perfil
              </button>

              {!canManageAlojamento && (
                <button 
                  onClick={() => handleNavigation('/gest/configuracoes?tab=funcoes')}
                  className="w-full flex items-center gap-3 px-4 py-2.5 rounded-xl text-gray-700 hover:bg-blue-50 hover:text-blue-600 transition-all font-semibold text-sm"
                >
                  <Home size={16} /> Solicitar Anfitrião
                </button>
              )}

              {canAccessDashboard && (
                <div className="border-t border-gray-100 my-2"></div>
              )}

              {canAccessDashboard && (
                <button 
                  onClick={() => handleNavigation('/gest/dashboard')}
                  className="w-full flex items-center gap-3 px-4 py-2.5 rounded-xl text-gray-700 hover:bg-blue-50 hover:text-blue-600 transition-all font-semibold text-sm"
                >
                  <LayoutDashboard size={16} /> Gerir anúncios e reservas
                </button>
              )}
            </div>

            <div className="mt-2 pt-2 border-t border-gray-100 px-2">
              <button 
                onClick={() => {
                  setIsOpen(false);
                  onLogout();
                }} 
                className="w-full flex items-center gap-3 px-4 py-3 text-red-600 hover:bg-red-50 rounded-xl transition-colors font-bold text-xs uppercase tracking-widest"
              >
                <LogOut size={16} /> {t('terminar_sessao')}
              </button>
            </div>
          </div>
        </>
      )}
    </div>
  );
};

export default UserDropdown;

// components/admin/AdminAnaliseAnuncio.jsx
import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import {
  ArrowLeft,
  FileText,
  CheckCircle2,
  XCircle,
  Pause,
  AlertTriangle,
  Loader2,
  Home,
  MapPin,
  DollarSign,
  User,
  Mail,
  Phone,
  Calendar,
  RefreshCw,
  Car,
  Compass,
  Users,
  Clock,
  Fuel,
  Settings,
  Bed,
  Bath,
  Eye,
} from 'lucide-react';
import SolicitarDocumentoModal from './SolicitarDocumentoModal';

const API_URL = import.meta.env.VITE_API_URL || 'https://welovepalop.com/api';

const TIPO_INFO = {
  alojamento: {
    label: 'Alojamento',
    Icone: Home,
    cor: 'text-blue-600 bg-blue-50',
  },
  experiencia: {
    label: 'Experiência',
    Icone: Compass,
    cor: 'text-purple-600 bg-purple-50',
  },
  carro: {
    label: 'Viatura',
    Icone: Car,
    cor: 'text-green-600 bg-green-50',
  },
};

export default function AdminAnaliseAnuncio() {
  const { tipo, id } = useParams();
  const navigate = useNavigate();

  const [anuncio, setAnuncio] = useState(null);
  const [loading, setLoading] = useState(true);
  const [erro, setErro] = useState('');
  const [showModalDocumento, setShowModalDocumento] = useState(false);
  const [showModalCorrecao, setShowModalCorrecao] = useState(false);
  const [showModalRejeicao, setShowModalRejeicao] = useState(false);
  const [motivoTexto, setMotivoTexto] = useState('');
  const [actionLoading, setActionLoading] = useState(false);
  const [msg, setMsg] = useState({ tipo: '', texto: '' });

  // ✅ NOVO — documento mais recente enviado pelo prestador
  const [ultimoDocumento, setUltimoDocumento] = useState(null);

  const tipoValido = tipo && TIPO_INFO[tipo];
  const tipoInfo = TIPO_INFO[tipo] || TIPO_INFO.alojamento;
  const TipoIcone = tipoInfo.Icone;

  // ============================================================
  // CARREGAR ANÚNCIO
  // ============================================================
  const carregarAnuncio = async () => {
    if (!tipoValido) {
      setErro('Tipo de anúncio inválido.');
      setLoading(false);
      return;
    }

    setLoading(true);
    setErro('');

    try {
      const res = await fetch(
        `${API_URL}/admin/anuncios/detalhe.php?tipo=${tipo}&id=${id}`
      );

      const texto = await res.text();

      if (!texto || texto.trim() === '') {
        setErro(`O servidor não devolveu resposta (HTTP ${res.status}).`);
        setLoading(false);
        return;
      }

      let data;
      try {
        data = JSON.parse(texto);
      } catch (parseErr) {
        console.error('Resposta não é JSON:', texto.substring(0, 300));
        setErro('Resposta inválida do servidor. Verifica a consola (F12).');
        setLoading(false);
        return;
      }

      if (data.success && data.data) {
        setAnuncio(data.data);
      } else {
        setErro(data.message || 'Anúncio não encontrado.');
      }
    } catch (err) {
      console.error('Erro de rede:', err);
      setErro('Erro de ligação ao servidor.');
    } finally {
      setLoading(false);
    }
  };

  // ============================================================
  // CARREGAR ÚLTIMO DOCUMENTO ENVIADO
  // ============================================================
  const carregarUltimoDocumento = async () => {
    if (!tipo || !id) return;

    try {
      const res = await fetch(`${API_URL}/admin/solicitar_documento.php`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'listar_por_anuncio',
          anuncio_id: parseInt(id),
          anuncio_tipo: tipo,
        }),
      });
      const data = await res.json();

      if (data.status === 'success' && Array.isArray(data.data)) {
        // Filtrar os que têm documento enviado
        const comDocumento = data.data.filter((p) => p.documento_url);
        // Ordenar por enviado_em desc
        comDocumento.sort((a, b) => {
          const da = a.enviado_em ? new Date(a.enviado_em).getTime() : 0;
          const db = b.enviado_em ? new Date(b.enviado_em).getTime() : 0;
          return db - da;
        });
        setUltimoDocumento(comDocumento[0] || null);
      }
    } catch (err) {
      console.error('Erro ao carregar documento:', err);
    }
  };

  useEffect(() => {
    carregarAnuncio();
  }, [tipo, id]);

  useEffect(() => {
    if (tipo && id) carregarUltimoDocumento();
  }, [tipo, id]);

  // ============================================================
  // EXECUTAR AÇÃO
  // ============================================================
  const executarAcao = async (acao, payload = {}) => {
    setActionLoading(true);
    setMsg({ tipo: '', texto: '' });

    const admin = JSON.parse(localStorage.getItem('morabeza_admin') || '{}');

    if (!admin.id) {
      setMsg({ tipo: 'erro', texto: 'Sessão expirada. Inicia sessão novamente.' });
      setActionLoading(false);
      return;
    }

    try {
      const res = await fetch(`${API_URL}/admin/anuncios/acao.php`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          anuncio_id: parseInt(id),
          tipo,
          admin_id: admin.id,
          acao,
          ...payload,
        }),
      });

      const texto = await res.text();

      if (!texto || texto.trim() === '') {
        setMsg({ tipo: 'erro', texto: `Servidor sem resposta (HTTP ${res.status}).` });
        setActionLoading(false);
        return;
      }

      let data;
      try {
        data = JSON.parse(texto);
      } catch {
        setMsg({ tipo: 'erro', texto: 'Resposta inválida do servidor.' });
        setActionLoading(false);
        return;
      }

      if (data.status === 'success') {
        setMsg({ tipo: 'sucesso', texto: data.message || 'Ação executada com sucesso.' });
        carregarAnuncio();
      } else {
        setMsg({ tipo: 'erro', texto: data.message || 'Erro ao executar ação.' });
      }
    } catch (err) {
      console.error(err);
      setMsg({ tipo: 'erro', texto: 'Erro de ligação ao servidor.' });
    } finally {
      setActionLoading(false);
    }
  };

  const handleAprovar = () => {
    if (!window.confirm('Confirmas a aprovação e publicação deste anúncio?')) return;
    executarAcao('aprovar');
  };

  const handlePedirCorrecao = () => {
    if (!motivoTexto.trim()) {
      setMsg({ tipo: 'erro', texto: 'Escreve o motivo da correção.' });
      return;
    }
    executarAcao('pedir_correcao', { motivo: motivoTexto.trim() });
    setShowModalCorrecao(false);
    setMotivoTexto('');
  };

  const handleRejeitar = () => {
    if (!motivoTexto.trim()) {
      setMsg({ tipo: 'erro', texto: 'Escreve o motivo da rejeição.' });
      return;
    }
    executarAcao('rejeitar', { motivo: motivoTexto.trim() });
    setShowModalRejeicao(false);
    setMotivoTexto('');
  };

  const handlePausar = () => {
    if (!window.confirm('Confirmas que queres pausar este anúncio?')) return;
    executarAcao('pausar');
  };

  // ✅ NOVO — Abrir PDF mais recente
  const handleVerDocumento = () => {
    if (!ultimoDocumento || !ultimoDocumento.documento_url) {
      setMsg({
        tipo: 'erro',
        texto: 'Nenhum documento foi enviado pelo prestador ainda.',
      });
      return;
    }

    // Corrigir URL se tiver "https:///"
    let url = ultimoDocumento.documento_url;
    if (url.startsWith('https:///')) {
      url = url.replace('https:///', 'https://');
    } else if (url.startsWith('http:///')) {
      url = url.replace('http:///', 'http://');
    }

    window.open(url, '_blank', 'noopener,noreferrer');
  };

  const formatarPreco = (valor) => {
    if (!valor && valor !== 0) return '-';
    return `${new Intl.NumberFormat('pt-CV', { maximumFractionDigits: 0 }).format(valor)} CVE`;
  };

  const formatarData = (d) => {
    if (!d) return '-';
    return new Date(d).toLocaleDateString('pt-PT', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  const StatusBadge = ({ estado }) => {
    const map = {
      rascunho: { cls: 'bg-gray-100 text-gray-700', txt: 'Rascunho' },
      pendente: { cls: 'bg-yellow-100 text-yellow-700', txt: 'Pendente' },
      em_analise: { cls: 'bg-yellow-100 text-yellow-700', txt: 'Em análise' },
      correcao_necessaria: { cls: 'bg-orange-100 text-orange-700', txt: 'Correção necessária' },
      documentacao_necessaria: { cls: 'bg-blue-100 text-blue-700', txt: 'Documentação necessária' },
      aprovado: { cls: 'bg-green-100 text-green-700', txt: 'Aprovado' },
      publicado: { cls: 'bg-green-100 text-green-700', txt: 'Publicado' },
      rejeitado: { cls: 'bg-red-100 text-red-700', txt: 'Rejeitado' },
      pausado: { cls: 'bg-gray-100 text-gray-700', txt: 'Pausado' },
      suspenso: { cls: 'bg-red-100 text-red-700', txt: 'Suspenso' },
    };
    const s = map[estado] || { cls: 'bg-gray-100 text-gray-700', txt: estado || '-' };
    return (
      <span className={`inline-flex items-center gap-1 px-3 py-1 rounded-full text-xs font-semibold ${s.cls}`}>
        {s.txt}
      </span>
    );
  };

  // ============================================================
  // LOADING
  // ============================================================
  if (loading) {
    return (
      <div className="flex justify-center items-center h-96">
        <Loader2 className="animate-spin text-[#003580]" size={32} />
      </div>
    );
  }

  // ============================================================
  // ERRO
  // ============================================================
  if (erro) {
    return (
      <div className="p-8 text-center max-w-lg mx-auto">
        <AlertTriangle className="mx-auto text-red-500 mb-4" size={48} />
        <p className="text-red-600 font-medium mb-4">{erro}</p>
        <div className="flex gap-3 justify-center">
          <button
            onClick={carregarAnuncio}
            className="inline-flex items-center gap-2 px-4 py-2 bg-[#003580] text-white rounded-lg text-sm hover:bg-[#002860] transition"
          >
            <RefreshCw size={16} /> Tentar novamente
          </button>
          <button
            onClick={() => navigate('/admin/propriedades')}
            className="inline-flex items-center gap-2 px-4 py-2 border border-gray-300 rounded-lg text-sm hover:bg-gray-50 transition"
          >
            <ArrowLeft size={16} /> Voltar
          </button>
        </div>
      </div>
    );
  }

  if (!anuncio) return null;

  const imagemPrincipal =
    anuncio.foto_principal ||
    anuncio.imagem_url ||
    anuncio.imagem_principal ||
    null;

  return (
    <div className="space-y-6 max-w-5xl mx-auto pb-12">
      {/* HEADER */}
      <div className="flex items-center gap-4 flex-wrap">
        <button
          onClick={() => navigate('/admin/propriedades')}
          className="p-2 rounded-lg hover:bg-gray-100 transition"
          title="Voltar"
        >
          <ArrowLeft size={20} />
        </button>

        <div className={`p-2.5 rounded-xl ${tipoInfo.cor}`}>
          <TipoIcone size={24} />
        </div>

        <div className="flex-1 min-w-0">
          <h1 className="text-2xl font-bold text-[#003580] truncate">
            Análise de {tipoInfo.label}
          </h1>
          <p className="text-sm text-gray-500 truncate">
            #{anuncio.id} — {anuncio.titulo}
          </p>
        </div>

        <StatusBadge estado={anuncio.estado || anuncio.status} />
      </div>

      {/* MENSAGEM */}
      {msg.texto && (
        <div
          className={`p-3 rounded-lg flex items-center gap-2 text-sm ${
            msg.tipo === 'sucesso'
              ? 'bg-green-50 text-green-800 border border-green-200'
              : 'bg-red-50 text-red-800 border border-red-200'
          }`}
        >
          {msg.tipo === 'sucesso' ? <CheckCircle2 size={16} /> : <XCircle size={16} />}
          <span>{msg.texto}</span>
        </div>
      )}

      {/* DADOS DO ANÚNCIO */}
      <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
        {imagemPrincipal && (
          <img
            src={imagemPrincipal}
            alt={anuncio.titulo}
            className="w-full h-64 object-cover"
            onError={(e) => {
              e.target.style.display = 'none';
            }}
          />
        )}

        <div className="p-6 space-y-4">
          <h2 className="text-xl font-bold text-gray-900">{anuncio.titulo}</h2>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-sm">
            <div className="flex items-center gap-2 text-gray-600">
              <MapPin size={16} className="flex-shrink-0" />
              <span>{anuncio.localizacao || anuncio.ilha || 'Localização não informada'}</span>
            </div>

            <div className="flex items-center gap-2 text-gray-600">
              <DollarSign size={16} className="flex-shrink-0" />
              {tipo === 'alojamento' && (
                <span>
                  <strong>{formatarPreco(anuncio.preco || anuncio.preco_noite)}</strong> / noite
                </span>
              )}
              {tipo === 'carro' && (
                <span>
                  <strong>{formatarPreco(anuncio.preco_dia)}</strong> / dia
                </span>
              )}
              {tipo === 'experiencia' && (
                <span>
                  <strong>{formatarPreco(anuncio.preco || anuncio.preco_pessoa)}</strong> / pessoa
                </span>
              )}
            </div>

            <div className="flex items-center gap-2 text-gray-600">
              <Calendar size={16} className="flex-shrink-0" />
              <span>Submetido em {formatarData(anuncio.criado_em || anuncio.created_at)}</span>
            </div>

            {tipo === 'alojamento' && (
              <>
                {anuncio.capacidade && (
                  <div className="flex items-center gap-2 text-gray-600">
                    <Users size={16} /> {anuncio.capacidade} hóspedes
                  </div>
                )}
                {anuncio.quartos && (
                  <div className="flex items-center gap-2 text-gray-600">
                    <Bed size={16} /> {anuncio.quartos} quartos
                  </div>
                )}
                {anuncio.casas_banho && (
                  <div className="flex items-center gap-2 text-gray-600">
                    <Bath size={16} /> {anuncio.casas_banho} casas de banho
                  </div>
                )}
              </>
            )}

            {tipo === 'carro' && (
              <>
                {anuncio.marca && (
                  <div className="flex items-center gap-2 text-gray-600">
                    <Car size={16} /> {anuncio.marca} {anuncio.modelo || ''}
                  </div>
                )}
                {anuncio.passageiros && (
                  <div className="flex items-center gap-2 text-gray-600">
                    <Users size={16} /> {anuncio.passageiros} lugares
                  </div>
                )}
                {anuncio.transmissao && (
                  <div className="flex items-center gap-2 text-gray-600">
                    <Settings size={16} /> {anuncio.transmissao}
                  </div>
                )}
                {anuncio.combustivel && (
                  <div className="flex items-center gap-2 text-gray-600">
                    <Fuel size={16} /> {anuncio.combustivel}
                  </div>
                )}
              </>
            )}

            {tipo === 'experiencia' && (
              <>
                {anuncio.duracao && (
                  <div className="flex items-center gap-2 text-gray-600">
                    <Clock size={16} /> {anuncio.duracao}
                  </div>
                )}
                {anuncio.max_participantes && (
                  <div className="flex items-center gap-2 text-gray-600">
                    <Users size={16} /> Máx. {anuncio.max_participantes} participantes
                  </div>
                )}
              </>
            )}
          </div>

          {anuncio.descricao && (
            <div className="pt-4 border-t">
              <h3 className="font-semibold text-gray-800 mb-2">Descrição</h3>
              <p className="text-sm text-gray-600 whitespace-pre-wrap">{anuncio.descricao}</p>
            </div>
          )}
        </div>
      </div>

      {/* DADOS DO PRESTADOR */}
      <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-6">
        <h3 className="font-semibold text-gray-800 mb-4 flex items-center gap-2">
          <User size={18} /> Prestador
        </h3>

        <div className="flex items-center gap-4">
          <img
            src={
              anuncio.prestador_foto ||
              `https://ui-avatars.com/api/?name=${encodeURIComponent(
                anuncio.prestador_nome || 'P'
              )}&background=003580&color=fff&size=80`
            }
            alt={anuncio.prestador_nome || 'Prestador'}
            className="w-14 h-14 rounded-full object-cover"
          />
          <div className="flex-1 min-w-0">
            <p className="font-medium text-gray-900 truncate">
              {anuncio.prestador_nome || 'Prestador não identificado'}
            </p>
            {anuncio.prestador_email && (
              <p className="text-sm text-gray-500 flex items-center gap-1 truncate">
                <Mail size={12} /> {anuncio.prestador_email}
              </p>
            )}
            {anuncio.prestador_phone && (
              <p className="text-sm text-gray-500 flex items-center gap-1">
                <Phone size={12} /> {anuncio.prestador_phone}
              </p>
            )}
          </div>
        </div>
      </div>

      {/* ============================================================ */}
      {/* BARRA DE AÇÕES */}
      {/* ============================================================ */}
      <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-6">
        <h3 className="font-semibold text-gray-800 mb-4">Ações de análise</h3>

        <div className="flex flex-wrap gap-3">
          <button
            onClick={handleAprovar}
            disabled={actionLoading}
            className="flex items-center gap-2 px-4 py-2.5 rounded-xl bg-green-600 hover:bg-green-700 text-white text-sm font-semibold transition disabled:opacity-50"
          >
            {actionLoading ? (
              <Loader2 size={16} className="animate-spin" />
            ) : (
              <CheckCircle2 size={16} />
            )}
            Aprovar / Publicar
          </button>

          <button
            onClick={() => setShowModalCorrecao(true)}
            disabled={actionLoading}
            className="flex items-center gap-2 px-4 py-2.5 rounded-xl bg-orange-500 hover:bg-orange-600 text-white text-sm font-semibold transition disabled:opacity-50"
          >
            <AlertTriangle size={16} /> Pedir correção
          </button>

          {/* ✅ NOVO — Ver PDF enviado pelo prestador */}
          <button
            onClick={handleVerDocumento}
            disabled={actionLoading || !ultimoDocumento}
            className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-sm font-semibold transition disabled:opacity-50 ${
              ultimoDocumento
                ? 'bg-indigo-600 hover:bg-indigo-700 text-white'
                : 'bg-gray-100 text-gray-400 cursor-not-allowed'
            }`}
            title={
              ultimoDocumento
                ? `Ver ${ultimoDocumento.tipo_documento} enviado`
                : 'Nenhum documento enviado ainda'
            }
          >
            <Eye size={16} /> Ver documento
            {ultimoDocumento && (
              <span className="ml-1 w-2 h-2 bg-green-400 rounded-full animate-pulse"></span>
            )}
          </button>

          <button
            onClick={() => setShowModalDocumento(true)}
            disabled={actionLoading}
            className="flex items-center gap-2 px-4 py-2.5 rounded-xl border-2 border-blue-300 text-blue-700 hover:bg-blue-50 text-sm font-semibold transition disabled:opacity-50"
          >
            <FileText size={16} /> Solicitar documento
          </button>

          <button
            onClick={() => setShowModalRejeicao(true)}
            disabled={actionLoading}
            className="flex items-center gap-2 px-4 py-2.5 rounded-xl bg-red-600 hover:bg-red-700 text-white text-sm font-semibold transition disabled:opacity-50"
          >
            <XCircle size={16} /> Rejeitar
          </button>

          <button
            onClick={handlePausar}
            disabled={actionLoading}
            className="flex items-center gap-2 px-4 py-2.5 rounded-xl bg-gray-600 hover:bg-gray-700 text-white text-sm font-semibold transition disabled:opacity-50"
          >
            <Pause size={16} /> Pausar
          </button>
        </div>

        {/* Info do documento mais recente */}
        {ultimoDocumento && (
          <div className="mt-4 p-3 bg-indigo-50 border border-indigo-100 rounded-xl flex items-center gap-3 text-xs text-indigo-900">
            <FileText size={16} className="flex-shrink-0" />
            <div className="flex-1">
              <strong>Documento mais recente:</strong> {ultimoDocumento.tipo_documento}
              {ultimoDocumento.enviado_em && ` • enviado em ${formatarData(ultimoDocumento.enviado_em)}`}
            </div>
          </div>
        )}
      </div>

      {/* MODAL — SOLICITAR DOCUMENTO */}
      {showModalDocumento && (
        <SolicitarDocumentoModal
          anuncioId={anuncio.id}
          anuncioTipo={tipo}
          prestadorId={anuncio.prestador_id || anuncio.user_id}
          onClose={() => setShowModalDocumento(false)}
          onSucesso={() => {
            carregarAnuncio();
            carregarUltimoDocumento();
            setMsg({
              tipo: 'sucesso',
              texto: 'Pedido de documento enviado ao prestador.',
            });
          }}
        />
      )}

      {/* MODAL — PEDIR CORREÇÃO */}
      {showModalCorrecao && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl max-w-md w-full p-6">
            <h3 className="text-lg font-bold mb-2 text-orange-600">Pedir correção</h3>
            <p className="text-sm text-gray-500 mb-4">
              Explica o que precisa ser corrigido. O prestador será notificado.
            </p>
            <textarea
              value={motivoTexto}
              onChange={(e) => setMotivoTexto(e.target.value)}
              rows={4}
              maxLength={500}
              placeholder="Ex: A descrição está incompleta. Falta indicar o número de quartos."
              className="w-full border border-gray-200 rounded-xl p-3 mb-4 focus:outline-none focus:ring-2 focus:ring-orange-500/20 text-sm resize-none"
              autoFocus
            />
            <p className="text-xs text-gray-400 mb-4">{motivoTexto.length}/500</p>
            <div className="flex gap-3">
              <button
                onClick={() => {
                  setShowModalCorrecao(false);
                  setMotivoTexto('');
                }}
                className="flex-1 bg-gray-200 py-2.5 rounded-xl hover:bg-gray-300 transition text-sm font-medium"
              >
                Cancelar
              </button>
              <button
                onClick={handlePedirCorrecao}
                disabled={!motivoTexto.trim() || actionLoading}
                className="flex-1 bg-orange-500 hover:bg-orange-600 text-white py-2.5 rounded-xl transition text-sm font-semibold disabled:opacity-50 flex items-center justify-center gap-2"
              >
                {actionLoading ? (
                  <Loader2 size={16} className="animate-spin" />
                ) : (
                  <AlertTriangle size={16} />
                )}
                Enviar pedido
              </button>
            </div>
          </div>
        </div>
      )}

      {/* MODAL — REJEITAR */}
      {showModalRejeicao && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl max-w-md w-full p-6">
            <h3 className="text-lg font-bold mb-2 text-red-600">Rejeitar anúncio</h3>
            <p className="text-sm text-gray-500 mb-4">
              Esta ação é definitiva para este anúncio. Explica o motivo.
            </p>
            <textarea
              value={motivoTexto}
              onChange={(e) => setMotivoTexto(e.target.value)}
              rows={4}
              maxLength={500}
              placeholder="Ex: O anúncio viola as políticas da plataforma."
              className="w-full border border-gray-200 rounded-xl p-3 mb-4 focus:outline-none focus:ring-2 focus:ring-red-500/20 text-sm resize-none"
              autoFocus
            />
            <p className="text-xs text-gray-400 mb-4">{motivoTexto.length}/500</p>
            <div className="flex gap-3">
              <button
                onClick={() => {
                  setShowModalRejeicao(false);
                  setMotivoTexto('');
                }}
                className="flex-1 bg-gray-200 py-2.5 rounded-xl hover:bg-gray-300 transition text-sm font-medium"
              >
                Cancelar
              </button>
              <button
                onClick={handleRejeitar}
                disabled={!motivoTexto.trim() || actionLoading}
                className="flex-1 bg-red-600 hover:bg-red-700 text-white py-2.5 rounded-xl transition text-sm font-semibold disabled:opacity-50 flex items-center justify-center gap-2"
              >
                {actionLoading ? (
                  <Loader2 size={16} className="animate-spin" />
                ) : (
                  <XCircle size={16} />
                )}
                Confirmar rejeição
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// components/admin/AdminLayout.jsx
import React, { useEffect } from 'react';
import { Outlet, useNavigate } from 'react-router-dom';
import AdminSidebar from './AdminSidebar';

const AdminLayout = () => {
  const navigate = useNavigate();

  useEffect(() => {
    // Verificar se admin está autenticado
    const adminData = localStorage.getItem('morabeza_admin');
    
    if (!adminData) {
      navigate('/admin/login', { replace: true });
      return;
    }

    try {
      const admin = JSON.parse(adminData);
      const isAdmin = 
        admin.role === 'admin' || 
        admin.tipo === 'admin' ||
