// components/admin/PropriedadesAdmin.jsx
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  MapPin, Eye, Check, X, Loader2, Search,
  AlertCircle, Home, Building, Hotel, Trash2,
  User, Mail, Calendar, DollarSign, Users,
  Car, Compass, Clock, Fuel, Settings, Star,
  Phone, Bed, Bath, Wifi, Coffee, Tv, Snowflake, Utensils,
  FileText,
} from 'lucide-react';

const API_URL = import.meta.env.VITE_API_URL || 'https://welovepalop.com/api';

const PropriedadesAdmin = () => {
  const navigate = useNavigate();

  const [activeTab, setActiveTab] = useState('alojamentos');
  const [alojamentos, setAlojamentos] = useState([]);
  const [experiencias, setExperiencias] = useState([]);
  const [carros, setCarros] = useState([]);
  const [loading, setLoading] = useState(false);
  const [search, setSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState('todos');
  const [stats, setStats] = useState(null);

  const carregarStats = async () => {
    try {
      const response = await fetch(`${API_URL}/admin/admin_all_content.php?action=dashboard`);
      const data = await response.json();
      if (data.status === 'success') {
        setStats(data.data);
      }
    } catch (err) {
      console.error('Erro:', err);
    }
  };

  const carregarConteudo = async () => {
    setLoading(true);
    try {
      const url = `${API_URL}/admin/admin_all_content.php?action=${activeTab}&status=${filterStatus}&search=${encodeURIComponent(search)}`;
      const response = await fetch(url);
      const data = await response.json();

      if (data.status === 'success') {
        if (activeTab === 'alojamentos') setAlojamentos(data.data);
        if (activeTab === 'experiencias') setExperiencias(data.data);
        if (activeTab === 'carros') setCarros(data.data);
      }
    } catch (err) {
      console.error('Erro:', err);
    }
    setLoading(false);
  };

  useEffect(() => {
    carregarStats();
  }, []);

  useEffect(() => {
    carregarConteudo();
  }, [activeTab, filterStatus, search]);

  const StatusBadge = ({ status }) => {
    const config = {
      aprovado: { bg: 'bg-green-100', text: 'text-green-700', label: '✓ Aprovado', icon: <Check size={12} /> },
      publicado: { bg: 'bg-green-100', text: 'text-green-700', label: '✓ Publicado', icon: <Check size={12} /> },
      pendente: { bg: 'bg-yellow-100', text: 'text-yellow-700', label: '⏳ Pendente', icon: <Clock size={12} /> },
      em_analise: { bg: 'bg-yellow-100', text: 'text-yellow-700', label: '⏳ Em análise', icon: <Clock size={12} /> },
      rejeitado: { bg: 'bg-red-100', text: 'text-red-700', label: '✗ Rejeitado', icon: <X size={12} /> },
      correcao_necessaria: { bg: 'bg-orange-100', text: 'text-orange-700', label: '⚠ Correção necessária', icon: <AlertCircle size={12} /> },
      documentacao_necessaria: { bg: 'bg-blue-100', text: 'text-blue-700', label: '📄 Documentação necessária', icon: <FileText size={12} /> },
      pausado: { bg: 'bg-gray-100', text: 'text-gray-700', label: '⏸ Pausado', icon: <Clock size={12} /> },
      suspenso: { bg: 'bg-red-100', text: 'text-red-700', label: '⛔ Suspenso', icon: <X size={12} /> },
    };
    const style = config[status?.toLowerCase()] || config.pendente;
    return (
      <span className={`inline-flex items-center gap-1 ${style.bg} ${style.text} px-2 py-1 rounded-md text-xs font-semibold`}>
        {style.icon} {style.label}
      </span>
    );
  };

  const formatarPreco = (preco) => `${Number(preco || 0).toLocaleString()} CVE`;

  const getTipoIcon = (tipo) => {
    switch (tipo?.toLowerCase()) {
      case 'villa': return <Building size={18} />;
      case 'guesthouse': return <Hotel size={18} />;
      default: return <Home size={18} />;
    }
  };

  const getCurrentItems = () => {
    if (activeTab === 'alojamentos') return alojamentos;
    if (activeTab === 'experiencias') return experiencias;
    return carros;
  };

  const currentItems = getCurrentItems();

  const totalPendentes = currentItems.filter((i) => {
    const st = (i.status || i.estado || '').toLowerCase();
    return st === 'pendente' || st === 'em_analise' || st === 'documentacao_necessaria';
  }).length;

  const getTipoSlug = () => {
    if (activeTab === 'alojamentos') return 'alojamento';
    if (activeTab === 'experiencias') return 'experiencia';
    return 'carro';
  };

  return (
    <div className="space-y-6">
      {/* Cabeçalho */}
      <div className="flex justify-between items-center flex-wrap gap-4">
        <div>
          <h1 className="text-3xl font-semibold text-[#003580]">Gestão de Conteúdo</h1>
          <p className="text-gray-600 mt-1">
            Analise alojamentos, experiências e viaturas antes de os publicar.
            {totalPendentes > 0 && (
              <span className="ml-2 text-yellow-600 font-medium">
                ({totalPendentes} aguardam análise)
              </span>
            )}
          </p>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex flex-wrap gap-2 border-b border-gray-200">
        <button
          onClick={() => setActiveTab('alojamentos')}
          className={`flex items-center gap-2 px-5 py-3 text-sm font-medium transition-all rounded-t-lg ${
            activeTab === 'alojamentos' ? 'bg-[#003580] text-white shadow-md' : 'text-gray-600 hover:bg-gray-100'
          }`}
        >
          <Home size={18} /> Alojamentos
          {stats?.alojamentos?.pendentes > 0 && (
            <span className="ml-1 bg-yellow-400 text-yellow-900 px-2 py-0.5 rounded-full text-xs">
              {stats.alojamentos.pendentes}
            </span>
          )}
        </button>
        <button
          onClick={() => setActiveTab('experiencias')}
          className={`flex items-center gap-2 px-5 py-3 text-sm font-medium transition-all rounded-t-lg ${
            activeTab === 'experiencias' ? 'bg-[#003580] text-white shadow-md' : 'text-gray-600 hover:bg-gray-100'
          }`}
        >
          <Compass size={18} /> Experiências
          {stats?.experiencias?.pendentes > 0 && (
            <span className="ml-1 bg-yellow-400 text-yellow-900 px-2 py-0.5 rounded-full text-xs">
              {stats.experiencias.pendentes}
            </span>
          )}
        </button>
        <button
          onClick={() => setActiveTab('carros')}
          className={`flex items-center gap-2 px-5 py-3 text-sm font-medium transition-all rounded-t-lg ${
            activeTab === 'carros' ? 'bg-[#003580] text-white shadow-md' : 'text-gray-600 hover:bg-gray-100'
          }`}
        >
          <Car size={18} /> Viaturas
          {stats?.carros?.pendentes > 0 && (
            <span className="ml-1 bg-yellow-400 text-yellow-900 px-2 py-0.5 rounded-full text-xs">
              {stats.carros.pendentes}
            </span>
          )}
        </button>
      </div>

      {/* Filtros e Busca */}
      <div className="flex flex-col sm:flex-row gap-4 justify-between">
        <div className="flex gap-2 flex-wrap">
          {['todos', 'pendente', 'aprovado', 'rejeitado'].map((status) => (
            <button
              key={status}
              onClick={() => setFilterStatus(status)}
              className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
                filterStatus === status
                  ? status === 'pendente'
                    ? 'bg-yellow-500 text-white'
                    : status === 'aprovado'
                    ? 'bg-green-600 text-white'
                    : status === 'rejeitado'
                    ? 'bg-red-600 text-white'
                    : 'bg-[#003580] text-white'
                  : 'bg-white text-gray-600 hover:bg-gray-100'
              }`}
            >
              {status === 'todos' ? 'Todos' : status === 'pendente' ? '⏳ Pendentes' : status === 'aprovado' ? '✓ Aprovados' : '✗ Rejeitados'}
            </button>
          ))}
        </div>
        <div className="relative w-full sm:w-80">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={18} />
          <input
            type="text"
            placeholder="Procurar por título ou localização..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full pl-10 pr-4 py-2 bg-white rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-[#003580]/20"
          />
        </div>
      </div>

      {/* Lista de Conteúdo */}
      {loading ? (
        <div className="py-20 flex justify-center items-center gap-2">
          <Loader2 className="animate-spin text-[#003580]" size={24} />
          <span>A carregar...</span>
        </div>
      ) : currentItems.length === 0 ? (
        <div className="py-20 text-center text-gray-500">
          {activeTab === 'alojamentos' && <Home size={48} className="mx-auto mb-4 text-gray-300" />}
          {activeTab === 'experiencias' && <Compass size={48} className="mx-auto mb-4 text-gray-300" />}
          {activeTab === 'carros' && <Car size={48} className="mx-auto mb-4 text-gray-300" />}
          <p>
            Nenhum {activeTab === 'alojamentos' ? 'alojamento' : activeTab === 'experiencias' ? 'experiência' : 'veículo'} encontrado
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-6">
          {currentItems.map((item) => (
            <div key={item.id} className="bg-white rounded-2xl shadow-md border border-gray-100 overflow-hidden hover:shadow-lg transition">
              {/* Imagem */}
              <div className="h-48 overflow-hidden relative">
                <img
                  src={item.imagem_url || item.imagem_principal || 'https://images.unsplash.com/photo-1499793983690-e29da59ef1c2?w=500'}
                  alt={item.titulo}
                  className="w-full h-full object-cover hover:scale-105 transition duration-300"
                />
                <div className="absolute top-3 right-3">
                  <StatusBadge status={item.status || item.estado} />
                </div>
                <div className="absolute bottom-3 left-3 bg-black/60 backdrop-blur-sm rounded-lg px-2 py-1 text-white text-xs flex items-center gap-1">
                  {activeTab === 'carros' ? <Car size={14} /> : activeTab === 'experiencias' ? <Compass size={14} /> : getTipoIcon(item.tipo)}
                  <span>{activeTab === 'carros' ? 'Viatura' : activeTab === 'experiencias' ? 'Experiência' : item.tipo || 'Apartamento'}</span>
                </div>
              </div>

              {/* Conteúdo */}
              <div className="p-5">
                <h3 className="text-lg font-bold text-gray-800 line-clamp-1">{item.titulo}</h3>
                <div className="flex items-center text-gray-500 mt-1 text-sm">
                  <MapPin size={14} className="mr-1" />
                  <span className="line-clamp-1">{item.localizacao || item.ilha || 'Localização não informada'}</span>
                </div>

                <div className="flex items-center justify-between mt-3">
                  <div className="text-[#003580] font-bold">
                    {activeTab === 'carros' ? formatarPreco(item.preco_dia) + '/dia' : formatarPreco(item.preco_noite || item.preco)}
                  </div>
                  <div className="flex items-center gap-1 text-gray-500 text-sm">
                    {activeTab === 'alojamentos' && <><Users size={14} /> {item.capacidade || 2} hóspedes</>}
                    {activeTab === 'carros' && <><Users size={14} /> {item.passageiros || 5} lugares</>}
                    {activeTab === 'experiencias' && <><Clock size={14} /> {item.duracao || '2h'}</>}
                  </div>
                </div>

                {(item.proprietario_nome || item.proprietario_email) && (
                  <div className="mt-3 pt-3 border-t border-gray-100 flex items-center gap-2 text-xs text-gray-500">
                    <User size={12} /> <span className="truncate">{item.proprietario_nome || 'Anónimo'}</span>
                    <Mail size={12} /> <span className="truncate">{item.proprietario_email || 'Email não disponível'}</span>
                  </div>
                )}

                {/* Ações — só Detalhes e Analisar */}
                <div className="mt-4 flex gap-2">
                  <button
                    onClick={() => navigate(`/admin/propriedades/${activeTab}/${item.id}`)}
                    className="flex-1 flex items-center justify-center gap-1 text-sm font-medium text-[#6b82c6] hover:text-[#003580] bg-gray-50 hover:bg-gray-100 py-2.5 rounded-lg transition"
                  >
                    <Eye size={16} /> Detalhes
                  </button>

                  <button
                    onClick={() => navigate(`/admin/analise-anuncio/${getTipoSlug()}/${item.id}`)}
                    className="flex-1 flex items-center justify-center gap-1 text-sm font-semibold text-white bg-[#003580] hover:bg-[#002860] py-2.5 rounded-lg transition shadow-sm"
                    title="Abrir análise completa do anúncio"
                  >
                    <FileText size={16} /> Analisar
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default PropriedadesAdmin;

import React, { useState, useEffect } from 'react';
import { FileText, Download, TrendingUp, Users, DollarSign, Calendar, Activity, Home, Car, Compass, Star, Loader2, Clock, Wallet, CheckCircle, XCircle, Lock, RotateCcw } from 'lucide-react';

const Relatorios = () => {
  const [stats, setStats] = useState({
    total: 0,
    faturacaoTotal: 0,
    reservasMes: 0,
    avaliacaoMedia: 0,
    crescimento: 0
  });

  const [financeiro, setFinanceiro] = useState({
    a_receber:   { bruto: 0, comissao: 0, taxas: 0, liquido: 0 },
    disponivel:  { bruto: 0, comissao: 0, taxas: 0, liquido: 0 },
    pago:        { bruto: 0, comissao: 0, taxas: 0, liquido: 0 },
    falhou:      { bruto: 0, comissao: 0, taxas: 0, liquido: 0 },
    retido:      { bruto: 0, comissao: 0, taxas: 0, liquido: 0 },
    reembolsado: { bruto: 0, comissao: 0, taxas: 0, liquido: 0 },
    totais:      { bruto: 0, comissao: 0, taxas: 0, liquido: 0 },
    total_reservas: 0,
  });

  const [relatorioAtivo, setRelatorioAtivo] = useState('alojamentos');
  const [loading, setLoading] = useState(false);
  const [apiData, setApiData] = useState(null);

  // Buscar dados da API
  const fetchReportData = async (tipo) => {
    setLoading(true);
    try {
      const response = await fetch(`https://welovepalop.com/api/admin/admin_reports.php?action=${tipo}`);
      const data = await response.json();
      
      if (data.success) {
        setApiData(data.data);
        
        // Atualizar stats baseado nos dados reais da API
        setStats({
          total: data.data.total || 0,
          faturacaoTotal: data.data.faturacao_total || 0,
          reservasMes: data.data.total_reservas || 0,
          avaliacaoMedia: data.data.rating_global || 4.5,
          crescimento: tipo === 'experiencias' ? 25 : tipo === 'carros' ? 18 : 8
        });
      }
    } catch (error) {
      console.error('Erro ao carregar dados:', error);
    }
    setLoading(false);
  };

  // Buscar dados financeiros da conta
  const fetchFinanceiro = async (contaId = 1) => {
    setLoading(true);
    try {
      const response = await fetch(`https://welovepalop.com/api/admin/admin_reports.php?action=financeiro&conta_id=${contaId}`);
      const data = await response.json();
      
      if (data.success) {
        setFinanceiro(data.data);
      }
    } catch (error) {
      console.error('Erro ao carregar dados financeiros:', error);
    }
    setLoading(false);
  };

  const handleRelatorioClick = (tipo) => {
    setRelatorioAtivo(tipo);
    if (tipo === 'financeiro') {
      fetchFinanceiro();
    } else {
      fetchReportData(tipo);
    }
  };

  const formatarMoeda = (valor) => {
    if (!valor || valor === 0) return '0 CVE';
    return new Intl.NumberFormat('pt-PT').format(valor) + ' CVE';
  };

  const formatarNumero = (valor) => {
    if (!valor) return '0';
    return new Intl.NumberFormat('pt-PT').format(valor);
  };

  // Carregar dados iniciais
  useEffect(() => {
    fetchReportData('alojamentos');
  }, []);

  // Detalhes para Alojamentos
  const getDetalhesAlojamentos = () => {
    if (!apiData) return [];
    return [
      { label: "Total de Alojamentos", valor: formatarNumero(apiData.total), percentual: "" },
      { label: "Aprovados", valor: formatarNumero(apiData.aprovados), percentual: `${Math.round((apiData.aprovados / apiData.total) * 100)}%` },
      { label: "Pendentes", valor: formatarNumero(apiData.pendentes), percentual: `${Math.round((apiData.pendentes / apiData.total) * 100)}%` },
      { label: "Villas", valor: getTipoCount('Villa'), percentual: getTipoPercentual('Villa') },
      { label: "Apartamentos", valor: getTipoCount('Apartamento'), percentual: getTipoPercentual('Apartamento') },
      { label: "Guest Houses", valor: getTipoCount('Guesthouse'), percentual: getTipoPercentual('Guesthouse') },
      { label: "Preço Médio/Noite", valor: formatarMoeda(apiData.preco_medio), percentual: "" },
      { label: "Preço Mínimo", valor: formatarMoeda(apiData.preco_min), percentual: "" },
      { label: "Preço Máximo", valor: formatarMoeda(apiData.preco_max), percentual: "" }
    ];
  };

  // Detalhes para Carros
  const getDetalhesCarros = () => {
    if (!apiData) return [];
    return [
      { label: "Total de Viaturas", valor: formatarNumero(apiData.total), percentual: "" },
      { label: "Disponíveis", valor: formatarNumero(apiData.disponiveis), percentual: `${Math.round((apiData.disponiveis / apiData.total) * 100)}%` },
      { label: "Indisponíveis", valor: formatarNumero(apiData.indisponiveis), percentual: `${Math.round((apiData.indisponiveis / apiData.total) * 100)}%` },
      { label: "SUVs", valor: getCarroTipoCount('SUV'), percentual: getCarroTipoPercentual('SUV') },
      { label: "Económicos", valor: getCarroTipoCount('Económico'), percentual: getCarroTipoPercentual('Económico') },
      { label: "Pickup", valor: getCarroTipoCount('Pickup'), percentual: getCarroTipoPercentual('Pickup') },
      { label: "Luxo", valor: getCarroTipoCount('Luxo'), percentual: getCarroTipoPercentual('Luxo') },
      { label: "Elétrico", valor: getCarroTipoCount('Elétrico'), percentual: getCarroTipoPercentual('Elétrico') },
      { label: "Preço Médio/Dia", valor: formatarMoeda(calcularPrecoMedioGeral()), percentual: "" }
    ];
  };

  // Detalhes para Experiências
  const getDetalhesExperiencias = () => {
    if (!apiData) return [];
    const categorias = {
      aventura: getCategoriaCount('aventura'),
      cultural: getCategoriaCount('cultural'),
      gastronomia: getCategoriaCount('gastronomia'),
      natureza: getCategoriaCount('natureza'),
      relax: getCategoriaCount('relax')
    };
    
    return [
      { label: "Total de Experiências", valor: formatarNumero(apiData.total), percentual: "" },
      { label: "Aprovadas", valor: formatarNumero(apiData.aprovadas), percentual: `${Math.round((apiData.aprovadas / apiData.total) * 100)}%` },
      { label: "Aventura", valor: categorias.aventura, percentual: getCategoriaPercentual('aventura') },
      { label: "Cultural", valor: categorias.cultural, percentual: getCategoriaPercentual('cultural') },
      { label: "Gastronomia", valor: categorias.gastronomia, percentual: getCategoriaPercentual('gastronomia') },
      { label: "Natureza", valor: categorias.natureza, percentual: getCategoriaPercentual('natureza') },
      { label: "Relax", valor: categorias.relax, percentual: getCategoriaPercentual('relax') },
      { label: "Rating Global", valor: `${apiData.rating_global || 0} ★`, percentual: "" },
      { label: "Total Reviews", valor: formatarNumero(apiData.total_reviews), percentual: "" },
      { label: "Preço Médio", valor: formatarMoeda(calcularPrecoMedioExperiencias()), percentual: "" }
    ];
  };

  // Detalhes para Utilizadores
  const getDetalhesUtilizadores = () => {
    if (!apiData) return [];
    return [
      { label: "Total Utilizadores", valor: formatarNumero(apiData.total), percentual: "" },
      { label: "Verificados", valor: formatarNumero(apiData.verificados), percentual: `${Math.round((apiData.verificados / apiData.total) * 100)}%` },
      { label: "Login Google", valor: formatarNumero(apiData.auth_google), percentual: `${Math.round((apiData.auth_google / apiData.total) * 100)}%` }
    ];
  };

  // Funções auxiliares para Alojamentos
  const getTipoCount = (tipo) => {
    if (!apiData?.distribuicao_tipos) return '0';
    const item = apiData.distribuicao_tipos.find(t => t.tipo === tipo);
    return item ? formatarNumero(item.total) : '0';
  };

  const getTipoPercentual = (tipo) => {
    if (!apiData?.distribuicao_tipos || !apiData.total) return '0%';
    const item = apiData.distribuicao_tipos.find(t => t.tipo === tipo);
    if (!item) return '0%';
    return `${Math.round((item.total / apiData.total) * 100)}%`;
  };

  // Funções auxiliares para Carros
  const getCarroTipoCount = (tipo) => {
    if (!apiData?.distribuicao_tipos) return '0';
    const item = apiData.distribuicao_tipos.find(t => t.tipo === tipo);
    return item ? formatarNumero(item.total) : '0';
  };

  const getCarroTipoPercentual = (tipo) => {
    if (!apiData?.distribuicao_tipos || !apiData.total) return '0%';
    const item = apiData.distribuicao_tipos.find(t => t.tipo === tipo);
    if (!item) return '0%';
    return `${Math.round((item.total / apiData.total) * 100)}%`;
  };

  const calcularPrecoMedioGeral = () => {
    if (!apiData?.precos_por_tipo || apiData.precos_por_tipo.length === 0) return 0;
    const soma = apiData.precos_por_tipo.reduce((acc, p) => acc + parseFloat(p.preco_medio), 0);
    return soma / apiData.precos_por_tipo.length;
  };

  // Funções auxiliares para Experiências
  const getCategoriaCount = (categoria) => {
    if (!apiData?.distribuicao_categorias) return '0';
    const item = apiData.distribuicao_categorias.find(c => c.categoria === categoria);
    return item ? formatarNumero(item.total) : '0';
  };

  const getCategoriaPercentual = (categoria) => {
    if (!apiData?.distribuicao_categorias || !apiData.total) return '0%';
    const item = apiData.distribuicao_categorias.find(c => c.categoria === categoria);
    if (!item) return '0%';
    return `${Math.round((item.total / apiData.total) * 100)}%`;
  };

  const getCategoriaRating = (categoria) => {
    if (!apiData?.distribuicao_categorias) return 0;
    const item = apiData.distribuicao_categorias.find(c => c.categoria === categoria);
    return item ? parseFloat(item.rating_medio).toFixed(1) : 0;
  };

  const calcularPrecoMedioExperiencias = () => {
    if (!apiData?.precos_por_categoria || apiData.precos_por_categoria.length === 0) return 0;
    const soma = apiData.precos_por_categoria.reduce((acc, p) => acc + parseFloat(p.preco_medio), 0);
    return soma / apiData.precos_por_categoria.length;
  };

  // Títulos dos relatórios
  const getTitulo = () => {
    switch(relatorioAtivo) {
      case 'alojamentos': return 'Relatório de Alojamentos';
      case 'carros': return 'Relatório de Viaturas';
      case 'experiencias': return 'Relatório de Experiências';
      case 'utilizadores': return 'Relatório de Utilizadores';
      case 'financeiro': return 'Relatório Financeiro';
      default: return 'Relatório de Alojamentos';
    }
  };

  // Detalhes atuais
  const getDetalhesAtuais = () => {
    switch(relatorioAtivo) {
      case 'alojamentos': return getDetalhesAlojamentos();
      case 'carros': return getDetalhesCarros();
      case 'experiencias': return getDetalhesExperiencias();
      case 'utilizadores': return getDetalhesUtilizadores();
      case 'financeiro': return [];
      default: return getDetalhesAlojamentos();
    }
  };

  // Cores para categorias de experiências
  const getCategoriaCor = (categoria) => {
    const cores = {
      aventura: '#FF6B6B',
      cultural: '#4ECDC4',
      gastronomia: '#FFE66D',
      natureza: '#95E77E',
      relax: '#A8E6CF'
    };
    return cores[categoria] || '#003580';
  };

  return (
    <div className="space-y-6">
      {/* Cabeçalho */}
      <div className="flex justify-between items-center flex-wrap gap-4">
        <div>
          <h1 className="text-3xl font-semibold text-[#003580]">Relatórios</h1>
          <p className="text-gray-600 mt-1">
            {getTitulo()}
            {relatorioAtivo !== 'geral' && (
              <span className="ml-2 text-sm text-[#003580] font-medium">
                • Dados específicos
              </span>
            )}
          </p>
        </div>
        <button className="flex items-center gap-2 bg-[#003580] text-white px-4 py-2 rounded-xl hover:bg-[#002060] transition">
          <Download size={18} /> Exportar PDF
        </button>
      </div>

      {/* Cards Principais */}
      <div className={`transition-all duration-300 ${loading ? 'opacity-50' : 'opacity-100'}`}>
        {relatorioAtivo === 'financeiro' ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {/* A receber */}
            <div className="bg-gradient-to-br from-blue-50 to-white p-5 rounded-2xl shadow-sm border border-blue-100">
              <Clock className="text-blue-500 mb-2" size={24} />
              <p className="text-xl font-bold mt-1">{formatarMoeda(financeiro.a_receber.bruto)}</p>
              <p className="text-sm text-gray-500">A receber</p>
              <div className="mt-3 text-xs space-y-0.5 border-t border-gray-100 pt-2">
                <div className="flex justify-between"><span className="text-gray-500">Bruto</span><span className="font-medium">{formatarMoeda(financeiro.a_receber.bruto)}</span></div>
                <div className="flex justify-between"><span className="text-gray-500">Comissão 10%</span><span className="font-medium text-[#003580]">{formatarMoeda(financeiro.a_receber.comissao)}</span></div>
                {financeiro.a_receber.taxas > 0 && (
                  <div className="flex justify-between"><span className="text-gray-500">Taxas</span><span className="font-medium">{formatarMoeda(financeiro.a_receber.taxas)}</span></div>
                )}
                <div className="flex justify-between"><span className="text-gray-500">Líquido</span><span className="font-semibold text-green-700">{formatarMoeda(financeiro.a_receber.liquido)}</span></div>
              </div>
            </div>

            {/* Disponível */}
            <div className="bg-gradient-to-br from-green-50 to-white p-5 rounded-2xl shadow-sm border border-green-100">
              <Wallet className="text-green-500 mb-2" size={24} />
              <p className="text-xl font-bold mt-1">{formatarMoeda(financeiro.disponivel.bruto)}</p>
              <p className="text-sm text-gray-500">Disponível</p>
              <div className="mt-3 text-xs space-y-0.5 border-t border-gray-100 pt-2">
                <div className="flex justify-between"><span className="text-gray-500">Bruto</span><span className="font-medium">{formatarMoeda(financeiro.disponivel.bruto)}</span></div>
                <div className="flex justify-between"><span className="text-gray-500">Comissão 10%</span><span className="font-medium text-[#003580]">{formatarMoeda(financeiro.disponivel.comissao)}</span></div>
                {financeiro.disponivel.taxas > 0 && (
                  <div className="flex justify-between"><span className="text-gray-500">Taxas</span><span className="font-medium">{formatarMoeda(financeiro.disponivel.taxas)}</span></div>
                )}
                <div className="flex justify-between"><span className="text-gray-500">Líquido</span><span className="font-semibold text-green-700">{formatarMoeda(financeiro.disponivel.liquido)}</span></div>
              </div>
            </div>

            {/* Pago */}
            <div className="bg-gradient-to-br from-emerald-50 to-white p-5 rounded-2xl shadow-sm border border-emerald-100">
              <CheckCircle className="text-emerald-500 mb-2" size={24} />
              <p className="text-xl font-bold mt-1">{formatarMoeda(financeiro.pago.bruto)}</p>
              <p className="text-sm text-gray-500">Pago</p>
              <div className="mt-3 text-xs space-y-0.5 border-t border-gray-100 pt-2">
                <div className="flex justify-between"><span className="text-gray-500">Bruto</span><span className="font-medium">{formatarMoeda(financeiro.pago.bruto)}</span></div>
                <div className="flex justify-between"><span className="text-gray-500">Comissão 10%</span><span className="font-medium text-[#003580]">{formatarMoeda(financeiro.pago.comissao)}</span></div>
                {financeiro.pago.taxas > 0 && (
                  <div className="flex justify-between"><span className="text-gray-500">Taxas</span><span className="font-medium">{formatarMoeda(financeiro.pago.taxas)}</span></div>
                )}
                <div className="flex justify-between"><span className="text-gray-500">Líquido</span><span className="font-semibold text-green-700">{formatarMoeda(financeiro.pago.liquido)}</span></div>
              </div>
            </div>

            {/* Falhou */}
            <div className="bg-gradient-to-br from-red-50 to-white p-5 rounded-2xl shadow-sm border border-red-100">
              <XCircle className="text-red-500 mb-2" size={24} />
              <p className="text-xl font-bold mt-1">{formatarMoeda(financeiro.falhou.bruto)}</p>
              <p className="text-sm text-gray-500">Falhou</p>
              <div className="mt-3 text-xs space-y-0.5 border-t border-gray-100 pt-2">
                <div className="flex justify-between"><span className="text-gray-500">Bruto</span><span className="font-medium">{formatarMoeda(financeiro.falhou.bruto)}</span></div>
                <div className="flex justify-between"><span className="text-gray-500">Comissão 10%</span><span className="font-medium text-[#003580]">{formatarMoeda(financeiro.falhou.comissao)}</span></div>
                {financeiro.falhou.taxas > 0 && (
                  <div className="flex justify-between"><span className="text-gray-500">Taxas</span><span className="font-medium">{formatarMoeda(financeiro.falhou.taxas)}</span></div>
                )}
                <div className="flex justify-between"><span className="text-gray-500">Líquido</span><span className="font-semibold text-green-700">{formatarMoeda(financeiro.falhou.liquido)}</span></div>
              </div>
            </div>

            {/* Retido */}
            <div className="bg-gradient-to-br from-orange-50 to-white p-5 rounded-2xl shadow-sm border border-orange-100">
              <Lock className="text-orange-500 mb-2" size={24} />
              <p className="text-xl font-bold mt-1">{formatarMoeda(financeiro.retido.bruto)}</p>
              <p className="text-sm text-gray-500">Retido</p>
              <div className="mt-3 text-xs space-y-0.5 border-t border-gray-100 pt-2">
                <div className="flex justify-between"><span className="text-gray-500">Bruto</span><span className="font-medium">{formatarMoeda(financeiro.retido.bruto)}</span></div>
                <div className="flex justify-between"><span className="text-gray-500">Comissão 10%</span><span className="font-medium text-[#003580]">{formatarMoeda(financeiro.retido.comissao)}</span></div>
                {financeiro.retido.taxas > 0 && (
                  <div className="flex justify-between"><span className="text-gray-500">Taxas</span><span className="font-medium">{formatarMoeda(financeiro.retido.taxas)}</span></div>
                )}
                <div className="flex justify-between"><span className="text-gray-500">Líquido</span><span className="font-semibold text-green-700">{formatarMoeda(financeiro.retido.liquido)}</span></div>
              </div>
            </div>

            {/* Reembolsado */}
            <div className="bg-gradient-to-br from-gray-50 to-white p-5 rounded-2xl shadow-sm border border-gray-100">
              <RotateCcw className="text-gray-500 mb-2" size={24} />
              <p className="text-xl font-bold mt-1">{formatarMoeda(financeiro.reembolsado.bruto)}</p>
              <p className="text-sm text-gray-500">Reembolsado</p>
              <div className="mt-3 text-xs space-y-0.5 border-t border-gray-100 pt-2">
                <div className="flex justify-between"><span className="text-gray-500">Bruto</span><span className="font-medium">{formatarMoeda(financeiro.reembolsado.bruto)}</span></div>
                <div className="flex justify-between"><span className="text-gray-500">Comissão 10%</span><span className="font-medium text-[#003580]">{formatarMoeda(financeiro.reembolsado.comissao)}</span></div>
                {financeiro.reembolsado.taxas > 0 && (
                  <div className="flex justify-between"><span className="text-gray-500">Taxas</span><span className="font-medium">{formatarMoeda(financeiro.reembolsado.taxas)}</span></div>
                )}
                <div className="flex justify-between"><span className="text-gray-500">Líquido</span><span className="font-semibold text-green-700">{formatarMoeda(financeiro.reembolsado.liquido)}</span></div>
              </div>
            </div>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            <div className="bg-gradient-to-br from-blue-50 to-white p-6 rounded-2xl shadow-sm border border-blue-100">
              <Users className="text-blue-500 mb-2" size={24} />
              <p className="text-2xl font-bold">{formatarNumero(stats.total)}</p>
              <p className="text-sm text-gray-500">
                {relatorioAtivo === 'utilizadores' ? 'Total de Utilizadores' : 
                 relatorioAtivo === 'alojamentos' ? 'Alojamentos' :
                 relatorioAtivo === 'carros' ? 'Viaturas' : 'Experiências'}
              </p>
              {stats.crescimento > 0 && (
                <p className="text-xs text-green-600 mt-2">+{stats.crescimento}% este mês</p>
              )}
            </div>
            
            <div className="bg-gradient-to-br from-green-50 to-white p-6 rounded-2xl shadow-sm border border-green-100">
              <DollarSign className="text-green-500 mb-2" size={24} />
              <p className="text-2xl font-bold">{formatarMoeda(stats.faturacaoTotal)}</p>
              <p className="text-sm text-gray-500">Faturação Total</p>
            </div>
            
            <div className="bg-gradient-to-br from-purple-50 to-white p-6 rounded-2xl shadow-sm border border-purple-100">
              <Calendar className="text-purple-500 mb-2" size={24} />
              <p className="text-2xl font-bold">{formatarNumero(stats.reservasMes)}</p>
              <p className="text-sm text-gray-500">Reservas</p>
            </div>
            
            <div className="bg-gradient-to-br from-orange-50 to-white p-6 rounded-2xl shadow-sm border border-orange-100">
              <Star className="text-orange-500 mb-2" size={24} />
              <p className="text-2xl font-bold">{stats.avaliacaoMedia === 0 ? 'N/A' : stats.avaliacaoMedia + ' ★'}</p>
              <p className="text-sm text-gray-500">Avaliação Média</p>
            </div>
          </div>
        )}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Menu de Relatórios Específicos */}
        <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6">
          <h3 className="font-semibold text-gray-800 mb-4 flex items-center gap-2">
            <FileText size={18} className="text-[#003580]" />
            Relatórios por Categoria
          </h3>
          <div className="space-y-2">
            <button 
              onClick={() => handleRelatorioClick('alojamentos')}
              className={`w-full text-left p-3 rounded-lg transition flex items-center gap-3 ${
                relatorioAtivo === 'alojamentos' 
                  ? 'bg-[#003580] text-white' 
                  : 'bg-gray-50 hover:bg-gray-100 text-gray-700'
              }`}
            >
              <Home size={18} />
              <span className="flex-1">Alojamentos</span>
              <span className="text-xs">27</span>
            </button>
            
            <button 
              onClick={() => handleRelatorioClick('carros')}
              className={`w-full text-left p-3 rounded-lg transition flex items-center gap-3 ${
                relatorioAtivo === 'carros' 
                  ? 'bg-[#003580] text-white' 
                  : 'bg-gray-50 hover:bg-gray-100 text-gray-700'
              }`}
            >
              <Car size={18} />
              <span className="flex-1">Viaturas</span>
              <span className="text-xs">15</span>
            </button>
            
            <button 
              onClick={() => handleRelatorioClick('experiencias')}
              className={`w-full text-left p-3 rounded-lg transition flex items-center gap-3 ${
                relatorioAtivo === 'experiencias' 
                  ? 'bg-[#003580] text-white' 
