import React, { useState, useEffect } from 'react';
import { 
  MailCheck, CheckCircle, XCircle, Clock, Search, 
  Loader2, User, Mail, Phone, Calendar, Eye, 
  Trash2, Check, X, AlertCircle, RefreshCw, Filter, Users
} from 'lucide-react';

const VerificacoesEmail = () => {
  const [usuarios, setUsuarios] = useState([]);
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState('todos');
  const [selectedUser, setSelectedUser] = useState(null);
  const [showModal, setShowModal] = useState(false);
  const [showRejectModal, setShowRejectModal] = useState(false);
  const [motivoRejeicao, setMotivoRejeicao] = useState('');
  const [actionLoading, setActionLoading] = useState(false);

  const carregarVerificacoes = async () => {
    setLoading(true);
    try {
      const url = `https://welovepalop.com/api/admin/verificacoes_email.php?action=listar&status=${filterStatus}&search=${encodeURIComponent(search)}`;
      const response = await fetch(url);
      const data = await response.json();
      if (data.status === 'success') {
        setUsuarios(data.data);
        setStats(data.stats);
      }
    } catch (err) {
      console.error('Erro:', err);
    }
    setLoading(false);
  };

  useEffect(() => {
    carregarVerificacoes();
  }, [filterStatus, search]);

  const verificarEmail = async (id) => {
    setActionLoading(true);
    try {
      const response = await fetch('/api/admin/verificacoes_email.php?action=verificar', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id })
      });
      const data = await response.json();
      if (data.status === 'success') {
        carregarVerificacoes();
        setShowModal(false);
        setSelectedUser(null);
      } else {
        alert('Erro: ' + data.message);
      }
    } catch (err) {
      console.error('Erro:', err);
      alert('Erro de conexão');
    }
    setActionLoading(false);
  };

  const rejeitarVerificacao = async (id) => {
    if (!motivoRejeicao.trim()) {
      alert('Por favor, insira um motivo para a rejeição');
      return;
    }
    
    setActionLoading(true);
    try {
      const response = await fetch('/api/admin/verificacoes_email.php?action=rejeitar', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id, motivo: motivoRejeicao })
      });
      const data = await response.json();
      if (data.status === 'success') {
        carregarVerificacoes();
        setShowRejectModal(false);
        setShowModal(false);
        setSelectedUser(null);
        setMotivoRejeicao('');
      } else {
        alert('Erro: ' + data.message);
      }
    } catch (err) {
      console.error('Erro:', err);
      alert('Erro de conexão');
    }
    setActionLoading(false);
  };

  const removerUtilizador = async (id) => {
    if (!window.confirm('Tem certeza que deseja remover este utilizador? Esta ação não pode ser desfeita.')) {
      return;
    }
    
    setActionLoading(true);
    try {
      const response = await fetch('/api/admin/verificacoes_email.php?action=remover', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id })
      });
      const data = await response.json();
      if (data.status === 'success') {
        carregarVerificacoes();
        setShowModal(false);
        setSelectedUser(null);
      } else {
        alert('Erro: ' + data.message);
      }
    } catch (err) {
      console.error('Erro:', err);
      alert('Erro de conexão');
    }
    setActionLoading(false);
  };

  const formatarData = (data) => {
    if (!data) return '-';
    const d = new Date(data);
    return d.toLocaleDateString('pt-PT', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
  };

  const StatusBadge = ({ usuario }) => {
    if (usuario.email_verificado === 1) {
      return (
        <span className="flex items-center gap-1 px-2 py-1 bg-green-100 text-green-700 rounded-md text-xs font-semibold">
          <CheckCircle size={12} /> Verificado
        </span>
      );
    }
    const criadoEm = new Date(usuario.criado_em);
    const diasDesdeCriacao = (new Date() - criadoEm) / (1000 * 60 * 60 * 24);
    if (diasDesdeCriacao < 7) {
      return (
        <span className="flex items-center gap-1 px-2 py-1 bg-yellow-100 text-yellow-700 rounded-md text-xs font-semibold">
          <Clock size={12} /> Pendente
        </span>
      );
    }
    return (
      <span className="flex items-center gap-1 px-2 py-1 bg-red-100 text-red-700 rounded-md text-xs font-semibold">
        <XCircle size={12} /> Rejeitado
      </span>
    );
  };

  return (
    <div className="space-y-6">
      {/* Cabeçalho */}
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-semibold text-[#003580]">Verificações de Email</h1>
          <p className="text-gray-600 mt-1">Gestão de verificações de email dos utilizadores.</p>
        </div>
        <button 
          onClick={carregarVerificacoes} 
          className="flex items-center gap-2 px-4 py-2 bg-white rounded-lg border border-gray-200 hover:bg-gray-50"
        >
          <RefreshCw size={16} /> Atualizar
        </button>
      </div>

      {/* Estatísticas */}
      {stats && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
          <div className="bg-white/80 backdrop-blur-md p-6 rounded-2xl border border-white text-center">
            <MailCheck className="mx-auto text-green-500 mb-2" size={32} />
            <p className="text-2xl font-bold text-gray-800">{stats.verificados}</p>
            <p className="text-sm text-gray-500">Emails Verificados</p>
          </div>
          <div className="bg-white/80 backdrop-blur-md p-6 rounded-2xl border border-white text-center">
            <Clock className="mx-auto text-yellow-500 mb-2" size={32} />
            <p className="text-2xl font-bold text-gray-800">{stats.pendentes}</p>
            <p className="text-sm text-gray-500">Pendentes</p>
          </div>
          <div className="bg-white/80 backdrop-blur-md p-6 rounded-2xl border border-white text-center">
            <XCircle className="mx-auto text-red-500 mb-2" size={32} />
            <p className="text-2xl font-bold text-gray-800">{stats.rejeitados}</p>
            <p className="text-sm text-gray-500">Rejeitados</p>
          </div>
          <div className="bg-white/80 backdrop-blur-md p-6 rounded-2xl border border-white text-center">
            <Users size={32} className="mx-auto text-blue-500 mb-2" />
            <p className="text-2xl font-bold text-gray-800">{stats.total}</p>
            <p className="text-sm text-gray-500">Total Utilizadores</p>
          </div>
        </div>
      )}

      {/* Filtros e Busca */}
      <div className="flex flex-col sm:flex-row gap-4 justify-between">
        <div className="flex gap-2 flex-wrap">
          <button
            onClick={() => setFilterStatus('todos')}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
              filterStatus === 'todos' 
                ? 'bg-[#003580] text-white' 
                : 'bg-white text-gray-600 hover:bg-gray-100'
            }`}
          >
            Todos
          </button>
          <button
            onClick={() => setFilterStatus('verificados')}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition flex items-center gap-1 ${
              filterStatus === 'verificados' 
                ? 'bg-green-600 text-white' 
                : 'bg-white text-gray-600 hover:bg-gray-100'
            }`}
          >
            <CheckCircle size={14} /> Verificados
          </button>
          <button
            onClick={() => setFilterStatus('pendentes')}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition flex items-center gap-1 ${
              filterStatus === 'pendentes' 
                ? 'bg-yellow-600 text-white' 
                : 'bg-white text-gray-600 hover:bg-gray-100'
            }`}
          >
            <Clock size={14} /> Pendentes
          </button>
          <button
            onClick={() => setFilterStatus('rejeitados')}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition flex items-center gap-1 ${
              filterStatus === 'rejeitados' 
                ? 'bg-red-600 text-white' 
                : 'bg-white text-gray-600 hover:bg-gray-100'
            }`}
          >
            <XCircle size={14} /> Rejeitados
          </button>
        </div>

        <div className="relative w-full sm:w-80">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={18} />
          <input 
            type="text" 
            placeholder="Procurar por nome ou email..." 
            value={search} 
            onChange={(e) => setSearch(e.target.value)} 
            className="w-full pl-10 pr-4 py-2 bg-white rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-[#003580]/20" 
          />
        </div>
      </div>

      {/* Tabela de Utilizadores */}
      {loading ? (
        <div className="py-20 flex justify-center items-center gap-2">
          <Loader2 className="animate-spin text-[#003580]" size={24} />
          <span className="text-gray-600">A carregar verificações...</span>
        </div>
      ) : usuarios.length === 0 ? (
        <div className="py-20 text-center text-gray-500">
          <MailCheck size={48} className="mx-auto mb-4 text-gray-300" />
          <p>Nenhum utilizador encontrado</p>
        </div>
      ) : (
        <div className="bg-white/80 backdrop-blur-md rounded-2xl border border-white overflow-hidden shadow-sm">
          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
              <thead className="bg-gray-50/50 text-[11px] uppercase tracking-wider text-gray-500 border-b border-gray-200">
                <tr>
                  <th className="px-6 py-4">Utilizador</th>
                  <th className="px-6 py-4">Contacto</th>
                  <th className="px-6 py-4">Data Registo</th>
                  <th className="px-6 py-4">Verificação</th>
                  <th className="px-6 py-4 text-center">Ações</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {usuarios.map((usuario) => (
                  <tr key={usuario.id} className="hover:bg-gray-50/50 transition-colors">
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-3">
                        <img 
                          src={usuario.foto || `https://ui-avatars.com/api/?name=${encodeURIComponent(usuario.nome)}&background=003580&color=fff`} 
                          alt={usuario.nome}
                          className="w-10 h-10 rounded-full object-cover"
                        />
                        <div>
                          <div className="font-medium text-gray-900">{usuario.nome}</div>
                          <div className="text-xs text-gray-400 flex items-center gap-1">
                            <Mail size={10} /> {usuario.email}
                          </div>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      {usuario.phone ? (
                        <div className="flex items-center gap-1 text-gray-600">
                          <Phone size={14} />
                          <span className="text-sm">{usuario.phone}</span>
                        </div>
                      ) : (
                        <span className="text-xs text-gray-400">Sem telefone</span>
                      )}
                    </td>
                    <td className="px-6 py-4">
                      <div className="text-sm">{formatarData(usuario.criado_em)}</div>
                      {usuario.email_verificado_em && (
                        <div className="text-xs text-gray-400">Verificado: {formatarData(usuario.email_verificado_em)}</div>
                      )}
                    </td>
                    <td className="px-6 py-4">
                      <StatusBadge usuario={usuario} />
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex justify-center gap-2">
                        <button
                          onClick={() => { setSelectedUser(usuario); setShowModal(true); }}
                          className="p-1.5 text-blue-600 hover:bg-blue-50 rounded-lg transition"
                          title="Ver detalhes"
                        >
                          <Eye size={18} />
                        </button>
                        {usuario.email_verificado !== 1 && (
                          <>
                            <button
                              onClick={() => verificarEmail(usuario.id)}
                              disabled={actionLoading}
                              className="p-1.5 text-green-600 hover:bg-green-50 rounded-lg transition"
                              title="Verificar email"
                            >
                              <Check size={18} />
                            </button>
                            <button
                              onClick={() => { setSelectedUser(usuario); setShowRejectModal(true); }}
                              disabled={actionLoading}
                              className="p-1.5 text-red-600 hover:bg-red-50 rounded-lg transition"
                              title="Rejeitar"
                            >
                              <X size={18} />
                            </button>
                          </>
                        )}
                        <button
                          onClick={() => removerUtilizador(usuario.id)}
                          disabled={actionLoading}
                          className="p-1.5 text-gray-500 hover:bg-gray-100 rounded-lg transition"
                          title="Remover"
                        >
                          <Trash2 size={18} />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Modal de Detalhes */}
      {showModal && selectedUser && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl max-w-md w-full">
            <div className="p-6">
              <div className="flex items-center gap-3 mb-4">
                <img 
                  src={selectedUser.foto || `https://ui-avatars.com/api/?name=${encodeURIComponent(selectedUser.nome)}&background=003580&color=fff&size=80`} 
                  alt={selectedUser.nome}
                  className="w-16 h-16 rounded-full object-cover"
                />
                <div>
                  <h3 className="text-lg font-bold text-gray-800">{selectedUser.nome}</h3>
                  <p className="text-sm text-gray-500 flex items-center gap-1">
                    <Mail size={14} /> {selectedUser.email}
                  </p>
                  {selectedUser.phone && (
                    <p className="text-sm text-gray-500 flex items-center gap-1">
                      <Phone size={14} /> {selectedUser.phone}
                    </p>
                  )}
                </div>
              </div>
              
              <div className="space-y-2 mb-4">
                <div className="flex justify-between py-2 border-b">
                  <span className="text-gray-500">Data de Registo:</span>
                  <span className="font-medium">{formatarData(selectedUser.criado_em)}</span>
                </div>
                <div className="flex justify-between py-2 border-b">
                  <span className="text-gray-500">Status:</span>
                  <StatusBadge usuario={selectedUser} />
                </div>
                {selectedUser.email_verificado_em && (
                  <div className="flex justify-between py-2 border-b">
                    <span className="text-gray-500">Verificado em:</span>
                    <span className="font-medium">{formatarData(selectedUser.email_verificado_em)}</span>
                  </div>
                )}
                <div className="flex justify-between py-2 border-b">
                  <span className="text-gray-500">Tipo de Conta:</span>
                  <span className="font-medium capitalize">{selectedUser.tipo_conta || 'Hóspede'}</span>
                </div>
              </div>

              <div className="flex gap-3">
                {selectedUser.email_verificado !== 1 && (
                  <>
                    <button 
                      onClick={() => verificarEmail(selectedUser.id)}
                      disabled={actionLoading}
                      className="flex-1 flex items-center justify-center gap-2 bg-green-600 hover:bg-green-700 text-white py-2 rounded-xl"
                    >
                      {actionLoading ? <Loader2 size={18} className="animate-spin" /> : <Check size={18} />}
                      Verificar
                    </button>
                    <button 
                      onClick={() => { setShowModal(false); setShowRejectModal(true); }}
                      className="flex-1 flex items-center justify-center gap-2 bg-red-600 hover:bg-red-700 text-white py-2 rounded-xl"
                    >
                      <X size={18} /> Rejeitar
                    </button>
                  </>
                )}
                <button 
                  onClick={() => setShowModal(false)}
                  className="flex-1 bg-gray-200 hover:bg-gray-300 text-gray-700 py-2 rounded-xl"
                >
                  Fechar
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Modal de Rejeição */}
      {showRejectModal && selectedUser && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl max-w-md w-full">
            <div className="p-6">
              <h3 className="text-lg font-bold text-gray-900 mb-2">Rejeitar Verificação</h3>
              <p className="text-sm text-gray-500 mb-4">
                Motivo da rejeição para <strong>{selectedUser.email}</strong>:
              </p>
              <textarea 
                value={motivoRejeicao} 
                onChange={(e) => setMotivoRejeicao(e.target.value)} 
                rows={4} 
                placeholder="Ex: Email inválido, não respondeu ao email de verificação..."
                className="w-full border border-gray-200 rounded-xl p-3 focus:outline-none focus:ring-2 focus:ring-red-500/20 text-sm mb-4 resize-none" 
                autoFocus
              />
              <div className="flex gap-3">
                <button 
                  onClick={() => rejeitarVerificacao(selectedUser.id)} 
                  disabled={!motivoRejeicao.trim() || actionLoading}
                  className="flex-1 bg-red-600 hover:bg-red-700 text-white font-semibold py-2.5 rounded-xl transition disabled:opacity-50"
                >
                  {actionLoading ? <Loader2 size={18} className="animate-spin mx-auto" /> : 'Confirmar Rejeição'}
                </button>
                <button 
                  onClick={() => { setShowRejectModal(false); setMotivoRejeicao(''); setSelectedUser(null); }}
                  className="flex-1 bg-gray-200 hover:bg-gray-300 text-gray-700 font-semibold py-2.5 rounded-xl transition"
                >
                  Cancelar
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default VerificacoesEmail;

import React, { createContext, useContext, useState, useCallback } from 'react';
import { CheckCircle, AlertCircle, X, Info } from 'lucide-react';

const ToastContext = createContext(null);

export const ToastProvider = ({ children }) => {
  const [toast, setToast] = useState(null);

  const showToast = useCallback((message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3500);
  }, []);

  return (
    <ToastContext.Provider value={{ showToast }}>
      {children}
      {toast && (
        <div className="fixed bottom-6 right-6 z-[9999] flex items-center gap-3 px-5 py-3 rounded-xl shadow-2xl text-white bg-gray-900 border border-gray-800">
          {toast.type === 'success' && <CheckCircle size={20} className="text-green-400 shrink-0" />}
          {toast.type === 'error' && <AlertCircle size={20} className="text-red-400 shrink-0" />}
          {toast.type === 'info' && <Info size={20} className="text-blue-400 shrink-0" />}
          <span className="text-sm font-medium tracking-wide">{toast.message}</span>
          <button onClick={() => setToast(null)} className="ml-2 text-gray-400 hover:text-white transition-colors">
            <X size={16} />
          </button>
        </div>
      )}
    </ToastContext.Provider>
  );
};

export const useToast = () => {
  const context = useContext(ToastContext);
  if (!context) throw new Error('useToast deve ser usado dentro de um ToastProvider');
  return context;
};

// src/components/gest/Avaliacoes.jsx
import React, { useState, useEffect } from 'react';
import { Star, Loader2, Home, Car, Compass, Award } from 'lucide-react';

export default function Avaliacoes() {
  const [loading, setLoading] = useState(true);
  const [avaliacoes, setAvaliacoes] = useState([]);
  const [estatisticas, setEstatisticas] = useState([]);
  const [mediaGeral, setMediaGeral] = useState(0);
  const [totalAvaliacoes, setTotalAvaliacoes] = useState(0);
  const [filtro, setFiltro] = useState('todos');
  const [usuarioLogado, setUsuarioLogado] = useState(null);
  const [userRoles, setUserRoles] = useState({
    anfitrion: false,
    guia: false,
    proprietarioVeiculos: false
  });
  const [tiposDisponiveis, setTiposDisponiveis] = useState([]);

  // Obter ID do utilizador de forma segura (JWT ou LocalStorage)
  const obterUserId = () => {
    try {
      const token = localStorage.getItem('token') || localStorage.getItem('morabeza_token');
      if (token) {
        const base64Url = token.split('.')[1];
        const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
        const jsonPayload = decodeURIComponent(atob(base64).split('').map(c => {
          return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
        }).join(''));
        const parsed = JSON.parse(jsonPayload);
        if (parsed.data?.id) return parsed.data.id;
        if (parsed.id) return parsed.id;
      }
      const savedUser = localStorage.getItem('user') || localStorage.getItem('morabeza_user');
      if (savedUser) {
        const user = JSON.parse(savedUser);
        return user.id;
      }
    } catch (e) {
      console.error('Erro ao obter ID:', e);
    }
    return null;
  };

  useEffect(() => {
    const userId = obterUserId();
    if (userId) {
      const token = localStorage.getItem('token') || localStorage.getItem('morabeza_token');
      // Criar objeto utilizador básico com base no ID se necessário
      let userObj = { id: userId };
      try {
        const savedUser = localStorage.getItem('user') || localStorage.getItem('morabeza_user');
        if (savedUser) {
          userObj = JSON.parse(savedUser);
        }
      } catch (e) {}

      setUsuarioLogado(userObj);
      fetchUserRoles(userId);
    }
  }, []);

  const fetchUserRoles = async (userId) => {
    try {
      const response = await fetch(`https://welovepalop.com/api/usuarios/listar_roles.php?usuario_id=${userId}`);
      const data = await response.json();
      
      if (data.success && data.roles) {
        const isAnfitrion = data.roles.some(r => r.name === 'anfitrion' && r.status === 'approved');
        const isGuia = data.roles.some(r => r.name === 'guia_experiencias' && r.status === 'approved');
        const isProprietarioVeiculos = data.roles.some(r => r.name === 'proprietario_veiculos' && r.status === 'approved');
        
        const tipos = [];
        if (isAnfitrion) tipos.push('alojamentos');
        if (isProprietarioVeiculos) tipos.push('carros');
        if (isGuia) tipos.push('experiencias');
        
        setTiposDisponiveis(tipos);
        setUserRoles({
          anfitrion: isAnfitrion,
          guia: isGuia,
          proprietarioVeiculos: isProprietarioVeiculos
        });
        
        if (filtro !== 'todos' && !tipos.includes(filtro)) {
          setFiltro('todos');
        }
      }
    } catch (error) {
      console.error('Erro ao buscar roles:', error);
    }
  };

  useEffect(() => {
    if (usuarioLogado && tiposDisponiveis.length > 0) {
      fetchAvaliacoes();
    }
  }, [filtro, usuarioLogado, tiposDisponiveis]);

  const fetchAvaliacoes = async () => {
    setLoading(true);
    try {
      let todasAvaliacoes = [];
      let todasEstatisticas = [];
      
      if (filtro === 'todos') {
        for (const tipo of tiposDisponiveis) {
          const response = await fetch(`https://welovepalop.com/api/avaliacoes/listar.php?usuario_id=${usuarioLogado.id}&tipo=${tipo}`);
          const data = await response.json();
          
          if (data.success && data.data) {
            todasAvaliacoes = [...todasAvaliacoes, ...(data.data.avaliacoes || [])];
            if (data.data.estatisticas) {
              todasEstatisticas = [...todasEstatisticas, ...data.data.estatisticas];
            }
          }
        }
      } else {
        const response = await fetch(`https://welovepalop.com/api/avaliacoes/listar.php?usuario_id=${usuarioLogado.id}&tipo=${filtro}`);
        const data = await response.json();
        
        if (data.success && data.data) {
          todasAvaliacoes = data.data.avaliacoes || [];
          todasEstatisticas = data.data.estatisticas || [];
        }
      }
      
      setAvaliacoes(todasAvaliacoes);
      setEstatisticas(todasEstatisticas);
      
      if (todasAvaliacoes.length > 0) {
        const soma = todasAvaliacoes.reduce((acc, curr) => acc + curr.rating, 0);
        setMediaGeral((soma / todasAvaliacoes.length).toFixed(1));
      } else {
        setMediaGeral(0);
      }
      setTotalAvaliacoes(todasAvaliacoes.length);
      
    } catch (error) {
      console.error('Erro ao buscar avaliações:', error);
    } finally {
      setLoading(false);
    }
  };

  const formatarData = (data) => {
    if (!data) return '';
    const date = new Date(data);
    const hoje = new Date();
    const ontem = new Date(hoje);
    ontem.setDate(ontem.getDate() - 1);
    
    if (date.toDateString() === hoje.toDateString()) {
      return 'Hoje';
    } else if (date.toDateString() === ontem.toDateString()) {
      return 'Ontem';
    } else {
      return date.toLocaleDateString('pt-PT', { day: '2-digit', month: 'short', year: 'numeric' });
    }
  };

  const getTipoIcone = (tipo) => {
    switch(tipo) {
      case 'alojamento': return <Home size={14} className="text-blue-500" />;
      case 'carro': return <Car size={14} className="text-green-500" />;
      case 'experiencia': return <Compass size={14} className="text-purple-500" />;
      default: return null;
    }
  };

  const RenderStars = ({ count }) => {
    return (
      <div className="flex gap-1">
        {[1, 2, 3, 4, 5].map((star) => (
          <Star 
            key={star} 
            className={`w-[14px] h-[14px] ${star <= count ? 'fill-[#fbbf24] text-[#fbbf24]' : 'fill-[#e2e8f0] text-[#e2e8f0]'}`} 
          />
        ))}
      </div>
    );
  };

  const RenderStarsLarge = ({ count }) => {
    return (
      <div className="flex items-center gap-1">
        {[1, 2, 3, 4, 5].map((star) => (
          <Star 
            key={star} 
            className={`w-[18px] h-[18px] ${star <= Math.floor(count) ? 'fill-[#fbbf24] text-[#fbbf24]' : 'fill-[#e2e8f0] text-[#e2e8f0]'}`} 
          />
        ))}
      </div>
    );
  };

  const hasAnyRole = userRoles.anfitrion || userRoles.guia || userRoles.proprietarioVeiculos;

  if (loading) {
    return (
      <div className="max-w-6xl w-full text-[#0f172a] px-4 py-6 md:px-0 flex justify-center items-center h-96">
        <Loader2 size={48} className="animate-spin text-blue-900" />
      </div>
    );
  }

  if (!hasAnyRole) {
    return (
      <div className="max-w-6xl w-full text-[#0f172a] px-4 py-6 md:px-0">
        <div className="bg-white rounded-2xl p-12 text-center border border-gray-100 shadow-sm">
          <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
            <Award size={40} className="text-gray-400" />
          </div>
          <h2 className="text-xl font-bold text-gray-800 mb-2">Acesso Restrito</h2>
          <p className="text-gray-500 max-w-md mx-auto">
            Você não tem permissão para aceder às avaliações.
            É necessário ter uma das seguintes funções aprovadas:
            Anfitrião, Guia de Experiências ou Proprietário de Veículos.
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-6xl w-full text-[#0f172a] px-4 py-6 md:px-0">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <h1 className="text-[22px] font-bold">Avaliações dos Clientes</h1>
        
        <div className="flex flex-wrap gap-2">
          {tiposDisponiveis.length > 1 && (
            <button
              onClick={() => setFiltro('todos')}
              className={`px-3 py-1.5 rounded-lg text-sm font-medium transition-colors ${
                filtro === 'todos' ? 'bg-blue-900 text-white' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
              }`}
            >
              Todos
            </button>
          )}
          
          {userRoles.anfitrion && (
            <button
              onClick={() => setFiltro('alojamentos')}
              className={`px-3 py-1.5 rounded-lg text-sm font-medium transition-colors flex items-center gap-1 ${
                filtro === 'alojamentos' ? 'bg-blue-900 text-white' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
              }`}
            >
              <Home size={14} /> Alojamentos
            </button>
          )}
          
          {userRoles.proprietarioVeiculos && (
            <button
              onClick={() => setFiltro('carros')}
              className={`px-3 py-1.5 rounded-lg text-sm font-medium transition-colors flex items-center gap-1 ${
                filtro === 'carros' ? 'bg-blue-900 text-white' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
              }`}
            >
              <Car size={14} /> Carros
            </button>
          )}
          
          {userRoles.guia && (
            <button
              onClick={() => setFiltro('experiencias')}
              className={`px-3 py-1.5 rounded-lg text-sm font-medium transition-colors flex items-center gap-1 ${
                filtro === 'experiencias' ? 'bg-blue-900 text-white' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
              }`}
            >
              <Compass size={14} /> Experiências
            </button>
          )}
        </div>
      </div>

      <div className="bg-white rounded-2xl border border-gray-100 shadow-[0_2px_10px_rgba(0,0,0,0.02)] p-6 md:p-8 mb-8 flex flex-col md:flex-row items-center md:items-start gap-8 md:gap-16">
        <div className="flex flex-col items-center justify-center flex-shrink-0">
          <h3 className="text-[14px] font-bold text-[#0f172a] mb-2">Avaliação Média</h3>
          <span className="text-[48px] font-bold leading-none mb-2">{mediaGeral > 0 ? mediaGeral : '0.0'}</span>
          <RenderStarsLarge count={mediaGeral} />
          <span className="text-[13px] font-medium text-[#64748b] mt-2">({totalAvaliacoes} avaliações)</span>
        </div>

        <div className="flex-1 w-full max-w-md flex flex-col gap-3 pt-2">
          {estatisticas.length > 0 ? (
            estatisticas.map((item) => (
              <div key={item.estrelas} className="flex items-center gap-4">
                <span className="text-[13px] font-semibold text-[#475569] w-20 whitespace-nowrap">
                  {item.estrelas} {item.estrelas === 1 ? 'estrela' : 'estrelas'}
                </span>
                
                <div className="flex-1 h-2 bg-[#f1f5f9] rounded-full overflow-hidden">
                  <div 
                    className="h-full bg-[#fbbf24] rounded-full"
                    style={{ width: `${item.percentagem || 0}%` }}
                  ></div>
                </div>
                
                <span className="text-[13px] font-semibold text-[#475569] w-8 text-right">
                  {item.quantidade || 0}
                </span>
              </div>
            ))
          ) : (
            <div className="text-center text-gray-400 py-4">
              Sem estatísticas disponíveis
            </div>
          )}
        </div>
      </div>

      <div className="space-y-4">
        {avaliacoes.length === 0 ? (
          <div className="bg-white rounded-2xl border border-gray-100 p-8 text-center">
            <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-3">
              <Star size={24} className="text-gray-400" />
            </div>
            <p className="text-gray-400">Nenhuma avaliação encontrada</p>
            <p className="text-sm text-gray-300 mt-2">
              {filtro !== 'todos' && tiposDisponiveis.length > 1
                ? `Nenhuma avaliação para esta categoria ainda`
                : 'As avaliações dos clientes aparecerão aqui assim que receber feedback'}
            </p>
          </div>
        ) : (
          avaliacoes.map((review) => (
            <div key={review.id} className="bg-white rounded-2xl border border-gray-100 shadow-[0_2px_10px_rgba(0,0,0,0.02)] p-5 md:p-6 transition-all hover:shadow-md">
              <div className="flex justify-between items-start mb-4">
                <div className="flex items-center gap-3 md:gap-4">
                  <img 
                    src={review.foto || `https://ui-avatars.com/api/?name=${encodeURIComponent(review.nome_usuario || 'User')}&background=0D8ABC&color=fff&size=100`} 
                    alt={review.nome_usuario} 
                    className="w-10 h-10 md:w-12 md:h-12 rounded-full object-cover border border-gray-200 flex-shrink-0"
                  />
                  <div className="flex flex-col">
                    <span className="text-[14px] md:text-[15px] font-bold text-[#0f172a]">{review.nome_usuario}</span>
                    <div className="flex items-center gap-2">
                      {getTipoIcone(review.tipo)}
                      <span className="text-[12px] md:text-[13px] font-medium text-[#2563eb]">
                        {review.item_titulo}
                      </span>
                    </div>
                  </div>
                </div>
                <span className="text-[12px] md:text-[13px] font-medium text-[#64748b] whitespace-nowrap">
                  {formatarData(review.created_at)}
                </span>
              </div>

              <div className="mb-3">
                <RenderStars count={review.rating} />
              </div>

              <p className="text-[14px] text-[#334155] leading-relaxed">
                {review.comentario}
              </p>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

