                      {dayObj.estado && dayObj.mesAtual && (
                        <>
                          <span className={`sm:hidden w-1.5 h-1.5 rounded-full ${getStatusDotFromEstado(dayObj.estado)}`} />
                          <span className="hidden sm:inline text-[10px] uppercase tracking-wider">{label}</span>
                        </>
                      )}
                    </div>
                  </div>
