                      className="mt-0.5 w-4 h-4 accent-blue-900"
                    />
                    <span className="text-sm text-blue-900">
                      Li e aceito as condições da Morabeza Stay.
                    </span>
                  </label>

                  <div className="flex flex-col sm:flex-row gap-3 pt-2">
                    <button
                      onClick={() => handleAtivarServico(servicoSelecionado)}
                      disabled={loadingRoles || !aceitouCondicoes}
                      className="flex items-center justify-center gap-2 bg-blue-900 hover:bg-blue-950 text-white px-5 py-2.5 rounded-xl text-sm font-semibold transition disabled:opacity-50 disabled:cursor-not-allowed shadow-sm"
                    >
                      {loadingRoles ? (
                        <>
                          <Loader2 size={16} className="animate-spin" /> A ativar...
                        </>
                      ) : (
                        <>
                          Confirmar ativação <ArrowRight size={16} />
                        </>
                      )}
                    </button>
                    <button
                      type="button"
                      onClick={() => {
                        setServicoSelecionado(null);
                        setAceitouCondicoes(false);
                      }}
                      className="px-5 py-2.5 rounded-xl text-sm font-medium border border-blue-200 text-blue-900 hover:bg-blue-100/50 transition"
                    >
                      Cancelar
                    </button>
                  </div>

                  <p className="text-xs text-blue-800/70 pt-1">
                    Sem documentos. Sem aprovação administrativa. Ativação imediata.
                  </p>
                </div>
              )}

              <div className="mt-8 p-4 bg-gray-50 rounded-xl border border-gray-100">
                <h3 className="font-semibold text-gray-800 mb-2 flex items-center gap-2">
                  <Shield className="w-4 h-4" /> Como funciona
                </h3>
                <ul className="text-sm text-gray-600 space-y-1">
                  <li>
                    • <strong>Cliente:</strong> função base da conta — sempre ativa.
                  </li>
                  <li>
                    • <strong>Anfitrião, Guia e Proprietário:</strong> ativas o serviço com um
                    clique e crias o anúncio de seguida.
                  </li>
                  <li>
                    • A análise e pedido de documentos acontecem <strong>por anúncio</strong>,
                    depois de o enviares para revisão.
                  </li>
                </ul>
              </div>
            </div>
          )}

          {activeMenu === 'Privilégios' && (
            <div className="p-6 md:p-8">
              <div className="mb-6">
                <h1 className="text-[24px] font-bold mb-1">Meus Serviços</h1>
                <p className="text-[14px] text-[#64748b]">
                  Gerencie os seus serviços comerciais ativos na plataforma.
                </p>
              </div>

              <div className="space-y-4">
                {isAnfitriao && (
                  <div className="bg-white border border-gray-100 rounded-xl p-5 shadow-sm flex items-start gap-4">
                    <div className="w-12 h-12 bg-blue-100 rounded-xl flex items-center justify-center text-blue-600">
                      <Home className="w-6 h-6" />
                    </div>
                    <div className="flex-1">
                      <h3 className="text-lg font-bold text-gray-900">Proprietário de Alojamentos</h3>
                      <p className="text-sm text-gray-500 mt-1">
                        Permissão ativa para alugar e gerir alojamentos no mapa.
                      </p>
                      <div className="mt-3 flex gap-4 text-sm font-semibold">
                        <button
                          onClick={() => (window.location.href = '/alojamento-registro/meus')}
                          className="text-blue-600 hover:underline"
                        >
                          Ver meus alojamentos →
                        </button>
                        <button
                          onClick={() => (window.location.href = '/alojamento-registro/fluxo')}
                          className="text-green-600 hover:underline"
                        >
                          + Adicionar propriedade
                        </button>
                      </div>
                    </div>
                  </div>
                )}

                {isGuia && (
                  <div className="bg-white border border-gray-100 rounded-xl p-5 shadow-sm flex items-start gap-4">
                    <div className="w-12 h-12 bg-purple-100 rounded-xl flex items-center justify-center text-purple-600">
                      <Compass className="w-6 h-6" />
                    </div>
                    <div className="flex-1">
                      <h3 className="text-lg font-bold text-gray-900">Guia de Experiências</h3>
                      <p className="text-sm text-gray-500 mt-1">
                        Permissão ativa para publicar roteiros e atividades turísticas.
                      </p>
                      <div className="mt-3 flex gap-4 text-sm font-semibold">
                        <button
                          onClick={() => (window.location.href = '/experiencia-registro/meus')}
                          className="text-purple-600 hover:underline"
                        >
                          Ver minhas experiências →
                        </button>
                        <button
                          onClick={() => (window.location.href = '/experiencia-registro/fluxo')}
                          className="text-green-600 hover:underline"
                        >
                          + Criar experiência
                        </button>
                      </div>
                    </div>
                  </div>
                )}

                {isProprietario && (
                  <div className="bg-white border border-gray-100 rounded-xl p-5 shadow-sm flex items-start gap-4">
                    <div className="w-12 h-12 bg-green-100 rounded-xl flex items-center justify-center text-green-600">
                      <Car className="w-6 h-6" />
                    </div>
                    <div className="flex-1">
                      <h3 className="text-lg font-bold text-gray-900">
                        Proprietário de Veículos
                      </h3>
                      <p className="text-sm text-gray-500 mt-1">
                        Permissão ativa para alugar carros e gerir a sua frota.
                      </p>
                      <div className="mt-3 flex gap-4 text-sm font-semibold">
                        <button
                          onClick={() => (window.location.href = '/carro-registro/meus')}
                          className="text-green-600 hover:underline"
                        >
                          Ver meus veículos →
                        </button>
                        <button
                          onClick={() => (window.location.href = '/carro-registro/fluxo')}
                          className="text-green-600 hover:underline"
                        >
                          + Adicionar veículo
                        </button>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            </div>
          )}
        </main>
      </div>
    </div>
  );
}

function SettingRow({ label, name, value, onChange, editando, placeholder }) {
  return (
    <div className="p-6 md:p-8 flex flex-col md:flex-row items-start gap-4 md:gap-0">
      <div className="w-full md:w-1/3">
        <span className="text-[14px] font-bold text-[#0f172a]">{label}</span>
      </div>
      <div className="flex-1 w-full">
        {editando ? (
          <input
            type="text"
            name={name}
            value={value}
            onChange={onChange}
            placeholder={placeholder}
            className="w-full max-w-md px-3 py-2 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500/20 text-[14px]"
          />
        ) : (
          <span className={`text-[14px] ${!value ? 'text-[#64748b]' : 'text-[#334155]'}`}>
            {value || placeholder || 'Não informado'}
          </span>
        )}
      </div>
    </div>
  );
}

// src/components/gest/ConfigurarBloqueios.jsx
import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import {
  Loader2, ArrowLeft, Plus, Trash2, Calendar, AlertCircle,
  Shield, X, Info, Clock, Save
} from 'lucide-react';

const API_BASE = 'https://welovepalop.com';

const TIPOS_BLOQUEIO = [
  { value: 'ferias', label: '🏖️ Férias', cor: 'blue' },
  { value: 'manutencao', label: '🔧 Manutenção', cor: 'orange' },
  { value: 'lotado', label: '📅 Lotado', cor: 'purple' },
  { value: 'outro', label: '📌 Outro', cor: 'slate' }
];

export default function ConfigurarBloqueios() {
  const { id } = useParams();
  const navigate = useNavigate();

  const [experiencia, setExperiencia] = useState(null);
  const [bloqueios, setBloqueios] = useState([]);
  const [loading, setLoading] = useState(true);
  const [mostrarModal, setMostrarModal] = useState(false);
  const [deletandoId, setDeletandoId] = useState(null);
  const [toast, setToast] = useState({ show: false, message: '', type: '' });

  // Configurações
  const [config, setConfig] = useState({
    antecedencia_minima_horas: 24,
    antecedencia_maxima_dias: 180,
    max_reservas_por_cliente: '',
    preco_epoca_alta: '',
    epoca_alta_inicio: '',
    epoca_alta_fim: ''
  });
  const [salvandoConfig, setSalvandoConfig] = useState(false);

  // Form de bloqueio
  const [formBloqueio, setFormBloqueio] = useState({
    data_inicio: new Date().toISOString().split('T')[0],
    data_fim: new Date().toISOString().split('T')[0],
    motivo: '',
    tipo: 'ferias'
  });

  const showToast = (message, type = 'success') => {
    setToast({ show: true, message, type });
    setTimeout(() => setToast({ show: false, message: '', type: '' }), 3000);
  };

  // Carregar dados
  useEffect(() => {
    const fetchDados = async () => {
      if (!id) return;
      setLoading(true);
      try {
        const [resExp, resBloq] = await Promise.all([
          fetch(`${API_BASE}/api/get_experiencias.php?id=${id}`),
          fetch(`${API_BASE}/api/bloqueios_experiencia.php?experiencia_id=${id}`)
        ]);

        const dataExp = await resExp.json();
        const exp = Array.isArray(dataExp.data) ? dataExp.data[0] : dataExp.data;
        setExperiencia(exp);

        if (exp) {
          setConfig({
            antecedencia_minima_horas: exp.antecedencia_minima_horas ?? 24,
            antecedencia_maxima_dias: exp.antecedencia_maxima_dias ?? 180,
            max_reservas_por_cliente: exp.max_reservas_por_cliente ?? '',
            preco_epoca_alta: exp.preco_epoca_alta ?? '',
            epoca_alta_inicio: exp.epoca_alta_inicio ?? '',
            epoca_alta_fim: exp.epoca_alta_fim ?? ''
          });
        }

        const dataBloq = await resBloq.json();
        if (dataBloq.success) {
          setBloqueios(dataBloq.bloqueios || []);
        }
      } catch (err) {
        console.error('Erro ao carregar dados:', err);
        showToast('Erro ao carregar dados', 'error');
      } finally {
        setLoading(false);
      }
    };
    fetchDados();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  // Criar bloqueio
  const criarBloqueio = async () => {
    if (!formBloqueio.data_inicio || !formBloqueio.data_fim) {
      showToast('Preencha as datas', 'error');
      return;
    }

    try {
      const res = await fetch(`${API_BASE}/api/bloqueios_experiencia.php`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...formBloqueio, experiencia_id: parseInt(id) })
      });
      const data = await res.json();

      if (data.success) {
        showToast('Bloqueio criado!', 'success');
        setMostrarModal(false);
        setFormBloqueio({
          data_inicio: new Date().toISOString().split('T')[0],
          data_fim: new Date().toISOString().split('T')[0],
          motivo: '',
          tipo: 'ferias'
        });
        // Recarregar
        const resBloq = await fetch(`${API_BASE}/api/bloqueios_experiencia.php?experiencia_id=${id}`);
        const dataBloq = await resBloq.json();
        if (dataBloq.success) setBloqueios(dataBloq.bloqueios || []);
      } else {
        showToast(data.error || 'Erro ao criar', 'error');
      }
    } catch (err) {
      console.error(err);
      showToast('Erro de conexão', 'error');
    }
  };

  // Deletar bloqueio
  const deletarBloqueio = async (bloqueioId) => {
    if (!window.confirm('Remover este bloqueio?')) return;
    setDeletandoId(bloqueioId);
    try {
      const res = await fetch(`${API_BASE}/api/bloqueios_experiencia.php?id=${bloqueioId}`, {
        method: 'DELETE'
      });
      const data = await res.json();
      if (data.success) {
        showToast('Bloqueio removido', 'success');
        setBloqueios(prev => prev.filter(b => b.id !== bloqueioId));
      } else {
        showToast(data.error || 'Erro ao remover', 'error');
      }
    } catch (err) {
      console.error(err);
    } finally {
      setDeletandoId(null);
    }
  };

  // Guardar configurações
  const guardarConfig = async () => {
    setSalvandoConfig(true);
    try {
      const res = await fetch(`${API_BASE}/api/experiencias.php`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          id: parseInt(id),
          antecedencia_minima_horas: parseInt(config.antecedencia_minima_horas) || 24,
          antecedencia_maxima_dias: parseInt(config.antecedencia_maxima_dias) || 180,
          max_reservas_por_cliente: config.max_reservas_por_cliente ? parseInt(config.max_reservas_por_cliente) : null,
          preco_epoca_alta: config.preco_epoca_alta ? parseFloat(config.preco_epoca_alta) : null,
          epoca_alta_inicio: config.epoca_alta_inicio || null,
          epoca_alta_fim: config.epoca_alta_fim || null
        })
      });
      const data = await res.json();
      if (data.success) {
        showToast('Configurações guardadas!', 'success');
      } else {
        showToast(data.error || 'Erro ao guardar', 'error');
      }
    } catch (err) {
      console.error(err);
      showToast('Erro de conexão', 'error');
    } finally {
      setSalvandoConfig(false);
    }
  };

  const formatarData = (data) => {
    if (!data) return '—';
    return new Date(data + 'T00:00:00').toLocaleDateString('pt-PT', {
      day: '2-digit', month: 'short', year: 'numeric'
    });
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 size={32} className="animate-spin text-blue-600" />
      </div>
    );
  }

  return (
    <div className="text-left">
      {/* TOAST */}
      {toast.show && (
        <div className={`fixed top-4 right-4 z-[100] px-4 py-3 rounded-xl shadow-2xl text-white font-medium text-sm flex items-center gap-2 ${
          toast.type === 'success' ? 'bg-emerald-600' :
          toast.type === 'error' ? 'bg-red-600' : 'bg-amber-600'
        }`}>
          <AlertCircle size={18} />
          <span>{toast.message}</span>
        </div>
      )}

      {/* HEADER */}
      <div className="flex flex-wrap justify-between items-start gap-4 mb-6">
        <div>
          <div className="flex items-center gap-3 mb-2">
            <button
              onClick={() => navigate('/gest/minhas-experiencias')}
              className="w-9 h-9 flex items-center justify-center rounded-xl border border-slate-200 hover:bg-slate-50 transition-colors"
            >
              <ArrowLeft size={16} className="text-slate-600" />
            </button>
            <h1 className="text-2xl font-bold text-slate-900 flex items-center gap-2">
              <Shield className="text-blue-600" size={24} />
              Bloqueios e Regras de Venda
            </h1>
          </div>
          <p className="text-sm text-slate-500 ml-12">
            {experiencia?.titulo || 'Experiência'}
          </p>
        </div>

        <button
          onClick={() => setMostrarModal(true)}
          className="flex items-center gap-2 bg-blue-900 hover:bg-blue-950 text-white font-bold text-sm px-5 py-3 rounded-xl transition shadow-md"
        >
          <Plus size={16} />
          Bloquear Datas
        </button>
      </div>

      {/* SEÇÃO 1: CONFIGURAÇÕES DE ANTECEDÊNCIA */}
      <div className="bg-white rounded-2xl border border-slate-200 p-6 mb-6">
        <div className="flex items-center gap-2 mb-4">
          <Clock className="text-blue-600" size={18} />
          <h2 className="text-base font-bold text-slate-900">Regras de Antecedência</h2>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="text-xs font-bold text-slate-700 block mb-1.5">
              Antecedência mínima (horas)
            </label>
            <input
              type="number"
              min="0"
              value={config.antecedencia_minima_horas}
              onChange={(e) => setConfig(prev => ({ ...prev, antecedencia_minima_horas: e.target.value }))}
              className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-600/20"
            />
            <p className="text-[10px] text-slate-400 mt-1">Cliente deve reservar pelo menos X horas antes</p>
          </div>

          <div>
            <label className="text-xs font-bold text-slate-700 block mb-1.5">
              Antecedência máxima (dias)
            </label>
            <input
              type="number"
              min="1"
              value={config.antecedencia_maxima_dias}
              onChange={(e) => setConfig(prev => ({ ...prev, antecedencia_maxima_dias: e.target.value }))}
              className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-600/20"
            />
            <p className="text-[10px] text-slate-400 mt-1">Cliente só pode reservar até X dias no futuro</p>
          </div>

          <div>
            <label className="text-xs font-bold text-slate-700 block mb-1.5">
              Máx. reservas por cliente (opcional)
            </label>
            <input
              type="number"
              min="1"
              value={config.max_reservas_por_cliente}
              onChange={(e) => setConfig(prev => ({ ...prev, max_reservas_por_cliente: e.target.value }))}
              placeholder="Sem limite"
              className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-600/20"
            />
            <p className="text-[10px] text-slate-400 mt-1">Limite de reservas do mesmo cliente nesta experiência</p>
          </div>

          <div>
            <label className="text-xs font-bold text-slate-700 block mb-1.5">
              Preço época alta (CVE)
            </label>
            <input
              type="number"
              min="0"
              step="0.01"
              value={config.preco_epoca_alta}
              onChange={(e) => setConfig(prev => ({ ...prev, preco_epoca_alta: e.target.value }))}
              placeholder="Sem preço dinâmico"
              className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-600/20"
            />
          </div>

          <div>
            <label className="text-xs font-bold text-slate-700 block mb-1.5">
              Época alta — início
            </label>
            <input
              type="date"
              value={config.epoca_alta_inicio}
              onChange={(e) => setConfig(prev => ({ ...prev, epoca_alta_inicio: e.target.value }))}
              className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-600/20"
            />
          </div>

          <div>
            <label className="text-xs font-bold text-slate-700 block mb-1.5">
              Época alta — fim
            </label>
            <input
              type="date"
              value={config.epoca_alta_fim}
              onChange={(e) => setConfig(prev => ({ ...prev, epoca_alta_fim: e.target.value }))}
              className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-600/20"
            />
          </div>
        </div>

        <button
          onClick={guardarConfig}
          disabled={salvandoConfig}
          className="mt-5 flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs px-5 py-2.5 rounded-xl transition disabled:opacity-50"
        >
          {salvandoConfig ? <Loader2 size={14} className="animate-spin" /> : <Save size={14} />}
          {salvandoConfig ? 'A guardar...' : 'Guardar Configurações'}
        </button>
      </div>

      {/* SEÇÃO 2: DATAS BLOQUEADAS */}
      <div className="bg-white rounded-2xl border border-slate-200 p-6">
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-2">
            <Calendar className="text-orange-500" size={18} />
            <h2 className="text-base font-bold text-slate-900">
              Datas Bloqueadas
              <span className="text-xs font-normal text-slate-400 ml-2">
                ({bloqueios.length})
              </span>
            </h2>
          </div>
        </div>

        {bloqueios.length === 0 ? (
          <div className="text-center py-8 bg-slate-50 rounded-xl">
            <Calendar size={32} className="text-slate-300 mx-auto mb-2" />
            <p className="text-sm text-slate-500">Nenhuma data bloqueada</p>
            <p className="text-xs text-slate-400 mt-1">Bloqueie datas para férias, manutenção ou outros motivos</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
            {bloqueios.map((b) => {
              const tipoInfo = TIPOS_BLOQUEIO.find(t => t.value === b.tipo) || TIPOS_BLOQUEIO[3];
              return (
                <div key={b.id} className="border border-slate-200 rounded-xl p-4 bg-white">
                  <div className="flex items-start justify-between mb-2">
                    <span className={`inline-flex items-center gap-1 px-2 py-1 text-[10px] font-bold rounded-full ${
                      b.tipo === 'ferias' ? 'bg-blue-100 text-blue-700' :
                      b.tipo === 'manutencao' ? 'bg-orange-100 text-orange-700' :
                      b.tipo === 'lotado' ? 'bg-purple-100 text-purple-700' :
                      'bg-slate-100 text-slate-700'
                    }`}>
                      {tipoInfo.label}
                    </span>
                    <button
                      onClick={() => deletarBloqueio(b.id)}
                      disabled={deletandoId === b.id}
                      className="text-red-500 hover:text-red-700 p-1"
                    >
                      {deletandoId === b.id
                        ? <Loader2 size={12} className="animate-spin" />
                        : <Trash2 size={12} />}
                    </button>
                  </div>

                  <p className="text-xs font-bold text-slate-900">
                    {formatarData(b.data_inicio)} → {formatarData(b.data_fim)}
                  </p>

                  {b.motivo && (
                    <p className="text-[11px] text-slate-500 mt-1 line-clamp-2">{b.motivo}</p>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* MODAL DE CRIAR BLOQUEIO */}
      {mostrarModal && (
        <div className="fixed inset-0 z-[100] bg-black/50 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md p-6">
            <div className="flex items-center justify-between mb-5">
              <h3 className="text-lg font-bold text-slate-900 flex items-center gap-2">
                <Calendar size={18} className="text-blue-600" />
                Bloquear Datas
              </h3>
              <button onClick={() => setMostrarModal(false)} className="text-slate-400 hover:text-slate-600">
                <X size={20} />
              </button>
            </div>

            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="text-xs font-bold text-slate-700 block mb-1.5">Data início *</label>
                  <input
                    type="date"
                    value={formBloqueio.data_inicio}
                    min={new Date().toISOString().split('T')[0]}
                    onChange={(e) => setFormBloqueio(prev => ({ ...prev, data_inicio: e.target.value }))}
                    className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-600/20"
                  />
                </div>
                <div>
                  <label className="text-xs font-bold text-slate-700 block mb-1.5">Data fim *</label>
                  <input
                    type="date"
                    value={formBloqueio.data_fim}
                    min={formBloqueio.data_inicio}
                    onChange={(e) => setFormBloqueio(prev => ({ ...prev, data_fim: e.target.value }))}
                    className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-600/20"
                  />
                </div>
              </div>

              <div>
                <label className="text-xs font-bold text-slate-700 block mb-1.5">Tipo</label>
                <div className="grid grid-cols-2 gap-2">
                  {TIPOS_BLOQUEIO.map((t) => (
                    <button
                      key={t.value}
                      type="button"
                      onClick={() => setFormBloqueio(prev => ({ ...prev, tipo: t.value }))}
                      className={`p-2 rounded-lg border text-xs font-bold transition ${
                        formBloqueio.tipo === t.value
                          ? 'border-blue-600 bg-blue-50 text-blue-700'
                          : 'border-slate-200 bg-white text-slate-600 hover:border-slate-300'
                      }`}
                    >
                      {t.label}
                    </button>
                  ))}
                </div>
              </div>

              <div>
                <label className="text-xs font-bold text-slate-700 block mb-1.5">Motivo (opcional)</label>
                <textarea
                  value={formBloqueio.motivo}
                  onChange={(e) => setFormBloqueio(prev => ({ ...prev, motivo: e.target.value }))}
                  rows={3}
                  placeholder="Ex: Férias de verão, manutenção do equipamento..."
                  className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-600/20 resize-none"
                />
              </div>
            </div>

            <div className="flex items-center justify-end gap-3 pt-5 mt-5 border-t border-slate-100">
              <button
                onClick={() => setMostrarModal(false)}
                className="px-4 py-2 text-xs font-bold text-slate-600 bg-slate-100 hover:bg-slate-200 rounded-xl transition"
              >
                Cancelar
              </button>
              <button
                onClick={criarBloqueio}
                className="px-5 py-2 text-xs font-bold text-white bg-blue-600 hover:bg-blue-700 rounded-xl transition shadow-md flex items-center gap-2"
              >
                <Plus size={12} />
                Criar Bloqueio
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// src/components/gest/ConfigurarSessoes.jsx
import React, { useState, useEffect, useCallback, useMemo, useRef, memo } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import {
  Loader2, Plus, Trash2, Calendar, Clock, Users, Save, ArrowLeft,
  AlertCircle, CheckCircle, X, Sun, Sunset, Info, Edit2, Copy,
  ToggleLeft, ToggleRight, DollarSign, RefreshCw, Search, ArrowRight,
  BarChart3
} from 'lucide-react';
import ModalTransferir from './ModalTransferir';
import HistoricoSessoes from './HistoricoSessoes';

const API_BASE = 'https://welovepalop.com';

// ============================================================
// HELPER: obter utilizador do JWT
// ============================================================
function obterUsuarioId() {
  try {
    const token = localStorage.getItem('token')
      || localStorage.getItem('morabeza_token')
      || localStorage.getItem('access_token')
      || localStorage.getItem('jwt');
    if (token) {
      const base64Url = token.split('.')[1];
      const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
      const parsed = JSON.parse(decodeURIComponent(
        atob(base64).split('').map(c => '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2)).join('')
      ));
      const user = parsed?.data || parsed?.user || parsed?.usuario || parsed;
      const id = user?.id || user?.userId || user?.user_id || user?.usuario_id || parsed?.sub;
      if (id) return Number(id);
    }
    const savedUser = localStorage.getItem('user') || localStorage.getItem('morabeza_user');
    if (savedUser) {
      const u = JSON.parse(savedUser);
      if (u?.id) return Number(u.id);
    }
    return null;
  } catch { return null; }
}

// ============================================================
// MODAL: Criar/Editar Sessão
// ============================================================
const ModalSessao = memo(function ModalSessao({
  show, onClose, onSave, sessaoEditando, experienciaId
}) {
  const { t } = useTranslation();
  const [form, setForm] = useState({
    data: '',
    hora_inicio: '08:00',
    hora_fim: '11:00',
    periodo: 'Manhã',
    capacidade_maxima: 15,
    preco_especial: '',
    ativo: 1
  });
  const [salvando, setSalvando] = useState(false);
  const [erro, setErro] = useState('');
  const abortRef = useRef(null);

  // cleanup ao desmontar
  useEffect(() => {
    return () => {
      if (abortRef.current) abortRef.current.abort();
    };
  }, []);

  // Reset quando abre
  useEffect(() => {
    if (show) {
      setErro('');
      if (sessaoEditando) {
        setForm({
          data: sessaoEditando.data || '',
          hora_inicio: sessaoEditando.hora_inicio?.substring(0, 5) || '08:00',
          hora_fim: sessaoEditando.hora_fim?.substring(0, 5) || '11:00',
          periodo: sessaoEditando.periodo || 'Manhã',
          capacidade_maxima: sessaoEditando.capacidade_maxima || 15,
          preco_especial: sessaoEditando.preco_especial || '',
          ativo: sessaoEditando.ativo ?? 1
        });
      } else {
        setForm({
          data: new Date().toISOString().split('T')[0],
          hora_inicio: '08:00',
          hora_fim: '11:00',
          periodo: 'Manhã',
          capacidade_maxima: 15,
          preco_especial: '',
          ativo: 1
        });
      }
    }
  }, [show, sessaoEditando]);

  // Auto-detectar período
  useEffect(() => {
    const hora = parseInt(form.hora_inicio.split(':')[0]);
    let periodo = 'Manhã';
    if (hora >= 12 && hora < 15) periodo = 'Meio dia';
    else if (hora >= 15) periodo = 'Tarde';
    if (periodo !== form.periodo) {
      setForm(prev => ({ ...prev, periodo }));
    }
  }, [form.hora_inicio, form.periodo]);

  // Auto-calcular hora fim (+3h)
  useEffect(() => {
    const [h, m] = form.hora_inicio.split(':').map(Number);
    const fimH = (h + 3) % 24;
    const fimStr = `${String(fimH).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
    if (fimStr !== form.hora_fim) {
      setForm(prev => ({ ...prev, hora_fim: fimStr }));
    }
  }, [form.hora_inicio, form.hora_fim]);

  const handleSave = useCallback(async () => {
    setErro('');
    if (!form.data) { setErro('Data obrigatória'); return; }
    if (!form.hora_inicio || !form.hora_fim) { setErro('Horas obrigatórias'); return; }
    if (form.capacidade_maxima < 1) { setErro('Capacidade mínima é 1'); return; }

    setSalvando(true);

    const controller = new AbortController();
    abortRef.current = controller;

    try {
      const payload = {
        experiencia_id: Number(experienciaId),
        data: form.data,
        hora_inicio: form.hora_inicio,
        hora_fim: form.hora_fim,
        periodo: form.periodo,
        capacidade_maxima: parseInt(form.capacidade_maxima),
        preco_especial: form.preco_especial !== '' ? parseFloat(form.preco_especial) : null,
        ativo: form.ativo ? 1 : 0
      };

      if (sessaoEditando) payload.id = Number(sessaoEditando.id);

      const isEdicao = !!sessaoEditando;
      let url = `${API_BASE}/api/sessoes_experiencia.php`;
      if (isEdicao) url += `?action=update`;

      const res = await fetch(url, {
        method: 'POST',
        mode: 'cors',
        credentials: 'omit',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json'
        },
        body: JSON.stringify(payload),
        signal: controller.signal
      });

      const text = await res.text();

      let data;
      try {
        data = JSON.parse(text);
      } catch {
        throw new Error('Resposta inválida do servidor');
      }

      if (data.success) {
        onSave?.();
        onClose?.();
      } else {
        setErro(data.error || 'Erro ao guardar');
      }
    } catch (err) {
      if (err.name === 'AbortError') return;
      console.error('❌ Erro:', err);
      if (err.message === 'Failed to fetch') {
        setErro('Não foi possível contactar o servidor. Verifique a conexão.');
      } else {
        setErro(err.message || 'Erro de conexão');
      }
    } finally {
      setSalvando(false);
      abortRef.current = null;
    }
  }, [form, sessaoEditando, experienciaId, onSave, onClose]);

  if (!show) return null;

  return (
    <div
      className="fixed inset-0 z-[100] flex items-center justify-center p-4"
      style={{ backgroundColor: 'rgba(0,0,0,0.45)' }}
    >
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg p-6 text-left max-h-[90vh] overflow-y-auto">

        {/* HEADER */}
        <div className="flex items-center justify-between mb-5">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-blue-100 rounded-full flex items-center justify-center">
              <Calendar size={18} className="text-blue-600" />
            </div>
            <div>
              <h3 className="text-lg font-bold text-slate-900">
                {sessaoEditando ? 'Editar Sessão' : 'Nova Sessão'}
              </h3>
              <p className="text-xs text-slate-500">
                {sessaoEditando ? 'Atualize os dados da sessão' : 'Crie uma nova sessão de horário'}
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="text-slate-400 hover:text-slate-600 transition"
          >
            <X size={20} />
          </button>
        </div>

        {/* ERRO */}
        {erro && (
          <div className="mb-4 p-3 bg-red-50 border border-red-200 rounded-xl flex items-start gap-2">
            <AlertCircle size={16} className="text-red-500 shrink-0 mt-0.5" />
            <p className="text-xs text-red-700 font-medium">{erro}</p>
          </div>
        )}

        <div className="space-y-4">
          {/* DATA */}
          <div>
            <label className="text-xs font-bold text-slate-700 block mb-1.5">Data *</label>
            <input
              type="date"
              value={form.data}
              min={new Date().toISOString().split('T')[0]}
              onChange={(e) => setForm(prev => ({ ...prev, data: e.target.value }))}
              className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-600/20 text-slate-900"
            />
          </div>

          {/* HORAS */}
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="text-xs font-bold text-slate-700 block mb-1.5">Hora início *</label>
              <input
                type="time"
                value={form.hora_inicio}
                onChange={(e) => setForm(prev => ({ ...prev, hora_inicio: e.target.value }))}
                className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-600/20 text-slate-900"
              />
            </div>
            <div>
              <label className="text-xs font-bold text-slate-700 block mb-1.5">Hora fim *</label>
              <input
                type="time"
                value={form.hora_fim}
                onChange={(e) => setForm(prev => ({ ...prev, hora_fim: e.target.value }))}
                className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-600/20 text-slate-900"
              />
            </div>
          </div>

          {/* PERÍODO */}
          <div>
            <label className="text-xs font-bold text-slate-700 block mb-1.5">Período</label>
            <div className="grid grid-cols-3 gap-2">
              {[
                { label: 'Manhã', Icon: Sun, cor: 'yellow' },
                { label: 'Meio dia', Icon: Sun, cor: 'orange' },
                { label: 'Tarde', Icon: Sunset, cor: 'red' }
              ].map((p) => {
                const Icon = p.Icon;
                const isSelected = form.periodo === p.label;
                return (
                  <button
                    key={p.label}
                    type="button"
                    onClick={() => setForm(prev => ({ ...prev, periodo: p.label }))}
                    className={`flex flex-col items-center justify-center p-2 rounded-xl border transition-all gap-1 ${
                      isSelected
                        ? 'border-blue-600 bg-blue-50/30 ring-1 ring-blue-600'
                        : 'border-slate-200 bg-white hover:border-slate-300'
                    }`}
                  >
                    <Icon size={16} className={
                      isSelected
                        ? (p.cor === 'yellow' ? 'text-yellow-500' : p.cor === 'orange' ? 'text-orange-400' : 'text-red-400')
                        : 'text-slate-300'
                    } />
                    <span className={`text-[11px] font-bold ${isSelected ? 'text-blue-700' : 'text-slate-600'}`}>
                      {p.label}
                    </span>
                  </button>
                );
              })}
            </div>
          </div>

          {/* CAPACIDADE */}
          <div>
            <label className="text-xs font-bold text-slate-700 block mb-1.5">Capacidade máxima *</label>
            <div className="flex items-center gap-3">
              <button
                type="button"
                onClick={() => setForm(prev => ({ ...prev, capacidade_maxima: Math.max(1, prev.capacidade_maxima - 1) }))}
                className="w-10 h-10 flex items-center justify-center rounded-xl border border-slate-200 text-slate-500 hover:bg-slate-50 font-bold"
              >
                −
              </button>
              <input
                type="number"
                min="1"
                value={form.capacidade_maxima}
                onChange={(e) => setForm(prev => ({ ...prev, capacidade_maxima: parseInt(e.target.value) || 1 }))}
                className="flex-1 border border-slate-200 rounded-xl p-3 text-sm text-center font-bold focus:outline-none focus:ring-2 focus:ring-blue-600/20 text-slate-900"
              />
              <button
                type="button"
                onClick={() => setForm(prev => ({ ...prev, capacidade_maxima: prev.capacidade_maxima + 1 }))}
                className="w-10 h-10 flex items-center justify-center rounded-xl border border-slate-200 text-slate-500 hover:bg-slate-50 font-bold"
              >
                +
              </button>
            </div>
            <p className="text-[10px] text-slate-400 mt-1">Número máximo de pessoas nesta sessão</p>
          </div>

          {/* PREÇO ESPECIAL */}
          <div>
            <label className="text-xs font-bold text-slate-700 block mb-1.5">Preço especial (opcional)</label>
            <div className="relative">
              <DollarSign size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
              <input
                type="number"
                min="0"
                step="0.01"
                value={form.preco_especial}
                onChange={(e) => setForm(prev => ({ ...prev, preco_especial: e.target.value }))}
                placeholder="Deixe vazio para usar o preço base"
                className="w-full border border-slate-200 rounded-xl p-3 pl-9 text-sm focus:outline-none focus:ring-2 focus:ring-blue-600/20 text-slate-900"
              />
            </div>
          </div>

          {/* ATIVO */}
          <div className="flex items-center justify-between p-3 bg-slate-50 rounded-xl">
            <div>
              <p className="text-xs font-bold text-slate-700">Sessão ativa</p>
              <p className="text-[10px] text-slate-400">Sessões inativas não aparecem para os clientes</p>
            </div>
            <button
              type="button"
              onClick={() => setForm(prev => ({ ...prev, ativo: prev.ativo ? 0 : 1 }))}
              className="text-blue-600"
            >
              {form.ativo ? <ToggleRight size={32} /> : <ToggleLeft size={32} className="text-slate-300" />}
            </button>
          </div>
        </div>

        {/* AÇÕES */}
        <div className="flex items-center justify-end gap-3 pt-5 mt-5 border-t border-slate-100">
          <button
            type="button"
            onClick={onClose}
            disabled={salvando}
            className="px-4 py-2 text-xs font-bold text-slate-600 bg-slate-100 hover:bg-slate-200 rounded-xl transition disabled:opacity-50"
          >
            Cancelar
          </button>
          <button
            type="button"
            onClick={handleSave}
            disabled={salvando}
            className="px-5 py-2 text-xs font-bold text-white bg-blue-600 hover:bg-blue-700 rounded-xl transition shadow-md disabled:opacity-50 flex items-center gap-2"
          >
            {salvando ? (
              <>
                <Loader2 size={12} className="animate-spin" />
                A guardar...
              </>
            ) : (
              <>
                <Save size={12} />
                {sessaoEditando ? 'Atualizar' : 'Criar Sessão'}
              </>
            )}
          </button>
        </div>
      </div>
    </div>
  );
});

// ============================================================
// COMPONENTE PRINCIPAL
// ============================================================
export default function ConfigurarSessoes() {
  const { t } = useTranslation();
  const { id } = useParams();
  const navigate = useNavigate();

  const [experiencia, setExperiencia] = useState(null);
  const [sessoes, setSessoes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [loadingExp, setLoadingExp] = useState(true);
  const [modalShow, setModalShow] = useState(false);
  const [sessaoEditando, setSessaoEditando] = useState(null);
  const [deletandoId, setDeletandoId] = useState(null);
  const [filtroData, setFiltroData] = useState(new Date().toISOString().split('T')[0]);
  const [filtroPeriodo, setFiltroPeriodo] = useState('');
  const [toast, setToast] = useState({ show: false, message: '', type: '' });
  const [transferirShow, setTransferirShow] = useState(false);
  const [historicoShow, setHistoricoShow] = useState(false);


  const toastTimerRef = useRef(null);

  const showToast = useCallback((message, type = 'success') => {
    if (toastTimerRef.current) clearTimeout(toastTimerRef.current);
    setToast({ show: true, message, type });
    toastTimerRef.current = setTimeout(() => {
      setToast({ show: false, message: '', type: '' });
    }, 3000);
  }, []);

  useEffect(() => {
    return () => {
      if (toastTimerRef.current) clearTimeout(toastTimerRef.current);
    };
  }, []);

  // ============================================================
  // CARREGAR EXPERIÊNCIA
  // ============================================================
  useEffect(() => {
    const abortController = new AbortController();

    const fetchExperiencia = async () => {
      if (!id) return;
      setLoadingExp(true);
      try {
        const res = await fetch(`${API_BASE}/api/get_experiencias.php?id=${id}`, {
          method: 'GET',
          mode: 'cors',
          credentials: 'omit',
          headers: { 'Accept': 'application/json' },
          signal: abortController.signal
        });
        const data = await res.json();

        let exp = null;
        if (data.success && data.data) {
          exp = Array.isArray(data.data) ? data.data[0] : data.data;
        } else if (Array.isArray(data)) {
          exp = data.find(e => Number(e.id) === Number(id)) || data[0];
        }

        setExperiencia(exp);
      } catch (err) {
        if (err.name === 'AbortError') return;
        console.error('Erro ao buscar experiência:', err);
      } finally {
        setLoadingExp(false);
      }
    };
    fetchExperiencia();

    return () => abortController.abort();
  }, [id]);

  // ============================================================
  // CARREGAR SESSÕES
  // ============================================================
  const fetchSessoes = useCallback(async () => {
    if (!id) return;
    setLoading(true);
    try {
      let url = `${API_BASE}/api/sessoes_experiencia.php?experiencia_id=${id}`;
      if (filtroData) url += `&data=${filtroData}`;
      if (filtroPeriodo) url += `&periodo=${encodeURIComponent(filtroPeriodo)}`;

      const res = await fetch(url, {
        method: 'GET',
        mode: 'cors',
        credentials: 'omit',
        headers: { 'Accept': 'application/json' }
      });

      const text = await res.text();
      let data;
      try {
        data = JSON.parse(text);
      } catch {
        throw new Error('Resposta inválida do servidor');
      }

      if (data.success) {
        const lista = (data.sessoes || []).map(s => ({
          ...s,
          hora_inicio: s.hora_inicio?.substring(0, 5) || s.hora_inicio,
          hora_fim: s.hora_fim?.substring(0, 5) || s.hora_fim,
          vagas_disponiveis: s.vagas_disponiveis ?? ((s.capacidade_maxima || 0) - (s.vagas_ocupadas || 0))
        }));
        setSessoes(lista);
      } else {
        setSessoes([]);
      }
    } catch (err) {
      console.error('Erro ao buscar sessões:', err);
      showToast('Erro ao carregar sessões', 'error');
      setSessoes([]);
    } finally {
      setLoading(false);
    }
  }, [id, filtroData, filtroPeriodo, showToast]);

  useEffect(() => {
    fetchSessoes();
  }, [fetchSessoes]);

  // ============================================================
  // DELETAR SESSÃO
  // ============================================================
  const deletarSessao = useCallback(async (sessaoId) => {
    if (!window.confirm('Tem certeza que deseja eliminar esta sessão?')) return;
    setDeletandoId(sessaoId);
    try {
      const res = await fetch(`${API_BASE}/api/sessoes_experiencia.php?id=${sessaoId}`, {
        method: 'DELETE',
        mode: 'cors',
        credentials: 'omit',
        headers: { 'Accept': 'application/json' }
      });
      const data = await res.json();
      if (data.success) {
        showToast('Sessão eliminada!', 'success');
        fetchSessoes();
      } else {
        showToast(data.error || 'Erro ao eliminar', 'error');
      }
    } catch (err) {
      console.error(err);
      showToast('Erro de conexão', 'error');
    } finally {
      setDeletandoId(null);
    }
  }, [fetchSessoes, showToast]);

  // ============================================================
  // TOGGLE ATIVO
  // ============================================================
  const toggleAtivo = useCallback(async (sessao) => {
    const payload = {
      id: Number(sessao.id),
      experiencia_id: Number(id),
      data: sessao.data,
      hora_inicio: sessao.hora_inicio,
      hora_fim: sessao.hora_fim,
      periodo: sessao.periodo,
      capacidade_maxima: sessao.capacidade_maxima,
      preco_especial: sessao.preco_especial,
      ativo: sessao.ativo ? 0 : 1
    };

    try {
      const res = await fetch(`${API_BASE}/api/sessoes_experiencia.php?action=update`, {
        method: 'POST',
        mode: 'cors',
        credentials: 'omit',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json'
        },
        body: JSON.stringify(payload)
      });

      const data = await res.json();
      if (data.success) {
        fetchSessoes();
      } else {
        showToast(data.error || 'Erro ao atualizar', 'error');
      }
    } catch (err) {
      console.error(err);
      showToast('Erro de conexão', 'error');
    }
  }, [id, fetchSessoes, showToast]);

  // ============================================================
  // HANDLERS (useCallback)
  // ============================================================
  const abrirNovaSessao = useCallback(() => {
    setSessaoEditando(null);
    setModalShow(true);
  }, []);

  const abrirEditarSessao = useCallback((sessao) => {
    setSessaoEditando(sessao);
    setModalShow(true);
  }, []);

  const fecharModalSessao = useCallback(() => {
    setModalShow(false);
    setSessaoEditando(null);
  }, []);

  const abrirTransferir = useCallback(() => setTransferirShow(true), []);
  const fecharTransferir = useCallback(() => setTransferirShow(false), []);
  const abrirHistorico = useCallback(() => setHistoricoShow(true), []);
  const fecharHistorico = useCallback(() => setHistoricoShow(false), []);


  const onTransferSuccess = useCallback(() => {
    setTransferirShow(false);
    showToast('Sessões transferidas!', 'success');
    fetchSessoes();
  }, [showToast, fetchSessoes]);

  const onSaveSessao = useCallback(() => {
    fetchSessoes();
    showToast('Sessão guardada!', 'success');
  }, [fetchSessoes, showToast]);

  const duplicarSessao = useCallback((sessao) => {
    setSessaoEditando({
      ...sessao,
      id: null,
      hora_inicio: '',
      hora_fim: ''
    });
    setModalShow(true);
  }, []);

  // ============================================================
  // DERIVADOS (useMemo)
  // ============================================================
  const sessoesPorPeriodo = useMemo(() => ({
    'Manhã': sessoes.filter(s => s.periodo === 'Manhã'),
    'Meio dia': sessoes.filter(s => s.periodo === 'Meio dia'),
    'Tarde': sessoes.filter(s => s.periodo === 'Tarde')
  }), [sessoes]);

  const totais = useMemo(() => ({
    capacidade: sessoes.reduce((acc, s) => acc + (s.capacidade_maxima || 0), 0),
    ocupadas: sessoes.reduce((acc, s) => acc + (s.vagas_ocupadas || 0), 0),
    disponiveis: sessoes.reduce((acc, s) => acc + (s.vagas_disponiveis || 0), 0)
  }), [sessoes]);

  const hojeStr = useMemo(() => new Date().toISOString().split('T')[0], []);

  // ============================================================
  // RENDER
  // ============================================================
  return (
    <div className="text-left">
      {/* TOAST */}
      {toast.show && (
        <div className={`fixed top-4 right-4 z-[100] px-4 py-3 rounded-xl shadow-2xl text-white font-medium text-sm flex items-center gap-2 ${
          toast.type === 'success' ? 'bg-emerald-600' :
          toast.type === 'error' ? 'bg-red-600' : 'bg-amber-600'
        }`}>
          <AlertCircle size={18} />
          <span>{toast.message}</span>
        </div>
      )}

      {/* HEADER */}
      <div className="flex flex-wrap justify-between items-start gap-4 mb-6">
        <div>
          <div className="flex items-center gap-3 mb-2">
            <button
              type="button"
              onClick={() => navigate('/gest/minhas-experiencias')}
              className="w-9 h-9 flex items-center justify-center rounded-xl border border-slate-200 hover:bg-slate-50 transition-colors"
            >
              <ArrowLeft size={16} className="text-slate-600" />
            </button>
            <h1 className="text-2xl font-bold text-slate-900">Configurar Sessões</h1>
          </div>
          <p className="text-sm text-slate-500 ml-12">
            {loadingExp ? (
              <span className="inline-flex items-center gap-2">
                <Loader2 size={12} className="animate-spin" /> A carregar experiência...
              </span>
            ) : experiencia ? (
              <>
                <span className="font-semibold text-slate-700">{experiencia.titulo}</span>
                {experiencia.ilha && <span className="text-slate-400"> — {experiencia.ilha}</span>}
              </>
            ) : (
              'Experiência não encontrada'
            )}
          </p>
        </div>

        {/* AÇÕES */}
        <div className="flex items-center gap-2">
          <button
  type="button"
  onClick={abrirHistorico}
  className="flex items-center gap-2 bg-white hover:bg-slate-50 text-slate-700 border border-slate-200 font-bold text-sm px-4 py-3 rounded-xl transition shadow-sm"
  title="Ver histórico de dias arquivados"
>
  <BarChart3 size={16} />
  Histórico
</button>
          <button
            type="button"
            onClick={abrirTransferir}
            className="flex items-center gap-2 bg-white hover:bg-slate-50 text-slate-700 border border-slate-200 font-bold text-sm px-4 py-3 rounded-xl transition shadow-sm"
            title="Transferir todas as sessões de uma data para outra"
          >
            <ArrowRight size={16} />
            Transferir dia
          </button>

          <button
            type="button"
            onClick={abrirNovaSessao}
            className="flex items-center gap-2 bg-blue-900 hover:bg-blue-950 text-white font-bold text-sm px-5 py-3 rounded-xl transition shadow-md"
          >
            <Plus size={16} />
            Nova Sessão
          </button>
        </div>
      </div>

      {/* INFO BOX */}
      <div className="bg-blue-50 border border-blue-100 rounded-xl p-4 flex gap-3 mb-6">
        <Info size={18} className="text-blue-600 shrink-0 mt-0.5" />
        <div>
          <p className="text-sm font-bold text-blue-900">Como funcionam as sessões</p>
          <p className="text-xs text-blue-700 mt-1">
            Cada sessão tem uma capacidade máxima. Quando um cliente reserva, as vagas diminuem automaticamente.
            O sistema bloqueia overbooking. Ao cancelar uma reserva, as vagas são restauradas. Lembre-se a regra de antecedência aplica-se só a sessões 24h depois aparece na pagina de detalhes. (ex: se são 16h, uma sessão às 20h de hoje não deve aparecer, Sessões com menos de 24h são totalmente escondidas na página pública.);
          </p>
        </div>
      </div>

      {/* FILTROS */}
      <div className="flex flex-wrap gap-3 mb-6 p-4 bg-slate-50 rounded-xl border border-slate-100">
        <div className="flex-1 min-w-[200px]">
          <label className="text-[10px] font-bold text-slate-500 uppercase block mb-1">Data</label>
          <input
            type="date"
            value={filtroData}
            onChange={(e) => setFiltroData(e.target.value)}
            className="w-full border border-slate-200 rounded-lg p-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-600/20 text-slate-900 bg-white"
          />
        </div>
        <div className="flex-1 min-w-[200px]">
          <label className="text-[10px] font-bold text-slate-500 uppercase block mb-1">Período</label>
          <select
            value={filtroPeriodo}
            onChange={(e) => setFiltroPeriodo(e.target.value)}
            className="w-full border border-slate-200 rounded-lg p-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-600/20 text-slate-900 bg-white"
          >
            <option value="">Todos os períodos</option>
            <option value="Manhã">Manhã</option>
            <option value="Meio dia">Meio dia</option>
            <option value="Tarde">Tarde</option>
          </select>
        </div>
        <div className="flex items-end gap-2">
          <button
            type="button"
            onClick={() => { setFiltroData(''); setFiltroPeriodo(''); }}
            className="px-4 py-2.5 text-xs font-bold text-slate-600 bg-white border border-slate-200 rounded-lg hover:bg-slate-50 transition"
          >
            Limpar
          </button>
          <button
            type="button"
            onClick={fetchSessoes}
            className="px-4 py-2.5 text-xs font-bold text-slate-600 bg-white border border-slate-200 rounded-lg hover:bg-slate-50 transition flex items-center gap-2"
          >
            <RefreshCw size={12} className={loading ? 'animate-spin' : ''} />
            Atualizar
          </button>
        </div>
      </div>

      {/* LISTA DE SESSÕES */}
      {loading ? (
        <div className="bg-white rounded-2xl border border-slate-200 p-12 text-center">
          <Loader2 size={32} className="animate-spin text-blue-600 mx-auto mb-3" />
          <p className="text-slate-500 text-sm">A carregar sessões...</p>
        </div>
      ) : sessoes.length === 0 ? (
        <div className="bg-white rounded-2xl border border-slate-200 p-12 text-center">
          <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mx-auto mb-4">
            <Calendar size={28} className="text-slate-400" />
          </div>
          <h3 className="text-lg font-bold text-slate-900 mb-2">Nenhuma sessão criada</h3>
          <p className="text-sm text-slate-500 mb-6">
            {filtroData || filtroPeriodo
              ? 'Nenhuma sessão encontrada com estes filtros'
              : 'Comece por criar a primeira sessão para esta experiência'}
          </p>
          <button
            type="button"
            onClick={abrirNovaSessao}
            className="inline-flex items-center gap-2 bg-blue-900 hover:bg-blue-950 text-white font-bold text-sm px-5 py-3 rounded-xl transition"
          >
            <Plus size={16} />
            Criar primeira sessão
          </button>
        </div>
      ) : (
        <div className="space-y-6">
          {Object.entries(sessoesPorPeriodo).map(([periodo, lista]) => {
            if (lista.length === 0) return null;
            return (
              <div key={periodo}>
                <div className="flex items-center gap-2 mb-3">
                  {periodo === 'Manhã' && <Sun size={16} className="text-yellow-500" />}
                  {periodo === 'Meio dia' && <Sun size={16} className="text-orange-400" />}
                  {periodo === 'Tarde' && <Sunset size={16} className="text-red-400" />}
                  <h2 className="text-sm font-bold text-slate-900 uppercase tracking-wide">{periodo}</h2>
                  <span className="text-xs text-slate-400 font-medium">
                    ({lista.length} {lista.length === 1 ? 'sessão' : 'sessões'})
                  </span>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
                  {lista.map((sessao) => {
                    const vagas = sessao.vagas_disponiveis;
                    const isEsgotado = vagas === 0;
                    const percentagem = sessao.capacidade_maxima > 0
                      ? (sessao.vagas_ocupadas / sessao.capacidade_maxima) * 100
                      : 0;

                    return (
                      <div
                        key={sessao.id}
                        className={`border rounded-2xl p-4 bg-white shadow-sm hover:shadow-md transition-all ${
                          !sessao.ativo ? 'opacity-60 border-slate-200' : 'border-slate-200'
                        }`}
                      >
                        {/* HEADER */}
                        <div className="flex items-start justify-between mb-3">
                          <div>
                            <div className="flex items-center gap-2">
                              <Clock size={14} className="text-blue-600" />
                              <span className="text-base font-bold text-slate-900">
                                {sessao.hora_inicio}
                              </span>
                              <span className="text-xs text-slate-400">→ {sessao.hora_fim}</span>
                            </div>
                            <p className="text-[10px] text-slate-500 mt-1">
                              {sessao.data ? new Date(sessao.data + 'T00:00:00').toLocaleDateString('pt-PT', {
                                day: '2-digit', month: 'short', year: 'numeric'
                              }) : '—'}
                            </p>
                          </div>
                          <button
                            type="button"
                            onClick={() => toggleAtivo(sessao)}
                            className="text-blue-600"
                            title={sessao.ativo ? 'Desativar' : 'Ativar'}
                          >
                            {sessao.ativo
                              ? <ToggleRight size={24} />
                              : <ToggleLeft size={24} className="text-slate-300" />}
                          </button>
                        </div>

                        {/* BARRA DE OCUPAÇÃO */}
                        <div className="mb-3">
                          <div className="flex justify-between items-center mb-1">
                            <span className="text-[10px] font-bold text-slate-500 uppercase">Ocupação</span>
                            <span className={`text-xs font-bold ${
                              vagas >= 4 ? 'text-green-600' :
                              vagas >= 1 ? 'text-orange-500' : 'text-red-600'
                            }`}>
                              {sessao.vagas_ocupadas}/{sessao.capacidade_maxima}
                            </span>
                          </div>
                          <div className="w-full h-1.5 bg-slate-100 rounded-full overflow-hidden">
                            <div
                              className={`h-full rounded-full transition-all ${
                                percentagem >= 100 ? 'bg-red-500' :
                                percentagem >= 70 ? 'bg-orange-500' : 'bg-green-500'
                              }`}
                              style={{ width: `${Math.min(percentagem, 100)}%` }}
                            />
                          </div>
                          <p className={`text-[10px] mt-1 font-medium ${
                            vagas >= 4 ? 'text-green-600' :
                            vagas >= 1 ? 'text-orange-500' : 'text-red-500'
                          }`}>
                            {isEsgotado ? 'Esgotado' : `${vagas} vagas disponíveis`}
                          </p>
                        </div>

                        {/* PREÇO ESPECIAL */}
                        {sessao.preco_especial && (
                          <div className="flex items-center gap-1 mb-3 px-2 py-1 bg-orange-50 rounded-lg border border-orange-100">
                            <DollarSign size={10} className="text-orange-500" />
                            <span className="text-[10px] font-bold text-orange-600">
                              Preço especial: {Number(sessao.preco_especial).toLocaleString('pt-PT')} CVE
                            </span>
                          </div>
                        )}

                        {/* AÇÕES */}
                        <div className="flex items-center gap-2 pt-3 border-t border-slate-100">
                          <button
                            type="button"
                            onClick={() => abrirEditarSessao(sessao)}
                            className="flex-1 flex items-center justify-center gap-1.5 py-2 text-[11px] font-bold text-blue-600 bg-blue-50 hover:bg-blue-100 rounded-lg transition"
                          >
                            <Edit2 size={12} />
                            Editar
                          </button>
                          <button
                            type="button"
                            onClick={() => duplicarSessao(sessao)}
                            className="flex-1 flex items-center justify-center gap-1.5 py-2 text-[11px] font-bold text-slate-600 bg-slate-50 hover:bg-slate-100 rounded-lg transition"
                            title="Duplicar para outro horário"
                          >
                            <Copy size={12} />
                            Duplicar
                          </button>
                          <button
                            type="button"
                            onClick={() => deletarSessao(sessao.id)}
                            disabled={deletandoId === sessao.id}
                            className="p-2 text-red-500 bg-red-50 hover:bg-red-100 rounded-lg transition disabled:opacity-50"
                            title="Eliminar"
                          >
                            {deletandoId === sessao.id
                              ? <Loader2 size={12} className="animate-spin" />
                              : <Trash2 size={12} />}
                          </button>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* RESUMO GERAL */}
      {!loading && sessoes.length > 0 && (
        <div className="mt-8 p-5 bg-slate-50 rounded-2xl border border-slate-100">
          <h3 className="text-sm font-bold text-slate-900 mb-4">Resumo geral</h3>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div>
              <p className="text-[10px] text-slate-500 font-bold uppercase">Total sessões</p>
              <p className="text-2xl font-bold text-slate-900">{sessoes.length}</p>
            </div>
            <div>
              <p className="text-[10px] text-slate-500 font-bold uppercase">Capacidade total</p>
              <p className="text-2xl font-bold text-slate-900">{totais.capacidade}</p>
            </div>
            <div>
              <p className="text-[10px] text-slate-500 font-bold uppercase">Vagas ocupadas</p>
              <p className="text-2xl font-bold text-orange-600">{totais.ocupadas}</p>
            </div>
            <div>
              <p className="text-[10px] text-slate-500 font-bold uppercase">Vagas disponíveis</p>
              <p className="text-2xl font-bold text-green-600">{totais.disponiveis}</p>
            </div>
          </div>
        </div>
      )}

      {/* MODAL SESSÃO */}
      <ModalSessao
        show={modalShow}
        onClose={fecharModalSessao}
        onSave={onSaveSessao}
        sessaoEditando={sessaoEditando}
        experienciaId={id}
      />

      {/* MODAL TRANSFERIR */}
      {transferirShow && (
        <ModalTransferir
          experienciaId={id}
          onClose={fecharTransferir}
          onSuccess={onTransferSuccess}
        />
      )}

      {historicoShow && (
  <HistoricoSessoes
    experienciaId={id}
    onClose={fecharHistorico}
  />
)}
    </div>
  );
}

// components/prestador/DadosRecebimento.jsx
import React, { useState, useEffect } from 'react';
import {
  Wallet, CheckCircle2, AlertCircle, Loader2, Save,
  Shield, Edit3, X, Building2, CreditCard, User, Globe,
} from 'lucide-react';

const API_URL = import.meta.env.VITE_API_URL || 'https://welovepalop.com/api';

export default function DadosRecebimento() {
  const [dados, setDados] = useState(null);
  const [loading, setLoading] = useState(true);
  const [editando, setEditando] = useState(false);
  const [saving, setSaving] = useState(false);
  const [msg, setMsg] = useState({ tipo: '', texto: '' });
  const [usuarioId, setUsuarioId] = useState(null);
  const [nomeUtilizador, setNomeUtilizador] = useState('');

  const [form, setForm] = useState({
    titular: '',
    iban: '',
    banco: '',
    pais: 'Cabo Verde',
    nif: '',
  });

  // ---------------------------------------------------------
  // Obter ID e dados do utilizador de forma segura (JWT ou LocalStorage)
  // ---------------------------------------------------------
  useEffect(() => {
    try {
      const token = localStorage.getItem('token') || localStorage.getItem('morabeza_token');
      if (token) {
        const base64Url = token.split('.')[1];
        const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
        const jsonPayload = decodeURIComponent(atob(base64).split('').map(c => {
          return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
        }).join(''));
        const parsed = JSON.parse(jsonPayload);
        const userData = parsed.data || parsed;
        if (userData?.id) {
          setUsuarioId(userData.id);
          setNomeUtilizador(userData.nome || userData.name || '');
          return;
        }
      }

      const chaves = ['user', 'morabeza_user', 'morabeza_admin'];
      for (const chave of chaves) {
        const raw = localStorage.getItem(chave);
        if (raw) {
          const user = JSON.parse(raw);
          const uid = user?.id || user?.sub || user?.user_id;
          if (uid) {
            setUsuarioId(uid);
            setNomeUtilizador(user.nome || user.name || '');
            break;
          }
        }
      }
    } catch (e) {
      console.error('Erro ao obter ID no DadosRecebimento:', e);
    }
  }, []);

  // Carregar dados bancários assim que tivermos o ID
  useEffect(() => {
    if (usuarioId) {
      carregar();
    } else if (usuarioId === null && !loading) {
      setLoading(false);
    }
  }, [usuarioId]);

  const carregar = async () => {
    if (!usuarioId) {
      setLoading(false);
      return;
    }

    setLoading(true);
    try {
      const res = await fetch(`${API_URL}/usuarios/dados_recebimento.php`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'obter',
          usuario_id: usuarioId,
        }),
      });
      const data = await res.json();

      if (data.status === 'success' && data.data) {
        setDados(data.data);
        setForm({
          titular: data.data.titular || '',
          iban: data.data.iban || '',
          banco: data.data.banco || '',
          pais: data.data.pais || 'Cabo Verde',
          nif: data.data.nif || '',
        });
      } else {
        setDados(null);
        setForm((f) => ({
          ...f,
          titular: nomeUtilizador || '',
        }));
        setEditando(true);
      }
    } catch (err) {
      console.error(err);
      setMsg({ tipo: 'erro', texto: 'Erro de ligação.' });
    } finally {
      setLoading(false);
    }
  };

  const guardar = async (e) => {
    e.preventDefault();
    setMsg({ tipo: '', texto: '' });

    if (!usuarioId) {
      setMsg({ tipo: 'erro', texto: 'Utilizador não identificado.' });
      return;
    }

    if (!form.titular || form.titular.trim().length < 3) {
      setMsg({ tipo: 'erro', texto: 'Indica o nome do titular.' });
      return;
    }

    const ibanLimpo = form.iban.replace(/\s+/g, '');
    if (!ibanLimpo || ibanLimpo.length < 15) {
      setMsg({ tipo: 'erro', texto: 'IBAN inválido. Verifica o número.' });
      return;
    }

    setSaving(true);

    try {
      const res = await fetch(`${API_URL}/usuarios/dados_recebimento.php`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'guardar',
          usuario_id: usuarioId,
          titular: form.titular.trim(),
          iban: form.iban,
          banco: form.banco.trim(),
          pais: form.pais,
          nif: form.nif.trim(),
        }),
      });
      const data = await res.json();

      if (data.status === 'success') {
        setMsg({ tipo: 'sucesso', texto: data.message });
        setEditando(false);
        await carregar();
        setTimeout(() => setMsg({ tipo: '', texto: '' }), 3000);
      } else {
        setMsg({ tipo: 'erro', texto: data.message || 'Erro ao guardar.' });
      }
    } catch (err) {
      console.error(err);
      setMsg({ tipo: 'erro', texto: 'Erro de ligação.' });
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="h-64 w-full flex flex-col justify-center items-center gap-2 text-gray-500">
        <Loader2 className="animate-spin text-[#003580]" size={32} />
        <span className="text-sm">A carregar dados...</span>
      </div>
    );
  }

  return (
    <div className="max-w-3xl mx-auto px-4 py-6 space-y-6">
      <div>
        <h1 className="text-2xl font-bold text-[#003580] flex items-center gap-2">
          <Wallet size={24} /> Dados de recebimento
        </h1>
        <p className="text-gray-600 mt-1 text-sm">
          Onde queres receber os pagamentos das tuas reservas.
        </p>
      </div>

      {msg.texto && (
        <div
          className={`p-3 rounded-xl flex items-center gap-2 text-sm ${
            msg.tipo === 'sucesso'
              ? 'bg-green-50 text-green-800 border border-green-200'
              : 'bg-red-50 text-red-800 border border-red-200'
          }`}
        >
          {msg.tipo === 'sucesso' ? <CheckCircle2 size={16} /> : <AlertCircle size={16} />}
          <span>{msg.texto}</span>
        </div>
      )}

      {!dados && !editando && (
        <div className="p-4 bg-yellow-50 border-2 border-yellow-200 rounded-2xl flex items-start gap-3">
          <AlertCircle className="text-yellow-600 flex-shrink-0 mt-0.5" size={22} />
          <div>
            <p className="text-sm font-bold text-yellow-900">
              Ainda não tens dados de recebimento
            </p>
            <p className="text-xs text-yellow-800 mt-1">
              Sem estes dados, a Morabeza Stay <strong>não pode fazer repasses</strong> dos teus
              repasses de cada reserva. Adiciona o teu IBAN abaixo.
            </p>
            <button
              onClick={() => setEditando(true)}
              className="mt-3 px-4 py-2 rounded-lg bg-yellow-600 hover:bg-yellow-700 text-white text-sm font-semibold transition"
            >
              Adicionar dados agora
            </button>
          </div>
        </div>
      )}

      <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
        <div className="flex items-center justify-between p-5 border-b border-gray-100">
          <div className="flex items-center gap-2">
            <CreditCard className="text-[#003580]" size={20} />
            <h2 className="font-bold text-gray-900">Conta bancária</h2>
          </div>

          {dados && !editando && (
            <button
              onClick={() => setEditando(true)}
              className="flex items-center gap-1.5 text-sm font-semibold text-[#2563eb] hover:text-[#003580] transition"
            >
              <Edit3 size={14} /> Editar
            </button>
          )}
        </div>

        <div className="p-5">
          {dados && !editando && (
            <div className="space-y-3">
              <div className="flex justify-between py-3 border-b border-gray-100">
                <span className="text-gray-500 text-sm flex items-center gap-1">
                  <User size={14} /> Titular
                </span>
                <span className="font-semibold text-sm text-gray-900">{dados.titular}</span>
              </div>

              <div className="flex justify-between py-3 border-b border-gray-100">
                <span className="text-gray-500 text-sm flex items-center gap-1">
                  <CreditCard size={14} /> IBAN
                </span>
                <span className="font-mono font-semibold text-sm text-gray-900">
                  {dados.iban_mascarado || dados.iban}
                </span>
              </div>

              {dados.banco && (
                <div className="flex justify-between py-3 border-b border-gray-100">
                  <span className="text-gray-500 text-sm flex items-center gap-1">
                    <Building2 size={14} /> Banco
                  </span>
                  <span className="font-semibold text-sm text-gray-900">{dados.banco}</span>
                </div>
              )}

              <div className="flex justify-between py-3 border-b border-gray-100">
                <span className="text-gray-500 text-sm flex items-center gap-1">
                  <Globe size={14} /> País
                </span>
                <span className="font-semibold text-sm text-gray-900">{dados.pais}</span>
              </div>

              {dados.nif && (
                <div className="flex justify-between py-3 border-b border-gray-100">
                  <span className="text-gray-500 text-sm">NIF</span>
                  <span className="font-semibold text-sm text-gray-900">{dados.nif}</span>
                </div>
              )}

              <div className="pt-3">
                <span className="inline-flex items-center gap-1.5 bg-green-100 text-green-700 px-3 py-1.5 rounded-full text-xs font-bold">
                  <CheckCircle2 size={14} /> Configurado
                </span>
              </div>
            </div>
          )}

          {(!dados || editando) && (
            <form onSubmit={guardar} className="space-y-4">
              <div>
                <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wider mb-2">
                  Nome do titular *
                </label>
                <input
                  type="text"
                  value={form.titular}
                  onChange={(e) => setForm({ ...form, titular: e.target.value })}
                  placeholder="Nome completo como aparece no banco"
                  className="w-full px-4 py-2.5 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-[#003580]/20 text-sm"
                  required
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wider mb-2">
                  IBAN *
                </label>
                <input
                  type="text"
                  value={form.iban}
                  onChange={(e) => setForm({ ...form, iban: e.target.value })}
                  placeholder="CV64 0000 0000 0000 0000 0000 0"
                  className="w-full px-4 py-2.5 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-[#003580]/20 text-sm font-mono"
                  required
                />
                <p className="text-xs text-gray-400 mt-1">
                  Podes escrever com ou sem espaços.
                </p>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wider mb-2">
                    Banco
                  </label>
                  <input
                    type="text"
                    value={form.banco}
                    onChange={(e) => setForm({ ...form, banco: e.target.value })}
                    placeholder="Ex: BCA, BAI, Caixa"
                    className="w-full px-4 py-2.5 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-[#003580]/20 text-sm"
                  />
                </div>

                <div>
                  <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wider mb-2">
                    NIF
                  </label>
                  <input
                    type="text"
                    value={form.nif}
                    onChange={(e) => setForm({ ...form, nif: e.target.value })}
                    placeholder="Opcional"
                    className="w-full px-4 py-2.5 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-[#003580]/20 text-sm"
                  />
                </div>
              </div>

              <div>
                <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wider mb-2">
                  País
                </label>
                <select
                  value={form.pais}
                  onChange={(e) => setForm({ ...form, pais: e.target.value })}
                  className="w-full px-4 py-2.5 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-[#003580]/20 text-sm"
                >
                  <option value="Cabo Verde">Cabo Verde</option>
                  <option value="Portugal">Portugal</option>
                  <option value="Brasil">Brasil</option>
                  <option value="Angola">Angola</option>
                  <option value="Outro">Outro</option>
                </select>
              </div>

              <div className="flex gap-3 pt-2">
                {dados && (
                  <button
                    type="button"
                    onClick={() => {
                      setEditando(false);
                      carregar();
                      setMsg({ tipo: '', texto: '' });
                    }}
                    disabled={saving}
                    className="flex-1 md:flex-initial md:px-6 px-4 py-2.5 rounded-xl text-sm font-medium border border-gray-300 hover:bg-gray-50 transition flex items-center justify-center gap-2"
                  >
                    <X size={16} /> Cancelar
                  </button>
                )}
                <button
                  type="submit"
                  disabled={saving}
                  className="flex-1 md:flex-initial md:px-6 px-4 py-2.5 rounded-xl text-sm font-semibold bg-[#003580] text-white hover:bg-[#002860] transition flex items-center justify-center gap-2 disabled:opacity-50"
                >
                  {saving ? (
                    <>
                      <Loader2 size={16} className="animate-spin" /> A guardar...
                    </>
                  ) : (
                    <>
                      <Save size={16} /> Guardar dados
                    </>
                  )}
                </button>
              </div>
            </form>
          )}
        </div>
      </div>

      <div className="p-4 bg-blue-50 rounded-2xl border border-blue-100">
        <h4 className="text-sm font-bold text-blue-900 mb-2 flex items-center gap-2">
          <Shield size={16} /> Porque pedimos isto?
        </h4>
        <ul className="text-xs text-blue-800 space-y-1">
          <li>• É para onde enviamos os teus repasses de cada reserva confirmada.</li>
          <li>• O IBAN fica guardado de forma protegida.</li>
          <li>• Só a Morabeza Stay e tu têm acesso.</li>
          <li>• Nunca partilhamos com terceiros.</li>
        </ul>
      </div>
    </div>
  );
}

// src/components/gest/Dashboard.jsx
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  Star, Home, Car, Compass, 
  Eye, MousePointer, Calendar, TrendingUp, 
  Loader2, Award, 
  Wallet, Clock
} from 'lucide-react';

export default function Dashboard() {
  const navigate = useNavigate();
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('overview');
  
  // 🔓 Desbloqueio total: por predefinição assumimos todas as permissões ativas para utilizadores logados
  const [userRoles, setUserRoles] = useState({
    anfitrion: true,
    guia: true,
    proprietarioVeiculos: true
  });
  
  // Estatísticas dos diferentes tipos
  const [estatisticas, setEstatisticas] = useState({
    alojamentos: { total_anuncios: 0, total_visualizacoes: 0, total_cliques_reserva: 0, taxa_conversao: 0, itens: [] },
    carros: { total_anuncios: 0, total_visualizacoes: 0, total_cliques_reserva: 0, taxa_conversao: 0, itens: [] },
    experiencias: { total_anuncios: 0, total_visualizacoes: 0, total_cliques_reserva: 0, taxa_conversao: 0, itens: [] },
    totais: { total_visualizacoes: 0, total_cliques_reserva: 0, total_anuncios: 0, taxa_conversao: 0 }
  });

  // Reservas recentes
  const [reservasRecentes, setReservasRecentes] = useState([]);

  useEffect(() => {
    // 🔑 Extrair dados de forma segura do token JWT no localStorage
    const obterDadosDoToken = () => {
      try {
        const token = localStorage.getItem('token') || localStorage.getItem('morabeza_token');
        if (!token) return null;
        const base64Url = token.split('.')[1];
        const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
        const jsonPayload = decodeURIComponent(atob(base64).split('').map(c => {
          return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
        }).join(''));
        const parsed = JSON.parse(jsonPayload);
        return parsed.data || parsed || null;
      } catch (e) {
        return null;
      }
    };

    const userData = obterDadosDoToken();
    
    if (userData && userData.id) {
      setUser(userData);
      fetchDashboardData(userData.id);
      fetchReservasRecentes(userData.id);
      fetchUserRoles(userData.id);
    } else {
      // Tentar fallback para o 'user' antigo se existir
      const savedUser = localStorage.getItem('user');
      if (savedUser) {
        try {
          const userParsed = JSON.parse(savedUser);
          setUser(userParsed);
          fetchDashboardData(userParsed.id);
          fetchReservasRecentes(userParsed.id);
          fetchUserRoles(userParsed.id);
          return;
        } catch (e) {}
      }
      navigate('/login');
    }
  }, [navigate]);

  const fetchUserRoles = async (userId) => {
    try {
      const response = await fetch(`https://welovepalop.com/api/usuarios/listar_roles.php?usuario_id=${userId}`);
      const data = await response.json();
      
      if (data.success && data.roles) {
        const isAnfitrion = data.roles.some(r => r.name === 'anfitrion' && r.status === 'approved');
        const isGuia = data.roles.some(r => r.name === 'guia_experiencias' && r.status === 'approved');
        const isProprietarioVeiculos = data.roles.some(r => r.name === 'proprietario_veiculos' && r.status === 'approved');
        
        // Se houver roles definidas na BD, aplica-as; caso contrário mantém o acesso livre
        if (isAnfitrion || isGuia || isProprietarioVeiculos) {
          setUserRoles({
            anfitrion: isAnfitrion,
            guia: isGuia,
            proprietarioVeiculos: isProprietarioVeiculos
          });
        }
      }
    } catch (error) {
      console.error('Erro ao buscar roles:', error);
    }
  };

  const fetchDashboardData = async (userId) => {
    setLoading(true);
    try {
      const response = await fetch(`https://welovepalop.com/api/dashboard/estatisticas.php?usuario_id=${userId}`);
      const data = await response.json();
      
      if (data.success && data.data) {
        setEstatisticas(data.data);
      }
    } catch (error) {
      console.error('Erro ao carregar dashboard:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchReservasRecentes = async (userId) => {
    try {
      const response = await fetch(`https://welovepalop.com/api/dashboard/reservas_recentes.php?usuario_id=${userId}`);
      const data = await response.json();
      
      if (data.success && data.data?.reservas) {
        setReservasRecentes(data.data.reservas);
      }
    } catch (error) {
      console.error('Erro ao buscar reservas:', error);
    }
  };

  // Calcular totais
  const totalAnuncios = estatisticas.totais?.total_anuncios || 0;
  const totalVisualizacoes = estatisticas.totais?.total_visualizacoes || 0;
  const totalCliques = estatisticas.totais?.total_cliques_reserva || 0;
  const taxaConversao = estatisticas.totais?.taxa_conversao || 0;

  // Tabs disponíveis
  const tabsDisponiveis = [
    { id: 'alojamentos', label: 'Alojamentos', icon: Home, count: estatisticas.alojamentos?.total_anuncios || 0 },
    { id: 'carros', label: 'Carros', icon: Car, count: estatisticas.carros?.total_anuncios || 0 },
    { id: 'experiencias', label: 'Experiências', icon: Compass, count: estatisticas.experiencias?.total_anuncios || 0 }
  ];

  if (loading) {
    return (
      <div className="min-h-screen bg-[#f8f9fc] flex items-center justify-center">
        <div className="text-center">
          <Loader2 size={48} className="animate-spin text-blue-900 mx-auto mb-4" />
          <p className="text-slate-600">Carregando seu dashboard...</p>
        </div>
      </div>
    );
  }

  if (!user) {
    return null;
  }

  return (
    <div className="min-h-screen bg-[#f8f9fc]">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
        
        {/* Tabs de Navegação */}
        <div className="flex gap-2 mb-6 border-b border-gray-200 flex-wrap">
          <button
            onClick={() => setActiveTab('overview')}
            className={`px-4 py-2 text-sm font-medium transition-colors ${
              activeTab === 'overview'
                ? 'text-blue-900 border-b-2 border-blue-900'
                : 'text-slate-500 hover:text-slate-700'
            }`}
          >
            Visão Geral
          </button>
          {tabsDisponiveis.map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`px-4 py-2 text-sm font-medium transition-colors flex items-center gap-2 ${
                activeTab === tab.id
                  ? 'text-blue-900 border-b-2 border-blue-900'
                  : 'text-slate-500 hover:text-slate-700'
              }`}
            >
              <tab.icon size={16} /> {tab.label} ({tab.count})
            </button>
          ))}
        </div>

        {/* Conteúdo do Dashboard */}
        {activeTab === 'overview' && (
          <>
            {/* Cards Principais */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
              <div className="bg-white rounded-xl p-5 border border-gray-100 shadow-sm">
                <div className="flex items-center justify-between mb-3">
                  <div className="w-10 h-10 bg-blue-100 rounded-xl flex items-center justify-center">
                    <Home size={20} className="text-blue-600" />
                  </div>
                </div>
                <div>
                  <h3 className="text-[13px] font-medium text-slate-500 mb-1">Total de Anúncios</h3>
                  <span className="text-[28px] font-bold text-slate-900">{totalAnuncios}</span>
                </div>
              </div>

              <div className="bg-white rounded-xl p-5 border border-gray-100 shadow-sm">
                <div className="flex items-center justify-between mb-3">
                  <div className="w-10 h-10 bg-green-100 rounded-xl flex items-center justify-center">
                    <Calendar size={20} className="text-green-600" />
                  </div>
                </div>
                <div>
                  <h3 className="text-[13px] font-medium text-slate-500 mb-1">Reservas Confirmadas</h3>
                  <span className="text-[28px] font-bold text-slate-900">0</span>
                </div>
              </div>

              <div className="bg-white rounded-xl p-5 border border-gray-100 shadow-sm">
                <div className="flex items-center justify-between mb-3">
                  <div className="w-10 h-10 bg-purple-100 rounded-xl flex items-center justify-center">
                    <Wallet size={20} className="text-purple-600" />
                  </div>
                </div>
                <div>
                  <h3 className="text-[13px] font-medium text-slate-500 mb-1">Ganhos (Este mês)</h3>
                  <div className="flex items-baseline gap-1">
                    <span className="text-[28px] font-bold text-slate-900">0</span>
                    <span className="text-[12px] font-bold text-slate-500">CVE</span>
                  </div>
                </div>
              </div>

              <div className="bg-white rounded-xl p-5 border border-gray-100 shadow-sm">
                <div className="flex items-center justify-between mb-3">
                  <div className="w-10 h-10 bg-yellow-100 rounded-xl flex items-center justify-center">
                    <Award size={20} className="text-yellow-600" />
                  </div>
                </div>
                <div>
                  <h3 className="text-[13px] font-medium text-slate-500 mb-1">Avaliação Média</h3>
                  <div className="flex items-center gap-2">
                    <span className="text-[28px] font-bold text-slate-900">4.8</span>
                    <div className="flex items-center gap-0.5">
                      {[1,2,3,4].map(star => (
                        <Star key={star} size={14} className="fill-yellow-400 text-yellow-400" />
                      ))}
                      <Star size={14} className="fill-gray-200 text-gray-200" />
                    </div>
                  </div>
                </div>
              </div>
            </div>

            {/* Desempenho */}
            <div className="mb-6">
              <h2 className="text-[14px] font-bold mb-3">Desempenho (Últimos 30 dias)</h2>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                <div className="bg-white rounded-xl p-5 border border-gray-100 shadow-sm">
                  <h3 className="text-[13px] font-medium text-slate-500 mb-4">Visualizações</h3>
                  <div className="flex items-end justify-between">
                    <span className="text-[28px] font-bold text-slate-900">{totalVisualizacoes.toLocaleString()}</span>
                  </div>
                </div>

                <div className="bg-white rounded-xl p-5 border border-gray-100 shadow-sm">
                  <h3 className="text-[13px] font-medium text-slate-500 mb-4">Cliques em Reserva</h3>
                  <div className="flex items-end justify-between">
                    <span className="text-[28px] font-bold text-slate-900">{totalCliques.toLocaleString()}</span>
                  </div>
                </div>

                <div className="bg-white rounded-xl p-5 border border-gray-100 shadow-sm">
                  <h3 className="text-[13px] font-medium text-slate-500 mb-4">Taxa de Conversão</h3>
                  <div className="flex items-end justify-between">
                    <span className="text-[28px] font-bold text-slate-900">{taxaConversao}%</span>
                  </div>
                </div>

                <div className="bg-white rounded-xl p-5 border border-gray-100 shadow-sm">
                  <h3 className="text-[13px] font-medium text-slate-500 mb-4">Receita Total</h3>
                  <div className="flex items-end justify-between">
                    <div className="flex items-baseline gap-1">
                      <span className="text-[28px] font-bold text-slate-900">0</span>
                      <span className="text-[11px] font-bold text-slate-500">CVE</span>
                    </div>
                  </div>
                </div>
              </div>
            </div>

            {/* Reservas Recentes */}
            <div className="bg-white rounded-xl border border-gray-100 shadow-sm">
              <div className="flex justify-between items-center px-5 py-4 border-b border-gray-50">
                <div className="flex items-center gap-2">
                  <Clock size={18} className="text-slate-500" />
                  <h2 className="text-[14px] font-bold">Reservas Recentes</h2>
                </div>
                <button 
                  onClick={() => navigate('/gest/reservas')}
                  className="text-[12px] text-blue-600 font-medium hover:underline"
                >
                  Ver todas
                </button>
              </div>

              <div className="flex flex-col">
                {reservasRecentes.length > 0 ? (
                  reservasRecentes.map((reserva, index) => (
                    <div 
                      key={reserva.id} 
                      className={`flex flex-col lg:flex-row lg:items-center justify-between px-5 py-4 hover:bg-gray-50/50 transition-colors gap-3 ${
                        index !== reservasRecentes.length - 1 ? 'border-b border-gray-50' : ''
                      }`}
                    >
                      <div className="flex items-center gap-3 lg:w-[25%]">
                        <img 
                          src={reserva.cliente_foto || 'https://ui-avatars.com/api/?name=Cliente&background=0D8ABC&color=fff'} 
                          alt={reserva.cliente_nome} 
                          className="w-10 h-10 rounded-full object-cover border border-gray-200"
                        />
                        <div>
                          <p className="text-[13px] font-bold">{reserva.cliente_nome}</p>
                          <p className="text-[10px] text-slate-400">{reserva.cliente_email}</p>
                        </div>
                      </div>

                      <div className="lg:w-[30%]">
                        <div className="flex items-center gap-1">
                          {reserva.tipo === 'alojamento' && <Home size={12} className="text-blue-500" />}
                          {reserva.tipo === 'carro' && <Car size={12} className="text-green-500" />}
                          {reserva.tipo === 'experiencia' && <Compass size={12} className="text-purple-500" />}
                          <p className="text-[13px] font-medium text-slate-600">{reserva.item_nome}</p>
                        </div>
                        <p className="text-[11px] text-slate-400 mt-1">{reserva.periodo}</p>
                      </div>

                      <div className="lg:w-[15%]">
                        <span className={`inline-block px-3 py-1 rounded-full text-[11px] font-medium ${
                          reserva.status === 'Confirmada' 
                            ? 'bg-green-100 text-green-700' 
                            : reserva.status === 'Pendente'
                            ? 'bg-yellow-100 text-yellow-700'
                            : 'bg-red-100 text-red-700'
                        }`}>
                          {reserva.status}
                        </span>
                      </div>

                      <div className="lg:w-[20%] text-left lg:text-right">
                        <p className="text-[14px] font-bold text-blue-600">{reserva.valor} CVE</p>
                      </div>
                    </div>
                  ))
                ) : (
                  <div className="text-center py-8">
                    <Clock size={40} className="mx-auto text-slate-300 mb-2" />
                    <p className="text-slate-400 text-sm">Nenhuma reserva recente</p>
                    <p className="text-slate-300 text-xs mt-1">As suas reservas aparecerão aqui</p>
                  </div>
                )}
              </div>
            </div>
          </>
        )}

        {activeTab === 'alojamentos' && estatisticas.alojamentos && (
          <EstatisticasTipo 
            tipo="Alojamentos" 
            dados={estatisticas.alojamentos} 
            onVerTodos={() => navigate('/alojamento-registro/meus')}
          />
        )}

        {activeTab === 'carros' && estatisticas.carros && (
          <EstatisticasTipo 
            tipo="Carros" 
            dados={estatisticas.carros} 
            onVerTodos={() => navigate('/carro-registo/meus')}
          />
        )}

        {activeTab === 'experiencias' && estatisticas.experiencias && (
          <EstatisticasTipo 
            tipo="Experiências" 
            dados={estatisticas.experiencias} 
            onVerTodos={() => navigate('/experiencia-registo/meus')}
          />
        )}
      </div>
    </div>
  );
}

function EstatisticasTipo({ tipo, dados, onVerTodos }) {
  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-lg font-bold text-slate-900">Estatísticas de {tipo}</h2>
        <button 
          onClick={onVerTodos}
          className="px-3 py-1.5 rounded-lg text-xs font-medium border border-blue-900 text-blue-900 hover:bg-blue-50 transition-colors"
        >
          Gerenciar
        </button>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <div className="bg-white rounded-xl p-5 border border-gray-100 shadow-sm">
          <div className="flex items-center gap-2 mb-3">
            <Eye size={18} className="text-blue-500" />
            <h3 className="text-[12px] font-medium text-slate-500">Visualizações</h3>
          </div>
          <p className="text-[28px] font-bold text-slate-900">{dados.total_visualizacoes?.toLocaleString() || 0}</p>
        </div>

        <div className="bg-white rounded-xl p-5 border border-gray-100 shadow-sm">
          <div className="flex items-center gap-2 mb-3">
            <MousePointer size={18} className="text-green-500" />
            <h3 className="text-[12px] font-medium text-slate-500">Cliques em Reserva</h3>
          </div>
          <p className="text-[28px] font-bold text-slate-900">{dados.total_cliques_reserva?.toLocaleString() || 0}</p>
        </div>

        <div className="bg-white rounded-xl p-5 border border-gray-100 shadow-sm">
          <div className="flex items-center gap-2 mb-3">
            <TrendingUp size={18} className="text-purple-500" />
            <h3 className="text-[12px] font-medium text-slate-500">Taxa de Conversão</h3>
          </div>
          <p className="text-[28px] font-bold text-slate-900">{parseFloat(dados.taxa_conversao || 0).toFixed(1)}%</p>
        </div>
      </div>

      {dados.itens && dados.itens.length > 0 && (
        <div className="bg-white rounded-xl border border-gray-100 shadow-sm">
          <div className="px-5 py-4 border-b border-gray-50">
            <h3 className="text-[13px] font-bold">Seus {tipo.toLowerCase()}</h3>
          </div>
          <div className="divide-y divide-gray-50 max-h-96 overflow-y-auto">
            {dados.itens.map((item, i) => (
              <div key={i} className="flex justify-between items-center px-5 py-3 hover:bg-gray-50">
                <div>
                  <p className="text-[13px] font-medium text-slate-900">{item.titulo}</p>
                  <p className="text-[11px] text-slate-400">{item.localizacao}</p>
                </div>
                <div className="text-right">
                  <p className="text-[12px] font-bold text-blue-600">{item.visualizacoes || 0} 👁️</p>
                  <p className="text-[10px] text-slate-400">{item.cliques_reserva || 0} 🖱️ reservas</p>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

// pages/DetalhesReservaPage.jsx

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { 
  ArrowLeft, Calendar, User, Phone, Mail, Download, Share2,
  CheckCircle, XCircle, Clock, AlertCircle, ChevronRight, Home,
  Receipt, DollarSign, Loader2, RefreshCw
} from 'lucide-react';

const API_URL = 'https://welovepalop.com';

export default function DetalhesReservaPage() {
  const { id, tipo } = useParams();
  const navigate = useNavigate();
  const [detalhes, setDetalhes] = useState(null);
  const [reembolsos, setReembolsos] = useState([]);
  const [loading, setLoading] = useState(true);
  const [loadingReembolsos, setLoadingReembolsos] = useState(false);
  const [error, setError] = useState(null);
  const [canceling, setCanceling] = useState(false);

  const obterUsuarioId = () => {
    try {
      const token = localStorage.getItem('token') || localStorage.getItem('morabeza_token');
      if (token) {
        const base64Url = token.split('.')[1];
        const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
        const jsonPayload = decodeURIComponent(atob(base64).split('').map(c => {
          return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
        }).join(''));
        const parsed = JSON.parse(jsonPayload);
        const userData = parsed.data || parsed;
        if (userData?.id) return userData.id;
      }

      const chaves = ['user', 'morabeza_user', 'morabeza_admin'];
      for (const chave of chaves) {
        const savedUser = localStorage.getItem(chave);
        if (savedUser) {
          const user = JSON.parse(savedUser);
          if (user?.id) return user.id;
        }
      }
    } catch (e) {
      console.error('Erro ao obter ID do utilizador:', e);
    }
    return null;
  };

  useEffect(() => {
    if (id && tipo) {
      fetchDetalhes();
    }
  }, [id, tipo]);

  const fetchDetalhes = async () => {
    setLoading(true);
    setError(null);
    try {
      const usuarioId = obterUsuarioId();
      if (!usuarioId) {
        setError('Usuário não autenticado');
        setLoading(false);
        return;
      }
      
      const response = await fetch(
        `${API_URL}/api/dashboard/detalhes_reserva.php?reserva_id=${id}&usuario_id=${usuarioId}&tipo=${tipo}`
      );
      const data = await response.json();
      
      if (data.success) {
        setDetalhes(data.data);
        // Buscar reembolsos em paralelo
        fetchReembolsos(usuarioId);
      } else {
        setError(data.message || 'Erro ao carregar detalhes');
      }
    } catch (err) {
      setError('Erro ao carregar detalhes da reserva');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchReembolsos = async (usuarioId) => {
    setLoadingReembolsos(true);
    try {
      const res = await fetch(
        `${API_URL}/api/reembolsos.php?reserva_id=${id}&tipo=${tipo}&usuario_id=${usuarioId || obterUsuarioId()}`
      );
      const data = await res.json();
      if (data.success) {
        setReembolsos(data.data || []);
      }
    } catch (err) {
      console.error('Erro ao buscar reembolsos:', err);
    } finally {
      setLoadingReembolsos(false);
    }
  };

  const handleCancelar = async () => {
    const confirmCancel = window.confirm('Tem certeza que deseja cancelar esta reserva?');
    if (!confirmCancel) return;

    setCanceling(true);
    try {
      const usuarioId = obterUsuarioId();
      if (!usuarioId) {
        alert('Usuário não autenticado');
        return;
      }
      
      const response = await fetch(`${API_URL}/api/dashboard/minhas_reservas.php`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          reserva_id: parseInt(id),
          tipo: tipo,
          usuario_id: usuarioId
        })
      });
      
      const data = await response.json();
      
      if (data.success) {
        alert('Reserva cancelada com sucesso!');
        navigate('/gest/minhas-reservas');
      } else {
        alert(data.message || 'Erro ao cancelar reserva');
      }
    } catch (error) {
      console.error('Erro ao cancelar reserva:', error);
      alert('Erro ao cancelar reserva. Tente novamente.');
    } finally {
      setCanceling(false);
    }
  };

  const baixarRecibo = () => {
    const usuarioId = obterUsuarioId();
    window.open(
      `${API_URL}/api/recibo.php?reserva_id=${id}&tipo=${tipo}&usuario_id=${usuarioId}`,
      '_blank'
    );
  };

  const getStatusConfig = (status) => {
    const statusMap = {
      'Confirmada': { bg: 'bg-green-50', text: 'text-green-700', border: 'border-green-200', icon: <CheckCircle className="w-5 h-5 text-green-500" />, label: 'Confirmada' },
      'Pendente': { bg: 'bg-yellow-50', text: 'text-yellow-700', border: 'border-yellow-200', icon: <Clock className="w-5 h-5 text-yellow-500" />, label: 'Pendente' },
      'Cancelada': { bg: 'bg-red-50', text: 'text-red-700', border: 'border-red-200', icon: <XCircle className="w-5 h-5 text-red-500" />, label: 'Cancelada' },
      'Concluída': { bg: 'bg-teal-50', text: 'text-teal-700', border: 'border-teal-200', icon: <CheckCircle className="w-5 h-5 text-teal-500" />, label: 'Concluída' }
    };
    const statusKey = Object.keys(statusMap).find(key => 
      key.toLowerCase() === status?.toLowerCase()
    );
    return statusMap[statusKey] || { bg: 'bg-gray-50', text: 'text-gray-700', border: 'border-gray-200', icon: <AlertCircle className="w-5 h-5 text-gray-500" />, label: status };
  };

  const getTipoIcon = (tipo) => {
    const tipos = { 'alojamento': '🏠', 'carro': '🚗', 'experiencia': '🏄' };
    return tipos[tipo] || '📦';
  };

  const downloadQRCode = () => {
    if (!detalhes?.qr_code) return;
    const link = document.createElement('a');
    link.download = `qr-code-${detalhes.codigo_reserva}.png`;
    link.href = detalhes.qr_code;
    link.target = '_blank';
    link.click();
  };

  const shareReserva = () => {
    if (!detalhes) return;
    const text = `Reserva ${detalhes.codigo_reserva} - ${detalhes.item_nome}\nPeríodo: ${detalhes.periodo}\nStatus: ${detalhes.status}\nValor: ${detalhes.valor} CVE`;
    if (navigator.share) {
      navigator.share({ title: `Reserva ${detalhes.codigo_reserva}`, text: text });
    } else {
      navigator.clipboard.writeText(text);
      alert('Detalhes copiados!');
    }
  };

  if (loading) {
    return (
      <div className="max-w-6xl mx-auto px-4 py-8">
        <div className="bg-white rounded-xl shadow-sm p-8 text-center">
          <Loader2 className="w-8 h-8 text-blue-600 mx-auto animate-spin" />
          <p className="text-gray-500 mt-4">Carregando detalhes da reserva...</p>
        </div>
      </div>
    );
  }

  if (error || !detalhes) {
    return (
      <div className="max-w-6xl mx-auto px-4 py-8">
        <div className="bg-white rounded-xl shadow-sm p-8 text-center">
          <AlertCircle className="w-12 h-12 text-red-500 mx-auto mb-4" />
          <h3 className="text-lg font-bold text-gray-900 mb-2">Erro ao carregar</h3>
          <p className="text-gray-600">{error || 'Reserva não encontrada'}</p>
          <button onClick={() => navigate('/gest/minhas-reservas')} className="mt-4 px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700">
            Voltar para Reservas
          </button>
        </div>
      </div>
    );
  }

  const statusConfig = getStatusConfig(detalhes.status);
  const valorTotal = Number(detalhes.valor) || 0;
  const valorPago = Number(detalhes.valor_pago) || valorTotal;
  const valorPendente = Math.max(0, valorTotal - valorPago);
  const temReembolso = reembolsos && reembolsos.length > 0;

  return (
    <div className="max-w-6xl mx-auto px-4 py-8">
      
      {/* Navegação */}
      <div className="flex items-center gap-2 text-sm text-gray-500 mb-6">
        <Link to="/gest" className="hover:text-blue-600 flex items-center gap-1">
          <Home className="w-4 h-4" /> Dashboard
        </Link>
        <ChevronRight className="w-4 h-4" />
        <Link to="/gest/minhas-reservas" className="hover:text-blue-600">Minhas Reservas</Link>
        <ChevronRight className="w-4 h-4" />
        <span className="text-gray-900 font-medium">{detalhes.codigo_reserva}</span>
      </div>

      {/* Header */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6 mb-6">
        <div className="flex flex-wrap items-start justify-between gap-4">
          <div className="flex items-center gap-4">
            <button onClick={() => navigate('/gest/minhas-reservas')} className="p-2 hover:bg-gray-100 rounded-full transition-colors">
              <ArrowLeft className="w-5 h-5 text-gray-600" />
            </button>
            <div>
              <div className="flex items-center gap-3">
                <span className="text-3xl">{getTipoIcon(detalhes.tipo)}</span>
                <div>
                  <h1 className="text-2xl font-bold text-gray-900">{detalhes.item_nome}</h1>
                  <p className="text-sm text-gray-500">Código: {detalhes.codigo_reserva}</p>
                </div>
              </div>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <button onClick={shareReserva} className="p-2 hover:bg-gray-100 rounded-lg transition-colors" title="Compartilhar">
              <Share2 className="w-5 h-5 text-gray-600" />
            </button>
            <button onClick={downloadQRCode} className="p-2 hover:bg-gray-100 rounded-lg transition-colors" title="Baixar QR Code">
              <Download className="w-5 h-5 text-gray-600" />
            </button>
          </div>
        </div>
      </div>

      {/* Status */}
      <div className={`${statusConfig.bg} border ${statusConfig.border} rounded-xl p-4 mb-6 flex flex-wrap items-center gap-4`}>
        <div className="flex items-center gap-2">
          {statusConfig.icon}
          <span className={`font-semibold ${statusConfig.text}`}>Status: {statusConfig.label}</span>
        </div>
        <span className="text-sm text-gray-500">Criado em {detalhes.data_criacao}</span>
        <div className="ml-auto text-right">
          <span className="text-sm text-gray-500">Valor Total</span>
          <p className="text-xl font-bold text-blue-600">{valorTotal.toLocaleString('pt-PT')} CVE</p>
        </div>
      </div>

      {/* Grid Principal */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        
        {/* Coluna Esquerda */}
        <div className="lg:col-span-2 space-y-6">
          
          {/* Item */}
          <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
            <div className="flex items-start gap-4">
              <img 
                src={detalhes.item_imagem || 'https://images.unsplash.com/photo-1560448204-e02f11c3d0e2?w=100&h=100&fit=crop'}
                alt={detalhes.item_nome}
                className="w-20 h-20 rounded-lg object-cover border border-gray-200"
              />
              <div className="flex-1">
                <h4 className="font-bold text-gray-900">{detalhes.item_nome}</h4>
                {detalhes.item_descricao && <p className="text-gray-600 text-sm mt-1">{detalhes.item_descricao}</p>}
                <div className="flex items-center gap-4 mt-2 text-sm text-gray-500">
                  <span className="flex items-center gap-1">
                    <Calendar className="w-4 h-4" /> {detalhes.periodo}
                  </span>
                </div>
              </div>
            </div>
          </div>

          {/* Detalhes Específicos */}
          <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
            <h4 className="font-bold text-gray-900 mb-4">📋 Detalhes da Reserva</h4>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
              {detalhes.especifico && Object.entries(detalhes.especifico).map(([key, value]) => {
                if (!value) return null;
                const labels = {
                  'checkin': 'Check-in', 'checkout': 'Check-out', 'noites': 'Noites', 'hospedes': 'Hóspedes',
                  'endereco': 'Endereço', 'cidade': 'Cidade', 'levantamento': 'Levantamento', 'devolucao': 'Devolução',
                  'dias': 'Dias', 'modelo': 'Modelo', 'marca': 'Marca', 'ano': 'Ano',
                  'data_participacao': 'Data', 'horario': 'Horário', 'pessoas': 'Pessoas',
                  'localizacao': 'Localização', 'duracao': 'Duração'
                };
                return (
                  <div key={key} className="flex flex-col p-2 bg-gray-50 rounded-lg">
                    <span className="text-xs text-gray-500">{labels[key] || key}</span>
                    <span className="font-medium text-gray-900">{value}</span>
                  </div>
                );
              })}
            </div>
          </div>

          {/* ⭐ RECIBO ⭐ */}
          <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
            <div className="flex items-center justify-between mb-4">
              <h4 className="font-bold text-gray-900 flex items-center gap-2">
                <Receipt className="w-5 h-5 text-blue-600" />
                Recibo
              </h4>
              <button
                onClick={baixarRecibo}
                className="flex items-center gap-2 px-3 py-1.5 bg-blue-600 hover:bg-blue-700 text-white text-xs font-bold rounded-lg transition-colors"
              >
                <Download className="w-3 h-3" />
                Baixar Recibo
              </button>
            </div>

            <div className="space-y-3">
              <div className="flex justify-between items-center p-3 bg-slate-50 rounded-lg">
                <span className="text-sm text-slate-600">Valor Total</span>
                <span className="font-bold text-slate-900">{valorTotal.toLocaleString('pt-PT')} CVE</span>
              </div>
              <div className="flex justify-between items-center p-3 bg-green-50 rounded-lg">
                <span className="text-sm text-green-700">Valor Pago</span>
                <span className="font-bold text-green-700">{valorPago.toLocaleString('pt-PT')} CVE</span>
              </div>
              {valorPendente > 0 && (
                <div className="flex justify-between items-center p-3 bg-orange-50 rounded-lg">
                  <span className="text-sm text-orange-700">Valor Pendente</span>
                  <span className="font-bold text-orange-700">{valorPendente.toLocaleString('pt-PT')} CVE</span>
                </div>
              )}
              <div className="flex justify-between items-center p-3 bg-blue-50 border-2 border-blue-200 rounded-lg">
                <span className="text-sm font-bold text-blue-700">Total Pago</span>
                <span className="text-lg font-black text-blue-700">{valorPago.toLocaleString('pt-PT')} CVE</span>
              </div>
            </div>

            <div className="mt-4 pt-4 border-t border-slate-100 text-xs text-slate-500">
              <p>Método: <strong>{detalhes.metodo_pagamento || 'Cartão'}</strong></p>
              <p>Emitido em: <strong>{detalhes.data_criacao}</strong></p>
            </div>
          </div>

          {/* ⭐ REEMBOLSO ⭐ */}
          {temReembolso && (
            <div className="bg-white rounded-xl shadow-sm border border-orange-200 p-6">
              <div className="flex items-center justify-between mb-4">
                <h4 className="font-bold text-gray-900 flex items-center gap-2">
                  <DollarSign className="w-5 h-5 text-orange-600" />
                  Reembolso
                </h4>
                <button
                  onClick={() => fetchReembolsos()}
                  className="p-1.5 hover:bg-orange-50 rounded-lg text-orange-600"
                  title="Atualizar"
                >
                  <RefreshCw size={14} className={loadingReembolsos ? 'animate-spin' : ''} />
                </button>
              </div>

              <div className="space-y-3">
                {reembolsos.map((re, i) => {
                  const statusRe = (re.status || '').toLowerCase();
                  const cor = statusRe.includes('process') ? 'bg-green-50 border-green-200 text-green-700'
                            : statusRe.includes('pendente') ? 'bg-yellow-50 border-yellow-200 text-yellow-700'
                            : statusRe.includes('rejeit') ? 'bg-red-50 border-red-200 text-red-700'
                            : 'bg-slate-50 border-slate-200 text-slate-700';
                  return (
                    <div key={i} className={`border-2 rounded-xl p-4 ${cor}`}>
                      <div className="flex justify-between items-start mb-2">
                        <span className="text-xs font-bold uppercase tracking-wider">
                          {re.status || 'Pendente'}
                        </span>
                        <span className="text-lg font-black">
                          {Number(re.valor).toLocaleString('pt-PT')} CVE
                        </span>
                      </div>
                      {re.motivo && (
                        <p className="text-xs opacity-80 mb-1">
                          <strong>Motivo:</strong> {re.motivo}
                        </p>
                      )}
                      <div className="flex flex-wrap gap-3 text-xs opacity-70 mt-2">
                        <span>Solicitado: {re.created_at_fmt}</span>
                        {re.processado_em_fmt && <span>Processado: {re.processado_em_fmt}</span>}
                        {re.metodo && <span>Método: {re.metodo}</span>}
                      </div>
                    </div>
                  );
                })}
              </div>

              <p className="text-xs text-slate-500 mt-4 pt-4 border-t border-orange-100">
                ℹ️ Os reembolsos são processados em até 5 dias úteis após a aprovação.
              </p>
            </div>
          )}

          {/* Histórico */}
          {detalhes.historico && detalhes.historico.length > 0 && (
            <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
              <h4 className="font-bold text-gray-900 mb-4">📋 Histórico</h4>
              <div className="space-y-4">
                {detalhes.historico.map((item, index) => (
                  <div key={index} className="flex gap-4">
                    <div className="flex flex-col items-center">
                      <div className="w-3 h-3 rounded-full border-2 border-white shadow" style={{ backgroundColor: item.cor || '#3b82f6' }}></div>
                      {index < detalhes.historico.length - 1 && <div className="w-0.5 h-8 bg-gray-300"></div>}
                    </div>
                    <div className="flex-1">
                      <div className="flex flex-wrap items-center justify-between">
                        <span className="font-medium text-gray-900">{item.status}</span>
                        <span className="text-sm text-gray-500">{item.data}</span>
                      </div>
                      {item.descricao && <p className="text-sm text-gray-600">{item.descricao}</p>}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

        </div>

        {/* Coluna Direita */}
        <div className="space-y-6">
          
          {/* QR Code */}
          <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6 text-center">
            <h4 className="font-bold text-gray-900 mb-3">📱 QR Code</h4>
            <div className="bg-white p-3 rounded-lg border border-gray-200 inline-block">
              <img src={detalhes.qr_code} alt="QR Code" className="w-40 h-40 object-contain" />
            </div>
            <p className="text-sm text-gray-500 mt-3">Apresente no check-in</p>
            <button onClick={downloadQRCode} className="mt-3 w-full px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 transition-colors">
              Baixar QR Code
            </button>
          </div>

          {/* Anfitrião */}
          {detalhes.proprietario && (
            <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
              <h4 className="font-bold text-gray-900 mb-3">👤 Anfitrião</h4>
              <div className="space-y-2">
                <div className="flex items-center gap-2 text-sm">
                  <User className="w-4 h-4 text-gray-500" />
                  <span className="font-medium">{detalhes.proprietario.nome}</span>
                </div>
                {detalhes.proprietario.email && (
                  <div className="flex items-center gap-2 text-sm">
                    <Mail className="w-4 h-4 text-gray-500" />
                    <a href={`mailto:${detalhes.proprietario.email}`} className="text-blue-600 hover:underline">{detalhes.proprietario.email}</a>
                  </div>
                )}
                {detalhes.proprietario.telefone && (
                  <div className="flex items-center gap-2 text-sm">
                    <Phone className="w-4 h-4 text-gray-500" />
                    <a href={`tel:${detalhes.proprietario.telefone}`} className="text-blue-600 hover:underline">{detalhes.proprietario.telefone}</a>
                  </div>
                )}
              </div>
            </div>
          )}

          {/* Ações */}
          <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
            <h4 className="font-bold text-gray-900 mb-3">⚡ Ações</h4>
            <div className="space-y-2">
              <button onClick={baixarRecibo} className="w-full px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 transition-colors flex items-center justify-center gap-2">
                <Receipt className="w-4 h-4" /> Baixar Recibo
              </button>
              <button onClick={() => window.print()} className="w-full px-4 py-2 bg-gray-100 text-gray-700 rounded-lg text-sm font-medium hover:bg-gray-200 transition-colors">
                🖨️ Imprimir
              </button>
              <Link to="/gest/minhas-reservas" className="w-full px-4 py-2 bg-blue-50 text-blue-600 rounded-lg text-sm font-medium hover:bg-blue-100 transition-colors block text-center">
                📋 Ver Todas
              </Link>
              {detalhes.status !== 'Cancelada' && detalhes.status !== 'Concluída' && (
                <button onClick={handleCancelar} disabled={canceling} className="w-full px-4 py-2 bg-red-600 text-white rounded-lg text-sm font-medium hover:bg-red-700 transition-colors disabled:opacity-50">
                  {canceling ? 'Cancelando...' : '❌ Cancelar Reserva'}
                </button>
              )}
            </div>
          </div>

        </div>
      </div>

    </div>
  );
}

// components/prestador/DocumentosSolicitados.jsx
import React, { useState, useEffect, useRef } from 'react';
import {
  FileText, Clock, CheckCircle2, XCircle, Upload,
  Loader2, AlertCircle, RefreshCw, X, Send, ArrowLeft,
  AlertTriangle, Edit3, Bell, Info,
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';

const API_URL = import.meta.env.VITE_API_URL || 'https://welovepalop.com/api';

const TIPOS_LABEL = {
  alvara:            'Alvará de funcionamento',
  licenca_turismo:   'Licença de turismo',
  caderneta_predial: 'Caderneta predial',
  certidao:          'Certidão permanente',
  bi_passaporte:     'BI ou Passaporte',
  carta_conducao:    'Carta de condução',
  livrete:           'Livrete do veículo',
  seguro:            'Apólice de seguro',
  licenca_guia:      'Licença de guia turístico',
  outro:             'Outro documento',
};

const TIPO_ANUNCIO = {
  alojamento:  { label: 'Alojamento',  base: '/alojamento-registro' },
  carro:       { label: 'Viatura',     base: '/carro-registo' },
  experiencia: { label: 'Experiência', base: '/experiencia-registro' },
};

export default function DocumentosSolicitados() {
  const navigate = useNavigate();

  const [pedidos, setPedidos] = useState([]);
  const [correcoes, setCorrecoes] = useState([]);
  const [notificacoes, setNotificacoes] = useState([]);
  const [naoLidas, setNaoLidas] = useState(0);
  const [loading, setLoading] = useState(true);
  const [pedidoSelecionado, setPedidoSelecionado] = useState(null);
  const [showModal, setShowModal] = useState(false);
  const [ficheiro, setFicheiro] = useState(null);
  const [enviando, setEnviando] = useState(false);
  const [msg, setMsg] = useState({ tipo: '', texto: '' });
  const [mostrarNotificacoes, setMostrarNotificacoes] = useState(false);
  const [usuarioId, setUsuarioId] = useState(null);

  const pollingRef = useRef(null);

  // Obter ID do utilizador de forma segura (JWT ou LocalStorage)
  useEffect(() => {
    const obterUserId = () => {
      try {
        const token = localStorage.getItem('token') || localStorage.getItem('morabeza_token');
        if (token) {
          const base64Url = token.split('.')[1];
          const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
          const jsonPayload = decodeURIComponent(atob(base64).split('').map(c => {
            return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
          }).join(''));
          const parsed = JSON.parse(jsonPayload);
          if (parsed.data?.id) return parsed.data.id;
          if (parsed.id) return parsed.id;
        }
        const savedUser = localStorage.getItem('user') || localStorage.getItem('morabeza_user');
        if (savedUser) {
          const user = JSON.parse(savedUser);
          return user.id;
        }
      } catch (e) {
        console.error('Erro ao obter ID:', e);
      }
      return null;
    };

    const id = obterUserId();
    setUsuarioId(id);
  }, []);

  const carregarNotificacoes = async () => {
    if (!usuarioId) return;

    try {
      const res = await fetch(`${API_URL}/usuarios/notificacoes.php`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'listar',
          usuario_id: usuarioId,
          limite: 20,
        }),
      });
      const texto = await res.text();
      let data;
      try { data = JSON.parse(texto); }
      catch { data = { status: 'error' }; }

      if (data.status === 'success') {
        setNotificacoes(data.data || []);
        setNaoLidas(data.nao_lidas || 0);
      }
    } catch (err) {
      console.error('Erro ao carregar notificações:', err);
    }
  };

  const carregarTudo = async () => {
    if (!usuarioId) {
      setLoading(false);
      return;
    }

    try {
      const resPedidos = await fetch(`${API_URL}/admin/solicitar_documento.php`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'listar_pedidos_prestador',
          prestador_id: usuarioId,
        }),
      });
      const textoPedidos = await resPedidos.text();
      let dataPedidos;
      try { dataPedidos = JSON.parse(textoPedidos); }
      catch { dataPedidos = { status: 'error' }; }

      if (dataPedidos.status === 'success') {
        setPedidos(dataPedidos.data || []);
      }

      const resCorr = await fetch(`${API_URL}/admin/solicitar_documento.php`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'listar_correcoes_prestador',
          prestador_id: usuarioId,
        }),
      });
      const textoCorr = await resCorr.text();
      let dataCorr;
      try { dataCorr = JSON.parse(textoCorr); }
      catch { dataCorr = { status: 'error' }; }

      if (dataCorr.status === 'success') {
        setCorrecoes(dataCorr.data || []);
      }

      await carregarNotificacoes();
    } catch (err) {
      console.error(err);
      setMsg({ tipo: 'erro', texto: 'Erro de ligação.' });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (usuarioId) {
      carregarTudo();

      pollingRef.current = setInterval(() => {
        carregarNotificacoes();
      }, 15000);
    }

    return () => {
      if (pollingRef.current) clearInterval(pollingRef.current);
    };
  }, [usuarioId]);

  const marcarTodasLidas = async () => {
    if (!usuarioId) return;
    try {
      await fetch(`${API_URL}/admin/anuncios/notificacoes.php`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'marcar_todas_lidas',
          usuario_id: usuarioId,
        }),
      });
      carregarNotificacoes();
    } catch (err) {
      console.error(err);
    }
  };

  const marcarLida = async (id) => {
    if (!usuarioId) return;
    try {
      await fetch(`${API_URL}/admin/anuncios/notificacoes.php`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'marcar_lida',
          notificacao_id: id,
          usuario_id: usuarioId,
        }),
      });
      carregarNotificacoes();
    } catch (err) {
      console.error(err);
    }
  };

  const abrirEnvio = (pedido) => {
    setPedidoSelecionado(pedido);
    setFicheiro(null);
    setMsg({ tipo: '', texto: '' });
    setShowModal(true);
  };

  const handleUploadEnviar = async (e) => {
    e.preventDefault();
    if (!ficheiro) {
      setMsg({ tipo: 'erro', texto: 'Escolhe um ficheiro.' });
      return;
    }

    setEnviando(true);
    setMsg({ tipo: '', texto: '' });

    try {
      const form = new FormData();
      form.append('documento', ficheiro);

      const resUp = await fetch(`${API_URL}/usuarios/upload_documento.php`, {
        method: 'POST',
        body: form,
      });
      const dataUp = await resUp.json();

      if (!dataUp.success) {
        setMsg({ tipo: 'erro', texto: dataUp.message || 'Falha no upload.' });
        setEnviando(false);
        return;
      }

      const resEnv = await fetch(`${API_URL}/admin/solicitar_documento.php`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'enviar_documento',
          pedido_id: pedidoSelecionado.id,
          prestador_id: usuarioId,
          documento_url: dataUp.documento_url,
        }),
      });
      const dataEnv = await resEnv.json();

      if (dataEnv.status === 'success') {
        setMsg({ tipo: 'sucesso', texto: dataEnv.message });
        await carregarTudo();
        setTimeout(() => {
          setShowModal(false);
          setPedidoSelecionado(null);
          setFicheiro(null);
        }, 1500);
      } else {
        setMsg({ tipo: 'erro', texto: dataEnv.message || 'Erro ao enviar.' });
      }
    } catch (err) {
      console.error(err);
      setMsg({ tipo: 'erro', texto: 'Erro de ligação.' });
    } finally {
      setEnviando(false);
    }
  };

  const formatarData = (d) => {
    if (!d) return '-';
    return new Date(d).toLocaleDateString('pt-PT', {
      day: '2-digit', month: '2-digit', year: 'numeric',
    });
  };

  const formatarRelativo = (d) => {
    if (!d) return '';
    const data = new Date(d);
    const agora = new Date();
    const diff = (agora - data) / 1000 / 60;

    if (diff < 1) return 'Agora';
    if (diff < 60) return `${Math.floor(diff)}m atrás`;
    if (diff < 1440) return `${Math.floor(diff / 60)}h atrás`;
    return data.toLocaleDateString('pt-PT', { day: '2-digit', month: '2-digit' });
  };

  const urlDocumentoComCache = (url, enviadoEm) => {
    if (!url) return '';
    let u = url;
    if (u.startsWith('https:///')) u = u.replace('https:///', 'https://');
    if (u.startsWith('http:///'))  u = u.replace('http:///', 'http://');
    const sep = u.includes('?') ? '&' : '?';
    const ts = enviadoEm ? new Date(enviadoEm).getTime() : Date.now();
    return `${u}${sep}v=${ts}`;
  };

  const StatusBadge = ({ estado }) => {
    const map = {
      pendente:  { cls: 'bg-yellow-100 text-yellow-700', ic: <Clock size={12} />,      txt: 'Pendente' },
      enviado:   { cls: 'bg-blue-100 text-blue-700',     ic: <Upload size={12} />,      txt: 'Enviado' },
      aprovado:  { cls: 'bg-green-100 text-green-700',   ic: <CheckCircle2 size={12} />, txt: 'Aprovado' },
      rejeitado: { cls: 'bg-red-100 text-red-700',       ic: <XCircle size={12} />,     txt: 'Rejeitado' },
      expirado:  { cls: 'bg-gray-100 text-gray-700',     ic: <AlertCircle size={12} />,  txt: 'Expirado' },
    };
    const s = map[estado] || map.pendente;
    return (
      <span className={`flex items-center gap-1 px-2 py-1 rounded-md text-xs font-semibold ${s.cls}`}>
        {s.ic} {s.txt}
      </span>
    );
  };

  const getIconeNotif = (tipo) => {
    switch (tipo) {
      case 'documento': return <FileText size={16} className="text-blue-600" />;
      case 'anuncio':   return <AlertTriangle size={16} className="text-orange-600" />;
      default:          return <Bell size={16} className="text-gray-600" />;
    }
  };

  const totalPendencias = correcoes.length + pedidos.filter(p => p.estado === 'pendente' || p.estado === 'rejeitado').length;

  return (
    <div className="max-w-4xl mx-auto px-4 py-6 space-y-6">
      <div className="flex items-center gap-4 flex-wrap">
        <button
          onClick={() => navigate(-1)}
          className="p-2 rounded-lg hover:bg-gray-100 transition"
          title="Voltar"
        >
          <ArrowLeft size={20} />
        </button>

        <div className="flex-1 min-w-0">
          <h1 className="text-2xl font-bold text-[#003580]">
            Pendências dos meus anúncios
          </h1>
          <p className="text-gray-600 mt-1 text-sm">
            Correções pedidas e documentos solicitados pela administração.
          </p>
        </div>

        {totalPendencias > 0 && (
          <span className="flex items-center gap-1 bg-red-100 text-red-700 px-3 py-1 rounded-full text-xs font-bold">
            <AlertCircle size={14} /> {totalPendencias} {totalPendencias === 1 ? 'pendência' : 'pendências'}
          </span>
        )}

        <button
          onClick={carregarTudo}
          className="flex items-center gap-2 px-4 py-2 bg-white rounded-lg border border-gray-200 hover:bg-gray-50 text-sm"
        >
          <RefreshCw size={16} /> Atualizar
        </button>
      </div>

      {msg.texto && !showModal && (
        <div className={`p-3 rounded-lg flex items-center gap-2 text-sm ${
          msg.tipo === 'sucesso' ? 'bg-green-50 text-green-800' : 'bg-red-50 text-red-800'
        }`}>
          {msg.tipo === 'sucesso' ? <CheckCircle2 size={16} /> : <AlertCircle size={16} />}
          <span>{msg.texto}</span>
        </div>
      )}

      {naoLidas > 0 && (
        <div className="bg-blue-50 border-2 border-blue-200 rounded-2xl p-5 shadow-sm">
          <div className="flex items-center gap-3 mb-3">
            <div className="relative">
              <Bell size={22} className="text-blue-600" />
              <span className="absolute -top-1 -right-1 bg-red-500 text-white text-[10px] font-bold rounded-full min-w-[16px] h-[16px] flex items-center justify-center px-1">
                {naoLidas > 9 ? '9+' : naoLidas}
              </span>
            </div>
            <h3 className="font-bold text-blue-900 text-base">
              Tens {naoLidas} {naoLidas === 1 ? 'notificação nova' : 'notificações novas'}
            </h3>
            <button
              onClick={marcarTodasLidas}
              className="ml-auto text-xs text-blue-700 hover:underline font-semibold flex items-center gap-1"
            >
              <CheckCircle2 size={12} /> Marcar todas como lidas
            </button>
          </div>

          <div className="space-y-2">
            {notificacoes.filter(n => n.lida == 0).slice(0, 3).map((n) => (
              <div
                key={n.id}
                className="bg-white rounded-xl p-3 flex items-start gap-3 cursor-pointer hover:bg-blue-50/50 transition"
                onClick={() => {
                  marcarLida(n.id);
                  if (n.tipo === 'documento' || n.tipo === 'anuncio') {
                    setMostrarNotificacoes(false);
                  }
                }}
              >
                <div className="flex-shrink-0 mt-0.5">
                  {getIconeNotif(n.tipo)}
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-bold text-gray-900">{n.titulo}</p>
                  <p className="text-xs text-gray-600 mt-0.5">{n.mensagem}</p>
                  <p className="text-[10px] text-gray-400 mt-1">{formatarRelativo(n.criado_em)}</p>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {notificacoes.length > 0 && (
        <div>
          <button
            onClick={() => setMostrarNotificacoes(!mostrarNotificacoes)}
            className="w-full flex items-center justify-between px-4 py-3 bg-white rounded-xl border border-gray-200 hover:bg-gray-50 transition text-sm font-semibold text-gray-700"
          >
            <span className="flex items-center gap-2">
              <Info size={16} /> Ver histórico de notificações ({notificacoes.length})
            </span>
            <span className={`transform transition-transform ${mostrarNotificacoes ? 'rotate-180' : ''}`}>
              ▼
            </span>
          </button>

          {mostrarNotificacoes && (
            <div className="mt-2 bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
              <div className="max-h-96 overflow-y-auto divide-y divide-gray-50">
                {notificacoes.map((n) => (
                  <div
                    key={n.id}
                    className={`p-4 flex items-start gap-3 hover:bg-gray-50 transition cursor-pointer ${
                      n.lida == 0 ? 'bg-blue-50/30' : ''
                    }`}
                    onClick={() => {
                      if (n.lida == 0) marcarLida(n.id);
                    }}
                  >
                    <div className="flex-shrink-0 mt-0.5">
                      {getIconeNotif(n.tipo)}
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <p className={`text-sm ${n.lida == 0 ? 'font-bold text-gray-900' : 'font-medium text-gray-700'}`}>
                          {n.titulo}
                        </p>
                        {n.lida == 0 && (
                          <span className="w-2 h-2 bg-blue-600 rounded-full flex-shrink-0"></span>
                        )}
                      </div>
                      <p className="text-xs text-gray-500 mt-1">{n.mensagem}</p>
                      <p className="text-[10px] text-gray-400 mt-1">{formatarRelativo(n.criado_em)}</p>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      )}

      {loading ? (
        <div className="py-20 flex justify-center">
          <Loader2 className="animate-spin text-[#003580]" size={32} />
        </div>
      ) : (
        <>
          {correcoes.length > 0 && (
            <div className="space-y-3">
              <h2 className="text-sm font-bold text-orange-600 uppercase tracking-wider flex items-center gap-2">
                <AlertTriangle size={16} /> Anúncios que precisam de correção
              </h2>

              {correcoes.map((c) => {
                const info = TIPO_ANUNCIO[c.tipo] || { label: c.tipo, base: '/' };

                return (
                  <div
                    key={`${c.tipo}-${c.id}`}
                    className="bg-orange-50 border-2 border-orange-200 rounded-2xl p-5 shadow-sm"
                  >
                    <div className="flex flex-col sm:flex-row sm:items-start justify-between gap-4">
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 flex-wrap mb-2">
                          <span className="px-2 py-0.5 bg-orange-200 text-orange-900 rounded-md text-xs font-bold">
                            {info.label}
                          </span>
                          <span className="px-2 py-0.5 bg-orange-600 text-white rounded-md text-xs font-semibold flex items-center gap-1">
                            <AlertTriangle size={10} /> Correção necessária
                          </span>
                        </div>

                        <h3 className="font-bold text-gray-900 text-base">
                          {c.titulo || `Anúncio #${c.id}`}
                        </h3>

                        {c.motivo && (
                          <div className="mt-3 p-3 bg-white border border-orange-100 rounded-xl">
                            <p className="text-xs font-semibold text-orange-700 uppercase tracking-wider mb-1">
                              O que precisa ser corrigido:
                            </p>
                            <p className="text-sm text-gray-700 whitespace-pre-wrap">
                              {c.motivo.replace(/^O teu anúncio precisa de correções\. Motivo: /i, '')}
                            </p>
                          </div>
                        )}

                        {!c.motivo && (
                          <p className="text-sm text-gray-500 mt-2">
                            A administração pediu correções neste anúncio. Verifica os dados e volta a enviar.
                          </p>
                        )}
                      </div>

                      <button
                        onClick={() => {
                          const url = `${info.base}/fluxo?edit=${c.id}&tipo=${c.tipo}`;
                          console.log('🔧 A abrir anúncio para correção:', url);
                          navigate(url);
                        }}
                        className="flex items-center gap-2 px-4 py-2.5 rounded-xl bg-orange-600 hover:bg-orange-700 text-white text-sm font-semibold transition flex-shrink-0"
                      >
                        <Edit3 size={14} /> Corrigir anúncio
                      </button>
                    </div>
                  </div>
                );
              })}
            </div>
          )}

          <div className="space-y-3">
            <h2 className="text-sm font-bold text-blue-600 uppercase tracking-wider flex items-center gap-2">
              <FileText size={16} /> Documentos solicitados
            </h2>

            {pedidos.length === 0 ? (
              <div className="py-12 text-center text-gray-500 bg-white rounded-2xl border border-gray-100">
                <FileText size={48} className="mx-auto mb-4 text-gray-300" />
                <p>Nenhum documento solicitado.</p>
                <p className="text-xs text-gray-400 mt-1">
                  Quando a administração pedir algo, aparece aqui.
                </p>
              </div>
            ) : (
              <div className="space-y-3">
                {pedidos.map((p) => {
                  const expirado = p.estado === 'pendente' && new Date(p.prazo) < new Date();
                  const podeEnviar =
                    p.estado === 'pendente' ||
                    p.estado === 'rejeitado' ||
                    p.estado === 'enviado';

                  return (
                    <div
                      key={p.id}
                      className="bg-white border border-gray-100 rounded-2xl p-5 shadow-sm flex flex-col sm:flex-row sm:items-center justify-between gap-4"
                    >
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 flex-wrap">
                          <h3 className="font-bold text-gray-900">
                            {TIPOS_LABEL[p.tipo_documento] || p.tipo_documento}
                          </h3>
                          <StatusBadge estado={expirado ? 'expirado' : p.estado} />
                        </div>
                        <p className="text-sm text-gray-500 mt-1">
                          Anúncio: <strong>{p.anuncio_titulo || `#${p.anuncio_id}`}</strong>
                        </p>
                        <p className="text-xs text-gray-500 mt-2">
                          <strong>Motivo:</strong> {p.motivo}
                        </p>
                        <p className="text-xs text-gray-400 mt-1">
                          Prazo: <strong>{formatarData(p.prazo)}</strong>
                          {p.enviado_em && ` • Enviado em: ${formatarData(p.enviado_em)}`}
                        </p>
                        {p.estado === 'rejeitado' && p.motivo_rejeicao && (
                          <div className="mt-2 text-xs bg-red-50 text-red-700 p-2 rounded-lg">
                            <strong>Motivo da rejeição:</strong> {p.motivo_rejeicao}
                          </div>
                        )}
                      </div>

                      <div className="flex items-center gap-2 flex-shrink-0">
                        {p.documento_url && (
                          <a
                            href={urlDocumentoComCache(p.documento_url, p.enviado_em)}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="text-sm text-blue-600 hover:underline"
                          >
                            Ver enviado
                          </a>
                        )}
                        {podeEnviar && (
                          <button
                            onClick={() => abrirEnvio(p)}
                            className={`flex items-center gap-2 px-4 py-2 rounded-xl text-white text-sm font-semibold transition ${
                              p.estado === 'enviado'
                                ? 'bg-gray-600 hover:bg-gray-700'
                                : 'bg-[#003580] hover:bg-[#002860]'
                            }`}
                          >
                            <Upload size={14} />
                            {p.estado === 'enviado'
                              ? 'Substituir documento'
                              : p.estado === 'rejeitado'
                              ? 'Reenviar'
                              : 'Enviar documento'}
                          </button>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </>
      )}

      {showModal && pedidoSelecionado && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl max-w-lg w-full">
            <div className="flex items-center justify-between p-5 border-b">
              <h2 className="text-lg font-bold text-[#003580]">
                {pedidoSelecionado.estado === 'enviado' ? 'Substituir documento' : 'Enviar documento'}
              </h2>
              <button
                onClick={() => setShowModal(false)}
                className="p-1.5 hover:bg-gray-100 rounded-lg"
              >
                <X size={20} />
              </button>
            </div>

            <form onSubmit={handleUploadEnviar} className="p-5 space-y-4">
              {msg.texto && (
                <div className={`p-3 rounded-lg flex items-center gap-2 text-sm ${
                  msg.tipo === 'sucesso' ? 'bg-green-50 text-green-800' : 'bg-red-50 text-red-800'
                }`}>
                  {msg.tipo === 'sucesso' ? <CheckCircle2 size={16} /> : <AlertCircle size={16} />}
                  <span>{msg.texto}</span>
                </div>
              )}

              {pedidoSelecionado.estado === 'enviado' && (
                <div className="p-3 bg-yellow-50 border border-yellow-200 rounded-xl text-xs text-yellow-800">
                  ⚠️ Já enviaste um documento. Se enviares outro, o anterior será <strong>substituído</strong>.
                </div>
              )}

              <div className="bg-gray-50 rounded-xl p-3 text-sm">
                <p className="text-gray-500">Documento solicitado:</p>
                <p className="font-bold text-gray-800">
                  {TIPOS_LABEL[pedidoSelecionado.tipo_documento]}
                </p>
                <p className="text-xs text-gray-500 mt-1">
                  Prazo: {formatarData(pedidoSelecionado.prazo)}
                </p>
              </div>

              <div>
                <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wider mb-2">
                  Ficheiro (PDF, JPG ou PNG · máx. 10MB)
                </label>
                <input
                  type="file"
                  accept=".pdf,.jpg,.jpeg,.png"
                  onChange={(e) => setFicheiro(e.target.files[0] || null)}
                  className="w-full border border-gray-200 rounded-xl px-4 py-2.5 text-sm file:mr-4 file:py-2 file:px-4 file:rounded-lg file:border-0 file:bg-[#003580] file:text-white file:text-xs file:font-semibold hover:file:bg-[#002860] cursor-pointer"
                  required
                />
                {ficheiro && (
                  <p className="text-xs text-gray-500 mt-2">
                    {ficheiro.name} ({(ficheiro.size / 1024).toFixed(0)} KB)
                  </p>
                )}
              </div>

              <div className="flex gap-3 pt-2">
                <button
                  type="button"
                  onClick={() => setShowModal(false)}
                  disabled={enviando}
                  className="flex-1 px-4 py-2.5 rounded-xl text-sm font-medium border border-gray-300 hover:bg-gray-50"
                >
                  Cancelar
                </button>
                <button
                  type="submit"
                  disabled={enviando || !ficheiro}
                  className="flex-1 flex items-center justify-center gap-2 bg-[#003580] hover:bg-[#002860] text-white px-4 py-2.5 rounded-xl text-sm font-semibold disabled:opacity-50"
                >
                  {enviando ? (
                    <><Loader2 size={16} className="animate-spin" /> A enviar...</>
                  ) : (
                    <><Send size={16} /> Enviar</>
                  )}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

