// src/components/gest/GestaoRouter.jsx

import React, { useState, useEffect, lazy, Suspense } from 'react';
import { Routes, Route, Navigate, useNavigate } from 'react-router-dom';
import { Menu } from 'lucide-react';

import Navbar from '../Navbar'; 
import Sidebar from './Sidebar';
import Dashboard from './Dashboard';
import Calendario from './Calendario';
import Reservas from './Reservas';
import Mensagens from './Mensagens';
import Financeiro from './Financeiro';
import Relatorios from './Relatorios';
import Historico from './Historico';
import Avaliacoes from './Avaliacoes';
import Configuracoes from './Configuracoes';
import MinhasReservas from './MinhasReservas';
import DetalhesReserva from './DetalhesReserva';
import DocumentosSolicitados from './DocumentosSolicitados';
import DadosRecebimento from './DadosRecebimento';
import UnidadesVeiculos from './UnidadesVeiculos';
import LevantamentoCaucaoCondicoes from './LevantamentoCaucaoCondicoes';
import MinhasExperiencias from './MinhasExperiencias';

// 🔥 Lazy para páginas mais pesadas
const ConfigurarSessoes = lazy(() => import('./ConfigurarSessoes'));
const ConfigurarBloqueios = lazy(() => import('./ConfigurarBloqueios'));
const PoliticasReserva = lazy(() => import('./PoliticasReserva'));

const LoadingSpinner = () => (
  <div className="flex items-center justify-center h-64">
    <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
  </div>
);

const LayoutGestao = ({ children }) => {
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [isAuthenticated, setIsAuthenticated] = useState(null);
  const navigate = useNavigate();
  
  useEffect(() => {
    const token = localStorage.getItem('token') || localStorage.getItem('morabeza_token');
    const userData = localStorage.getItem('user');
    
    if (token) {
      try {
        const base64Url = token.split('.')[1];
        if (base64Url) {
          const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
          const jsonPayload = decodeURIComponent(atob(base64).split('').map(c => {
            return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
          }).join(''));
          
          const payload = JSON.parse(jsonPayload);
          
          if (payload.exp && Date.now() >= payload.exp * 1000) {
            localStorage.removeItem('token');
            localStorage.removeItem('morabeza_token');
            navigate('/login');
            return;
          }
        }
        setIsAuthenticated(true);
      } catch (e) {
        setIsAuthenticated(true);
      }
    } else if (userData) {
      setIsAuthenticated(true);
    } else {
      navigate('/login');
    }
  }, [navigate]);
  
  if (isAuthenticated === null) {
    return (
      <div className="h-screen flex items-center justify-center bg-[#f8f9fc]">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-900 mx-auto"></div>
          <p className="mt-4 text-slate-600">Verificando acesso...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="h-screen flex flex-col bg-[#f8f9fc] overflow-hidden relative">
      
      <Navbar />

      <div className="flex flex-1 overflow-hidden relative">
        <Sidebar isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} />
        
        {sidebarOpen && (
          <div 
            onClick={() => setSidebarOpen(false)} 
            className="lg:hidden fixed inset-0 bg-black/40 z-30" 
          />
        )}

        <div className="flex-1 flex flex-col overflow-hidden">
          
          <div className="lg:hidden flex items-center justify-between bg-white px-4 py-3 border-b border-gray-100 shadow-sm z-20">
            <span className="font-bold text-[#0f172a] text-[15px]">Menu do Anfitrião</span>
            <button 
              onClick={() => setSidebarOpen(true)}
              className="bg-[#f8fafc] border border-gray-100 hover:bg-gray-100 p-2 rounded-lg transition-colors flex items-center justify-center shadow-sm"
            >
              <Menu className="w-6 h-6 text-[#0f172a]" strokeWidth={2} />
            </button>
          </div>

          <div className="flex-1 overflow-y-auto p-4 md:p-8">
            <Suspense fallback={<LoadingSpinner />}>
              {children}
            </Suspense>
          </div>

        </div>
      </div>
    </div>
  );
};

const GestaoRouter = () => {
  return (
    <Routes>
      <Route path="dashboard" element={<LayoutGestao><Dashboard /></LayoutGestao>} />
      <Route path="calendario" element={<LayoutGestao><Calendario /></LayoutGestao>} />
      <Route path="reservas" element={<LayoutGestao><Reservas /></LayoutGestao>} />
      <Route path="mensagens" element={<LayoutGestao><Mensagens /></LayoutGestao>} />
      <Route path="financeiro" element={<LayoutGestao><Financeiro /></LayoutGestao>} />
      <Route path="historico" element={<LayoutGestao><Historico /></LayoutGestao>} />
      <Route path="relatorios" element={<LayoutGestao><Relatorios /></LayoutGestao>} />
      <Route path="avaliacoes" element={<LayoutGestao><Avaliacoes /></LayoutGestao>} />
      <Route path="configuracoes" element={<LayoutGestao><Configuracoes /></LayoutGestao>} />
      <Route path="minhas-reservas" element={<LayoutGestao><MinhasReservas /></LayoutGestao>} />
      <Route path="documentos-solicitados" element={<LayoutGestao><DocumentosSolicitados /></LayoutGestao>} />
      <Route path="dados-recebimento" element={<LayoutGestao><DadosRecebimento /></LayoutGestao>} />
      <Route path="unidades-veiculos" element={<LayoutGestao><UnidadesVeiculos /></LayoutGestao>} />
      <Route path="condicoes-veiculos" element={<LayoutGestao><LevantamentoCaucaoCondicoes /></LayoutGestao>} />

      {/* ============================================================ */}
      {/* 🔥 EXPERIÊNCIAS DO ANFITRIÃO */}
      {/* ============================================================ */}
      <Route path="minhas-experiencias" element={<LayoutGestao><MinhasExperiencias /></LayoutGestao>} />
      <Route path="experiencia/:id/sessoes" element={<LayoutGestao><ConfigurarSessoes /></LayoutGestao>} />
      <Route path="experiencia/:id/bloqueios" element={<LayoutGestao><ConfigurarBloqueios /></LayoutGestao>} />
      <Route path="experiencia/:id/politicas" element={<LayoutGestao><PoliticasReserva /></LayoutGestao>} />

      {/* ============================================================ */}
      {/* DETALHES DA RESERVA */}
      {/* ============================================================ */}
      <Route path="reserva/:id/:tipo" element={<LayoutGestao><DetalhesReserva /></LayoutGestao>} />

      {/* ============================================================ */}
      {/* REDIRECIONAMENTOS */}
      {/* ============================================================ */}
      <Route path="" element={<Navigate to="/gest/dashboard" replace />} />
      <Route path="*" element={<Navigate to="/gest/dashboard" replace />} />
    </Routes>
  );
};

export default GestaoRouter;

// src/components/gest/Historico.jsx
import React, { useState, useEffect } from 'react';
import { Loader2, Home, Car, Compass, Award, Filter } from 'lucide-react';

export default function Historico() {
  const [pagamentos, setPagamentos] = useState([]);
  const [loading, setLoading] = useState(true);
  const [userRoles, setUserRoles] = useState({
    anfitrion: false,
    guia: false,
    proprietarioVeiculos: false
  });
  const [filtroTipo, setFiltroTipo] = useState('todos');
  const [resumo, setResumo] = useState({
    totalBruto: 0,
    totalLiquido: 0,
    totalPago: 0,
    totalPendente: 0
  });

  // Obter ID do utilizador de forma segura (JWT ou LocalStorage)
  const obterUserId = () => {
    try {
      const token = localStorage.getItem('token') || localStorage.getItem('morabeza_token');
      if (token) {
        const base64Url = token.split('.')[1];
        const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
        const jsonPayload = decodeURIComponent(atob(base64).split('').map(c => {
          return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
        }).join(''));
        const parsed = JSON.parse(jsonPayload);
        if (parsed.data?.id) return parsed.data.id;
        if (parsed.id) return parsed.id;
      }
      const savedUser = localStorage.getItem('user') || localStorage.getItem('morabeza_user');
      if (savedUser) {
        const user = JSON.parse(savedUser);
        return user.id;
      }
    } catch (e) {
      console.error('Erro ao obter ID:', e);
    }
    return null;
  };

  useEffect(() => {
    fetchHistorico();
  }, []);

  const fetchHistorico = async () => {
    setLoading(true);
    try {
      const userId = obterUserId();
      if (!userId) {
        setLoading(false);
        return;
      }
      
      // Buscar roles do usuário
      const rolesResponse = await fetch(`https://welovepalop.com/api/usuarios/listar_roles.php?usuario_id=${userId}`);
      const rolesData = await rolesResponse.json();
      
      let isAnfitrion = false;
      let isGuia = false;
      let isProprietarioVeiculos = false;
      
      if (rolesData.success && rolesData.roles) {
        isAnfitrion = rolesData.roles.some(r => r.name === 'anfitrion' && r.status === 'approved');
        isGuia = rolesData.roles.some(r => r.name === 'guia_experiencias' && r.status === 'approved');
        isProprietarioVeiculos = rolesData.roles.some(r => r.name === 'proprietario_veiculos' && r.status === 'approved');
        
        setUserRoles({
          anfitrion: isAnfitrion,
          guia: isGuia,
          proprietarioVeiculos: isProprietarioVeiculos
        });
      }
      
      // Buscar reservas
      const response = await fetch(`https://welovepalop.com/api/dashboard/reservas_recentes.php?usuario_id=${userId}`);
      const data = await response.json();
      
      let pagamentosList = [];
      let totalBruto = 0;
      let totalLiquido = 0;
      let totalPago = 0;
      let totalPendente = 0;
      
      if (data.success && data.data?.reservas) {
        // Filtrar reservas apenas dos tipos que o usuário tem role
        const reservasFiltradas = data.data.reservas.filter(reserva => {
          if (reserva.tipo === 'alojamento' && !isAnfitrion) return false;
          if (reserva.tipo === 'carro' && !isProprietarioVeiculos) return false;
          if (reserva.tipo === 'experiencia' && !isGuia) return false;
          return true;
        });
        
        pagamentosList = reservasFiltradas.map((reserva) => {
          const valorBruto = parseFloat(reserva.valor) || 0;
          const valorLiquido = valorBruto * 0.9;
          const statusPagamento = reserva.status === 'Confirmada' ? 'Pago' : 'Pendente';
          
          if (statusPagamento === 'Pago') {
            totalPago += valorLiquido;
          } else {
            totalPendente += valorLiquido;
          }
          totalBruto += valorBruto;
          totalLiquido += valorLiquido;
          
          return {
            id: reserva.codigo || `#RES${String(reserva.id)}`,
            data: reserva.created_at ? new Date(reserva.created_at).toLocaleDateString('pt-PT') : 'Data não informada',
            desc: reserva.item_nome,
            periodo: reserva.periodo || 'Período não informado',
            tipo: reserva.tipo,
            bruto: valorBruto,
            liquido: valorLiquido,
            status: statusPagamento
          };
        });
      }
      
      setPagamentos(pagamentosList);
      setResumo({
        totalBruto,
        totalLiquido,
        totalPago,
        totalPendente
      });
      
    } catch (error) {
      console.error('Erro ao buscar histórico:', error);
    } finally {
      setLoading(false);
    }
  };

  const getTipoIcone = (tipo) => {
    switch(tipo) {
      case 'alojamento': return <Home size={14} className="text-blue-500" />;
      case 'carro': return <Car size={14} className="text-green-500" />;
      case 'experiencia': return <Compass size={14} className="text-purple-500" />;
      default: return null;
    }
  };

  // Filtrar pagamentos por tipo
  const pagamentosFiltrados = filtroTipo === 'todos' 
    ? pagamentos 
    : pagamentos.filter(p => p.tipo === filtroTipo);

  const hasAnyRole = userRoles.anfitrion || userRoles.guia || userRoles.proprietarioVeiculos;

  if (loading) {
    return (
      <div className="max-w-6xl w-full text-[#1a1f36] px-4 py-6 md:px-0 flex justify-center items-center h-96">
        <Loader2 size={48} className="animate-spin text-blue-900" />
      </div>
    );
  }

  if (!hasAnyRole) {
    return (
      <div className="max-w-6xl w-full text-[#1a1f36] px-4 py-6 md:px-0">
        <div className="bg-white rounded-2xl p-12 text-center border border-gray-100 shadow-sm">
          <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
            <Award size={40} className="text-gray-400" />
          </div>
          <h2 className="text-xl font-bold text-gray-800 mb-2">Acesso Restrito</h2>
          <p className="text-gray-500 max-w-md mx-auto">
            Você não tem permissão para aceder ao histórico de pagamentos.
            É necessário ter uma das seguintes funções aprovadas:
            Anfitrião, Guia de Experiências ou Proprietário de Veículos.
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-7xl w-full text-[#1a1f36] px-4 py-6 md:px-0">
      <h1 className="text-[24px] font-bold mb-6">Histórico de Pagamentos</h1>
      
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
        <div className="bg-white rounded-xl p-4 border border-gray-100 shadow-sm">
          <p className="text-[11px] font-bold text-gray-400 mb-1">Total Bruto</p>
          <p className="text-[22px] font-bold text-gray-800">{resumo.totalBruto.toLocaleString()} CVE</p>
        </div>
        <div className="bg-white rounded-xl p-4 border border-gray-100 shadow-sm">
          <p className="text-[11px] font-bold text-gray-400 mb-1">Total Líquido (após 10%)</p>
          <p className="text-[22px] font-bold text-green-600">{resumo.totalLiquido.toLocaleString()} CVE</p>
        </div>
        <div className="bg-white rounded-xl p-4 border border-gray-100 shadow-sm">
          <p className="text-[11px] font-bold text-gray-400 mb-1">Já Recebido</p>
          <p className="text-[22px] font-bold text-blue-600">{resumo.totalPago.toLocaleString()} CVE</p>
        </div>
        <div className="bg-white rounded-xl p-4 border border-gray-100 shadow-sm">
          <p className="text-[11px] font-bold text-gray-400 mb-1">A Receber</p>
          <p className="text-[22px] font-bold text-orange-600">{resumo.totalPendente.toLocaleString()} CVE</p>
        </div>
      </div>

      <div className="flex flex-wrap items-center gap-3 mb-4">
        <div className="flex items-center gap-2">
          <Filter size={16} className="text-gray-400" />
          <span className="text-[12px] font-medium text-gray-500">Filtrar por tipo:</span>
        </div>
        <button
          onClick={() => setFiltroTipo('todos')}
          className={`px-3 py-1.5 rounded-lg text-[12px] font-medium transition-colors ${
            filtroTipo === 'todos' 
              ? 'bg-blue-900 text-white' 
              : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
          }`}
        >
          Todos
        </button>
        {userRoles.anfitrion && (
          <button
            onClick={() => setFiltroTipo('alojamento')}
            className={`px-3 py-1.5 rounded-lg text-[12px] font-medium transition-colors flex items-center gap-1 ${
              filtroTipo === 'alojamento' 
                ? 'bg-blue-900 text-white' 
                : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
            }`}
          >
            <Home size={12} /> Alojamentos
          </button>
        )}
        {userRoles.proprietarioVeiculos && (
          <button
            onClick={() => setFiltroTipo('carro')}
            className={`px-3 py-1.5 rounded-lg text-[12px] font-medium transition-colors flex items-center gap-1 ${
              filtroTipo === 'carro' 
                ? 'bg-blue-900 text-white' 
                : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
            }`}
          >
            <Car size={12} /> Carros
          </button>
        )}
        {userRoles.guia && (
          <button
            onClick={() => setFiltroTipo('experiencia')}
            className={`px-3 py-1.5 rounded-lg text-[12px] font-medium transition-colors flex items-center gap-1 ${
              filtroTipo === 'experiencia' 
                ? 'bg-blue-900 text-white' 
                : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
            }`}
          >
            <Compass size={12} /> Experiências
          </button>
        )}
      </div>
      
      <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
        {pagamentosFiltrados.length === 0 ? (
          <div className="text-center py-12">
            <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-3">
              <Award size={24} className="text-gray-400" />
            </div>
            <p className="text-gray-500">Nenhum pagamento encontrado</p>
            <p className="text-xs text-gray-400 mt-1">
              {filtroTipo !== 'todos' ? 'Nenhum pagamento para o tipo selecionado' : 'Os seus pagamentos aparecerão aqui'}
            </p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full min-w-[800px] text-left">
              <thead>
                <tr className="bg-gray-50/50 border-b border-gray-100">
                  <th className="px-6 py-4 text-[12px] font-bold text-gray-500 uppercase">Data</th>
                  <th className="px-6 py-4 text-[12px] font-bold text-gray-500 uppercase">Descrição</th>
                  <th className="px-6 py-4 text-[12px] font-bold text-gray-500 uppercase">Reserva</th>
                  <th className="px-6 py-4 text-[12px] font-bold text-gray-500 uppercase">Bruto</th>
                  <th className="px-6 py-4 text-[12px] font-bold text-gray-500 uppercase">Líquido (90%)</th>
                  <th className="px-6 py-4 text-[12px] font-bold text-gray-500 uppercase">Status</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {pagamentosFiltrados.map((pag, i) => (
                  <tr key={i} className="hover:bg-gray-50/50 transition-colors">
                    <td className="px-6 py-5 text-[13px] font-bold">{pag.data}</td>
                    <td className="px-6 py-5">
                      <div className="flex items-center gap-2">
                        {getTipoIcone(pag.tipo)}
                        <div className="flex flex-col">
                          <span className="text-[14px] font-bold">{pag.desc}</span>
                          <span className="text-[12px] text-gray-500">{pag.periodo}</span>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-5 text-[13px] font-bold text-[#2563eb]">{pag.id}</td>
                    <td className="px-6 py-5 text-[14px] font-bold">{pag.bruto.toLocaleString()} CVE</td>
                    <td className="px-6 py-5 text-[14px] font-bold text-green-600">{pag.liquido.toLocaleString()} CVE</td>
                    <td className="px-6 py-5">
                      <span className={`px-3 py-1 rounded-md text-[11px] font-bold ${
                        pag.status === 'Pago' 
                          ? 'bg-green-100 text-green-700' 
                          : 'bg-orange-100 text-orange-700'
                      }`}>
                        {pag.status}
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
      
      <div className="mt-6 bg-gray-50 rounded-xl p-4 border border-gray-100">
        <div className="flex items-start gap-3">
          <div className="w-8 h-8 bg-blue-100 rounded-full flex items-center justify-center flex-shrink-0">
            <span className="text-blue-600 font-bold text-sm">%</span>
          </div>
          <div>
            <p className="text-[12px] text-gray-600">
              <span className="font-bold">Nota:</span> O valor líquido apresentado já tem deduzida a comissão de 10% da Morabeza Stay. 
              Os pagamentos são processados após a confirmação do check-in pelo hóspede.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}

// src/components/gest/ConfigurarSessoes.jsx
import React, { useState, useEffect, useCallback, useMemo, useRef, memo } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import {
  Loader2, Plus, Trash2, Calendar, Clock, Users, Save, ArrowLeft,
  AlertCircle, CheckCircle, X, Sun, Sunset, Info, Edit2, Copy,
  ToggleLeft, ToggleRight, DollarSign, RefreshCw, Search, ArrowRight,
  BarChart3, AlertTriangle
} from 'lucide-react';
import ModalTransferir from './ModalTransferir';
import HistoricoSessoes from './HistoricoSessoes';

const API_BASE = 'https://welovepalop.com';

// ============================================================
// HELPER: obter utilizador do JWT
// ============================================================
function obterUsuarioId() {
  try {
    const token = localStorage.getItem('token')
      || localStorage.getItem('morabeza_token')
      || localStorage.getItem('access_token')
      || localStorage.getItem('jwt');
    if (token) {
      const base64Url = token.split('.')[1];
      const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
      const parsed = JSON.parse(decodeURIComponent(
        atob(base64).split('').map(c => '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2)).join('')
      ));
      const user = parsed?.data || parsed?.user || parsed?.usuario || parsed;
      const id = user?.id || user?.userId || user?.user_id || user?.usuario_id || parsed?.sub;
      if (id) return Number(id);
    }
    const savedUser = localStorage.getItem('user') || localStorage.getItem('morabeza_user');
    if (savedUser) {
      const u = JSON.parse(savedUser);
      if (u?.id) return Number(u.id);
    }
    return null;
  } catch { return null; }
}

// ============================================================
// HELPER: normalizar data -> sempre "YYYY-MM-DD"
// Aceita: "2026-10-08", "2026-10-08 00:00:00", "08/10/2026", etc.
// ============================================================
const normalizarData = (d) => {
  if (!d) return '';
  const s = String(d).trim();

  // Formato ISO: "2026-10-08..." ou "2026-10-08T..."
  const isoMatch = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (isoMatch) return `${isoMatch[1]}-${isoMatch[2]}-${isoMatch[3]}`;

  // Formato PT: "08/10/2026"
  const ptMatch = s.match(/^(\d{2})\/(\d{2})\/(\d{4})/);
  if (ptMatch) return `${ptMatch[3]}-${ptMatch[2]}-${ptMatch[1]}`;

  return s;
};

// ============================================================
// HELPER: normalizar hora -> sempre "HH:MM"
// Aceita: "08:00", "08:00:00", "8:00", "08:00:00.000"
// ============================================================
const normalizarHora = (h) => {
  if (!h) return '';
  const s = String(h).trim();
  const match = s.match(/^(\d{1,2}):(\d{2})/);
  if (!match) return s.substring(0, 5);
  return `${match[1].padStart(2, '0')}:${match[2]}`;
};

// ============================================================
// HELPER: sanitizar mensagens de erro do backend
// Cobre SQLSTATE, Duplicate, Integrity, uk_sessao, PDOException,
// Erro BD, MySQL, etc. — devolve SEMPRE mensagem amigável.
// ============================================================
const sanitizarErroBackend = (msg, contexto = {}) => {
  const { data, hora_inicio } = contexto;

  if (!msg) {
    return 'Não foi possível guardar a sessão. Tente novamente.';
  }

  const texto = String(msg);
  const lower = texto.toLowerCase();

  // ─── Duplicação (UNIQUE) ───
  const isDuplicado =
    lower.includes('duplicate') ||
    lower.includes('1062') ||
    lower.includes('uk_sessao') ||
    lower.includes('integrity constraint') ||
    lower.includes('integrity') ||
    lower.includes('já existe') ||
    lower.includes('ja existe') ||
    lower.includes('duplicad');

  if (isDuplicado) {
    const dataFmt = data ? normalizarData(data) : '';
    const horaFmt = hora_inicio ? normalizarHora(hora_inicio) : '';
    const quando = dataFmt && horaFmt ? ` (${dataFmt} às ${horaFmt})` : '';
    return `Já existe uma sessão nesse horário${quando}. Escolha um horário diferente ou edite a sessão existente.`;
  }

  // ─── Qualquer erro técnico SQL / BD ───
  const isTecnico =
    lower.includes('sqlstate') ||
    lower.includes('pdoexception') ||
    lower.includes('syntax error') ||
    lower.includes('mysql') ||
    lower.includes('sqlite') ||
    lower.includes('erro bd') ||
    lower.includes('erro db') ||
    lower.includes('database error') ||
    lower.includes('base de dados') ||
    lower.includes('unknown column') ||
    lower.includes('foreign key') ||
    lower.includes('constraint');

  if (isTecnico) {
    return 'Não foi possível guardar a sessão. Verifique os dados e tente novamente.';
  }

  // ─── Rede ───
  if (
    lower.includes('failed to fetch') ||
    lower.includes('network') ||
    lower.includes('load failed')
  ) {
    return 'Não foi possível contactar o servidor. Verifique a sua ligação à internet.';
  }

  // ─── Mensagem já amigável do backend → passa ───
  return texto;
};

// ============================================================
// HELPER: extrair mensagem de erro do backend
// Suporta data.error, data.erro, data.message, data.mensagem
// ============================================================
const extrairErroBackend = (data) => {
  if (!data || typeof data !== 'object') return '';
  return (
    data.error ||
    data.erro ||
    data.message ||
    data.mensagem ||
    ''
  );
};

// ============================================================
// MODAL: Criar/Editar Sessão
// ============================================================
const ModalSessao = memo(function ModalSessao({
  show, onClose, onSave, sessaoEditando, experienciaId, sessoesExistentes = []
}) {
  const { t } = useTranslation();
  const [form, setForm] = useState({
    data: '',
    hora_inicio: '08:00',
    hora_fim: '11:00',
    periodo: 'Manhã',
    capacidade_maxima: 15,
    preco_especial: '',
    ativo: 1
  });
  const [salvando, setSalvando] = useState(false);
  const [erro, setErro] = useState('');
  const abortRef = useRef(null);

  // cleanup ao desmontar
  useEffect(() => {
    return () => {
      if (abortRef.current) abortRef.current.abort();
    };
  }, []);

  // Reset quando abre
  useEffect(() => {
    if (show) {
      setErro('');
      if (sessaoEditando) {
        setForm({
          data: normalizarData(sessaoEditando.data) || '',
          hora_inicio: normalizarHora(sessaoEditando.hora_inicio) || '08:00',
          hora_fim: normalizarHora(sessaoEditando.hora_fim) || '11:00',
          periodo: sessaoEditando.periodo || 'Manhã',
          capacidade_maxima: sessaoEditando.capacidade_maxima || 15,
          preco_especial: sessaoEditando.preco_especial || '',
          ativo: sessaoEditando.ativo ?? 1
        });
      } else {
        setForm({
          data: new Date().toISOString().split('T')[0],
          hora_inicio: '08:00',
          hora_fim: '11:00',
          periodo: 'Manhã',
          capacidade_maxima: 15,
          preco_especial: '',
          ativo: 1
        });
      }
    }
  }, [show, sessaoEditando]);

  // Auto-detectar período
  useEffect(() => {
    const hora = parseInt(form.hora_inicio.split(':')[0]);
    let periodo = 'Manhã';
    if (hora >= 12 && hora < 15) periodo = 'Meio dia';
    else if (hora >= 15) periodo = 'Tarde';
    if (periodo !== form.periodo) {
      setForm(prev => ({ ...prev, periodo }));
    }
  }, [form.hora_inicio, form.periodo]);

  // Auto-calcular hora fim (+3h)
  useEffect(() => {
    const [h, m] = form.hora_inicio.split(':').map(Number);
    const fimH = (h + 3) % 24;
    const fimStr = `${String(fimH).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
    if (fimStr !== form.hora_fim) {
      setForm(prev => ({ ...prev, hora_fim: fimStr }));
    }
  }, [form.hora_inicio, form.hora_fim]);

  // ============================================================
  // Sessões do dia (com DATA NORMALIZADA — correção do bug)
  // ============================================================
  const sessoesDoDia = useMemo(() => {
    if (!form.data) return [];
    const dataFormNorm = normalizarData(form.data);

    return sessoesExistentes
      .filter(s => normalizarData(s.data) === dataFormNorm)
      .filter(s => !sessaoEditando || Number(s.id) !== Number(sessaoEditando.id))
      .sort((a, b) =>
        normalizarHora(a.hora_inicio).localeCompare(normalizarHora(b.hora_inicio))
      );
  }, [sessoesExistentes, form.data, sessaoEditando]);

  // ============================================================
  // Conflito em tempo real — mesma HORA INÍCIO (normalizada)
  // ============================================================
  const conflito = useMemo(() => {
    if (!form.data || !form.hora_inicio) return null;
    const horaFormNorm = normalizarHora(form.hora_inicio);
    return sessoesDoDia.find(s =>
      normalizarHora(s.hora_inicio) === horaFormNorm
    ) || null;
  }, [sessoesDoDia, form.data, form.hora_inicio]);

  // ============================================================
  // handleSave — validação + sanitização SEMPRE
  // ============================================================
  const handleSave = useCallback(async () => {
    setErro('');

    // ─────────────────────────────────────────────
    // VALIDAÇÕES BÁSICAS
    // ─────────────────────────────────────────────
    if (!form.data) { setErro('Indique a data da sessão.'); return; }
    if (!form.hora_inicio || !form.hora_fim) { setErro('Indique as horas de início e fim.'); return; }
    if (form.capacidade_maxima < 1) { setErro('A capacidade mínima é 1 pessoa.'); return; }

    // ─────────────────────────────────────────────
    // ✅ VALIDAÇÃO 1 — hora fim > hora início
    // ─────────────────────────────────────────────
    if (normalizarHora(form.hora_fim) <= normalizarHora(form.hora_inicio)) {
      setErro('A hora de fim tem de ser posterior à hora de início.');
      return;
    }

    // ─────────────────────────────────────────────
    // ✅ VALIDAÇÃO 2 — duplicado (DATA NORMALIZADA + HORA NORMALIZADA)
    // ─────────────────────────────────────────────
    const dataFormNorm = normalizarData(form.data);
    const horaFormNorm = normalizarHora(form.hora_inicio);

    const duplicado = sessoesExistentes.find(s => {
      if (sessaoEditando && Number(s.id) === Number(sessaoEditando.id)) return false;
      return (
        normalizarData(s.data) === dataFormNorm &&
        normalizarHora(s.hora_inicio) === horaFormNorm
      );
    });

    if (duplicado) {
      setErro(
        `Já existe uma sessão em ${dataFormNorm} às ${horaFormNorm}. ` +
        `Escolha outro horário ou edite a sessão existente.`
      );
      return;
    }

    setSalvando(true);

    const controller = new AbortController();
    abortRef.current = controller;

    try {
      const payload = {
        experiencia_id: Number(experienciaId),
        data: form.data,
        hora_inicio: form.hora_inicio,
        hora_fim: form.hora_fim,
        periodo: form.periodo,
        capacidade_maxima: parseInt(form.capacidade_maxima),
        preco_especial: form.preco_especial !== '' ? parseFloat(form.preco_especial) : null,
        ativo: form.ativo ? 1 : 0
      };

      if (sessaoEditando) payload.id = Number(sessaoEditando.id);

      const isEdicao = !!sessaoEditando;
      let url = `${API_BASE}/api/sessoes_experiencia.php`;
      if (isEdicao) url += `?action=update`;

      const res = await fetch(url, {
        method: 'POST',
        mode: 'cors',
        credentials: 'omit',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json'
        },
        body: JSON.stringify(payload),
        signal: controller.signal
      });

      const text = await res.text();

      let data;
      try {
        data = JSON.parse(text);
      } catch {
        // Backend devolveu texto não-JSON (raro) → sanitizar mesmo assim
        setErro(sanitizarErroBackend(text, {
          data: form.data,
          hora_inicio: form.hora_inicio
        }));
        return;
      }

      if (data.success) {
        onSave?.();
        onClose?.();
      } else {
        // Extrair erro de qualquer campo possível (error, erro, message, mensagem)
        const msgBackend = extrairErroBackend(data);

        // ✅ Sanitização blindada — SQLSTATE nunca chega ao utilizador
        setErro(sanitizarErroBackend(msgBackend, {
          data: form.data,
          hora_inicio: form.hora_inicio
        }));
      }
    } catch (err) {
      if (err.name === 'AbortError') return;
      console.error('❌ Erro:', err);

      // ✅ Também sanitiza erros de exceção (rede, parse, etc.)
      setErro(sanitizarErroBackend(err.message, {
        data: form.data,
        hora_inicio: form.hora_inicio
      }));
    } finally {
      setSalvando(false);
      abortRef.current = null;
    }
  }, [form, sessaoEditando, experienciaId, onSave, onClose, sessoesExistentes]);

  if (!show) return null;

  return (
    <div
      className="fixed inset-0 z-[100] flex items-center justify-center p-4"
      style={{ backgroundColor: 'rgba(0,0,0,0.45)' }}
    >
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg p-6 text-left max-h-[90vh] overflow-y-auto">

        {/* HEADER */}
        <div className="flex items-center justify-between mb-5">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-blue-100 rounded-full flex items-center justify-center">
              <Calendar size={18} className="text-blue-600" />
            </div>
            <div>
              <h3 className="text-lg font-bold text-slate-900">
                {sessaoEditando ? 'Editar Sessão' : 'Nova Sessão'}
              </h3>
              <p className="text-xs text-slate-500">
                {sessaoEditando ? 'Atualize os dados da sessão' : 'Crie uma nova sessão de horário'}
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="text-slate-400 hover:text-slate-600 transition"
          >
            <X size={20} />
          </button>
        </div>

        {/* ERRO */}
        {erro && (
          <div className="mb-4 p-3 bg-red-50 border border-red-200 rounded-xl flex items-start gap-2">
            <AlertCircle size={16} className="text-red-500 shrink-0 mt-0.5" />
            <p className="text-xs text-red-700 font-medium">{erro}</p>
          </div>
        )}

        {/* ⚠️ AVISO: sessões já existentes no dia */}
        {sessoesDoDia.length > 0 && (
          <div className="mb-4 p-3 bg-amber-50 border border-amber-200 rounded-xl">
            <div className="flex items-start gap-2 mb-2">
              <AlertTriangle size={14} className="text-amber-600 shrink-0 mt-0.5" />
              <p className="text-[11px] font-bold text-amber-800">
                Já existem {sessoesDoDia.length} sessão(ões) neste dia:
              </p>
            </div>
            <div className="flex flex-wrap gap-1.5">
              {sessoesDoDia.map(s => {
                const isConflito = normalizarHora(s.hora_inicio) === normalizarHora(form.hora_inicio);
                return (
                  <span
                    key={s.id}
                    className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-bold ${
                      isConflito
                        ? 'bg-red-100 text-red-700 ring-1 ring-red-300'
                        : 'bg-white text-amber-800 border border-amber-200'
                    }`}
                  >
                    <Clock size={9} />
                    {normalizarHora(s.hora_inicio)} – {normalizarHora(s.hora_fim)}
                    {isConflito && ' • conflito'}
                  </span>
                );
              })}
            </div>
          </div>
        )}

        {/* ⚠️ AVISO EM TEMPO REAL: conflito detetado */}
        {conflito && !erro && (
          <div className="mb-4 p-3 bg-red-50 border border-red-200 rounded-xl flex items-start gap-2">
            <AlertTriangle size={14} className="text-red-500 shrink-0 mt-0.5" />
            <p className="text-[11px] font-medium text-red-700">
              Já existe uma sessão às <strong>{normalizarHora(conflito.hora_inicio)}</strong>.
              Escolha outro horário.
            </p>
          </div>
        )}

        <div className="space-y-4">
          {/* DATA */}
          <div>
            <label className="text-xs font-bold text-slate-700 block mb-1.5">Data *</label>
            <input
              type="date"
              value={form.data}
              min={new Date().toISOString().split('T')[0]}
              onChange={(e) => setForm(prev => ({ ...prev, data: e.target.value }))}
              className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-600/20 text-slate-900"
            />
          </div>

          {/* HORAS */}
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="text-xs font-bold text-slate-700 block mb-1.5">Hora início *</label>
              <input
                type="time"
                value={form.hora_inicio}
                onChange={(e) => setForm(prev => ({ ...prev, hora_inicio: e.target.value }))}
                className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-600/20 text-slate-900"
              />
            </div>
            <div>
              <label className="text-xs font-bold text-slate-700 block mb-1.5">Hora fim *</label>
              <input
                type="time"
                value={form.hora_fim}
                onChange={(e) => setForm(prev => ({ ...prev, hora_fim: e.target.value }))}
                className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-600/20 text-slate-900"
              />
            </div>
          </div>

          {/* PERÍODO */}
          <div>
            <label className="text-xs font-bold text-slate-700 block mb-1.5">Período</label>
            <div className="grid grid-cols-3 gap-2">
              {[
                { label: 'Manhã', Icon: Sun, cor: 'yellow' },
                { label: 'Meio dia', Icon: Sun, cor: 'orange' },
                { label: 'Tarde', Icon: Sunset, cor: 'red' }
              ].map((p) => {
                const Icon = p.Icon;
                const isSelected = form.periodo === p.label;
                return (
                  <button
                    key={p.label}
                    type="button"
                    onClick={() => setForm(prev => ({ ...prev, periodo: p.label }))}
                    className={`flex flex-col items-center justify-center p-2 rounded-xl border transition-all gap-1 ${
                      isSelected
                        ? 'border-blue-600 bg-blue-50/30 ring-1 ring-blue-600'
                        : 'border-slate-200 bg-white hover:border-slate-300'
                    }`}
                  >
                    <Icon size={16} className={
                      isSelected
                        ? (p.cor === 'yellow' ? 'text-yellow-500' : p.cor === 'orange' ? 'text-orange-400' : 'text-red-400')
                        : 'text-slate-300'
                    } />
                    <span className={`text-[11px] font-bold ${isSelected ? 'text-blue-700' : 'text-slate-600'}`}>
                      {p.label}
                    </span>
                  </button>
                );
              })}
            </div>
          </div>

          {/* CAPACIDADE */}
          <div>
            <label className="text-xs font-bold text-slate-700 block mb-1.5">Capacidade máxima *</label>
            <div className="flex items-center gap-3">
              <button
                type="button"
                onClick={() => setForm(prev => ({ ...prev, capacidade_maxima: Math.max(1, prev.capacidade_maxima - 1) }))}
                className="w-10 h-10 flex items-center justify-center rounded-xl border border-slate-200 text-slate-500 hover:bg-slate-50 font-bold"
              >
                −
              </button>
              <input
                type="number"
                min="1"
                value={form.capacidade_maxima}
                onChange={(e) => setForm(prev => ({ ...prev, capacidade_maxima: parseInt(e.target.value) || 1 }))}
                className="flex-1 border border-slate-200 rounded-xl p-3 text-sm text-center font-bold focus:outline-none focus:ring-2 focus:ring-blue-600/20 text-slate-900"
              />
              <button
                type="button"
                onClick={() => setForm(prev => ({ ...prev, capacidade_maxima: prev.capacidade_maxima + 1 }))}
                className="w-10 h-10 flex items-center justify-center rounded-xl border border-slate-200 text-slate-500 hover:bg-slate-50 font-bold"
              >
                +
              </button>
            </div>
            <p className="text-[10px] text-slate-400 mt-1">Número máximo de pessoas nesta sessão</p>
          </div>

          {/* PREÇO ESPECIAL */}
          <div>
            <label className="text-xs font-bold text-slate-700 block mb-1.5">Preço especial (opcional)</label>
            <div className="relative">
              <DollarSign size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
              <input
                type="number"
                min="0"
                step="0.01"
                value={form.preco_especial}
                onChange={(e) => setForm(prev => ({ ...prev, preco_especial: e.target.value }))}
                placeholder="Deixe vazio para usar o preço base"
                className="w-full border border-slate-200 rounded-xl p-3 pl-9 text-sm focus:outline-none focus:ring-2 focus:ring-blue-600/20 text-slate-900"
              />
            </div>
          </div>

          {/* ATIVO */}
          <div className="flex items-center justify-between p-3 bg-slate-50 rounded-xl">
            <div>
              <p className="text-xs font-bold text-slate-700">Sessão ativa</p>
              <p className="text-[10px] text-slate-400">Sessões inativas não aparecem para os clientes</p>
            </div>
            <button
              type="button"
              onClick={() => setForm(prev => ({ ...prev, ativo: prev.ativo ? 0 : 1 }))}
              className="text-blue-600"
            >
              {form.ativo ? <ToggleRight size={32} /> : <ToggleLeft size={32} className="text-slate-300" />}
            </button>
          </div>
        </div>

        {/* AÇÕES */}
        <div className="flex items-center justify-end gap-3 pt-5 mt-5 border-t border-slate-100">
          <button
            type="button"
            onClick={onClose}
            disabled={salvando}
            className="px-4 py-2 text-xs font-bold text-slate-600 bg-slate-100 hover:bg-slate-200 rounded-xl transition disabled:opacity-50"
          >
            Cancelar
          </button>
          <button
            type="button"
            onClick={handleSave}
            disabled={salvando || !!conflito}
            className="px-5 py-2 text-xs font-bold text-white bg-blue-600 hover:bg-blue-700 rounded-xl transition shadow-md disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
            title={conflito ? 'Resolva o conflito de horário primeiro' : ''}
          >
            {salvando ? (
              <>
                <Loader2 size={12} className="animate-spin" />
                A guardar...
              </>
            ) : (
              <>
                <Save size={12} />
                {sessaoEditando ? 'Atualizar' : 'Criar Sessão'}
              </>
            )}
          </button>
        </div>
      </div>
    </div>
  );
});

// ============================================================
// COMPONENTE PRINCIPAL
// ============================================================
export default function ConfigurarSessoes() {
  const { t } = useTranslation();
  const { id } = useParams();
  const navigate = useNavigate();

  const [experiencia, setExperiencia] = useState(null);
  const [sessoes, setSessoes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [loadingExp, setLoadingExp] = useState(true);
  const [modalShow, setModalShow] = useState(false);
  const [sessaoEditando, setSessaoEditando] = useState(null);
  const [deletandoId, setDeletandoId] = useState(null);
  const [filtroData, setFiltroData] = useState(new Date().toISOString().split('T')[0]);
  const [filtroPeriodo, setFiltroPeriodo] = useState('');
  const [toast, setToast] = useState({ show: false, message: '', type: '' });
  const [transferirShow, setTransferirShow] = useState(false);
  const [historicoShow, setHistoricoShow] = useState(false);

  const toastTimerRef = useRef(null);

  const showToast = useCallback((message, type = 'success') => {
    if (toastTimerRef.current) clearTimeout(toastTimerRef.current);
    setToast({ show: true, message, type });
    toastTimerRef.current = setTimeout(() => {
      setToast({ show: false, message: '', type: '' });
    }, 3000);
  }, []);

  useEffect(() => {
    return () => {
      if (toastTimerRef.current) clearTimeout(toastTimerRef.current);
    };
  }, []);

  // ============================================================
  // CARREGAR EXPERIÊNCIA
  // ============================================================
  useEffect(() => {
    const abortController = new AbortController();

    const fetchExperiencia = async () => {
      if (!id) return;
      setLoadingExp(true);
      try {
        const res = await fetch(`${API_BASE}/api/get_experiencias.php?id=${id}`, {
          method: 'GET',
          mode: 'cors',
          credentials: 'omit',
          headers: { 'Accept': 'application/json' },
          signal: abortController.signal
        });
        const data = await res.json();

        let exp = null;
        if (data.success && data.data) {
          exp = Array.isArray(data.data) ? data.data[0] : data.data;
        } else if (Array.isArray(data)) {
          exp = data.find(e => Number(e.id) === Number(id)) || data[0];
        }

        setExperiencia(exp);
      } catch (err) {
        if (err.name === 'AbortError') return;
        console.error('Erro ao buscar experiência:', err);
      } finally {
        setLoadingExp(false);
      }
    };
    fetchExperiencia();

    return () => abortController.abort();
  }, [id]);

  // ============================================================
  // CARREGAR SESSÕES — SEMPRE TODAS (sem filtro de data)
  // para que a validação no modal veja TODAS as sessões.
  // O filtro visual é aplicado só na renderização.
  // ============================================================
  const fetchSessoes = useCallback(async () => {
    if (!id) return;
    setLoading(true);
    try {
      const url = `${API_BASE}/api/sessoes_experiencia.php?experiencia_id=${id}`;

      const res = await fetch(url, {
        method: 'GET',
        mode: 'cors',
        credentials: 'omit',
        headers: { 'Accept': 'application/json' }
      });

      const text = await res.text();
      let data;
      try {
        data = JSON.parse(text);
      } catch {
        throw new Error('Resposta inválida do servidor');
      }

      if (data.success) {
        const lista = (data.sessoes || []).map(s => ({
          ...s,
          data: normalizarData(s.data),
          hora_inicio: normalizarHora(s.hora_inicio),
          hora_fim: normalizarHora(s.hora_fim),
          vagas_disponiveis: s.vagas_disponiveis ?? ((s.capacidade_maxima || 0) - (s.vagas_ocupadas || 0))
        }));
        setSessoes(lista);
      } else {
        setSessoes([]);
      }
    } catch (err) {
      console.error('Erro ao buscar sessões:', err);
      showToast('Erro ao carregar sessões', 'error');
      setSessoes([]);
    } finally {
      setLoading(false);
    }
  }, [id, showToast]);

  useEffect(() => {
    fetchSessoes();
  }, [fetchSessoes]);

  // ============================================================
  // Sessões filtradas para EXIBIÇÃO
  // ============================================================
  const sessoesFiltradas = useMemo(() => {
    const filtroNorm = filtroData ? normalizarData(filtroData) : '';
    return sessoes.filter(s => {
      if (filtroNorm && normalizarData(s.data) !== filtroNorm) return false;
      if (filtroPeriodo && s.periodo !== filtroPeriodo) return false;
      return true;
    });
  }, [sessoes, filtroData, filtroPeriodo]);

  // ============================================================
  // DELETAR SESSÃO
  // ============================================================
  const deletarSessao = useCallback(async (sessaoId) => {
    if (!window.confirm('Tem certeza que deseja eliminar esta sessão?')) return;
    setDeletandoId(sessaoId);
    try {
      const res = await fetch(`${API_BASE}/api/sessoes_experiencia.php?id=${sessaoId}`, {
        method: 'DELETE',
        mode: 'cors',
        credentials: 'omit',
        headers: { 'Accept': 'application/json' }
      });
      const data = await res.json();
      if (data.success) {
        showToast('Sessão eliminada!', 'success');
        fetchSessoes();
      } else {
        showToast(sanitizarErroBackend(extrairErroBackend(data)), 'error');
      }
    } catch (err) {
      console.error(err);
      showToast(sanitizarErroBackend(err.message), 'error');
    } finally {
      setDeletandoId(null);
    }
  }, [fetchSessoes, showToast]);

  // ============================================================
  // TOGGLE ATIVO
  // ============================================================
  const toggleAtivo = useCallback(async (sessao) => {
    const payload = {
      id: Number(sessao.id),
      experiencia_id: Number(id),
      data: sessao.data,
      hora_inicio: sessao.hora_inicio,
      hora_fim: sessao.hora_fim,
      periodo: sessao.periodo,
      capacidade_maxima: sessao.capacidade_maxima,
      preco_especial: sessao.preco_especial,
      ativo: sessao.ativo ? 0 : 1
    };

    try {
      const res = await fetch(`${API_BASE}/api/sessoes_experiencia.php?action=update`, {
        method: 'POST',
        mode: 'cors',
        credentials: 'omit',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json'
        },
        body: JSON.stringify(payload)
      });

      const data = await res.json();
      if (data.success) {
        fetchSessoes();
      } else {
        showToast(sanitizarErroBackend(extrairErroBackend(data)), 'error');
      }
    } catch (err) {
      console.error(err);
      showToast(sanitizarErroBackend(err.message), 'error');
    }
  }, [id, fetchSessoes, showToast]);

  // ============================================================
  // HANDLERS
  // ============================================================
  const abrirNovaSessao = useCallback(() => {
    // 🔄 Refresca as sessões ANTES de abrir o modal, para garantir
    //    que a validação tem a lista mais recente.
    fetchSessoes();
    setSessaoEditando(null);
    setModalShow(true);
  }, [fetchSessoes]);

  const abrirEditarSessao = useCallback((sessao) => {
    setSessaoEditando(sessao);
    setModalShow(true);
  }, []);

  const fecharModalSessao = useCallback(() => {
    setModalShow(false);
    setSessaoEditando(null);
  }, []);

  const abrirTransferir = useCallback(() => setTransferirShow(true), []);
  const fecharTransferir = useCallback(() => setTransferirShow(false), []);
  const abrirHistorico = useCallback(() => setHistoricoShow(true), []);
  const fecharHistorico = useCallback(() => setHistoricoShow(false), []);

  const onTransferSuccess = useCallback(() => {
    setTransferirShow(false);
    showToast('Sessões transferidas!', 'success');
    fetchSessoes();
  }, [showToast, fetchSessoes]);

  const onSaveSessao = useCallback(() => {
    fetchSessoes();
    showToast('Sessão guardada!', 'success');
  }, [fetchSessoes, showToast]);

  const duplicarSessao = useCallback((sessao) => {
    setSessaoEditando({
      ...sessao,
      id: null,
      hora_inicio: '',
      hora_fim: ''
    });
    setModalShow(true);
  }, []);

  // ============================================================
  // DERIVADOS
  // ============================================================
  const sessoesPorPeriodo = useMemo(() => ({
    'Manhã': sessoesFiltradas.filter(s => s.periodo === 'Manhã'),
    'Meio dia': sessoesFiltradas.filter(s => s.periodo === 'Meio dia'),
    'Tarde': sessoesFiltradas.filter(s => s.periodo === 'Tarde')
  }), [sessoesFiltradas]);

  const totais = useMemo(() => ({
    capacidade: sessoesFiltradas.reduce((acc, s) => acc + (s.capacidade_maxima || 0), 0),
    ocupadas: sessoesFiltradas.reduce((acc, s) => acc + (s.vagas_ocupadas || 0), 0),
    disponiveis: sessoesFiltradas.reduce((acc, s) => acc + (s.vagas_disponiveis || 0), 0)
  }), [sessoesFiltradas]);

  const hojeStr = useMemo(() => new Date().toISOString().split('T')[0], []);

  // ============================================================
  // RENDER
  // ============================================================
  return (
    <div className="text-left">
      {/* TOAST */}
      {toast.show && (
        <div className={`fixed top-4 right-4 z-[100] px-4 py-3 rounded-xl shadow-2xl text-white font-medium text-sm flex items-center gap-2 ${
          toast.type === 'success' ? 'bg-emerald-600' :
          toast.type === 'error' ? 'bg-red-600' : 'bg-amber-600'
        }`}>
          <AlertCircle size={18} />
          <span>{toast.message}</span>
        </div>
      )}

      {/* HEADER */}
      <div className="flex flex-wrap justify-between items-start gap-4 mb-6">
        <div>
          <div className="flex items-center gap-3 mb-2">
            <button
              type="button"
              onClick={() => navigate('/gest/minhas-experiencias')}
              className="w-9 h-9 flex items-center justify-center rounded-xl border border-slate-200 hover:bg-slate-50 transition-colors"
            >
              <ArrowLeft size={16} className="text-slate-600" />
            </button>
            <h1 className="text-2xl font-bold text-slate-900">Configurar Sessões</h1>
          </div>
          <p className="text-sm text-slate-500 ml-12">
            {loadingExp ? (
              <span className="inline-flex items-center gap-2">
                <Loader2 size={12} className="animate-spin" /> A carregar experiência...
              </span>
            ) : experiencia ? (
              <>
                <span className="font-semibold text-slate-700">{experiencia.titulo}</span>
                {experiencia.ilha && <span className="text-slate-400"> — {experiencia.ilha}</span>}
              </>
            ) : (
              'Experiência não encontrada'
            )}
          </p>
        </div>

        {/* AÇÕES */}
        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={abrirHistorico}
            className="flex items-center gap-2 bg-white hover:bg-slate-50 text-slate-700 border border-slate-200 font-bold text-sm px-4 py-3 rounded-xl transition shadow-sm"
            title="Ver histórico de dias arquivados"
          >
            <BarChart3 size={16} />
            Histórico
          </button>
          <button
            type="button"
            onClick={abrirTransferir}
            className="flex items-center gap-2 bg-white hover:bg-slate-50 text-slate-700 border border-slate-200 font-bold text-sm px-4 py-3 rounded-xl transition shadow-sm"
            title="Transferir todas as sessões de uma data para outra"
          >
            <ArrowRight size={16} />
            Transferir dia
          </button>

          <button
            type="button"
            onClick={abrirNovaSessao}
            className="flex items-center gap-2 bg-blue-900 hover:bg-blue-950 text-white font-bold text-sm px-5 py-3 rounded-xl transition shadow-md"
          >
            <Plus size={16} />
            Nova Sessão
          </button>
        </div>
      </div>

      {/* INFO BOX */}
      <div className="bg-blue-50 border border-blue-100 rounded-xl p-4 flex gap-3 mb-6">
        <Info size={18} className="text-blue-600 shrink-0 mt-0.5" />
        <div>
          <p className="text-sm font-bold text-blue-900">Como funcionam as sessões</p>
          <p className="text-xs text-blue-700 mt-1">
            Cada sessão tem uma capacidade máxima. Quando um cliente reserva, as vagas diminuem automaticamente.
            O sistema bloqueia overbooking. Ao cancelar uma reserva, as vagas são restauradas. Lembre-se a regra de antecedência aplica-se só a sessões 24h depois aparece na pagina de detalhes. (ex: se são 16h, uma sessão às 20h de hoje não deve aparecer, Sessões com menos de 24h são totalmente escondidas na página pública.);
          </p>
        </div>
      </div>

      {/* FILTROS */}
      <div className="flex flex-wrap gap-3 mb-6 p-4 bg-slate-50 rounded-xl border border-slate-100">
        <div className="flex-1 min-w-[200px]">
          <label className="text-[10px] font-bold text-slate-500 uppercase block mb-1">Data</label>
          <input
            type="date"
            value={filtroData}
            onChange={(e) => setFiltroData(e.target.value)}
            className="w-full border border-slate-200 rounded-lg p-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-600/20 text-slate-900 bg-white"
          />
        </div>
        <div className="flex-1 min-w-[200px]">
          <label className="text-[10px] font-bold text-slate-500 uppercase block mb-1">Período</label>
          <select
            value={filtroPeriodo}
            onChange={(e) => setFiltroPeriodo(e.target.value)}
            className="w-full border border-slate-200 rounded-lg p-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-600/20 text-slate-900 bg-white"
          >
            <option value="">Todos os períodos</option>
            <option value="Manhã">Manhã</option>
            <option value="Meio dia">Meio dia</option>
            <option value="Tarde">Tarde</option>
          </select>
        </div>
        <div className="flex items-end gap-2">
          <button
            type="button"
            onClick={() => { setFiltroData(''); setFiltroPeriodo(''); }}
            className="px-4 py-2.5 text-xs font-bold text-slate-600 bg-white border border-slate-200 rounded-lg hover:bg-slate-50 transition"
          >
            Limpar
          </button>
          <button
            type="button"
            onClick={fetchSessoes}
            className="px-4 py-2.5 text-xs font-bold text-slate-600 bg-white border border-slate-200 rounded-lg hover:bg-slate-50 transition flex items-center gap-2"
          >
            <RefreshCw size={12} className={loading ? 'animate-spin' : ''} />
            Atualizar
          </button>
        </div>
      </div>

      {/* LISTA DE SESSÕES */}
      {loading ? (
        <div className="bg-white rounded-2xl border border-slate-200 p-12 text-center">
          <Loader2 size={32} className="animate-spin text-blue-600 mx-auto mb-3" />
          <p className="text-slate-500 text-sm">A carregar sessões...</p>
        </div>
      ) : sessoesFiltradas.length === 0 ? (
        <div className="bg-white rounded-2xl border border-slate-200 p-12 text-center">
          <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mx-auto mb-4">
            <Calendar size={28} className="text-slate-400" />
          </div>
          <h3 className="text-lg font-bold text-slate-900 mb-2">Nenhuma sessão criada</h3>
          <p className="text-sm text-slate-500 mb-6">
            {filtroData || filtroPeriodo
              ? 'Nenhuma sessão encontrada com estes filtros'
              : 'Comece por criar a primeira sessão para esta experiência'}
          </p>
          <button
            type="button"
            onClick={abrirNovaSessao}
            className="inline-flex items-center gap-2 bg-blue-900 hover:bg-blue-950 text-white font-bold text-sm px-5 py-3 rounded-xl transition"
          >
            <Plus size={16} />
            Criar primeira sessão
          </button>
        </div>
      ) : (
        <div className="space-y-6">
          {Object.entries(sessoesPorPeriodo).map(([periodo, lista]) => {
            if (lista.length === 0) return null;
            return (
              <div key={periodo}>
                <div className="flex items-center gap-2 mb-3">
                  {periodo === 'Manhã' && <Sun size={16} className="text-yellow-500" />}
                  {periodo === 'Meio dia' && <Sun size={16} className="text-orange-400" />}
                  {periodo === 'Tarde' && <Sunset size={16} className="text-red-400" />}
                  <h2 className="text-sm font-bold text-slate-900 uppercase tracking-wide">{periodo}</h2>
                  <span className="text-xs text-slate-400 font-medium">
                    ({lista.length} {lista.length === 1 ? 'sessão' : 'sessões'})
                  </span>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
                  {lista.map((sessao) => {
                    const vagas = sessao.vagas_disponiveis;
                    const isEsgotado = vagas === 0;
                    const percentagem = sessao.capacidade_maxima > 0
                      ? (sessao.vagas_ocupadas / sessao.capacidade_maxima) * 100
                      : 0;

                    return (
                      <div
                        key={sessao.id}
                        className={`border rounded-2xl p-4 bg-white shadow-sm hover:shadow-md transition-all ${
                          !sessao.ativo ? 'opacity-60 border-slate-200' : 'border-slate-200'
                        }`}
                      >
                        <div className="flex items-start justify-between mb-3">
                          <div>
                            <div className="flex items-center gap-2">
                              <Clock size={14} className="text-blue-600" />
                              <span className="text-base font-bold text-slate-900">
                                {sessao.hora_inicio}
                              </span>
                              <span className="text-xs text-slate-400">→ {sessao.hora_fim}</span>
                            </div>
                            <p className="text-[10px] text-slate-500 mt-1">
                              {sessao.data ? new Date(sessao.data + 'T00:00:00').toLocaleDateString('pt-PT', {
                                day: '2-digit', month: 'short', year: 'numeric'
                              }) : '—'}
                            </p>
                          </div>
                          <button
                            type="button"
                            onClick={() => toggleAtivo(sessao)}
                            className="text-blue-600"
                            title={sessao.ativo ? 'Desativar' : 'Ativar'}
                          >
                            {sessao.ativo
                              ? <ToggleRight size={24} />
                              : <ToggleLeft size={24} className="text-slate-300" />}
                          </button>
                        </div>

                        <div className="mb-3">
                          <div className="flex justify-between items-center mb-1">
                            <span className="text-[10px] font-bold text-slate-500 uppercase">Ocupação</span>
                            <span className={`text-xs font-bold ${
                              vagas >= 4 ? 'text-green-600' :
                              vagas >= 1 ? 'text-orange-500' : 'text-red-600'
                            }`}>
                              {sessao.vagas_ocupadas}/{sessao.capacidade_maxima}
                            </span>
                          </div>
                          <div className="w-full h-1.5 bg-slate-100 rounded-full overflow-hidden">
                            <div
                              className={`h-full rounded-full transition-all ${
                                percentagem >= 100 ? 'bg-red-500' :
                                percentagem >= 70 ? 'bg-orange-500' : 'bg-green-500'
                              }`}
                              style={{ width: `${Math.min(percentagem, 100)}%` }}
                            />
                          </div>
                          <p className={`text-[10px] mt-1 font-medium ${
                            vagas >= 4 ? 'text-green-600' :
                            vagas >= 1 ? 'text-orange-500' : 'text-red-500'
                          }`}>
                            {isEsgotado ? 'Esgotado' : `${vagas} vagas disponíveis`}
                          </p>
                        </div>

                        {sessao.preco_especial && (
                          <div className="flex items-center gap-1 mb-3 px-2 py-1 bg-orange-50 rounded-lg border border-orange-100">
                            <DollarSign size={10} className="text-orange-500" />
                            <span className="text-[10px] font-bold text-orange-600">
                              Preço especial: {Number(sessao.preco_especial).toLocaleString('pt-PT')} CVE
                            </span>
                          </div>
                        )}

                        <div className="flex items-center gap-2 pt-3 border-t border-slate-100">
                          <button
                            type="button"
                            onClick={() => abrirEditarSessao(sessao)}
                            className="flex-1 flex items-center justify-center gap-1.5 py-2 text-[11px] font-bold text-blue-600 bg-blue-50 hover:bg-blue-100 rounded-lg transition"
                          >
                            <Edit2 size={12} />
                            Editar
                          </button>
                          <button
                            type="button"
                            onClick={() => duplicarSessao(sessao)}
                            className="flex-1 flex items-center justify-center gap-1.5 py-2 text-[11px] font-bold text-slate-600 bg-slate-50 hover:bg-slate-100 rounded-lg transition"
                            title="Duplicar para outro horário"
                          >
                            <Copy size={12} />
                            Duplicar
                          </button>
                          <button
                            type="button"
                            onClick={() => deletarSessao(sessao.id)}
                            disabled={deletandoId === sessao.id}
                            className="p-2 text-red-500 bg-red-50 hover:bg-red-100 rounded-lg transition disabled:opacity-50"
                            title="Eliminar"
                          >
                            {deletandoId === sessao.id
                              ? <Loader2 size={12} className="animate-spin" />
                              : <Trash2 size={12} />}
                          </button>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* RESUMO GERAL */}
      {!loading && sessoesFiltradas.length > 0 && (
        <div className="mt-8 p-5 bg-slate-50 rounded-2xl border border-slate-100">
          <h3 className="text-sm font-bold text-slate-900 mb-4">Resumo geral</h3>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div>
              <p className="text-[10px] text-slate-500 font-bold uppercase">Total sessões</p>
              <p className="text-2xl font-bold text-slate-900">{sessoesFiltradas.length}</p>
            </div>
            <div>
              <p className="text-[10px] text-slate-500 font-bold uppercase">Capacidade total</p>
              <p className="text-2xl font-bold text-slate-900">{totais.capacidade}</p>
            </div>
            <div>
              <p className="text-[10px] text-slate-500 font-bold uppercase">Vagas ocupadas</p>
              <p className="text-2xl font-bold text-orange-600">{totais.ocupadas}</p>
            </div>
            <div>
              <p className="text-[10px] text-slate-500 font-bold uppercase">Vagas disponíveis</p>
              <p className="text-2xl font-bold text-green-600">{totais.disponiveis}</p>
            </div>
          </div>
        </div>
      )}

      {/* MODAL SESSÃO */}
      <ModalSessao
        show={modalShow}
        onClose={fecharModalSessao}
        onSave={onSaveSessao}
        sessaoEditando={sessaoEditando}
        experienciaId={id}
        sessoesExistentes={sessoes}
      />

      {/* MODAL TRANSFERIR */}
      {transferirShow && (
        <ModalTransferir
          experienciaId={id}
          onClose={fecharTransferir}
          onSuccess={onTransferSuccess}
        />
      )}

      {historicoShow && (
        <HistoricoSessoes
          experienciaId={id}
          onClose={fecharHistorico}
        />
      )}
    </div>
  );
}

// src/components/gest/Mensagens.jsx
import React, { useState, useEffect, useRef } from 'react';
import { Send, Search, X, ChevronLeft, Loader2, Home, Car, Compass } from 'lucide-react';

const API_BASE = 'https://welovepalop.com/api/mensagens';

function obterUsuario() {
  try {
    const token = localStorage.getItem('token') 
               || localStorage.getItem('morabeza_token')
               || localStorage.getItem('access_token')
               || localStorage.getItem('jwt');
    if (token) {
      const base64Url = token.split('.')[1];
      const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
      const parsed = JSON.parse(decodeURIComponent(
        atob(base64).split('').map(c => '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2)).join('')
      ));
      const user = parsed?.data || parsed?.user || parsed?.usuario || parsed;
      const id = user?.id || user?.userId || user?.user_id || user?.usuario_id || parsed?.sub;
      if (id) return {
        id: Number(id),
        nome: user.nome || user.name || 'Utilizador',
        foto: user.foto || user.picture || null
      };
    }
    const saved = localStorage.getItem('user') || localStorage.getItem('morabeza_user');
    if (saved) return JSON.parse(saved);
    return null;
  } catch { return null; }
}

// ============================================================
// ÍCONE + COR + LABEL do tipo de anúncio
// ============================================================
const getIconeTipo = (tipo, size = 14) => {
  switch(tipo) {
    case 'alojamento': return <Home size={size} className="text-blue-500" />;
    case 'carro': return <Car size={size} className="text-green-500" />;
    case 'experiencia': return <Compass size={size} className="text-purple-500" />;
    default: return <Home size={size} className="text-slate-400" />;
  }
};

const getLabelTipo = (tipo) => {
  switch(tipo) {
    case 'alojamento': return 'Alojamento';
    case 'carro': return 'Carro';
    case 'experiencia': return 'Experiência';
    default: return 'Anúncio';
  }
};

const getCorTipo = (tipo) => {
  switch(tipo) {
    case 'alojamento': return 'bg-blue-50 text-blue-700 border-blue-200';
    case 'carro': return 'bg-green-50 text-green-700 border-green-200';
    case 'experiencia': return 'bg-purple-50 text-purple-700 border-purple-200';
    default: return 'bg-slate-50 text-slate-700 border-slate-200';
  }
};

// Nome a mostrar: título ou fallback "#ID"
const getNomeAnuncio = (titulo, tipo, id) => {
  if (titulo) return titulo;
  return `${getLabelTipo(tipo)} #${id}`;
};

export default function Mensagens({ onClose }) {
  const [contactos, setContactos] = useState([]);
  const [activeContact, setActiveContact] = useState(null);
  const [mensagens, setMensagens] = useState([]);
  const [novaMensagem, setNovaMensagem] = useState('');
  const [loading, setLoading] = useState(false);
  const [loadingChat, setLoadingChat] = useState(false);
  const [isChatOpenMobile, setIsChatOpenMobile] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [usuarioLogado, setUsuarioLogado] = useState(null);

  const messagesEndRef = useRef(null);
  const inputRef = useRef(null);

  useEffect(() => {
    const user = obterUsuario();
    if (user) setUsuarioLogado(user);
  }, []);

  useEffect(() => {
    if (usuarioLogado?.id) fetchContactos();
  }, [usuarioLogado, searchTerm]);

  useEffect(() => {
    if (activeContact?.id && usuarioLogado?.id) {
      fetchMensagens(activeContact);
      marcarLidas();
    }
  }, [activeContact?.id]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [mensagens]);

  // ============ FETCH CONTACTOS ============
  const fetchContactos = async () => {
    if (!usuarioLogado?.id) return;
    setLoading(true);
    try {
      const url = `${API_BASE}/usuarios.php?usuario_id=${usuarioLogado.id}` + 
                  (searchTerm ? `&busca=${encodeURIComponent(searchTerm)}` : '');
      const response = await fetch(url);
      const data = await response.json();
      
      if (data.success && data.data) {
        setContactos(data.data);
      }
    } catch (error) {
      console.error('Erro:', error);
    } finally {
      setLoading(false);
    }
  };

  // ============ FETCH MENSAGENS ============
  const fetchMensagens = async (contacto) => {
    if (!contacto?.id || !usuarioLogado?.id) return;
    try {
      setLoadingChat(true);
      const url = `${API_BASE}/conversa.php?usuario_id=${usuarioLogado.id}&outro_usuario_id=${contacto.id}`;
      const response = await fetch(url);
      const data = await response.json();
      
      if (data.success && data.data) {
        setMensagens(data.data);
      } else {
        setMensagens([]);
      }
    } catch (error) {
      console.error('Erro:', error);
      setMensagens([]);
    } finally {
      setLoadingChat(false);
    }
  };

  // ============ MARCAR LIDAS ============
  const marcarLidas = async () => {
    if (!activeContact?.id || !usuarioLogado?.id) return;
    try {
      await fetch(`${API_BASE}/marcar_lidas.php`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          usuario_id: usuarioLogado.id,
          remetente_id: activeContact.id
        })
      });
      setContactos(prev => prev.map(c => 
        c.id === activeContact.id ? { ...c, nao_lidas_count: 0, mensagem_nao_lida: false } : c
      ));
    } catch (error) {
      console.error('Erro:', error);
    }
  };

  // ============ ENVIAR MENSAGEM ============
  const enviarMensagem = async () => {
    if (!novaMensagem.trim() || !activeContact) return;
    
    const texto = novaMensagem;
    setNovaMensagem('');
    
    try {
      const payload = { mensagem: texto };
      if (activeContact.anuncio_id) payload.anuncio_id = activeContact.anuncio_id;
      if (activeContact.tipo_anuncio) payload.tipo_anuncio = activeContact.tipo_anuncio;

      const response = await fetch(
        `${API_BASE}/conversa.php?usuario_id=${usuarioLogado.id}&outro_usuario_id=${activeContact.id}`,
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload)
        }
      );
      const data = await response.json();
      
      if (data.success) {
        setMensagens(prev => [...prev, {
          id: data.data?.id || Date.now(),
          remetente_id: usuarioLogado.id,
          destinatario_id: activeContact.id,
          mensagem: texto,
          anuncio_id: activeContact.anuncio_id || null,
          tipo_anuncio: activeContact.tipo_anuncio || null,
          anuncio_titulo: activeContact.anuncio_titulo || null,
          created_at: new Date().toISOString(),
          lida: 0
        }]);
      }
    } catch (error) {
      console.error('Erro:', error);
      setNovaMensagem(texto);
    }
  };

  const formatarHora = (data) => {
    if (!data) return '';
    const d = new Date(data);
    const hoje = new Date();
    if (d.toDateString() === hoje.toDateString()) {
      return d.toLocaleTimeString('pt-PT', { hour: '2-digit', minute: '2-digit' });
    }
    return d.toLocaleDateString('pt-PT', { day: '2-digit', month: '2-digit' });
  };

  if (!usuarioLogado) {
    return (
      <div className="w-full h-[calc(100vh-120px)] bg-white rounded-xl border border-gray-100 flex items-center justify-center">
        <div className="text-center">
          <Loader2 className="w-8 h-8 animate-spin text-blue-600 mx-auto mb-3" />
          <p className="text-sm text-gray-500">A carregar...</p>
        </div>
      </div>
    );
  }

  // ============ ANÚNCIO ATIVO ============
  const anuncioAtivo = (() => {
    for (let i = mensagens.length - 1; i >= 0; i--) {
      if (mensagens[i].anuncio_id) {
        return {
          id: mensagens[i].anuncio_id,
          tipo: mensagens[i].tipo_anuncio || activeContact?.tipo_anuncio || 'alojamento',
          titulo: mensagens[i].anuncio_titulo || activeContact?.anuncio_titulo || null
        };
      }
    }
    if (activeContact?.anuncio_id) {
      return {
        id: activeContact.anuncio_id,
        tipo: activeContact.tipo_anuncio || 'alojamento',
        titulo: activeContact.anuncio_titulo || null
      };
    }
    return null;
  })();

  return (
    <div className="w-full h-[calc(100vh-120px)] min-h-[600px] bg-white rounded-xl border border-gray-100 shadow-sm flex overflow-hidden">
      
      {/* ============ PAINEL ESQUERDO — Lista de contactos ============ */}
      <div className={`w-full md:w-[340px] flex-shrink-0 flex flex-col border-r border-gray-100 ${isChatOpenMobile ? 'hidden md:flex' : 'flex'}`}>
        
        <div className="flex items-center justify-between p-4 border-b border-gray-100 h-[64px]">
          <h2 className="text-lg font-bold">Mensagens</h2>
          {onClose && (
            <button onClick={onClose} className="p-1.5 hover:bg-gray-100 rounded-full text-gray-500">
              <X size={18} />
            </button>
          )}
        </div>

        <div className="p-3 border-b border-gray-100">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
            <input
              type="text"
              placeholder="Buscar..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-9 pr-3 py-2 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500/20"
            />
          </div>
        </div>

        <div className="flex-1 overflow-y-auto">
          {loading ? (
            <div className="text-center py-8">
              <Loader2 className="w-6 h-6 animate-spin text-blue-600 mx-auto" />
            </div>
          ) : contactos.length === 0 ? (
            <div className="text-center py-8 text-gray-400 text-sm px-4">
              Nenhum contacto encontrado
            </div>
          ) : (
            contactos.map((contacto) => {
              const naoLidas = contacto.nao_lidas_count || 0;
              const temAnuncio = contacto.anuncio_id;
              return (
                <div 
                  key={contacto.id}
                  onClick={() => { setActiveContact(contacto); setIsChatOpenMobile(true); }}
                  className={`flex items-start gap-3 p-3.5 cursor-pointer border-l-2 transition-colors ${
                    activeContact?.id === contacto.id 
                      ? 'bg-blue-50 border-blue-600' 
                      : 'bg-white border-transparent hover:bg-gray-50'
                  }`}
                >
                  {/* Avatar */}
                  <div className="relative flex-shrink-0">
                    <img 
                      src={contacto.foto || `https://ui-avatars.com/api/?name=${encodeURIComponent(contacto.nome || 'U')}&background=0D8ABC&color=fff`} 
                      alt={contacto.nome} 
                      className="w-12 h-12 rounded-full object-cover border border-gray-200"
                    />
                    {/* 🔴 Badge vermelha */}
                    {naoLidas > 0 && (
                      <span className="absolute -bottom-1 -right-1 bg-red-500 text-white text-[10px] font-bold rounded-full min-w-[20px] h-5 flex items-center justify-center px-1 border-2 border-white shadow-md">
                        {naoLidas > 99 ? '99+' : naoLidas}
                      </span>
                    )}
                  </div>
                  
                  <div className="flex-1 min-w-0">
                    <div className="flex justify-between items-baseline mb-0.5">
                      <span className={`text-sm truncate ${naoLidas > 0 ? 'font-bold text-gray-900' : 'font-semibold text-gray-700'}`}>
                        {contacto.nome || 'Utilizador'}
                      </span>
                      <span className="text-[11px] text-gray-400 whitespace-nowrap ml-2">
                        {formatarHora(contacto.ultima_mensagem_data)}
                      </span>
                    </div>

                    {/* 🏷️ Badge do anúncio — NOME */}
                    {temAnuncio && (
                      <div className="flex items-center gap-1 mb-1">
                        <span className={`inline-flex items-center gap-1 text-[10px] font-semibold px-1.5 py-0.5 rounded border ${getCorTipo(contacto.tipo_anuncio)} max-w-full`}>
                          {getIconeTipo(contacto.tipo_anuncio, 10)}
                          <span className="truncate">
                            {getNomeAnuncio(contacto.anuncio_titulo, contacto.tipo_anuncio, contacto.anuncio_id)}
                          </span>
                        </span>
                      </div>
                    )}

                    <p className={`text-xs truncate ${naoLidas > 0 ? 'text-gray-900 font-semibold' : 'text-gray-500'}`}>
                      {contacto.ultima_mensagem || 'Nenhuma mensagem ainda'}
                    </p>
                  </div>
                </div>
              );
            })
          )}
        </div>
      </div>

      {/* ============ PAINEL DIREITO — Conversa ============ */}
      <div className={`flex-1 bg-gray-50 flex flex-col ${!isChatOpenMobile ? 'hidden md:flex' : 'flex'}`}>
        
        {activeContact ? (
          <>
            {/* Cabeçalho */}
            <div className="bg-white border-b border-gray-100">
              <div className="flex items-center gap-3 p-3.5 h-[64px]">
                <button 
                  onClick={() => setIsChatOpenMobile(false)}
                  className="md:hidden p-1 hover:bg-gray-100 rounded-lg"
                >
                  <ChevronLeft size={20} />
                </button>
                <img 
                  src={activeContact.foto || `https://ui-avatars.com/api/?name=${encodeURIComponent(activeContact.nome || 'U')}&background=0D8ABC&color=fff`} 
                  alt={activeContact.nome} 
                  className="w-10 h-10 rounded-full object-cover"
                />
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-bold text-gray-900 truncate">{activeContact.nome}</p>
                  <p className="text-[11px] text-gray-500">{activeContact.online ? 'Online' : 'Offline'}</p>
                </div>
              </div>

              {/* 🏷️ Barra do anúncio — NOME */}
              {anuncioAtivo && (
                <div className={`flex items-center gap-2 px-4 py-2 border-t text-xs font-medium ${getCorTipo(anuncioAtivo.tipo)}`}>
                  {getIconeTipo(anuncioAtivo.tipo, 13)}
                  <span>Referente a</span>
                  <span className="font-bold truncate max-w-[240px]">
                    {getNomeAnuncio(anuncioAtivo.titulo, anuncioAtivo.tipo, anuncioAtivo.id)}
                  </span>
                </div>
              )}
            </div>

            {/* Lista de mensagens */}
            <div className="flex-1 overflow-y-auto p-4 space-y-3">
              {loadingChat ? (
                <div className="text-center py-8">
                  <Loader2 className="w-6 h-6 animate-spin text-blue-600 mx-auto" />
                </div>
              ) : mensagens.length === 0 ? (
                <div className="text-center py-12 text-gray-400 text-sm">
                  Nenhuma mensagem ainda. Diga olá! 👋
                </div>
              ) : (
                mensagens.map((msg, i) => {
                  const isMeu = Number(msg.remetente_id) === Number(usuarioLogado.id);
                  const mostrarBadgeAnuncio = msg.anuncio_id && 
                    (i === 0 || mensagens[i-1]?.anuncio_id !== msg.anuncio_id);

                  return (
                    <React.Fragment key={msg.id || i}>
                      {/* Separador do anúncio — NOME */}
                      {mostrarBadgeAnuncio && (
                        <div className="flex justify-center my-2">
                          <span className={`inline-flex items-center gap-1.5 text-[10px] font-bold px-2.5 py-1 rounded-full border ${getCorTipo(msg.tipo_anuncio)} max-w-[90%]`}>
                            {getIconeTipo(msg.tipo_anuncio, 11)}
                            <span className="truncate">
                              {getNomeAnuncio(msg.anuncio_titulo, msg.tipo_anuncio, msg.anuncio_id)}
                            </span>
                          </span>
                        </div>
                      )}

                      <div className={`flex ${isMeu ? 'justify-end' : 'justify-start'}`}>
                        <div className={`max-w-[75%] px-3.5 py-2 rounded-2xl ${
                          isMeu 
                            ? 'bg-blue-600 text-white rounded-tr-sm' 
                            : 'bg-white border border-gray-200 text-gray-900 rounded-tl-sm'
                        }`}>
                          <p className="text-sm leading-relaxed break-words">{msg.mensagem}</p>
                          <span className={`text-[10px] block text-right mt-1 ${isMeu ? 'text-blue-200' : 'text-gray-400'}`}>
                            {formatarHora(msg.created_at)}
                          </span>
                        </div>
                      </div>
                    </React.Fragment>
                  );
                })
              )}
              <div ref={messagesEndRef} />
            </div>

            {/* Input */}
            <div className="p-3 bg-white border-t border-gray-100">
              <div className="flex items-center gap-2 bg-gray-50 border border-gray-200 rounded-full px-2 py-1">
                <input 
                  ref={inputRef}
                  type="text" 
                  placeholder="Escreva uma mensagem..." 
                  value={novaMensagem}
                  onChange={(e) => setNovaMensagem(e.target.value)}
                  onKeyPress={(e) => { if (e.key === 'Enter') enviarMensagem(); }}
                  className="flex-1 bg-transparent border-none focus:outline-none text-sm px-2 py-1.5"
                />
                <button 
                  onClick={enviarMensagem}
                  disabled={!novaMensagem.trim()}
                  className={`p-2 rounded-full ${
                    novaMensagem.trim() ? 'bg-blue-600 text-white' : 'bg-gray-200 text-gray-400'
                  }`}
                >
                  <Send size={16} />
                </button>
              </div>
            </div>
          </>
        ) : (
          <div className="flex-1 flex items-center justify-center text-center p-8">
            <div>
              <div className="w-a16 h-16 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-3">
                <Send size={28} className="text-gray-400" />
              </div>
              <p className="text-gray-500 text-sm">Selecione uma conversa</p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

// src/components/gest/MinhasExperiencias.jsx
import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import {
  Loader2, Compass, Plus, Edit2, Trash2, Settings2, Eye, MapPin,
  Star, Users, Clock, AlertCircle, RefreshCw, CheckCircle,
  XCircle, Search, User, Shield, Ban
} from 'lucide-react';

const API_BASE = 'https://welovepalop.com';

// ============================================================
// HELPER: obter utilizador do JWT
// ============================================================
function obterUsuarioId() {
  try {
    const token = localStorage.getItem('token')
      || localStorage.getItem('morabeza_token')
      || localStorage.getItem('access_token')
      || localStorage.getItem('jwt');
    if (token) {
      const base64Url = token.split('.')[1];
      const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
      const parsed = JSON.parse(decodeURIComponent(
        atob(base64).split('').map(c => '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2)).join('')
      ));
      const user = parsed?.data || parsed?.user || parsed?.usuario || parsed;
      const id = user?.id || user?.userId || user?.user_id || user?.usuario_id || parsed?.sub;
      if (id) return Number(id);
    }
    const savedUser = localStorage.getItem('user') || localStorage.getItem('morabeza_user');
    if (savedUser) {
      const u = JSON.parse(savedUser);
      if (u?.id) return Number(u.id);
    }
    return null;
  } catch { return null; }
}

export default function MinhasExperiencias() {
  const { t } = useTranslation();
  const navigate = useNavigate();

  const [experiencias, setExperiencias] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [busca, setBusca] = useState('');
  const [deletandoId, setDeletandoId] = useState(null);
  const [toast, setToast] = useState({ show: false, message: '', type: '' });

  const showToast = (message, type = 'success') => {
    setToast({ show: true, message, type });
    setTimeout(() => setToast({ show: false, message: '', type: '' }), 3000);
  };

  // ============================================================
  // CARREGAR EXPERIÊNCIAS DO ANFITRIÃO
  // ============================================================
  const fetchExperiencias = async () => {
    setLoading(true);
    setError(null);
    try {
      const usuarioId = obterUsuarioId();
      console.log('👤 Usuario ID:', usuarioId);

      if (!usuarioId) {
        setError('Utilizador não autenticado');
        setLoading(false);
        return;
      }

      const res = await fetch(`${API_BASE}/api/get_experiencias.php?usuario_id=${usuarioId}`);
      const data = await res.json();

      console.log('📦 Resposta API:', data);

      let lista = [];
      if (data.success && data.data) {
        lista = Array.isArray(data.data) ? data.data : [data.data];
      } else if (Array.isArray(data)) {
        lista = data;
      }

      // Validar que cada experiência tem id
      const listaValida = lista.filter(exp => exp && exp.id);
      console.log(`✅ ${listaValida.length} experiências carregadas`);

      setExperiencias(listaValida);
    } catch (err) {
      console.error('❌ Erro ao buscar experiências:', err);
      setError('Erro ao carregar experiências');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchExperiencias();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // ============================================================
  // DELETAR EXPERIÊNCIA
  // ============================================================
  const deletarExperiencia = async (exp) => {
    if (!window.confirm(`Tem certeza que deseja eliminar "${exp.titulo}"?\nEsta ação não pode ser desfeita.`)) return;

    setDeletandoId(exp.id);
    try {
      const res = await fetch(`${API_BASE}/api/experiencias.php?id=${exp.id}`, {
        method: 'DELETE'
      });
      const data = await res.json();
      if (data.success) {
        showToast('Experiência eliminada!', 'success');
        fetchExperiencias();
      } else {
        showToast(data.error || 'Erro ao eliminar', 'error');
      }
    } catch (err) {
      console.error(err);
      showToast('Erro de conexão', 'error');
    } finally {
      setDeletandoId(null);
    }
  };

  // ============================================================
  // FILTRAR
  // ============================================================
  const experienciasFiltradas = experiencias.filter(exp => {
    if (!busca.trim()) return true;
    const termo = busca.toLowerCase();
    return (
      (exp.titulo || '').toLowerCase().includes(termo) ||
      (exp.ilha || '').toLowerCase().includes(termo) ||
      (exp.localizacao || '').toLowerCase().includes(termo)
    );
  });

  // ============================================================
  // RENDER
  // ============================================================
  return (
    <div className="text-left">
      {toast.show && (
        <div className={`fixed top-4 right-4 z-[100] px-4 py-3 rounded-xl shadow-2xl text-white font-medium text-sm flex items-center gap-2 ${
          toast.type === 'success' ? 'bg-emerald-600' :
          toast.type === 'error' ? 'bg-red-600' : 'bg-amber-600'
        }`}>
          <AlertCircle size={18} />
          <span>{toast.message}</span>
        </div>
      )}

      {/* HEADER */}
      <div className="flex flex-wrap justify-between items-start gap-4 mb-6">
        <div>
          <h1 className="text-2xl font-bold text-slate-900 flex items-center gap-2">
            <Compass className="text-blue-600" size={24} />
            Minhas Experiências
          </h1>
          <p className="text-sm text-slate-500 mt-1">
            Gerir as suas experiências, horários e sessões
          </p>
        </div>

        <div className="flex items-center gap-2">
          <button
            onClick={fetchExperiencias}
            className="flex items-center gap-1.5 px-3 py-2 bg-white hover:bg-slate-50 text-slate-700 font-medium text-xs rounded-lg border border-slate-200 transition"
          >
            <RefreshCw size={14} className={loading ? 'animate-spin' : ''} />
            Atualizar
          </button>
          <button
            onClick={() => navigate('/experiencia-registo')}
            className="flex items-center gap-2 bg-blue-900 hover:bg-blue-950 text-white font-bold text-sm px-4 py-2.5 rounded-xl transition shadow-md"
          >
            <Plus size={16} />
            Nova Experiência
          </button>
        </div>
      </div>

      {/* BUSCA */}
      {experiencias.length > 0 && (
        <div className="mb-5">
          <div className="relative max-w-md">
            <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
            <input
              type="text"
              value={busca}
              onChange={(e) => setBusca(e.target.value)}
              placeholder="Pesquisar por título, ilha ou localização..."
              className="w-full border border-slate-200 rounded-xl pl-9 pr-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-600/20 text-slate-900"
            />
          </div>
        </div>
      )}

      {/* ESTADOS */}
      {loading ? (
        <div className="bg-white rounded-2xl border border-slate-200 p-12 text-center">
          <Loader2 size={32} className="animate-spin text-blue-600 mx-auto mb-3" />
          <p className="text-slate-500 text-sm">A carregar experiências...</p>
        </div>
      ) : error ? (
        <div className="bg-red-50 rounded-2xl border border-red-200 p-8 text-center">
          <AlertCircle size={32} className="text-red-500 mx-auto mb-3" />
          <p className="text-red-700 font-medium">{error}</p>
          <button
            onClick={fetchExperiencias}
            className="mt-4 px-4 py-2 bg-red-600 hover:bg-red-700 text-white rounded-lg text-sm font-bold transition"
          >
            Tentar novamente
          </button>
        </div>
      ) : experiencias.length === 0 ? (
        <div className="bg-white rounded-2xl border border-slate-200 p-12 text-center">
          <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mx-auto mb-4">
            <Compass size={28} className="text-slate-400" />
          </div>
          <h3 className="text-lg font-bold text-slate-900 mb-2">Nenhuma experiência criada</h3>
          <p className="text-sm text-slate-500 mb-6">
            Comece por criar a sua primeira experiência para começar a receber reservas
          </p>
          <button
            onClick={() => navigate('/experiencia-registo')}
            className="inline-flex items-center gap-2 bg-blue-900 hover:bg-blue-950 text-white font-bold text-sm px-5 py-3 rounded-xl transition"
          >
            <Plus size={16} />
            Criar primeira experiência
          </button>
        </div>
      ) : experienciasFiltradas.length === 0 ? (
        <div className="bg-white rounded-2xl border border-slate-200 p-12 text-center">
          <Search size={32} className="text-slate-400 mx-auto mb-3" />
          <p className="text-slate-500 text-sm">Nenhuma experiência encontrada para "{busca}"</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-5">
          {experienciasFiltradas.map((exp) => (
            <div
              key={exp.id}
              className="bg-white rounded-2xl border border-slate-200 overflow-hidden shadow-sm hover:shadow-md transition-all flex flex-col"
            >
              {/* IMAGEM */}
              <div className="relative h-44 bg-slate-100">
                <img
                  src={exp.imagem_principal || 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?w=600&h=400&fit=crop'}
                  alt={exp.titulo}
                  className="w-full h-full object-cover"
                  onError={(e) => {
                    e.target.src = 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?w=600&h=400&fit=crop';
                  }}
                />

                {/* BADGE STATUS */}
                <div className="absolute top-3 left-3 flex gap-1.5">
                  {exp.ativo === 1 || exp.status === 'aprovado' ? (
                    <span className="inline-flex items-center gap-1 px-2 py-1 bg-green-500/95 backdrop-blur text-white text-[10px] font-bold rounded-full">
                      <CheckCircle size={10} />
                      Ativo
                    </span>
                  ) : exp.status === 'pendente' ? (
                    <span className="inline-flex items-center gap-1 px-2 py-1 bg-amber-500/95 backdrop-blur text-white text-[10px] font-bold rounded-full">
                      <Clock size={10} />
                      Pendente
                    </span>
                  ) : (
                    <span className="inline-flex items-center gap-1 px-2 py-1 bg-slate-500/95 backdrop-blur text-white text-[10px] font-bold rounded-full">
                      <XCircle size={10} />
                      Inativo
                    </span>
                  )}

                  {/* BADGE MODELO */}
                  {exp.modelo_reserva === 'grupo_privado' ? (
                    <span className="inline-flex items-center gap-1 px-2 py-1 bg-purple-500/95 backdrop-blur text-white text-[10px] font-bold rounded-full">
                      <Users size={10} />
                      Grupo
                    </span>
                  ) : (
                    <span className="inline-flex items-center gap-1 px-2 py-1 bg-blue-500/95 backdrop-blur text-white text-[10px] font-bold rounded-full">
                      <User size={10} />
                      Por Pessoa
                    </span>
                  )}
                </div>

                {/* RATING */}
                {exp.rating_formatado && (
                  <div className="absolute top-3 right-3 bg-white/95 backdrop-blur rounded-full px-2 py-1 flex items-center gap-1 shadow-sm">
                    <Star size={10} className="fill-orange-400 text-orange-400" />
                    <span className="text-[10px] font-bold text-slate-900">{exp.rating_formatado}</span>
                  </div>
                )}
              </div>

              {/* CONTEÚDO */}
              <div className="p-4 flex-1 flex flex-col">
                <h3 className="text-sm font-bold text-slate-900 leading-tight line-clamp-2 mb-2">
                  {exp.titulo}
                </h3>

                <div className="flex items-center gap-1 text-[11px] text-slate-500 mb-3">
                  <MapPin size={11} className="text-orange-500" />
                  <span className="truncate">{exp.ilha}{exp.localizacao ? `, ${exp.localizacao}` : ''}</span>
                </div>

                {/* MÉTRICAS */}
                <div className="grid grid-cols-3 gap-2 mb-4">
                  <div className="bg-slate-50 rounded-lg p-2 text-center">
                    <Clock size={12} className="text-blue-600 mx-auto mb-1" />
                    <p className="text-[10px] font-bold text-slate-900 truncate">{exp.duracao || '—'}</p>
                    <p className="text-[9px] text-slate-400">Duração</p>
                  </div>
                  <div className="bg-slate-50 rounded-lg p-2 text-center">
                    <Users size={12} className="text-green-600 mx-auto mb-1" />
                    <p className="text-[10px] font-bold text-slate-900">
                      {exp.modelo_reserva === 'grupo_privado'
                        ? (exp.max_pessoas_grupo || '—')
                        : (exp.max_pessoas || '—')}
                    </p>
                    <p className="text-[9px] text-slate-400">Máx.</p>
                  </div>
                  <div className="bg-slate-50 rounded-lg p-2 text-center">
                    <Star size={12} className="text-orange-500 mx-auto mb-1" />
                    <p className="text-[10px] font-bold text-slate-900">{exp.total_avaliacoes || 0}</p>
                    <p className="text-[9px] text-slate-400">Aval.</p>
                  </div>
                </div>

                {/* PREÇO */}
                {(exp.preco || exp.preco_grupo) && (
                  <div className="mb-4 flex items-baseline gap-1">
                    <span className="text-lg font-bold text-blue-600">
                      {exp.modelo_reserva === 'grupo_privado'
                        ? Number(exp.preco_grupo || 0).toLocaleString('pt-PT')
                        : Number(exp.preco || 0).toLocaleString('pt-PT')}
                    </span>
                    <span className="text-xs text-slate-500">
                      CVE {exp.modelo_reserva === 'grupo_privado' ? '/ grupo' : '/ pessoa'}
                    </span>
                  </div>
                )}

                {/* AÇÕES */}
               <div className="mt-auto pt-3 border-t border-slate-100 space-y-2">
                        {/* 🔥 Botão principal: Configurar Sessões */}
                        <button
                            onClick={() => navigate(`/gest/experiencia/${exp.id}/sessoes`)}
                            className="w-full flex items-center justify-center gap-2 bg-blue-900 hover:bg-blue-950 text-white font-bold text-xs py-2.5 rounded-xl transition shadow-sm"
                        >
                            <Settings2 size={14} />
                            Configurar Sessões
                        </button>

                        {/* 🔥 Botão secundário: Bloqueios */}
                        <button
                            onClick={() => navigate(`/gest/experiencia/${exp.id}/bloqueios`)}
                            className="w-full flex items-center justify-center gap-2 bg-orange-500 hover:bg-orange-600 text-white font-bold text-xs py-2.5 rounded-xl transition shadow-sm"
                        >
                            <Shield size={14} />
                            Bloqueios e Regras
                        </button>

                          {/* 🔥 NOVO Botão: Políticas de Reserva */}
                          <button
                            onClick={() => navigate(`/gest/experiencia/${exp.id}/politicas`)}
                            className="w-full flex items-center justify-center gap-2 bg-purple-600 hover:bg-purple-700 text-white font-bold text-xs py-2.5 rounded-xl transition shadow-sm"
                          >
                            <Ban size={14} />
                            Políticas de Reserva
                          </button>

                        {/* 🔥 Ações rápidas */}
                        <div className="grid grid-cols-3 gap-2">
                            <button
                            onClick={() => navigate(`/experiencia/${exp.slug || exp.id}`)}
                            className="flex items-center justify-center gap-1 py-2 text-[10px] font-bold text-slate-600 bg-slate-50 hover:bg-slate-100 rounded-lg transition"
                            title="Ver página pública"
                            >
                            <Eye size={12} />
                            Ver
                            </button>

                            <button
                            onClick={() => navigate(`/experiencia-registo/editar/${exp.id}`)}
                            className="flex items-center justify-center gap-1 py-2 text-[10px] font-bold text-slate-600 bg-slate-50 hover:bg-slate-100 rounded-lg transition"
                            title="Editar experiência"
                            >
                            <Edit2 size={12} />
                            Editar
                            </button>

                            <button
                            onClick={() => deletarExperiencia(exp)}
                            disabled={deletandoId === exp.id}
                            className="flex items-center justify-center gap-1 py-2 text-[10px] font-bold text-red-500 bg-red-50 hover:bg-red-100 rounded-lg transition disabled:opacity-50"
                            title="Eliminar experiência"
                            >
                            {deletandoId === exp.id ? (
                                <Loader2 size={12} className="animate-spin" />
                            ) : (
                                <Trash2 size={12} />
                            )}
                            Eliminar
                            </button>
                        </div>
                        </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* RESUMO */}
      {!loading && experiencias.length > 0 && (
        <div className="mt-8 p-5 bg-slate-50 rounded-2xl border border-slate-100">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div>
              <p className="text-[10px] text-slate-500 font-bold uppercase">Total experiências</p>
              <p className="text-2xl font-bold text-slate-900">{experiencias.length}</p>
            </div>
            <div>
              <p className="text-[10px] text-slate-500 font-bold uppercase">Ativas</p>
              <p className="text-2xl font-bold text-green-600">
                {experiencias.filter(e => e.ativo === 1 || e.status === 'aprovado').length}
              </p>
            </div>
            <div>
              <p className="text-[10px] text-slate-500 font-bold uppercase">Pendentes</p>
              <p className="text-2xl font-bold text-amber-600">
                {experiencias.filter(e => e.status === 'pendente').length}
              </p>
            </div>
            <div>
              <p className="text-[10px] text-slate-500 font-bold uppercase">Total avaliações</p>
              <p className="text-2xl font-bold text-blue-600">
                {experiencias.reduce((acc, e) => acc + (parseInt(e.total_avaliacoes) || 0), 0)}
              </p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

