// src/components/gest/Relatorios.jsx
import React, { useState, useEffect } from 'react';
import { Loader2, Home, Car, Compass, Award, TrendingUp, DollarSign, Percent } from 'lucide-react';

export default function Relatorios() {
  const [loading, setLoading] = useState(true);
  const [userRoles, setUserRoles] = useState({
    anfitrion: false,
    guia: false,
    proprietarioVeiculos: false
  });
  const [dados, setDados] = useState({
    totalRecebido: 0,
    comissao: 0,
    valorLiquido: 0,
    pendentes: 0,
    porTipo: {
      alojamentos: { total: 0, receita: 0, comissao: 0, liquido: 0 },
      carros: { total: 0, receita: 0, comissao: 0, liquido: 0 },
      experiencias: { total: 0, receita: 0, comissao: 0, liquido: 0 }
    }
  });

  // Obter ID do utilizador de forma segura (JWT ou LocalStorage)
  const obterUserId = () => {
    try {
      const token = localStorage.getItem('token') || localStorage.getItem('morabeza_token');
      if (token) {
        const base64Url = token.split('.')[1];
        const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
        const jsonPayload = decodeURIComponent(atob(base64).split('').map(c => {
          return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
        }).join(''));
        const parsed = JSON.parse(jsonPayload);
        if (parsed.data?.id) return parsed.data.id;
        if (parsed.id) return parsed.id;
      }
      const savedUser = localStorage.getItem('user') || localStorage.getItem('morabeza_user');
      if (savedUser) {
        const user = JSON.parse(savedUser);
        return user.id;
      }
    } catch (e) {
      console.error('Erro ao obter ID:', e);
    }
    return null;
  };

  useEffect(() => {
    fetchRelatorios();
  }, []);

  const fetchRelatorios = async () => {
    setLoading(true);
    try {
      const userId = obterUserId();
      if (!userId) {
        setLoading(false);
        return;
      }
      
      // Buscar roles do usuário
      const rolesResponse = await fetch(`https://welovepalop.com/api/usuarios/listar_roles.php?usuario_id=${userId}`);
      const rolesData = await rolesResponse.json();
      
      let isAnfitrion = false;
      let isGuia = false;
      let isProprietarioVeiculos = false;
      
      if (rolesData.success && rolesData.roles) {
        isAnfitrion = rolesData.roles.some(r => r.name === 'anfitrion' && r.status === 'approved');
        isGuia = rolesData.roles.some(r => r.name === 'guia_experiencias' && r.status === 'approved');
        isProprietarioVeiculos = rolesData.roles.some(r => r.name === 'proprietario_veiculos' && r.status === 'approved');
        
        setUserRoles({
          anfitrion: isAnfitrion,
          guia: isGuia,
          proprietarioVeiculos: isProprietarioVeiculos
        });
      }
      
      // Buscar estatísticas
      const statsResponse = await fetch(`https://welovepalop.com/api/dashboard/estatisticas.php?usuario_id=${userId}`);
      const statsData = await statsResponse.json();
      
      let totalRecebido = 0;
      let dadosPorTipo = {
        alojamentos: { total: 0, receita: 0, comissao: 0, liquido: 0 },
        carros: { total: 0, receita: 0, comissao: 0, liquido: 0 },
        experiencias: { total: 0, receita: 0, comissao: 0, liquido: 0 }
      };
      
      if (statsData.success && statsData.data) {
        const alojamentos = statsData.data.alojamentos || {};
        const carros = statsData.data.carros || {};
        const experiencias = statsData.data.experiencias || {};
        
        // Calcular apenas para roles aprovadas
        if (isAnfitrion) {
          const receitaAloj = (alojamentos.total_anuncios || 0) * 5000;
          const comissaoAloj = receitaAloj * 0.10;
          dadosPorTipo.alojamentos = {
            total: alojamentos.total_anuncios || 0,
            receita: receitaAloj,
            comissao: comissaoAloj,
            liquido: receitaAloj - comissaoAloj
          };
          totalRecebido += receitaAloj;
        }
        
        if (isProprietarioVeiculos) {
          const receitaCarros = (carros.total_anuncios || 0) * 3000;
          const comissaoCarros = receitaCarros * 0.10;
          dadosPorTipo.carros = {
            total: carros.total_anuncios || 0,
            receita: receitaCarros,
            comissao: comissaoCarros,
            liquido: receitaCarros - comissaoCarros
          };
          totalRecebido += receitaCarros;
        }
        
        if (isGuia) {
          const receitaExp = (experiencias.total_anuncios || 0) * 2000;
          const comissaoExp = receitaExp * 0.10;
          dadosPorTipo.experiencias = {
            total: experiencias.total_anuncios || 0,
            receita: receitaExp,
            comissao: comissaoExp,
            liquido: receitaExp - comissaoExp
          };
          totalRecebido += receitaExp;
        }
      }
      
      const comissaoTotal = totalRecebido * 0.10;
      const valorLiquido = totalRecebido - comissaoTotal;
      const pendentes = totalRecebido * 0.3;
      
      setDados({
        totalRecebido: Math.round(totalRecebido),
        comissao: Math.round(comissaoTotal),
        valorLiquido: Math.round(valorLiquido),
        pendentes: Math.round(pendentes),
        porTipo: dadosPorTipo
      });
      
    } catch (error) {
      console.error('Erro ao buscar relatórios:', error);
    } finally {
      setLoading(false);
    }
  };

  const hasAnyRole = userRoles.anfitrion || userRoles.guia || userRoles.proprietarioVeiculos;

  if (loading) {
    return (
      <div className="max-w-6xl w-full text-[#1a1f36] px-4 py-6 md:px-0 flex justify-center items-center h-96">
        <Loader2 size={48} className="animate-spin text-blue-900" />
      </div>
    );
  }

  if (!hasAnyRole) {
    return (
      <div className="max-w-6xl w-full text-[#1a1f36] px-4 py-6 md:px-0">
        <div className="bg-white rounded-2xl p-12 text-center border border-gray-100 shadow-sm">
          <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
            <Award size={40} className="text-gray-400" />
          </div>
          <h2 className="text-xl font-bold text-gray-800 mb-2">Acesso Restrito</h2>
          <p className="text-gray-500 max-w-md mx-auto">
            Você não tem permissão para aceder aos relatórios financeiros.
            É necessário ter uma das seguintes funções aprovadas: Anfitrião, Guia de Experiências ou Proprietário de Veículos.
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-6xl w-full text-[#1a1f36] px-4 py-6 md:px-0">
      <h1 className="text-[24px] font-bold mb-6">Resumo Financeiro</h1>

      <div className="space-y-10">
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          <ResumoCard 
            title="Total Recebido (Bruto)" 
            value={dados.totalRecebido.toLocaleString()} 
            icon={<DollarSign size={20} className="text-green-500" />}
            color="text-[#0f172a]" 
          />
          <ResumoCard 
            title="Comissão (10%)" 
            value={dados.comissao.toLocaleString()} 
            icon={<Percent size={20} className="text-red-500" />}
            color="text-[#dc2626]" 
          />
          <ResumoCard 
            title="Valor Líquido" 
            value={dados.valorLiquido.toLocaleString()} 
            icon={<TrendingUp size={20} className="text-green-500" />}
            color="text-[#16a34a]" 
          />
          <ResumoCard 
            title="Pagamentos Pendentes" 
            value={dados.pendentes.toLocaleString()} 
            icon={<Award size={20} className="text-orange-500" />}
            color="text-[#d97706]" 
          />
        </div>

        <div>
          <h2 className="text-[16px] font-bold mb-4">Detalhamento por Tipo de Anúncio</h2>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {userRoles.anfitrion && dados.porTipo.alojamentos.total > 0 && (
              <TipoFinanceiroCard 
                titulo="Alojamentos"
                icone={<Home size={20} />}
                cor="bg-blue-50 border-blue-100"
                corTexto="text-blue-700"
                dados={dados.porTipo.alojamentos}
              />
            )}
            {userRoles.proprietarioVeiculos && dados.porTipo.carros.total > 0 && (
              <TipoFinanceiroCard 
                titulo="Carros"
                icone={<Car size={20} />}
                cor="bg-green-50 border-green-100"
                corTexto="text-green-700"
                dados={dados.porTipo.carros}
              />
            )}
            {userRoles.guia && dados.porTipo.experiencias.total > 0 && (
              <TipoFinanceiroCard 
                titulo="Experiências"
                icone={<Compass size={20} />}
                cor="bg-purple-50 border-purple-100"
                corTexto="text-purple-700"
                dados={dados.porTipo.experiencias}
              />
            )}
          </div>
        </div>

        <div>
          <h2 className="text-[16px] font-bold mb-4">Detalhamento Financeiro</h2>
          <div className="bg-white rounded-xl border border-gray-100 shadow-sm overflow-hidden">
            <DetailRow 
              label="Reservas Confirmadas" 
              value={`${dados.totalRecebido.toLocaleString()} CVE`} 
              sub="Total de reservas" 
            />
            <DetailRow 
              label="Comissão da Plataforma (10%)" 
              value={`${dados.comissao.toLocaleString()} CVE`} 
              color="text-red-500"
              sub="Taxa de serviço"
            />
            <DetailRow 
              label="Valor Líquido para Receber" 
              value={`${dados.valorLiquido.toLocaleString()} CVE`} 
              color="text-green-600"
              sub="Após comissão"
            />
            <DetailRow 
              label="Pagamentos Pendentes" 
              value={`${dados.pendentes.toLocaleString()} CVE`} 
              color="text-orange-500"
              sub="Aguardando confirmação"
              last
            />
          </div>
        </div>

        <div className="bg-blue-50 rounded-xl p-4 border border-blue-100">
          <div className="flex items-start gap-3">
            <div className="w-10 h-10 bg-blue-100 rounded-full flex items-center justify-center flex-shrink-0">
              <span className="text-blue-600 font-bold text-lg">%</span>
            </div>
            <div>
              <h4 className="text-[14px] font-bold text-blue-800 mb-1">Comissão Morabeza Stay</h4>
              <p className="text-[12px] text-blue-600">
                A taxa de comissão aplicada é de 10% sobre o valor total de cada reserva. 
                Este valor cobre os custos de operação, suporte ao cliente e marketing da plataforma.
                O valor líquido é creditado na sua conta após a confirmação do check-in.
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

function ResumoCard({ title, value, icon, color }) {
  return (
    <div className="bg-white rounded-xl p-5 border border-gray-100 shadow-sm">
      <div className="flex items-center justify-between mb-3">
        <h3 className="text-[12px] font-bold text-gray-500">{title}</h3>
        {icon}
      </div>
      <div className={`text-[24px] font-bold leading-none ${color}`}>
        {value} <span className="text-[13px] font-normal text-gray-400">CVE</span>
      </div>
    </div>
  );
}

function TipoFinanceiroCard({ titulo, icone, cor, corTexto, dados }) {
  return (
    <div className={`rounded-xl p-4 border ${cor}`}>
      <div className="flex items-center justify-between mb-3">
        <h4 className={`text-sm font-bold ${corTexto}`}>{titulo}</h4>
        <div className={corTexto}>{icone}</div>
      </div>
      <div className="space-y-2">
        <div className="flex justify-between">
          <span className="text-xs text-gray-500">Anúncios</span>
          <span className="text-sm font-bold text-gray-700">{dados.total}</span>
        </div>
        <div className="flex justify-between">
          <span className="text-xs text-gray-500">Receita Bruta</span>
          <span className="text-sm font-bold text-green-600">{dados.receita.toLocaleString()} CVE</span>
        </div>
        <div className="flex justify-between">
          <span className="text-xs text-gray-500">Comissão</span>
          <span className="text-sm font-bold text-red-500">{dados.comissao.toLocaleString()} CVE</span>
        </div>
        <div className="flex justify-between pt-2 border-t border-gray-100">
          <span className="text-xs font-bold text-gray-600">Valor Líquido</span>
          <span className="text-sm font-bold text-blue-600">{dados.liquido.toLocaleString()} CVE</span>
        </div>
      </div>
    </div>
  );
}

function DetailRow({ label, value, sub, color, last }) {
  return (
    <div className={`flex flex-col md:flex-row md:items-center justify-between px-6 py-4 ${!last ? 'border-b border-gray-50' : ''}`}>
      <div className="flex flex-col">
        <span className="text-[13px] md:text-[14px] font-bold text-[#1e3a8a]">{label}</span>
        {sub && <span className="text-[10px] text-gray-400 mt-0.5">{sub}</span>}
      </div>
      <div className="flex items-center justify-between md:justify-end w-full md:w-auto mt-2 md:mt-0">
        <span className={`text-[14px] font-bold ${color || 'text-[#0f172a]'} md:ml-8`}>{value}</span>
      </div>
    </div>
  );
}

// src/components/gest/Reservas.jsx
import React, { useState, useEffect } from 'react';
import { Eye, RefreshCw, Home, Car, Compass, CheckCircle, XCircle, AlertCircle, PauseCircle, Trash2, DollarSign } from 'lucide-react';
import ReembolsoModal from './ReembolsoModal';

export default function Reservas() {
  const [activeTab, setActiveTab] = useState('Todas');
  const [reservas, setReservas] = useState([]);
  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState(null);
  
  const [showReembolsoModal, setShowReembolsoModal] = useState(false);
  const [reservaSelecionadaReembolso, setReservaSelecionadaReembolso] = useState(null);
  const [showConfirmModal, setShowConfirmModal] = useState(null);
  const [showCancelModal, setShowCancelModal] = useState(null);
  const [showSuspendModal, setShowSuspendModal] = useState(null);
  const [showDeleteModal, setShowDeleteModal] = useState(null);
  
  const [motivoCancelamento, setMotivoCancelamento] = useState('');
  const [toast, setToast] = useState({ show: false, message: '', type: '' });
  const [counts, setCounts] = useState({
    todas: 0,
    confirmadas: 0,
    pendentes: 0,
    canceladas: 0,
    suspensas: 0,
    concluidas: 0
  });

  const formatStatus = (status) => {
    if (!status) return 'Pendente';
    const s = status.toLowerCase();
    if (s === 'confirmada' || s === 'approved' || s === 'confirmado') return 'Confirmada';
    if (s === 'cancelada' || s === 'cancelled') return 'Cancelada';
    if (s === 'suspensa' || s === 'suspended') return 'Suspensa';
    if (s === 'concluída' || s === 'concluida') return 'Concluída';
    return 'Pendente';
  };

  useEffect(() => {
    fetchReservas();
  }, []);

  const fetchReservas = async () => {
    setLoading(true);
    try {
      // 🔑 Obter ID de forma segura através do Token JWT ou chaves locais
      let userId = null;
      const token = localStorage.getItem('token') || localStorage.getItem('morabeza_token');
      
      if (token) {
        try {
          const base64Url = token.split('.')[1];
          const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
          const jsonPayload = decodeURIComponent(atob(base64).split('').map(c => {
            return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
          }).join(''));
          const parsed = JSON.parse(jsonPayload);
          userId = parsed.data?.id || parsed.id;
        } catch (e) {
          console.error('Erro ao ler token:', e);
        }
      }

      if (!userId) {
        const savedUser = localStorage.getItem('morabeza_user') || localStorage.getItem('user');
        if (savedUser) {
          const userObj = JSON.parse(savedUser);
          userId = userObj.id;
        }
      }

      if (!userId) {
        setLoading(false);
        return;
      }
      
      const response = await fetch(`https://welovepalop.com/api/dashboard/reservas_recentes.php?usuario_id=${userId}`);
      const data = await response.json();
      
      if (data.success && data.data?.reservas) {
        const reservasData = data.data.reservas;
        
        const reservasFormatadas = reservasData.map(reserva => ({
          ...reserva,
          status: formatStatus(reserva.status),
          tipo: reserva.tipo || 'desconhecido',
          cliente_nome: reserva.cliente_nome || 'Cliente',
          cliente_foto: reserva.cliente_foto || `https://ui-avatars.com/api/?name=${encodeURIComponent(reserva.cliente_nome || 'Cliente')}&background=0D8ABC&color=fff`,
          item_nome: reserva.item_nome || 'Item não identificado',
          valor: reserva.valor || '0',
          periodo: reserva.periodo || 'Data não informada',
          codigo: reserva.codigo || 'N/A'
        }));
        
        setReservas(reservasFormatadas);
        
        setCounts({
          todas: reservasFormatadas.length,
          confirmadas: reservasFormatadas.filter(r => r.status === 'Confirmada').length,
          pendentes: reservasFormatadas.filter(r => r.status === 'Pendente').length,
          canceladas: reservasFormatadas.filter(r => r.status === 'Cancelada').length,
          suspensas: reservasFormatadas.filter(r => r.status === 'Suspensa').length,
          concluidas: reservasFormatadas.filter(r => r.status === 'Concluída').length
        });
      } else {
        setReservas([]);
      }
    } catch (error) {
      console.error('Erro ao buscar reservas:', error);
      showToast('Erro ao carregar reservas', 'error');
    } finally {
      setLoading(false);
    }
  };

  const showToast = (message, type = 'success') => {
    setToast({ show: true, message, type });
    setTimeout(() => setToast({ show: false, message: '', type: '' }), 3000);
  };

  const executarAcaoAPI = async (reserva, novoStatus, sucessoMsg, modalSetter) => {
    setActionLoading(reserva.id);
    try {
      const response = await fetch('https://welovepalop.com/api/admin/atualizar_status_reserva.php', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          id: reserva.id,
          tipo_reserva: reserva.tipo,
          status: novoStatus,
          motivo: motivoCancelamento.trim() || 'Ação executada pelo Anfitrião'
        })
      });
      
      const rawText = await response.text();
      let data;
      
      try {
        const jsonStart = rawText.indexOf('{');
        const jsonEnd = rawText.lastIndexOf('}') + 1;
        data = JSON.parse(jsonStart !== -1 && jsonEnd !== -1 ? rawText.slice(jsonStart, jsonEnd) : rawText);
      } catch (parseError) {
        showToast('Erro de leitura no servidor.', 'error');
        setActionLoading(null);
        return;
      }
      
      if (data && data.success) {
        showToast(sucessoMsg, 'success');
        fetchReservas();
        modalSetter(null);
        setMotivoCancelamento('');
      } else {
        showToast(data?.message || 'Erro ao processar ação', 'error');
      }
    } catch (error) {
      showToast('Erro de conexão com o servidor', 'error');
    } finally {
      setActionLoading(null);
    }
  };

  const tabs = [
    { key: 'Todas', label: `Todas (${counts.todas})` },
    { key: 'Confirmada', label: `Confirmadas (${counts.confirmadas})` },
    { key: 'Pendente', label: `Pendentes (${counts.pendentes})` },
    { key: 'Suspensa', label: `Suspensas (${counts.suspensas})` },
    { key: 'Cancelada', label: `Canceladas (${counts.canceladas})` },
    { key: 'Concluída', label: `Concluídas (${counts.concluidas})` }
  ];

  const getFilteredReservas = () => {
    if (activeTab === 'Todas') return reservas;
    return reservas.filter(r => r.status === activeTab);
  };

  const filteredReservas = getFilteredReservas();

  const getStatusBadge = (status) => {
    switch(status) {
      case 'Confirmada': return <span className="bg-[#e6f4ea] text-[#137333] px-3 py-1 rounded-md text-[12px] font-semibold flex items-center gap-1"><CheckCircle size={12} /> Confirmada</span>;
      case 'Pendente': return <span className="bg-[#fef3c7] text-[#b45309] px-3 py-1 rounded-md text-[12px] font-semibold flex items-center gap-1"><AlertCircle size={12} /> Pendente</span>;
      case 'Suspensa': return <span className="bg-orange-100 text-orange-800 px-3 py-1 rounded-md text-[12px] font-semibold flex items-center gap-1"><PauseCircle size={12} /> Suspensa</span>;
      case 'Concluída': return <span className="bg-[#e0f2f1] text-[#0f766e] px-3 py-1 rounded-md text-[12px] font-semibold flex items-center gap-1">✓ Concluída</span>;
      case 'Cancelada': return <span className="bg-[#fee2e2] text-[#b91c1c] px-3 py-1 rounded-md text-[12px] font-semibold flex items-center gap-1"><XCircle size={12} /> Cancelada</span>;
      default: return <span className="bg-gray-100 text-gray-700 px-3 py-1 rounded-md text-[12px] font-semibold">{status}</span>;
    }
  };

  return (
    <div className="max-w-7xl w-full text-[#0f172a] px-4 py-6 md:px-0">
      {toast.show && (
        <div className={`fixed top-4 right-4 z-50 px-4 py-3 rounded-lg shadow-lg ${toast.type === 'success' ? 'bg-green-500 text-white' : toast.type === 'error' ? 'bg-red-500 text-white' : 'bg-yellow-500 text-white'}`}>
          {toast.message}
        </div>
      )}

      <div className="bg-white rounded-xl border border-gray-100 shadow-sm overflow-hidden">
        <div className="px-5 pt-5 pb-3 border-b border-gray-100 flex justify-between items-center">
          <div>
            <h2 className="text-xl font-bold text-[#0f172a]">Gestão de Reservas</h2>
            <p className="text-sm text-gray-500">Reservas feitas nos seus anúncios</p>
          </div>
          <button onClick={fetchReservas} className="p-2 text-gray-500 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition">
            <RefreshCw size={18} className={loading ? 'animate-spin' : ''} />
          </button>
        </div>

        <div className="border-b border-gray-100 px-5 pt-2 overflow-x-auto whitespace-nowrap">
          <div className="flex gap-6">
            {tabs.map((tab) => (
              <button
                key={tab.key}
                onClick={() => setActiveTab(tab.key)}
                className={`pb-4 pt-3 text-sm font-medium transition relative ${activeTab === tab.key ? 'text-blue-600' : 'text-gray-500 hover:text-gray-900'}`}
              >
                {tab.label}
                {activeTab === tab.key && <div className="absolute bottom-0 left-0 right-0 h-[2px] bg-blue-600 rounded-t-full"></div>}
              </button>
            ))}
          </div>
        </div>

        {filteredReservas.length === 0 && (
          <div className="text-center py-12 text-gray-400">
            <Home size={48} className="mx-auto text-gray-300 mb-2" />
            <p className="text-lg font-medium">Nenhuma reserva encontrada</p>
          </div>
        )}

        {filteredReservas.length > 0 && (
          <div className="overflow-x-auto">
            <table className="w-full min-w-[900px]">
              <thead>
                <tr className="border-b border-gray-100 bg-gray-50/50 text-left text-xs text-gray-500">
                  <th className="px-6 py-3">Cliente / Item</th>
                  <th className="px-6 py-3">Período</th>
                  <th className="px-6 py-3">Valor</th>
                  <th className="px-6 py-3">Status</th>
                  <th className="px-6 py-3">Código</th>
                  <th className="px-center py-3 text-center">Ações</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {filteredReservas.map((reserva) => (
                  <tr key={reserva.id} className="hover:bg-gray-50/50 transition">
                    <td className="px-6 py-4 flex items-center gap-3">
                      <img src={reserva.cliente_foto} alt="" className="w-10 h-10 rounded-full object-cover border" />
                      <div>
                        <p className="text-sm font-semibold text-gray-900">{reserva.cliente_nome}</p>
                        <p className="text-xs text-gray-500">{reserva.item_nome}</p>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-sm text-gray-600">{reserva.periodo}</td>
                    <td className="px-6 py-4 text-sm font-bold text-gray-900">{reserva.valor} CVE</td>
                    <td className="px-6 py-4">{getStatusBadge(reserva.status)}</td>
                    <td className="px-6 py-4 font-mono text-xs text-gray-500">{reserva.codigo}</td>
                    <td className="px-6 py-4">
                      <div className="flex items-center justify-center gap-1.5">
                        <button onClick={() => setShowConfirmModal(reserva)} className="p-1 text-green-600 hover:bg-green-50 rounded" title="Confirmar">
                          <CheckCircle size={18} />
                        </button>
                        <button onClick={() => setShowSuspendModal(reserva)} className="p-1 text-orange-600 hover:bg-orange-50 rounded" title="Suspender">
                          <PauseCircle size={18} />
                        </button>
                        <button 
                          onClick={() => {
                            setReservaSelecionadaReembolso(reserva);
                            setShowReembolsoModal(true);
                          }} 
                          className="p-1 text-blue-600 hover:bg-blue-50 rounded" 
                          title="Reembolsar"
                        >
                          <DollarSign size={18} />
                        </button>
                        <button onClick={() => setShowCancelModal(reserva)} className="p-1 text-red-600 hover:bg-red-50 rounded" title="Cancelar">
                          <XCircle size={18} />
                        </button>
                        <button onClick={() => setShowDeleteModal(reserva)} className="p-1 text-gray-400 hover:text-red-700 hover:bg-red-50 rounded" title="Eliminar Definitivamente">
                          <Trash2 size={18} />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Modal Confirmar */}
      {showConfirmModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl max-w-md w-full p-6 text-center">
            <h3 className="text-lg font-bold mb-2">Confirmar Reserva</h3>
            <p className="text-gray-500 text-sm mb-4">Deseja aprovar a reserva <strong>{showConfirmModal.codigo}</strong>?</p>
            <div className="flex gap-3">
              <button onClick={() => executarAcaoAPI(showConfirmModal, 'confirmada', 'Reserva confirmada!', setShowConfirmModal)} className="flex-1 bg-green-600 text-white py-2 rounded-lg font-semibold">Sim, Confirmar</button>
              <button onClick={() => setShowConfirmModal(null)} className="flex-1 bg-gray-100 text-gray-700 py-2 rounded-lg font-semibold">Cancelar</button>
            </div>
          </div>
        </div>
      )}

      {/* Modal Suspender */}
      {showSuspendModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl max-w-md w-full p-6 text-center">
            <h3 className="text-lg font-bold mb-2 text-orange-600">Suspender Reserva</h3>
            <p className="text-gray-500 text-sm mb-4">Deseja colocar temporariamente a reserva <strong>{showSuspendModal.codigo}</strong> como suspensa?</p>
            <div className="flex gap-3">
              <button onClick={() => executarAcaoAPI(showSuspendModal, 'suspensa', 'Reserva suspensa com sucesso!', setShowSuspendModal)} className="flex-1 bg-orange-600 text-white py-2 rounded-lg font-semibold">Sim, Suspender</button>
              <button onClick={() => setShowSuspendModal(null)} className="flex-1 bg-gray-100 text-gray-700 py-2 rounded-lg font-semibold">Voltar</button>
            </div>
          </div>
        </div>
      )}

      {/* Modal Reembolso */}
      {showReembolsoModal && (
        <ReembolsoModal 
          reserva={reservaSelecionadaReembolso}
          onClose={() => setShowReembolsoModal(false)}
          onSuccess={(mensagem) => {
            showToast(mensagem, 'success');
            fetchReservas();
          }}
        />
      )}

      {/* Modal Cancelar */}
      {showCancelModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl max-w-md w-full p-6 text-left">
            <h3 className="text-lg font-bold mb-2 text-read-600 text-center">Cancelar Reserva</h3>
            <p className="text-gray-500 text-sm mb-3 text-center">Tem certeza que deseja cancelar a reserva <strong>{showCancelModal.codigo}</strong>?</p>
            <textarea value={motivoCancelamento} onChange={(e) => setMotivoCancelamento(e.target.value)} placeholder="Informe o motivo..." className="w-full border p-2 rounded text-sm mb-4" rows={3}></textarea>
            <div className="flex gap-3">
              <button disabled={!motivoCancelamento.trim()} onClick={() => executarAcaoAPI(showCancelModal, 'cancelada', 'Reserva cancelada.', setShowCancelModal)} className="flex-1 bg-red-600 text-white py-2 rounded-lg font-semibold disabled:opacity-50">Sim, Cancelar</button>
              <button onClick={() => setShowCancelModal(null)} className="flex-1 bg-gray-100 text-gray-700 py-2 rounded-lg font-semibold">Voltar</button>
            </div>
          </div>
        </div>
      )}

      {/* Modal Eliminar */}
      {showDeleteModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl max-w-md w-full p-6 text-center">
            <h3 className="text-lg font-bold mb-2 text-red-700">Eliminar Definitivamente</h3>
            <p className="text-gray-500 text-sm mb-4">Atenção! Esta ação apaga o registo da base de dados de forma irreversível. Deseja continuar?</p>
            <div className="flex gap-3">
              <button onClick={() => executarAcaoAPI(showDeleteModal, 'eliminar', 'Reserva eliminada da base de dados.', setShowDeleteModal)} className="flex-1 bg-red-700 text-white py-2 rounded-lg font-semibold">Sim, Eliminar</button>
              <button onClick={() => setShowDeleteModal(null)} className="flex-1 bg-gray-100 text-gray-700 py-2 rounded-lg font-semibold">Cancelar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// src/components/gest/UnidadesVeiculos.jsx
import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Loader2, Car, Plus, Pencil, Wrench, History, X, Save,
  CheckCircle, AlertCircle, FileText, Key, Search, ChevronDown, Check,
  Upload, Eye, Trash2, Lock, Unlock, Truck, CircleDot, Shield
} from 'lucide-react';

const API = 'https://welovepalop.com/api';

const ESTADOS = [
  { valor: 'disponivel',   label: 'Disponível',   cor: 'bg-green-100 text-green-700',   dot: 'bg-green-500',   icone: '🟢' },
  { valor: 'reservada',    label: 'Reservada',    cor: 'bg-blue-100 text-blue-700',     dot: 'bg-blue-500',    icone: '🔵' },
  { valor: 'entregue',     label: 'Entregue',     cor: 'bg-purple-100 text-purple-700', dot: 'bg-purple-500',  icone: '🟣' },
  { valor: 'manutencao',   label: 'Manutenção',   cor: 'bg-orange-100 text-orange-700', dot: 'bg-orange-500',  icone: '🟠' },
  { valor: 'indisponivel', label: 'Indisponível', cor: 'bg-gray-200 text-gray-700',     dot: 'bg-gray-500',    icone: '⚫' }
];

export default function UnidadesVeiculos() {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [carros, setCarros] = useState([]);
  const [carroSelecionado, setCarroSelecionado] = useState(null);
  const [unidades, setUnidades] = useState([]);
  const [loadingUnidades, setLoadingUnidades] = useState(false);

  // LOV (dropdown com search)
  const [dropdownAberto, setDropdownAberto] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const dropdownRef = useRef(null);

  // Modais
  const [modalForm, setModalForm] = useState(false);
  const [modalHistorico, setModalHistorico] = useState(false);
  const [unidadeEditando, setUnidadeEditando] = useState(null);
  const [historico, setHistorico] = useState(null);
  const [loadingHistorico, setLoadingHistorico] = useState(false);

  // Upload documentos
  const [tipoDoc, setTipoDoc] = useState('seguro');
  const [ficheiro, setFicheiro] = useState(null);
  const [uploadando, setUploadando] = useState(false);

  // Menu de estados (dropdown por linha)
  const [estadoMenuAberto, setEstadoMenuAberto] = useState(null);
  const estadoMenuRef = useRef(null);

  // Modal de motivo (obrigatório para manutencao/indisponivel)
  const [modalMotivo, setModalMotivo] = useState(null); // { unidade, estado }
  const [motivoTexto, setMotivoTexto] = useState('');

  const [toast, setToast] = useState({ show: false, tipo: 'ok', msg: '' });

  // Form
  const [form, setForm] = useState({
    matricula: '', ano: '', cor: '', quilometragem: ''
  });

  // Fecha dropdowns ao clicar fora
  useEffect(() => {
    const handleClickOutside = (e) => {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target)) {
        setDropdownAberto(false);
      }
      if (estadoMenuRef.current && !estadoMenuRef.current.contains(e.target)) {
        setEstadoMenuAberto(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const obterUserId = () => {
    try {
      const token = localStorage.getItem('token') || localStorage.getItem('morabeza_token');
      if (token) {
        const base64Url = token.split('.')[1];
        const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
        const jsonPayload = decodeURIComponent(atob(base64).split('').map(c => {
          return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
        }).join(''));
        const parsed = JSON.parse(jsonPayload);
        if (parsed.data?.id) return parsed.data.id;
        if (parsed.id) return parsed.id;
      }
      const savedUser = localStorage.getItem('user') || localStorage.getItem('morabeza_user');
      if (savedUser) return JSON.parse(savedUser).id;
    } catch (e) { console.error('Erro ao obter ID:', e); }
    return null;
  };

  const showToast = (tipo, msg) => {
    setToast({ show: true, tipo, msg });
    setTimeout(() => setToast({ show: false, tipo: 'ok', msg: '' }), 3500);
  };

  // ============ CARREGAR CARROS ============
  useEffect(() => { fetchCarros(); }, []);

  const fetchCarros = async () => {
    setLoading(true);
    try {
      const userId = obterUserId();
      if (!userId) { setLoading(false); return; }

      const res = await fetch(`${API}/carro/listar.php?usuario_id=${userId}`);
      const data = await res.json();

      let lista = [];
      if (data.success && data.data?.items && Array.isArray(data.data.items)) {
        lista = data.data.items;
      } else if (data.success && Array.isArray(data.data)) {
        lista = data.data;
      } else if (data.success && data.data?.carros) {
        lista = data.data.carros;
      }

      setCarros(lista);
      if (lista.length > 0) setCarroSelecionado(lista[0]);
    } catch (e) {
      console.error(e);
      showToast('erro', 'Erro ao carregar carros');
    } finally {
      setLoading(false);
    }
  };

  // ============ CARREGAR UNIDADES ============
  useEffect(() => {
    if (carroSelecionado?.id) {
      fetchUnidades(carroSelecionado.id);
    } else {
      setUnidades([]);
    }
  }, [carroSelecionado?.id]);

  const fetchUnidades = async (carroId) => {
    if (!carroId) { setUnidades([]); return; }
    setLoadingUnidades(true);
    try {
      const userId = obterUserId();
      if (!userId) { setLoadingUnidades(false); return; }

      const url = `${API}/carro/unidades_listar.php?carro_id=${carroId}&usuario_id=${userId}`;
      const res = await fetch(url);
      const data = await res.json();

      if (data.success) {
        setUnidades(Array.isArray(data.data) ? data.data : []);
      } else {
        setUnidades([]);
      }
    } catch (e) {
      console.error(e);
      showToast('erro', 'Erro ao carregar unidades');
      setUnidades([]);
    } finally {
      setLoadingUnidades(false);
    }
  };

  // ============ FORM ============
  const abrirNovaUnidade = () => {
    setUnidadeEditando(null);
    setForm({ matricula: '', ano: '', cor: '', quilometragem: '' });
    setFicheiro(null);
    setTipoDoc('seguro');
    setModalForm(true);
  };

  const abrirEditarUnidade = (u) => {
    setUnidadeEditando(u);
    setForm({
      matricula: u.matricula || '',
      ano: u.ano || '',
      cor: u.cor || '',
      quilometragem: u.quilometragem || ''
    });
    setFicheiro(null);
    setTipoDoc('seguro');
    setModalForm(true);
  };

  const guardarUnidade = async () => {
    if (!form.matricula.trim()) {
      showToast('erro', 'Matrícula é obrigatória');
      return;
    }

    const userId = obterUserId();
    if (!userId) { showToast('erro', 'Sessão expirada'); return; }

    const payload = {
      usuario_id: userId,
      carro_id: carroSelecionado.id,
      matricula: form.matricula.trim(),
      ano: form.ano ? parseInt(form.ano) : null,
      cor: form.cor.trim() || null,
      quilometragem: form.quilometragem ? parseInt(form.quilometragem) : 0
    };
    if (unidadeEditando) payload.id = unidadeEditando.id;

    try {
      const url = unidadeEditando
        ? `${API}/carro/unidades_editar.php`
        : `${API}/carro/unidades_criar.php`;

      const res = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      const data = await res.json();

      if (data.success) {
        showToast('ok', unidadeEditando ? 'Unidade atualizada' : 'Unidade criada');

        if (!unidadeEditando && data.data?.id) {
          await fetchUnidades(carroSelecionado.id);
          setUnidadeEditando({
            id: data.data.id,
            matricula: data.data.matricula,
            ano: data.data.ano,
            cor: data.data.cor,
            quilometragem: data.data.quilometragem,
            documentos: [],
            estado: 'disponivel'
          });
        } else {
          setModalForm(false);
          fetchUnidades(carroSelecionado.id);
        }
      } else {
        showToast('erro', data.message || 'Erro ao guardar');
      }
    } catch (e) {
      console.error(e);
      showToast('erro', 'Erro de rede');
    }
  };

  // ============ UPLOAD / REMOÇÃO DE DOCUMENTOS ============
  const enviarDocumento = async () => {
    if (!ficheiro) { showToast('erro', 'Escolhe um ficheiro'); return; }
    if (!unidadeEditando?.id) { showToast('erro', 'Unidade inválida'); return; }

    const userId = obterUserId();
    if (!userId) { showToast('erro', 'Sessão expirada'); return; }

    setUploadando(true);
    try {
      const fd = new FormData();
      fd.append('usuario_id', userId);
      fd.append('unidade_id', unidadeEditando.id);
      fd.append('tipo', tipoDoc);
      fd.append('ficheiro', ficheiro);

      const res = await fetch(`${API}/carro/unidade_documento_upload.php`, {
        method: 'POST',
        body: fd
      });
      const data = await res.json();

      if (data.success) {
        showToast('ok', 'Documento enviado');
        setFicheiro(null);
        const input = document.getElementById('input-ficheiro-unidade');
        if (input) input.value = '';

        setUnidadeEditando(prev => ({
          ...prev,
          documentos: [...(prev.documentos || []), data.data.documento]
        }));
        fetchUnidades(carroSelecionado.id);
      } else {
        showToast('erro', data.message || 'Erro no upload');
      }
    } catch (e) {
      console.error(e);
      showToast('erro', 'Erro de rede');
    } finally {
      setUploadando(false);
    }
  };

  const removerDocumento = async (docId) => {
    if (!confirm('Remover este documento?')) return;

    const userId = obterUserId();
    if (!userId) { showToast('erro', 'Sessão expirada'); return; }

    try {
      const res = await fetch(`${API}/carro/unidade_documento_remover.php`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          usuario_id: userId,
          unidade_id: unidadeEditando.id,
          documento_id: docId
        })
      });
      const data = await res.json();

      if (data.success) {
        showToast('ok', 'Documento removido');
        setUnidadeEditando(prev => ({
          ...prev,
          documentos: (prev.documentos || []).filter(d => d.id !== docId)
        }));
        fetchUnidades(carroSelecionado.id);
      } else {
        showToast('erro', data.message || 'Erro ao remover');
      }
    } catch (e) {
      console.error(e);
      showToast('erro', 'Erro de rede');
    }
  };

  // ============ ESTADOS ============
  const ESTADOS_MANUAIS = ['disponivel', 'manutencao', 'indisponivel'];

  const mudarEstadoManual = (unidade, novoEstado) => {
    if (novoEstado === 'manutencao' || novoEstado === 'indisponivel') {
      setModalMotivo({ unidade, estado: novoEstado });
      setMotivoTexto(unidade.motivo_bloqueio || '');
      return;
    }
    executarMudancaEstado(unidade, novoEstado, null);
  };

  const executarMudancaEstado = async (unidade, novoEstado, motivo) => {
    const userId = obterUserId();
    if (!userId) { showToast('erro', 'Sessão expirada'); return; }

    try {
      const res = await fetch(`${API}/carro/unidades_estado.php`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          usuario_id: userId,
          id: unidade.id,
          estado: novoEstado,
          motivo: motivo || null
        })
      });
      const data = await res.json();

      if (data.success) {
        const label = ESTADOS.find(e => e.valor === novoEstado)?.label || novoEstado;
        showToast('ok', `Estado: ${label}`);
        setEstadoMenuAberto(null);
        setModalMotivo(null);
        setMotivoTexto('');
        fetchUnidades(carroSelecionado.id);
      } else {
        showToast('erro', data.message || 'Erro ao alterar estado');
      }
    } catch (e) {
      console.error(e);
      showToast('erro', 'Erro de rede');
    }
  };

  // ============ HISTÓRICO ============
  const verHistorico = async (unidade) => {
    setModalHistorico(true);
    setLoadingHistorico(true);
    setHistorico(null);

    const userId = obterUserId();
    if (!userId) { showToast('erro', 'Sessão expirada'); setLoadingHistorico(false); return; }

    try {
      const res = await fetch(`${API}/carro/unidades_historico.php?unidade_id=${unidade.id}&usuario_id=${userId}`);
      const data = await res.json();
      if (data.success) setHistorico(data.data);
      else showToast('erro', data.message || 'Erro ao carregar histórico');
    } catch (e) {
      console.error(e);
      showToast('erro', 'Erro de rede');
    } finally {
      setLoadingHistorico(false);
    }
  };

  const estadoBadge = (estado) => {
    const e = ESTADOS.find(x => x.valor === estado);
    if (!e) return (
      <span className="px-3 py-1 rounded-md text-[11px] font-bold bg-gray-100 text-gray-700">
        {estado}
      </span>
    );
    return (
      <span className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-md text-[11px] font-bold ${e.cor}`}>
        <span className={`w-1.5 h-1.5 rounded-full ${e.dot}`} />
        {e.label}
      </span>
    );
  };

  // ============ LOV: filtro ============
  const carrosFiltrados = carros.filter(c => {
    const t = (c.titulo || '').toLowerCase();
    const m = (c.marca || '').toLowerCase();
    const mo = (c.modelo || '').toLowerCase();
    const s = searchTerm.toLowerCase();
    return t.includes(s) || m.includes(s) || mo.includes(s);
  });

  if (loading) {
    return (
      <div className="max-w-6xl w-full text-[#1a1f36] px-4 py-6 md:px-0 flex justify-center items-center h-96">
        <Loader2 size={48} className="animate-spin text-blue-900" />
      </div>
    );
  }

  if (carros.length === 0) {
    return (
      <div className="max-w-6xl w-full text-[#1a1f36] px-4 py-6 md:px-0">
        <h1 className="text-[24px] font-bold mb-6">Unidades dos Meus Veículos</h1>
        <div className="bg-white rounded-2xl p-12 text-center border border-gray-100 shadow-sm">
          <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
            <Car size={40} className="text-gray-400" />
          </div>
          <h2 className="text-xl font-bold text-gray-800 mb-2">Sem veículos</h2>
          <p className="text-gray-500">Ainda não tem viaturas registadas.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-7xl w-full text-[#1a1f36] px-4 py-6 md:px-0">
      <h1 className="text-[24px] font-bold mb-6">Unidades dos Meus Veículos</h1>

      {/* LOV — Dropdown com search bar */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-6">
        <h2 className="text-[18px] font-bold">
          Unidades {carroSelecionado && `— ${carroSelecionado.titulo || carroSelecionado.modelo}`}
        </h2>

        <div className="relative w-full md:w-80" ref={dropdownRef}>
          <button
            onClick={() => setDropdownAberto(!dropdownAberto)}
            className="w-full flex items-center justify-between bg-white border border-gray-200 text-[#0f172a] text-[14px] font-medium rounded-xl px-4 py-2.5 shadow-sm hover:bg-gray-50 transition-colors"
          >
            <div className="flex items-center gap-2 truncate">
              <Car size={18} className="text-green-600 flex-shrink-0" />
              <span className="truncate">{carroSelecionado?.titulo || 'Selecione um veículo...'}</span>
            </div>
            <ChevronDown className={`w-4 h-4 text-gray-500 transition-transform ${dropdownAberto ? 'rotate-180' : ''}`} />
          </button>

          {dropdownAberto && (
            <div className="absolute right-0 mt-2 w-full bg-white rounded-xl shadow-xl border border-gray-100 z-50 p-2">
              <div className="relative mb-2">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-gray-400" />
                <input
                  type="text"
                  placeholder="Pesquisar veículo..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="w-full pl-8 pr-3 py-2 text-xs border border-gray-200 rounded-lg focus:outline-none bg-gray-50/50"
                  autoFocus
                />
              </div>

              <div className="max-h-56 overflow-y-auto space-y-1">
                {carrosFiltrados.length > 0 ? (
                  carrosFiltrados.map(c => {
                    const isSelected = carroSelecionado?.id === c.id;
                    return (
                      <button
                        key={c.id}
                        onClick={() => {
                          setCarroSelecionado(c);
                          setDropdownAberto(false);
                          setSearchTerm('');
                        }}
                        className={`w-full flex items-center justify-between px-3 py-2 rounded-lg text-xs font-medium transition-colors text-left ${
                          isSelected ? 'bg-blue-50 text-blue-900 font-bold' : 'hover:bg-gray-50 text-gray-700'
                        }`}
                      >
                        <span className="truncate">
                          {c.titulo || `${c.marca} ${c.modelo}`} {c.ano ? `(${c.ano})` : ''}
                        </span>
                        {isSelected && <Check size={14} className="text-blue-900" />}
                      </button>
                    );
                  })
                ) : (
                  <p className="text-center py-3 text-xs text-gray-400">Nenhum veículo encontrado</p>
                )}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Botões de ação */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-end gap-2 mb-4">
        <button
          onClick={() => navigate('/gest/condicoes-veiculos')}
          className="flex items-center justify-center gap-2 bg-white border border-gray-200 hover:bg-gray-50 text-gray-800 px-4 py-2 rounded-lg text-[13px] font-bold transition-colors"
        >
          <Shield size={16} /> Condições dos Veículos
        </button>
        <button
          onClick={abrirNovaUnidade}
          className="flex items-center justify-center gap-2 bg-blue-900 hover:bg-blue-800 text-white px-4 py-2 rounded-lg text-[13px] font-bold transition-colors"
        >
          <Plus size={16} /> Adicionar Unidade
        </button>
      </div>

      {/* Legenda de estados */}
      <div className="flex flex-wrap items-center gap-3 mb-3">
        <span className="text-[11px] font-bold text-gray-400 uppercase">Estados:</span>
        {ESTADOS.map(e => (
          <span key={e.valor} className={`inline-flex items-center gap-1.5 px-2 py-0.5 rounded text-[10px] font-bold ${e.cor}`}>
            <span className={`w-1.5 h-1.5 rounded-full ${e.dot}`} />
            {e.label}
          </span>
        ))}
      </div>

      {/* Tabela */}
      <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-visible">
        {loadingUnidades ? (
          <div className="text-center py-12">
            <Loader2 size={32} className="animate-spin text-blue-900 mx-auto" />
          </div>
        ) : unidades.length === 0 ? (
          <div className="text-center py-12">
            <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-3">
              <Key size={24} className="text-gray-400" />
            </div>
            <p className="text-gray-500">Nenhuma unidade registada para este veículo</p>
            <p className="text-xs text-gray-400 mt-1">
              Adicione pelo menos uma unidade para poder aprovar reservas
            </p>
          </div>
        ) : (
          <div className="overflow-visible">
            <table className="w-full min-w-[1000px] text-left">
              <thead>
                <tr className="bg-gray-50/50 border-b border-gray-100">
                  <th className="px-6 py-4 text-[12px] font-bold text-gray-500 uppercase">Matrícula</th>
                  <th className="px-6 py-4 text-[12px] font-bold text-gray-500 uppercase">Ano</th>
                  <th className="px-6 py-4 text-[12px] font-bold text-gray-500 uppercase">Cor</th>
                  <th className="px-6 py-4 text-[12px] font-bold text-gray-500 uppercase">KM</th>
                  <th className="px-6 py-4 text-[12px] font-bold text-gray-500 uppercase">Documentos</th>
                  <th className="px-6 py-4 text-[12px] font-bold text-gray-500 uppercase">Estado</th>
                  <th className="px-6 py-4 text-[12px] font-bold text-gray-500 uppercase text-right">Ações</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {unidades.map(u => {
                  const bloqueado = u.estado === 'reservada' || u.estado === 'entregue';
                  return (
                    <tr key={u.id} className="hover:bg-gray-50/50 transition-colors">
                      <td className="px-6 py-5">
                        <span className="text-[14px] font-bold tracking-wide">{u.matricula}</span>
                        {u.motivo_bloqueio && (
                          <p className="text-[10px] text-gray-500 mt-0.5 italic truncate max-w-[180px]">
                            {u.motivo_bloqueio}
                          </p>
                        )}
                      </td>
                      <td className="px-6 py-5 text-[13px]">{u.ano || '—'}</td>
                      <td className="px-6 py-5 text-[13px]">{u.cor || '—'}</td>
                      <td className="px-6 py-5 text-[13px]">
                        {u.quilometragem ? `${u.quilometragem.toLocaleString()} km` : '—'}
                      </td>
                      <td className="px-6 py-5">
                        {u.documentos && u.documentos.length > 0 ? (
                          <span className="inline-flex items-center gap-1 text-[12px] text-blue-600 font-bold">
                            <FileText size={12} /> {u.documentos.length}
                          </span>
                        ) : (
                          <span className="text-[12px] text-gray-400">Sem docs</span>
                        )}
                      </td>
                      <td className="px-6 py-5">{estadoBadge(u.estado)}</td>
                      <td className="px-6 py-5">
                        <div className="flex items-center justify-end gap-2">
                          <button
                            onClick={() => abrirEditarUnidade(u)}
                            className="p-2 rounded-lg bg-gray-100 hover:bg-gray-200 transition-colors"
                            title="Editar"
                          >
                            <Pencil size={14} className="text-gray-600" />
                          </button>

                          <div className="relative" ref={estadoMenuAberto === u.id ? estadoMenuRef : null}>
                            <button
                              onClick={() => setEstadoMenuAberto(estadoMenuAberto === u.id ? null : u.id)}
                              disabled={bloqueado}
                              className={`p-2 rounded-lg transition-colors ${
                                u.estado === 'manutencao'   ? 'bg-orange-100 hover:bg-orange-200' :
                                u.estado === 'indisponivel' ? 'bg-gray-200 hover:bg-gray-300' :
                                u.estado === 'reservada'    ? 'bg-blue-100' :
                                u.estado === 'entregue'     ? 'bg-purple-100' :
                                'bg-green-100 hover:bg-green-200'
                              } disabled:opacity-50 disabled:cursor-not-allowed`}
                              title={bloqueado ? 'Estado gerido por reserva' : 'Alterar estado'}
                            >
                              <Wrench size={14} className={
                                u.estado === 'manutencao'   ? 'text-orange-700' :
                                u.estado === 'indisponivel' ? 'text-gray-700' :
                                u.estado === 'reservada'    ? 'text-blue-700' :
                                u.estado === 'entregue'     ? 'text-purple-700' :
                                'text-green-700'
                              } />
                            </button>

                            {estadoMenuAberto === u.id && !bloqueado && (
                              <div className="absolute right-0 mt-1 w-48 bg-white rounded-lg shadow-xl border border-gray-100 z-[999] py-1">
                                <div className="px-3 py-1.5 text-[10px] font-bold text-gray-400 uppercase border-b border-gray-100">
                                  Alterar estado
                                </div>
                                {ESTADOS.filter(e => ESTADOS_MANUAIS.includes(e.valor)).map(e => (
                                  <button
                                    key={e.valor}
                                    onClick={() => mudarEstadoManual(u, e.valor)}
                                    disabled={u.estado === e.valor}
                                    className="w-full flex items-center gap-2 text-left px-3 py-2 text-[12px] font-medium hover:bg-gray-50 disabled:opacity-40"
                                  >
                                    <span className={`w-2 h-2 rounded-full ${e.dot}`} />
                                    {e.label}
                                    {u.estado === e.valor && <Check size={12} className="ml-auto text-blue-900" />}
                                  </button>
                                ))}
                              </div>
                            )}
                          </div>

                          <button
                            onClick={() => verHistorico(u)}
                            className="p-2 rounded-lg bg-gray-100 hover:bg-gray-200 transition-colors"
                            title="Histórico"
                          >
                            <History size={14} className="text-gray-600" />
                          </button>
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Nota */}
      <div className="mt-6 bg-gray-50 rounded-xl p-4 border border-gray-100">
        <div className="flex items-start gap-3">
          <div className="w-8 h-8 bg-blue-100 rounded-full flex items-center justify-center flex-shrink-0">
            <AlertCircle size={16} className="text-blue-600" />
          </div>
          <div className="text-[12px] text-gray-600 space-y-1">
            <p>
              <span className="font-bold">Nota:</span> A matrícula e os documentos são <span className="font-bold">privados</span> —
              o cliente final nunca os vê.
            </p>
            <p>
              <span className="font-bold">Bloqueio:</span> Marcar como <em>Manutenção</em> ou <em>Indisponível</em> retira a unidade
              das reservas sem criar reserva.
            </p>
            <p>
              <span className="font-bold">Estados automáticos:</span> <em>Reservada</em> e <em>Entregue</em> são geridos pelo sistema
              ao aprovar/entregar reservas.
            </p>
          </div>
        </div>
      </div>

      {/* ============ MODAL: Criar/Editar ============ */}
      {modalForm && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[9999] p-4">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-3xl max-h-[90vh] overflow-y-auto">
            <div className="flex items-center justify-between p-5 border-b border-gray-100 sticky top-0 bg-white z-10 rounded-t-2xl">
              <h3 className="text-[18px] font-bold">
                {unidadeEditando ? 'Editar Unidade' : 'Nova Unidade'}
              </h3>
              <button onClick={() => setModalForm(false)} className="p-2 hover:bg-gray-100 rounded-lg">
                <X size={18} />
              </button>
            </div>

            <div className="p-6 space-y-5">
              <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                <div className="md:col-span-2">
                  <label className="text-[11px] font-bold text-gray-500 uppercase block mb-1">
                    Matrícula *
                  </label>
                  <input
                    type="text"
                    value={form.matricula}
                    onChange={(e) => setForm({ ...form, matricula: e.target.value })}
                    placeholder="CV-12345"
                    className="w-full border border-gray-200 rounded-lg px-4 py-2.5 text-[14px] font-medium focus:outline-none focus:ring-2 focus:ring-blue-900"
                  />
                </div>
                <div>
                  <label className="text-[11px] font-bold text-gray-500 uppercase block mb-1">Ano</label>
                  <input
                    type="number"
                    value={form.ano}
                    onChange={(e) => setForm({ ...form, ano: e.target.value })}
                    placeholder="2023"
                    className="w-full border border-gray-200 rounded-lg px-4 py-2.5 text-[14px] focus:outline-none focus:ring-2 focus:ring-blue-900"
                  />
                </div>
                <div>
                  <label className="text-[11px] font-bold text-gray-500 uppercase block mb-1">Cor</label>
                  <input
                    type="text"
                    value={form.cor}
                    onChange={(e) => setForm({ ...form, cor: e.target.value })}
                    placeholder="Preto"
                    className="w-full border border-gray-200 rounded-lg px-4 py-2.5 text-[14px] focus:outline-none focus:ring-2 focus:ring-blue-900"
                  />
                </div>
              </div>

              <div>
                <label className="text-[11px] font-bold text-gray-500 uppercase block mb-1">
                  Quilometragem (km)
                </label>
                <input
                  type="number"
                  value={form.quilometragem}
                  onChange={(e) => setForm({ ...form, quilometragem: e.target.value })}
                  placeholder="25000"
                  className="w-full border border-gray-200 rounded-lg px-4 py-2.5 text-[14px] focus:outline-none focus:ring-2 focus:ring-blue-900"
                />
              </div>

              <div className="border-t border-gray-100 pt-4">
                <label className="text-[11px] font-bold text-gray-500 uppercase block mb-2">
                  Documentos
                </label>

                {unidadeEditando ? (
                  <>
                    {(unidadeEditando.documentos || []).length > 0 ? (
                      <div className="space-y-2 mb-3">
                        {unidadeEditando.documentos.map(doc => (
                          <div
                            key={doc.id}
                            className="flex items-center justify-between bg-gray-50 border border-gray-100 rounded-lg px-3 py-2"
                          >
                            <div className="flex items-center gap-2 min-w-0">
                              <FileText size={16} className="text-blue-600 flex-shrink-0" />
                              <div className="min-w-0">
                                <p className="text-[12px] font-bold truncate">{doc.nome}</p>
                                <p className="text-[10px] text-gray-500 capitalize">
                                  {doc.tipo}
                                  {doc.enviado_em && ` · ${new Date(doc.enviado_em).toLocaleDateString('pt-PT')}`}
                                </p>
                              </div>
                            </div>
                            <div className="flex items-center gap-1 flex-shrink-0">
                              <a
                                href={doc.url}
                                target="_blank"
                                rel="noreferrer"
                                className="p-1.5 rounded hover:bg-blue-100 text-blue-600"
                                title="Ver"
                              >
                                <Eye size={14} />
                              </a>
                              <button
                                type="button"
                                onClick={() => removerDocumento(doc.id)}
                                className="p-1.5 rounded hover:bg-red-100 text-red-600"
                                title="Remover"
                              >
                                <Trash2 size={14} />
                              </button>
                            </div>
                          </div>
                        ))}
                      </div>
                    ) : (
                      <p className="text-[12px] text-gray-400 mb-3">Sem documentos anexados</p>
                    )}

                    <div className="flex flex-col sm:flex-row gap-2 items-stretch">
                      <select
                        value={tipoDoc}
                        onChange={(e) => setTipoDoc(e.target.value)}
                        className="border border-gray-200 rounded-lg px-3 py-2 text-[12px] font-medium focus:outline-none focus:ring-2 focus:ring-blue-900 bg-white"
                      >
                        <option value="seguro">Seguro</option>
                        <option value="inspecao">Inspeção</option>
                        <option value="licenca">Licença</option>
                        <option value="fatura">Fatura</option>
                        <option value="outro">Outro</option>
                      </select>

                      <input
                        id="input-ficheiro-unidade"
                        type="file"
                        accept=".pdf,.jpg,.jpeg,.png,.webp"
                        onChange={(e) => setFicheiro(e.target.files[0] || null)}
                        className="flex-1 border border-gray-200 rounded-lg px-3 py-2 text-[12px] file:mr-3 file:py-1 file:px-3 file:rounded file:border-0 file:bg-blue-900 file:text-white file:text-[11px] file:font-bold file:cursor-pointer"
                      />

                      <button
                        type="button"
                        onClick={enviarDocumento}
                        disabled={!ficheiro || uploadando}
                        className="flex items-center justify-center gap-1 bg-blue-900 hover:bg-blue-800 text-white px-4 py-2 rounded-lg text-[12px] font-bold disabled:opacity-50 disabled:cursor-not-allowed"
                      >
                        {uploadando ? (
                          <Loader2 size={14} className="animate-spin" />
                        ) : (
                          <Upload size={14} />
                        )}
                        {uploadando ? 'A enviar...' : 'Enviar'}
                      </button>
                    </div>
                    <p className="text-[11px] text-gray-400 mt-2">
                      Aceita PDF, JPG, PNG ou WEBP (máx 8 MB).
                    </p>
                  </>
                ) : (
                  <div className="bg-blue-50 border border-blue-100 rounded-lg px-4 py-3">
                    <p className="text-[12px] text-blue-700">
                      Guarda a unidade primeiro para poderes anexar documentos.
                    </p>
                  </div>
                )}
              </div>
            </div>

            <div className="flex items-center justify-end gap-2 p-5 border-t border-gray-100 sticky bottom-0 bg-white rounded-b-2xl">
              <button
                onClick={() => setModalForm(false)}
                className="px-4 py-2 rounded-lg text-[13px] font-bold text-gray-600 hover:bg-gray-100"
              >
                Fechar
              </button>
              <button
                onClick={guardarUnidade}
                className="flex items-center gap-2 bg-blue-900 hover:bg-blue-800 text-white px-5 py-2 rounded-lg text-[13px] font-bold transition-colors"
              >
                <Save size={16} /> {unidadeEditando ? 'Guardar alterações' : 'Guardar'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* ============ MODAL: Motivo ============ */}
      {modalMotivo && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[9999] p-4">
          <div className="bg-white rounded-2xl shadow-xl w-full max-w-md">
            <div className="flex items-center justify-between p-5 border-b border-gray-100">
              <h3 className="text-[16px] font-bold flex items-center gap-2">
                {modalMotivo.estado === 'manutencao' ? (
                  <><Wrench size={18} className="text-orange-600" /> Marcar em Manutenção</>
                ) : (
                  <><Lock size={18} className="text-gray-600" /> Marcar Indisponível</>
                )}
              </h3>
              <button onClick={() => setModalMotivo(null)} className="p-2 hover:bg-gray-100 rounded-lg">
                <X size={18} />
              </button>
            </div>

            <div className="p-5">
              <p className="text-[12px] text-gray-500 mb-4">
                Unidade <span className="font-bold text-gray-700">{modalMotivo.unidade.matricula}</span> vai
                ficar <span className="font-bold">bloqueada</span> e não poderá ser atribuída a novas reservas.
              </p>

              <label className="text-[11px] font-bold text-gray-500 uppercase block mb-1">
                Motivo *
              </label>
              <textarea
                value={motivoTexto}
                onChange={(e) => setMotivoTexto(e.target.value)}
                rows={3}
                placeholder={
                  modalMotivo.estado === 'manutencao'
                    ? 'Ex: Troca de óleo, revisão dos travões, pneus novos...'
                    : 'Ex: Viatura reservada para uso interno, sinistro, etc.'
                }
                className="w-full border border-gray-200 rounded-lg px-4 py-2.5 text-[13px] focus:outline-none focus:ring-2 focus:ring-blue-900"
              />
              <p className="text-[11px] text-gray-400 mt-1">
                O motivo só é visível para ti e para o administrador.
              </p>
            </div>

            <div className="flex items-center justify-end gap-2 p-5 border-t border-gray-100">
              <button
                onClick={() => setModalMotivo(null)}
                className="px-4 py-2 rounded-lg text-[13px] font-bold text-gray-600 hover:bg-gray-100"
              >
                Cancelar
              </button>
              <button
                onClick={() => executarMudancaEstado(modalMotivo.unidade, modalMotivo.estado, motivoTexto)}
                disabled={!motivoTexto.trim()}
                className="flex items-center gap-2 bg-blue-900 hover:bg-blue-800 text-white px-5 py-2 rounded-lg text-[13px] font-bold disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {modalMotivo.estado === 'manutencao' ? <Wrench size={16} /> : <Lock size={16} />}
                Confirmar
              </button>
            </div>
          </div>
        </div>
      )}

      {/* ============ MODAL: Histórico ============ */}
      {modalHistorico && (
        <div className="fixed inset-0 bg-black/40 flex items-center justify-center z-[9999] p-4">
          <div className="bg-white rounded-2xl shadow-xl w-full max-w-3xl max-h-[90vh] overflow-y-auto">
            <div className="flex items-center justify-between p-5 border-b border-gray-100">
              <h3 className="text-[16px] font-bold">
                Histórico — {historico?.unidade?.matricula || '...'}
              </h3>
              <button onClick={() => setModalHistorico(false)} className="p-2 hover:bg-gray-100 rounded-lg">
                <X size={18} />
              </button>
            </div>

            <div className="p-5">
              {loadingHistorico ? (
                <div className="text-center py-8">
                  <Loader2 size={28} className="animate-spin text-blue-900 mx-auto" />
                </div>
              ) : !historico || !historico.reservas || historico.reservas.length === 0 ? (
                <div className="text-center py-8">
                  <History size={32} className="text-gray-300 mx-auto mb-2" />
                  <p className="text-gray-500 text-[13px]">Sem reservas registadas para esta unidade</p>
                </div>
              ) : (
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead>
                      <tr className="bg-gray-50/50 border-b border-gray-100">
                        <th className="px-4 py-3 text-[11px] font-bold text-gray-500 uppercase">Reserva</th>
                        <th className="px-4 py-3 text-[11px] font-bold text-gray-500 uppercase">Levantamento</th>
                        <th className="px-4 py-3 text-[11px] font-bold text-gray-500 uppercase">Devolução</th>
                        <th className="px-4 py-3 text-[11px] font-bold text-gray-500 uppercase">Total</th>
                        <th className="px-4 py-3 text-[11px] font-bold text-gray-500 uppercase">Estado</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-50">
                      {historico.reservas.map(r => (
                        <tr key={r.id}>
                          <td className="px-4 py-3 text-[12px] font-bold text-[#2563eb]">
                            {r.codigo_reserva}
                          </td>
                          <td className="px-4 py-3 text-[12px]">{r.data_levantamento}</td>
                          <td className="px-4 py-3 text-[12px]">{r.data_devolucao}</td>
                          <td className="px-4 py-3 text-[12px] font-bold">
                            {parseFloat(r.preco_total).toLocaleString()} CVE
                          </td>
                          <td className="px-4 py-3">
                            <span className={`px-2 py-1 rounded-md text-[10px] font-bold ${
                              r.status === 'confirmada' ? 'bg-green-100 text-green-700' :
                              r.status === 'cancelada'  ? 'bg-red-100 text-red-700' :
                              'bg-orange-100 text-orange-700'
                            }`}>
                              {r.status}
                            </span>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Toast */}
      {toast.show && (
        <div className={`fixed bottom-6 right-6 px-5 py-3 rounded-xl shadow-lg text-white text-[13px] font-bold flex items-center gap-2 z-[10000] ${
          toast.tipo === 'ok' ? 'bg-green-600' : 'bg-red-600'
        }`}>
          {toast.tipo === 'ok' ? <CheckCircle size={16} /> : <AlertCircle size={16} />}
          {toast.msg}
        </div>
      )}
    </div>
  );
}

// src/features/alojamento/components/Alojamentos.jsx
import React, {
  useState, useEffect, useMemo, useCallback, useDeferredValue, memo,
} from 'react';
import axios from 'axios';
import { Helmet } from 'react-helmet-async';
import { Loader2, LayoutGrid, List, Info, ArrowRight, ChevronDown, X } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { useLocation, useNavigate } from 'react-router-dom';

import CardAlojamento from './CardAlojamento';
import FiltrosLateralAlojamento from './FiltrosLateralAlojamento';
import SearchBar from './SearchBarAlojamento';
import AlojamentoHero from './AlojamentoHero';

// ============================================================
// Constantes
// ============================================================
const ORCAMENTO_MAX_DEFAULT = 100000;
const ORCAMENTO_MIN_DEFAULT = 1000;

// ============================================================
// Helpers
// ============================================================
const normalizarTexto = (s) =>
  String(s || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim();

const calcularNoites = (entrada, saida) => {
  if (!entrada || !saida) return 0;
  const d1 = new Date(entrada);
  const d2 = new Date(saida);
  if (isNaN(d1) || isNaN(d2)) return 0;
  return Math.max(0, Math.round((d2 - d1) / 86400000));
};

// ============================================================
// Componentes memoizados
// ============================================================
const Breadcrumbs = memo(({ navigate, t, filtroDestino }) => (
  <div className="text-left text-[10px] font-black uppercase tracking-widest text-gray-400 mb-8 flex gap-2">
    <span className="text-blue-600 cursor-pointer" onClick={() => navigate('/')}>
      {t('inicio', 'Início')}
    </span>
    {' / '}
    <span>{t('alojamentos', 'Alojamentos')}</span>
    {filtroDestino && <> / <span className="text-gray-900">{filtroDestino}</span></>}
  </div>
));
Breadcrumbs.displayName = 'Breadcrumbs';

const AvisoPreco = memo(({ t }) => (
  <div className="bg-blue-50 border border-blue-100 text-blue-800 p-4 rounded-xl mb-8 flex items-center gap-3 text-sm font-medium text-left">
    <Info size={18} className="text-blue-600 shrink-0" />
    <span>{t('precos_finais_com_taxas', 'Preços em CVE. Taxas incluídas.')}</span>
  </div>
));
AvisoPreco.displayName = 'AvisoPreco';

const LoadingState = memo(({ t }) => (
  <div className="flex flex-col items-center justify-center py-32 text-center">
    <Loader2 size={40} className="animate-spin mb-4 text-blue-600 opacity-20" />
    <p className="font-black uppercase tracking-widest text-[10px] text-gray-400">
      {t('sincronizar_espacos', 'A sincronizar espaços...')}
    </p>
  </div>
));
LoadingState.displayName = 'LoadingState';

const EmptyState = memo(({ t, onLimpar, filtroDestino }) => (
  <div className="col-span-full py-24 text-center bg-white rounded-[40px] border-2 border-dashed border-gray-100 flex flex-col items-center gap-4">
    <Info size={40} className="text-gray-300" />
    <p className="text-gray-400 font-bold uppercase text-xs">
      {t('nenhum_alojamento_encontrado', 'Nenhum alojamento encontrado')}
      {filtroDestino && (
        <>
          {' '}
          {t('em', 'em')} <span className="text-gray-700">{filtroDestino}</span>
        </>
      )}
    </p>
    <button
      onClick={onLimpar}
      className="text-blue-600 font-black text-[10px] underline uppercase"
    >
      {t('limpar_filtros', 'Limpar filtros')}
    </button>
  </div>
));
EmptyState.displayName = 'EmptyState';

const CTAFinal = memo(({ navigate, t }) => (
  <div className="mt-24">
    <div className="relative rounded-[2.5rem] overflow-hidden h-[300px] flex items-center shadow-xl text-left">
      <img
        src="https://images.unsplash.com/photo-1539635278303-d4002c07eae3?auto=format&fit=crop&q=80&w=1200"
        className="absolute inset-0 w-full h-full object-cover transform-gpu"
        loading="lazy"
        decoding="async"
        alt="Cabo Verde"
      />
      <div className="absolute inset-0 bg-gradient-to-r from-white/95 via-white/70 to-transparent" />
      <div className="relative z-10 p-8 md:p-12 max-w-lg">
        <h2 className="text-2xl md:text-3xl font-black text-gray-900 leading-tight mb-4 tracking-tighter uppercase italic">
          {t('viva_aventuras_inesqueciveis', 'Viva aventuras inesquecíveis')}
        </h2>
        <button
          onClick={() => navigate('/experiencias')}
          className="bg-blue-600 hover:bg-blue-700 text-white font-black px-8 py-4 rounded-2xl transition-all flex items-center gap-2"
        >
          {t('buscar_experiencias', 'Buscar experiências')} <ArrowRight size={20} />
        </button>
      </div>
    </div>
  </div>
));
CTAFinal.displayName = 'CTAFinal';

// ============================================================
// COMPONENTE PRINCIPAL
// ============================================================
const Alojamentos = () => {
  const { t } = useTranslation();
  const location = useLocation();
  const navigate = useNavigate();

  // ----------------------------------------------------------
  // URL como fonte de verdade
  // ----------------------------------------------------------
  const searchParams = useMemo(() => {
    const p = new URLSearchParams(location.search);
    return {
      destino:  p.get('destino')  || '',
      entrada:  p.get('entrada')  || '',
      saida:    p.get('saida')    || '',
      hospedes: parseInt(p.get('hospedes') || '1', 10) || 1,
      adultos:  parseInt(p.get('adultos')  || '2', 10) || 2,
      criancas: parseInt(p.get('criancas') || '0', 10) || 0,
      quartos:  parseInt(p.get('quartos')  || '1', 10) || 1,
      pet:      p.get('pet') === '1',
    };
  }, [location.search]);

  const filtroDestino = searchParams.destino;

  const noites = useMemo(
    () => calcularNoites(searchParams.entrada, searchParams.saida),
    [searchParams.entrada, searchParams.saida]
  );

  // ----------------------------------------------------------
  // Estados
  // ----------------------------------------------------------
  const [alojamentos, setAlojamentos] = useState([]);
  const [loading, setLoading] = useState(true);
  const [erro, setErro] = useState(null);

  const [viewMode, setViewMode] = useState('grid');
  const [ordenar, setOrdenar] = useState('recomendados');
  const [dropdownAberto, setDropdownAberto] = useState(false);

  // Filtros locais (client-side)
  const [orcamento, setOrcamento] = useState(ORCAMENTO_MAX_DEFAULT);
  const [tiposSelecionados, setTiposSelecionados] = useState([]);
  const [mapaAberto, setMapaAberto] = useState(false);

  const orcamentoDeferido = useDeferredValue(orcamento);
  const tiposDeferidos = useDeferredValue(tiposSelecionados);

  // ----------------------------------------------------------
  // Opções de ordenação
  // ----------------------------------------------------------
  const opcoesOrdenar = useMemo(
    () => [
      { value: 'recomendados', label: t('ordenar_recomendados', 'Recomendados') },
      { value: 'preco_asc',    label: t('ordenar_preco_asc',    'Preço mais baixo') },
      { value: 'preco_desc',   label: t('ordenar_preco_desc',   'Preço mais alto') },
      { value: 'avaliacao',    label: t('ordenar_avaliacao',    'Melhor avaliação') },
    ],
    [t]
  );

  const labelOrdenarAtual = useMemo(
    () => opcoesOrdenar.find((o) => o.value === ordenar)?.label || 'Recomendados',
    [opcoesOrdenar, ordenar]
  );

  // ----------------------------------------------------------
  // Atualizar URL (fonte de verdade para pesquisa)
  // ----------------------------------------------------------
  const updateSearchParams = useCallback(
    (patch) => {
      const params = new URLSearchParams(location.search);

      Object.entries(patch).forEach(([k, v]) => {
        if (v === null || v === undefined || v === '' || v === false) {
          params.delete(k);
        } else {
          params.set(k, String(v));
        }
      });

      // Recalcula "hospedes" = adultos + criancas
      const adultos  = parseInt(params.get('adultos')  || '0', 10) || 0;
      const criancas = parseInt(params.get('criancas') || '0', 10) || 0;
      if (adultos + criancas > 0) {
        params.set('hospedes', String(adultos + criancas));
      }

      navigate({ search: params.toString() }, { replace: true });
    },
    [location.search, navigate]
  );

  // ----------------------------------------------------------
  // FETCH
  // ----------------------------------------------------------
  useEffect(() => {
    const controller = new AbortController();

    const fetchDados = async () => {
      try {
        setLoading(true);
        setErro(null);

        const apiParams = {
          destino:  searchParams.destino,
          entrada:  searchParams.entrada,
          saida:    searchParams.saida,
          hospedes: searchParams.hospedes,
          quartos:  searchParams.quartos,
          pet:      searchParams.pet ? 1 : 0,
        };

        console.log('📡 GET get_alojamentos.php', apiParams);

        const response = await axios.get(
          'https://welovepalop.com/api/get_alojamentos.php',
          { params: apiParams, signal: controller.signal }
        );

        const lista = Array.isArray(response.data) ? response.data : [];

        console.log(`📦 API devolveu ${lista.length} alojamentos`);

        setAlojamentos(lista);
      } catch (error) {
        if (error.name !== 'CanceledError' && error.name !== 'AbortError') {
          console.error('❌ Erro na API Morabeza:', error);
          setErro(error.message || 'Erro ao carregar alojamentos');
          setAlojamentos([]);
        }
      } finally {
        setLoading(false);
      }
    };

    fetchDados();
    return () => controller.abort();
  }, [
    searchParams.destino,
    searchParams.entrada,
    searchParams.saida,
    searchParams.hospedes,
    searchParams.quartos,
    searchParams.pet,
  ]);

  // Fechar dropdown
  useEffect(() => {
    const fechar = (e) => {
      if (!e.target.closest('[data-dropdown-ordernar]')) {
        setDropdownAberto(false);
      }
    };
    document.addEventListener('mousedown', fechar);
    return () => document.removeEventListener('mousedown', fechar);
  }, []);

  // ============================================================
  // FILTRAGEM LOCAL
  // ============================================================
  const alojamentosFiltrados = useMemo(() => {
    const destinoNorm = normalizarTexto(filtroDestino);
    const isGeral =
      !destinoNorm ||
      destinoNorm === 'cabo verde' ||
      destinoNorm === 'todas';

    const tiposSetLower = new Set(
      [...tiposDeferidos].map((t) => String(t).toLowerCase().trim())
    );

    // Total de pessoas = adultos + crianças (fallback: hospedes)
    const totalPessoas = Math.max(
      searchParams.hospedes || 1,
      (searchParams.adultos || 0) + (searchParams.criancas || 0)
    );

    return alojamentos.filter((casa) => {
      // 1) Orçamento
      const preco = Number(casa.preco_mostrar ?? casa.preco_noite ?? 0);
      if (preco > orcamentoDeferido) return false;

      // 2) Tipo de propriedade
      if (tiposSetLower.size > 0) {
        const tipoCasa = String(casa.tipo_propriedade || '').toLowerCase().trim();
        if (!tiposSetLower.has(tipoCasa)) return false;
      }

      // 3) Capacidade (usa capacidade_efetiva do backend)
      const capacidade = Number(casa.capacidade_efetiva ?? casa.capacidade ?? 0);
      if (capacidade < totalPessoas) return false;

      // 4) Destino — procura em ilha, localizacao, cidade, titulo
      if (!isGeral) {
        const campos = [
          casa.ilha,
          casa.localizacao,
          casa.cidade,
          casa.titulo,
        ].map(normalizarTexto);

        if (!campos.some((c) => c.includes(destinoNorm))) return false;
      }

      // 5) Pet-friendly (usa flag do backend)
      if (searchParams.pet && !casa.pet_friendly) return false;

      return true;
    });
  }, [
    alojamentos,
    orcamentoDeferido,
    tiposDeferidos,
    filtroDestino,
    searchParams.hospedes,
    searchParams.adultos,
    searchParams.criancas,
    searchParams.pet,
  ]);

  // ----------------------------------------------------------
  // Ordenação
  // ----------------------------------------------------------
  const alojamentosOrdenados = useMemo(() => {
    if (ordenar === 'recomendados') return alojamentosFiltrados;

    const copia = [...alojamentosFiltrados];
    const precoDe = (c) => Number(c.preco_mostrar ?? c.preco_noite ?? 0);

    if (ordenar === 'preco_asc') copia.sort((a, b) => precoDe(a) - precoDe(b));
    else if (ordenar === 'preco_desc') copia.sort((a, b) => precoDe(b) - precoDe(a));
    else if (ordenar === 'avaliacao')
      copia.sort((a, b) => Number(b.estrelas || 0) - Number(a.estrelas || 0));

    return copia;
  }, [alojamentosFiltrados, ordenar]);

  // ----------------------------------------------------------
  // Callbacks
  // ----------------------------------------------------------
  const limparFiltros = useCallback(() => {
    setOrcamento(ORCAMENTO_MAX_DEFAULT);
    setTiposSelecionados([]);
    setOrdenar('recomendados');
    navigate('/alojamentos', { replace: true });
  }, [navigate]);

  const toggleDropdown = useCallback(() => setDropdownAberto((v) => !v), []);
  const abrirMapa = useCallback(() => setMapaAberto(true), []);
  const setGridMode = useCallback(() => setViewMode('grid'), []);
  const setListMode = useCallback(() => setViewMode('list'), []);
  const irParaExperiencias = useCallback(() => navigate('/experiencias'), [navigate]);
  const irParaInicio = useCallback(() => navigate('/'), [navigate]);

  const selecionarOrdem = useCallback((value) => {
    setOrdenar(value);
    setDropdownAberto(false);
  }, []);

  const gridClassName = useMemo(
    () =>
      viewMode === 'grid'
        ? 'grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6 md:gap-8 text-left'
        : 'flex flex-col gap-6 text-left',
    [viewMode]
  );

  const isListMode = viewMode === 'list';

  // ============================================================
  // RENDER
  // ============================================================
  return (
    <div className="bg-[#f8f9fc] min-h-screen">
      <Helmet>
        <title>
          MorabezaStay | {t('alojamentos', 'Alojamentos')}
          {filtroDestino && ` ${t('em', 'em')} ${filtroDestino}`}
        </title>
      </Helmet>

      <AlojamentoHero />

      <div className="relative -mt-12 z-40 px-4 flex justify-center">
        <div className="w-full max-w-6xl">
          <SearchBar />
        </div>
      </div>

      <main className="max-w-[1400px] mx-auto py-12 md:py-16 px-4 md:px-6">
        <Breadcrumbs navigate={irParaInicio} t={t} filtroDestino={filtroDestino} />

        {/* Chips da pesquisa activa */}
        {(searchParams.hospedes > 1 ||
          searchParams.entrada ||
          searchParams.saida ||
          searchParams.pet ||
          searchParams.criancas > 0) && (
          <div className="mb-6 text-left text-xs text-gray-500 font-semibold flex flex-wrap gap-2">
            {searchParams.entrada && searchParams.saida && (
              <span className="inline-flex items-center gap-1 bg-white border border-gray-100 rounded-full px-3 py-1">
                📅 {searchParams.entrada} → {searchParams.saida}
                {noites > 0 && (
                  <span className="ml-1 text-blue-600 font-black">
                    ({noites} {noites === 1 ? 'noite' : 'noites'})
                  </span>
                )}
              </span>
            )}
            <span className="inline-flex items-center gap-1 bg-white border border-gray-100 rounded-full px-3 py-1">
              👥 {searchParams.hospedes}{' '}
              {searchParams.hospedes === 1 ? 'hóspede' : 'hóspedes'}
              {searchParams.criancas > 0 && (
                <span className="text-gray-400">
                  ({searchParams.adultos}A + {searchParams.criancas}C)
                </span>
              )}
            </span>
            {searchParams.quartos > 1 && (
              <span className="inline-flex items-center gap-1 bg-white border border-gray-100 rounded-full px-3 py-1">
                🛏️ {searchParams.quartos} quartos
              </span>
            )}
            {searchParams.pet && (
              <span className="inline-flex items-center gap-1 bg-blue-50 border border-blue-100 text-blue-700 rounded-full px-3 py-1">
                🐾 Com animal
              </span>
            )}
          </div>
        )}

        <div className="flex flex-col lg:grid lg:grid-cols-12 gap-8 lg:gap-12 items-start">
          {/* FILTROS LATERAIS */}
          <aside className="w-full lg:col-span-3 lg:sticky lg:top-28 z-10">
            <FiltrosLateralAlojamento
              orcamento={orcamento}
              setOrcamento={setOrcamento}
              orcamentoMaximo={ORCAMENTO_MAX_DEFAULT}
              orcamentoMinimo={ORCAMENTO_MIN_DEFAULT}
              tiposSelecionados={tiposSelecionados}
              setTiposSelecionados={setTiposSelecionados}
              totalEncontrados={alojamentosFiltrados.length}
              onAbrirMapa={abrirMapa}
              searchParams={searchParams}
              onUpdateSearchParams={updateSearchParams}
            />
          </aside>

          {/* LISTA */}
          <div className="w-full lg:col-span-9">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-8">
              <h1 className="text-xl md:text-3xl font-black text-[#1a2b6d] leading-tight italic uppercase tracking-tighter text-left">
                {filtroDestino || t('explorar', 'Explorar')}:{' '}
                <span className="text-blue-600 text-3xl md:text-4xl">
                  {alojamentosOrdenados.length}
                </span>{' '}
                {t('opcoes', 'opções')}
              </h1>

              <div className="flex items-center gap-2 bg-white p-1.5 rounded-full shadow-sm border border-gray-100 self-stretch md:self-auto">
                <div className="relative" data-dropdown-ordernar>
                  <button
                    type="button"
                    onClick={toggleDropdown}
                    className="flex items-center gap-2 bg-blue-600 text-white px-4 md:px-5 py-2.5 rounded-full text-[10px] font-black uppercase tracking-widest hover:bg-blue-700 transition-colors"
                  >
                    <span className="whitespace-nowrap">
                      {t('ordenar_por', 'Ordenar por')}: {labelOrdenarAtual}
                    </span>
                    <ChevronDown
                      size={14}
                      className={`transition-transform duration-150 ${
                        dropdownAberto ? 'rotate-180' : ''
                      }`}
                    />
                  </button>

                  {dropdownAberto && (
                    <div className="absolute right-0 mt-2 w-56 bg-white rounded-2xl shadow-2xl border border-gray-100 overflow-hidden z-50">
                      {opcoesOrdenar.map((opcao) => (
                        <button
                          key={opcao.value}
                          onClick={() => selecionarOrdem(opcao.value)}
                          className={`w-full text-left px-4 py-3 text-xs font-bold uppercase tracking-wider transition-colors ${
                            ordenar === opcao.value
                              ? 'bg-blue-50 text-blue-700'
                              : 'text-gray-600 hover:bg-gray-50'
                          }`}
                        >
                          {opcao.label}
                          {ordenar === opcao.value && (
                            <span className="float-right text-blue-600">✓</span>
                          )}
                        </button>
                      ))}
                    </div>
                  )}
                </div>

                <div className="w-px h-6 bg-gray-100 mx-1" />

                <button
                  type="button"
                  onClick={setGridMode}
                  aria-label="Vista em grelha"
                  className={`p-3 rounded-full transition-colors ${
                    viewMode === 'grid'
                      ? 'text-blue-600 bg-blue-50'
                      : 'text-gray-400 hover:bg-gray-50'
                  }`}
                >
                  <LayoutGrid size={18} />
                </button>
                <button
                  type="button"
                  onClick={setListMode}
                  aria-label="Vista em lista"
                  className={`p-3 rounded-full transition-colors ${
                    viewMode === 'list'
                      ? 'text-blue-600 bg-blue-50'
                      : 'text-gray-400 hover:bg-gray-50'
                  }`}
                >
                  <List size={18} />
                </button>
              </div>
            </div>

            <AvisoPreco t={t} />

            {erro && !loading && (
              <div className="mb-6 bg-red-50 border border-red-100 text-red-800 p-4 rounded-xl flex items-start gap-3 text-sm text-left">
                <X size={18} className="text-red-600 shrink-0 mt-0.5" />
                <div>
                  <p className="font-bold">{t('erro_carregar', 'Erro ao carregar')}</p>
                  <p className="text-xs mt-1 opacity-80">{erro}</p>
                  <button
                    onClick={() => window.location.reload()}
                    className="mt-2 text-[10px] font-black uppercase underline"
                  >
                    {t('tentar_novamente', 'Tentar novamente')}
                  </button>
                </div>
              </div>
            )}

            {loading ? (
              <LoadingState t={t} />
            ) : (
              <div className={gridClassName}>
                {alojamentosOrdenados.length > 0 ? (
                  alojamentosOrdenados.map((casa) => (
                    <CardAlojamento key={casa.id} {...casa} isList={isListMode} />
                  ))
                ) : (
                  <EmptyState
                    t={t}
                    onLimpar={limparFiltros}
                    filtroDestino={filtroDestino}
                  />
                )}
              </div>
            )}
          </div>
        </div>

        <CTAFinal navigate={irParaExperiencias} t={t} />
      </main>
    </div>
  );
};

export default Alojamentos;

// AvaliacoesSeccaoAlojamento.jsx
import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { Star, User, Calendar, ThumbsUp, Flag, X, Loader2, CheckCircle } from 'lucide-react';

const AvaliacoesSeccaoAlojamento = ({ alojamentoId, usuarioLogado, onOpenLoginModal, isEmbedded = false }) => {
  const { t } = useTranslation();
  const [avaliacoes, setAvaliacoes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [mediaRating, setMediaRating] = useState(0);
  const [totalReviews, setTotalReviews] = useState(0);
  const [showForm, setShowForm] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [formSuccess, setFormSuccess] = useState(false);
  
  const [formData, setFormData] = useState({
    rating: 5,
    comentario: '',
    data_estadia: ''
  });

  const fetchAvaliacoes = async () => {
    setLoading(true);
    try {
      const response = await fetch(`https://welovepalop.com/api/get_alojamento_avaliacoes.php?id=${alojamentoId}`);
      const data = await response.json();
      
      if (data.success) {
        setAvaliacoes(data.avaliacoes || []);
        setMediaRating(Number(data.media_rating) || 0);
        setTotalReviews(Number(data.total_reviews) || 0);
      } else {
        setError(data.message || t('erro_carregar_avaliacoes'));
      }
    } catch (err) {
      console.error('Erro ao buscar avaliações:', err);
      setError(t('erro_carregar_avaliacoes'));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (alojamentoId) {
      fetchAvaliacoes();
    }
  }, [alojamentoId]);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleRatingClick = (rating) => {
    setFormData(prev => ({ ...prev, rating }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (!usuarioLogado) {
      if (onOpenLoginModal) {
        onOpenLoginModal();
      } else {
        alert(t('login_para_avaliar'));
      }
      return;
    }

    if (!formData.comentario.trim()) {
      alert(t('escreva_comentario'));
      return;
    }

    if (!formData.data_estadia) {
      alert(t('informe_data_estadia'));
      return;
    }

    setSubmitting(true);
    
    try {
      const response = await fetch('https://welovepalop.com/api/save_alojamento_avaliacao.php', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          alojamento_id: alojamentoId,
          usuario_id: usuarioLogado.id,
          nome_usuario: usuarioLogado.name || usuarioLogado.full_name || usuarioLogado.nome,
          foto: usuarioLogado.foto || usuarioLogado.picture,
          email_usuario: usuarioLogado.email,
          rating: formData.rating,
          comentario: formData.comentario,
          data_estadia: formData.data_estadia
        })
      });
      
      const result = await response.json();
      
      if (result.success) {
        setFormSuccess(true);
        setFormData({ rating: 5, comentario: '', data_estadia: '' });
        setShowForm(false);
        fetchAvaliacoes();
        setTimeout(() => setFormSuccess(false), 3000);
      } else {
        alert(result.message || t('erro_enviar_avaliacao'));
      }
    } catch (err) {
      console.error('Erro ao enviar avaliação:', err);
      alert(t('erro_enviar_avaliacao'));
    } finally {
      setSubmitting(false);
    }
  };

  const formatarData = (data) => {
    if (!data) return '';
    const d = new Date(data);
    return d.toLocaleDateString('pt-PT', { day: '2-digit', month: 'short', year: 'numeric' });
  };

  const renderStars = (rating, size = 16) => {
    return (
      <div className="flex items-center gap-0.5">
        {[1, 2, 3, 4, 5].map((star) => (
          <Star
            key={star}
            size={size}
            className={`${star <= rating ? 'fill-orange-400 text-orange-400' : 'fill-slate-200 text-slate-200'}`}
          />
        ))}
      </div>
    );
  };

  if (loading) {
    return (
      <div className="flex justify-center items-center py-12">
        <Loader2 size={32} className="animate-spin text-[#003580]" />
      </div>
    );
  }

  if (error) {
    return (
      <div className="text-center py-8">
        <p className="text-red-500 text-sm">{error}</p>
        <button onClick={fetchAvaliacoes} className="mt-2 text-[#003580] text-sm underline">
          {t('tentar_novamente')}
        </button>
      </div>
    );
  }

  const primeiroNomeDisplay = avaliacoes[0] ? (avaliacoes[0].nome_usuario || avaliacoes[0].nome || avaliacoes[0].autor || t('anonimo')) : t('anonimo');
  const primeiroComentario = avaliacoes[0] ? (avaliacoes[0].comentario || avaliacoes[0].texto || '') : '';
  const primeiroRating = avaliacoes[0] ? (Number(avaliacoes[0].rating) || 5) : 5;

  // Categorias de avaliação traduzidas
  const categoriasAvaliacao = [
    { label: t('limpeza'), val: 4.9 },
    { label: t('conforto'), val: 4.7 },
    { label: t('consumo'), val: 4.8 },
    { label: t('atendimento'), val: 4.8 },
    { label: t('levantamento'), val: 4.9 },
    { label: t('custo_beneficio'), val: 4.7 }
  ];

  return (
    <div className={isEmbedded ? '' : 'bg-white rounded-2xl'}>
      {/* 1. TOPO DA SECÇÃO */}
      <div className="flex justify-between items-center mb-6">
        <div>
          <h2 className="text-xl font-bold text-slate-900">{t('avaliacoes_hospedes')}</h2>
          <p className="text-xs text-slate-400 font-medium mt-0.5">
            {t('baseado_em')} {totalReviews} {totalReviews === 1 ? t('avaliacao') : t('avaliacoes')}
          </p>
        </div>
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-2">
            <span className="text-2xl font-black text-slate-900">{mediaRating.toFixed(1)}</span>
            <div className="flex flex-col justify-center">
              {renderStars(Math.round(mediaRating), 14)}
            </div>
          </div>
          <button
            onClick={() => {
              if (!usuarioLogado && onOpenLoginModal) {
                onOpenLoginModal();
              } else {
                setShowForm(!showForm);
              }
            }}
            className="px-4 py-2 bg-[#003580] text-white text-xs font-bold rounded-lg hover:bg-blue-900 transition-all shadow-sm"
          >
            {showForm ? t('cancelar') : t('avaliar_estadia')}
          </button>
        </div>
      </div>

      {/* 2. LINHA DE SUBTÍTULO */}
      <div className="flex justify-between items-center mb-4 px-1">
        <span className="text-sm font-bold text-slate-800">
          {t('avaliacoes_participantes')} <span className="text-slate-400 font-normal text-xs">({totalReviews} {t('avaliacoes')})</span>
        </span>
        <div className="flex items-center gap-1 text-sm font-bold text-slate-800">
          <span className="text-orange-500 text-base">★</span> {mediaRating.toFixed(1)}
        </div>
      </div>

      {/* 3. PAINEL DE NOTAS PROFISSIONAL */}
      <div className="border border-slate-200 rounded-3xl p-8 bg-white shadow-sm grid grid-cols-1 lg:grid-cols-12 gap-8 items-center mb-8">
        
        <div className="lg:col-span-3 text-center lg:text-left flex flex-col justify-center border-b lg:border-b-0 lg:border-r border-slate-100 pb-6 lg:pb-0 lg:pr-6">
          <h4 className="text-sm font-bold text-slate-900 mb-4">{t('avaliacoes_clientes')}</h4>
          <div className="text-6xl font-black text-[#1a2b6d] tracking-tighter mb-2">{mediaRating.toFixed(1)}</div>
          <div className="flex justify-center lg:justify-start mb-1">
            {renderStars(Math.round(mediaRating), 16)}
          </div>
          <p className="text-[10px] font-semibold text-slate-400 mt-1">
            {t('baseado_em')} {totalReviews} {totalReviews === 1 ? t('avaliacao') : t('avaliacoes')}
          </p>
        </div>

        <div className="lg:col-span-5 space-y-3.5 px-2">
          {categoriasAvaliacao.map((cat, i) => (
            <div key={i} className="flex items-center justify-between text-xs font-semibold text-slate-600">
              <span className="w-24 text-slate-400 text-left font-medium">{cat.label}</span>
              <div className="flex-1 mx-4 bg-slate-100 h-1 rounded-full overflow-hidden">
                <div 
                  className="bg-blue-600 h-full rounded-full transition-all duration-500" 
                  style={{ width: `${(cat.val / 5) * 100}%` }}
                />
              </div>
              <span className="w-6 text-right text-slate-900 font-bold">{cat.val.toFixed(1)}</span>
            </div>
          ))}
        </div>

        <div className="lg:col-span-4 bg-white border border-slate-100 rounded-2xl p-5 shadow-sm flex flex-col justify-between h-full min-h-[190px]">
          {avaliacoes.length > 0 ? (
            <>
              <div className="flex items-center justify-between mb-4">
                <div className="flex items-center gap-3">
                  <img 
                    src={avaliacoes[0].foto || "https://images.unsplash.com/photo-1544551763-46a013bb70d5?w=100&h=100&fit=crop"} 
                    className="w-10 h-10 rounded-full object-cover border border-slate-100"
                    alt={primeiroNomeDisplay} 
                  />
                  <div>
                    <h5 className="text-xs font-bold text-slate-900">{primeiroNomeDisplay}</h5>
                    <p className="text-[10px] text-slate-400 font-medium">{t('maio_2026')}</p>
                  </div>
                </div>
                <div className="bg-emerald-50 text-emerald-600 text-xs font-bold px-2 py-1 rounded-lg">
                  {primeiroRating}/5
                </div>
              </div>
              <p className="text-xs text-slate-500 italic line-clamp-3 mb-4">
                "{primeiroComentario}"
              </p>
              <button 
                onClick={() => {
                  const el = document.getElementById('reviews-anchor-list');
                  if (el) el.scrollIntoView({ behavior: 'smooth' });
                }}
                className="text-blue-600 text-xs font-bold hover:underline flex items-center text-left"
              >
                {t('ver_todas_avaliacoes')} ({totalReviews})
              </button>
            </>
          ) : (
            <div className="text-center py-8 text-slate-400 text-xs my-auto">
              {t('nenhuma_avaliacao_disponivel')}
            </div>
          )}
        </div>
      </div>

      {/* Formulário de Avaliação */}
      {showForm && (
        <div className="mb-8 p-6 bg-slate-50 rounded-2xl border border-slate-200">
          <div className="flex justify-between items-center mb-4">
            <h4 className="font-bold text-slate-900">{t('como_foi_estadia')}</h4>
            <button onClick={() => setShowForm(false)} className="text-slate-400 hover:text-slate-600">
              <X size={20} />
            </button>
          </div>
          
          <form onSubmit={handleSubmit}>
            <div className="mb-5">
              <label className="block text-sm font-bold text-slate-700 mb-2">{t('sua_nota')}</label>
              <div className="flex gap-2">
                {[1, 2, 3, 4, 5].map((star) => (
                  <button
                    key={star}
                    type="button"
                    onClick={() => handleRatingClick(star)}
                    className="focus:outline-none transition-transform hover:scale-110"
                  >
                    <Star
                      size={32}
                      className={`${star <= formData.rating ? 'fill-orange-400 text-orange-400' : 'fill-slate-300 text-slate-300'} transition-colors`}
                    />
                  </button>
                ))}
              </div>
            </div>

            <div className="mb-5">
              <label className="block text-sm font-bold text-slate-700 mb-2">{t('data_estadia')}</label>
              <input
                type="date"
                name="data_estadia"
                value={formData.data_estadia}
                onChange={handleInputChange}
                max={new Date().toISOString().split('T')[0]}
                className="w-full max-w-xs border border-slate-300 rounded-xl px-4 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-[#003580]/20"
                required
              />
            </div>

            <div className="mb-5">
              <label className="block text-sm font-bold text-slate-700 mb-2">{t('seu_comentario')}</label>
              <textarea
                name="comentario"
                value={formData.comentario}
                onChange={handleInputChange}
                rows={4}
                placeholder={t('compartilhe_experiencia')}
                className="w-full border border-slate-300 rounded-xl px-4 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-[#003580]/20 resize-none"
                required
              />
            </div>

            <button
              type="submit"
              disabled={submitting}
              className="px-6 py-2.5 bg-[#003580] text-white font-bold rounded-xl hover:bg-blue-900 transition-all disabled:opacity-50"
            >
              {submitting ? <Loader2 size={18} className="animate-spin inline mr-2" /> : null}
              {submitting ? t('enviando') : t('enviar_avaliacao')}
            </button>
          </form>
        </div>
      )}

      {/* Mensagem de sucesso */}
      {formSuccess && (
        <div className="mb-6 p-4 bg-green-50 border border-green-200 rounded-xl flex items-center gap-3">
          <CheckCircle className="text-green-500" size={20} />
          <p className="text-green-700 text-sm">{t('avaliacao_enviada_sucesso')}</p>
        </div>
      )}

      {/* 4. LISTA DE COMENTÁRIOS */}
      <div id="reviews-anchor-list" className="space-y-6 mt-10">
        {avaliacoes.length === 0 ? (
          <div className="text-center py-12 bg-slate-50 rounded-2xl">
            <Star size={48} className="text-slate-300 mx-auto mb-3" />
            <p className="text-slate-500">{t('sem_avaliacoes_ainda')}</p>
          </div>
        ) : (
          avaliacoes.map((avaliacao, index) => {
            const nomeDisplay = avaliacao.nome_usuario || avaliacao.nome || avaliacao.autor || t('anonimo');
            const textoComentario = avaliacao.comentario || avaliacao.texto || '';
            const notaRating = Number(avaliacao.rating) || 5;

            return (
              <div key={avaliacao.id || index} className={`pb-6 ${index !== avaliacoes.length - 1 ? 'border-b border-slate-100' : ''}`}>
                <div className="flex items-start gap-4">
                  <div className="shrink-0 mt-0.5">
                    {avaliacao.foto ? (
                      <img src={avaliacao.foto} alt={nomeDisplay} className="w-9 h-9 rounded-full object-cover border border-slate-100" />
                    ) : (
                      <div className="w-9 h-9 bg-gradient-to-br from-[#003580] to-blue-600 rounded-full flex items-center justify-center">
                        <User size={16} className="text-white" />
                      </div>
                    )}
                  </div>
                  
                  <div className="flex-1">
                    <div className="flex items-center justify-between gap-4">
                      <div className="flex flex-col md:flex-row md:items-center gap-x-3 gap-y-0.5">
                        <h4 className="text-sm font-bold text-slate-900">{nomeDisplay}</h4>
                        <div className="flex items-center gap-1.5 text-[10px] text-slate-400 font-medium">
                          <Calendar size={11} className="text-slate-400" />
                          <span>{t('estadia')}: {formatarData(avaliacao.data_estadia)}</span>
                        </div>
                      </div>
                      <span className="text-[10px] text-slate-400 font-medium">{formatarData(avaliacao.created_at)}</span>
                    </div>

                    <div className="mt-1">
                      {renderStars(notaRating, 12)}
                    </div>

                    <p className="text-sm text-slate-600 mt-2 leading-relaxed font-normal">{textoComentario}</p>
                    
                    <div className="flex items-center gap-4 mt-3">
                      <button className="flex items-center gap-1 text-[10px] text-slate-400 hover:text-slate-600 font-semibold transition">
                        <ThumbsUp size={11} />
                        <span>{t('util')}</span>
                      </button>
                      <button className="flex items-center gap-1 text-[10px] text-slate-400 hover:text-slate-600 font-semibold transition">
                        <Flag size={11} />
                        <span>{t('reportar')}</span>
                      </button>
                    </div>
                  </div>
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
};

export default AvaliacoesSeccaoAlojamento;

// src/features/alojamento/components/CardAlojamento.jsx
import React, { memo } from 'react';
import { useTranslation } from 'react-i18next';
import { MapPin, Star, ArrowRight } from 'lucide-react';
import { Link, useLocation } from 'react-router-dom';
import BotaoFavorito from '../../../components/BotaoFavorito';

const BASE_URL_IMAGENS = "https://welovepalop.com/api/uploads/";
const PLACEHOLDER = "https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?q=80&w=400";

const CardAlojamento = ({
  id,
  slug,
  imagem_url,
  titulo,
  localizacao,
  descricao,
  preco_noite,
  preco_mostrar,
  preco_rotulo,
  tipo,
  tipo_propriedade,
  estrelas,
  comodidades,
  imagens_extra,
  total_avaliacoes,
  isList
}) => {
  const { t } = useTranslation();

  // 🔑 LER OS PARÂMETROS DA PESQUISA ATUAL
  const location = useLocation();
  const query = location.search || ''; // já vem com "?" no início

  const imagemCompleta = imagem_url
    ? (imagem_url.startsWith('http') ? imagem_url : `${BASE_URL_IMAGENS}${imagem_url}`)
    : PLACEHOLDER;

  // 🔑 CONCATENAR OS PARAMS DA PESQUISA AO LINK
  const baseLink = slug ? `/alojamentos/${slug}` : `/alojamentos/${id}`;
  const linkTo = `${baseLink}${query}`;

  const itemFavorito = {
    id,
    titulo,
    localizacao,
    imagem_url: imagemCompleta,
    preco_noite,
    estrelas,
    slug,
    tipo: 'alojamento'
  };

  // 🔑 Tipo a mostrar: prioriza tipo_propriedade sobre tipo (enum antigo)
  const tipoFinal =
    (typeof tipo_propriedade === 'string' && tipo_propriedade.trim()) ||
    (typeof tipo === 'string' && tipo.trim()) ||
    t('alojamento');

  // 🔑 Preço a mostrar: usa preco_mostrar (calculado pela API) com fallback em preco_noite
  const precoFinal = Number(preco_mostrar ?? preco_noite ?? 0);
  const precoFormatado = precoFinal.toLocaleString('pt-PT');
  const mostrarAPartirDe = preco_rotulo === 'a_partir_de';

  const estrelasFormatadas = Number(estrelas || 4.8).toFixed(1);

  return (
    <div
      className={`relative group bg-white border border-gray-100 overflow-hidden transition-shadow duration-200 hover:shadow-lg [content-visibility:auto] [contain-intrinsic-size:380px] ${
        isList
          ? "flex flex-col md:flex-row rounded-[40px] p-4 gap-6 w-full"
          : "flex flex-col h-full w-full rounded-2xl"
      }`}
    >
      <div
        className={`relative overflow-hidden shrink-0 bg-gray-100 ${
          isList
            ? "w-full md:w-[320px] lg:w-[360px] h-56 md:h-64 rounded-[32px]"
            : "aspect-[4/3] w-full rounded-t-2xl"
        }`}
      >
        <img
          src={imagemCompleta}
          alt={titulo}
          className="absolute inset-0 w-full h-full object-cover transform-gpu transition-transform duration-300 ease-out will-change-transform group-hover:scale-[1.03]"
          loading="lazy"
          decoding="async"
          fetchpriority="low"
        />

        <div className="absolute bottom-3 left-3 bg-blue-600 text-white text-[10px] font-black px-3 py-1.5 rounded-lg shadow-md z-10">
          {tipoFinal}
        </div>

        <BotaoFavorito
          tipo="alojamentos"
          item={itemFavorito}
          size={18}
          className="absolute top-3 right-3 z-10"
        />
      </div>

      <div className={`flex flex-col flex-1 text-left ${isList ? 'py-4 pr-4 justify-between' : 'p-4'}`}>

        <div>
          <div className="flex items-center gap-1.5 text-[#1a2b6d] mb-1.5">
            <MapPin size={14} className="text-blue-500" />
            <span className="text-[11px] font-bold opacity-80 tracking-tight truncate">
              {localizacao}
            </span>
          </div>

          <h3 className="text-lg font-bold text-[#1a2b6d] mb-3 leading-tight line-clamp-2 transition-colors duration-150 group-hover:text-blue-600">
            {titulo}
          </h3>

          {isList && (
            <p className="text-gray-400 text-sm font-medium mb-4 line-clamp-2 leading-relaxed">
              {descricao || t('descricao_padrao_alojamento', { tipo: tipoFinal, localizacao })}
            </p>
          )}

          {comodidades && comodidades.length > 0 && !isList && (
            <div className="flex flex-wrap gap-2 mb-3">
              {comodidades.slice(0, 3).map((comodidade, index) => (
                <span key={index} className="text-[9px] text-gray-500 bg-gray-50 px-2 py-1 rounded-full">
                  {comodidade.nome}
                </span>
              ))}
              {comodidades.length > 3 && (
                <span className="text-[9px] text-gray-500 bg-gray-50 px-2 py-1 rounded-full">
                  +{comodidades.length - 3}
                </span>
              )}
            </div>
          )}
        </div>

        <div className={`flex items-center justify-between ${!isList ? 'mt-auto border-t border-gray-50 pt-3' : ''}`}>

          <div className="flex flex-col gap-1">
            <div className="flex items-center gap-1 bg-amber-50 px-2 py-0.5 rounded-lg w-fit">
