  );
};

// ============================================================
// HELPER: string ISO -> Date local
// ============================================================
const fromISODate = (str) => {
  if (!str) return null;
  const [y, m, d] = String(str).split('-').map(Number);
  if (!y || !m || !d) return null;
  const date = new Date(y, m - 1, d);
  return isNaN(date.getTime()) ? null : date;
};

