  'Boa Vista': { lat: 16.1000, lng: -22.8000 },
  'Fogo': { lat: 14.9167, lng: -24.3333 },
  'Ilha do Fogo': { lat: 14.9167, lng: -24.3333 },
  'Santo Antão': { lat: 17.0667, lng: -25.1667 },
  'Maio': { lat: 15.1333, lng: -23.2167 },
  'São Nicolau': { lat: 16.6167, lng: -24.2667 },
