import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import Slider from 'rc-slider';
import 'rc-slider/assets/index.css';

const SidebarFiltros = ({ onFiltrar, onLimpar, filtrosAtuais }) => {
  const { t } = useTranslation();
  const [priceRange, setPriceRange] = useState([filtrosAtuais.precoMin, filtrosAtuais.precoMax]);
  const [categoriasSelecionadas, setCategoriasSelecionadas] = useState(filtrosAtuais.categorias);

  // Categorias reais da API
  const categorias = [
    t('aventura'), 
    t('cultural'), 
    t('gastronomia'), 
    t('natureza'), 
    t('relax')
  ];

  useEffect(() => {
    setPriceRange([filtrosAtuais.precoMin, filtrosAtuais.precoMax]);
    setCategoriasSelecionadas(filtrosAtuais.categorias);
  }, [filtrosAtuais]);

  const handlePriceChange = (val) => {
    console.log('Preço alterado:', val);
    setPriceRange(val);
    const novosFiltros = {
      precoMin: val[0],
      precoMax: val[1],
      categorias: categoriasSelecionadas
    };
    onFiltrar(novosFiltros);
  };

  const handleCategoriaChange = (categoria) => {
    console.log('Categoria clicada:', categoria);
    let novasCategorias;
    if (categoriasSelecionadas.includes(categoria)) {
      novasCategorias = categoriasSelecionadas.filter(c => c !== categoria);
    } else {
      novasCategorias = [...categoriasSelecionadas, categoria];
    }
    
    console.log('Categorias selecionadas:', novasCategorias);
    setCategoriasSelecionadas(novasCategorias);
    
    const novosFiltros = {
      precoMin: priceRange[0],
      precoMax: priceRange[1],
      categorias: novasCategorias
    };
    onFiltrar(novosFiltros);
  };

  const handleLimparFiltros = () => {
    console.log('Limpar filtros clicado');
    setPriceRange([0, 10000]);
    setCategoriasSelecionadas([]);
    onLimpar();
  };

  return (
    <div className="w-full md:w-64 space-y-10 pr-6">
      <h3 className="text-xs font-black text-gray-400 uppercase tracking-[0.3em] mb-6">{t('filtrar')}</h3>

      {/* PREÇO POR DIA */}
      <div>
        <h4 className="text-sm font-black text-gray-900 mb-6 italic uppercase tracking-tighter">{t('preco_por_dia')}</h4>
        <div className="px-2">
          <Slider
            range
            min={0}
            max={10000}
            value={priceRange}
            onChange={handlePriceChange}
            trackStyle={[{ backgroundColor: '#2563eb', height: 4 }]}
            handleStyle={[
              { borderColor: '#2563eb', height: 18, width: 18, marginTop: -7, backgroundColor: '#fff', opacity: 1 },
              { borderColor: '#2563eb', height: 18, width: 18, marginTop: -7, backgroundColor: '#fff', opacity: 1 }
            ]}
            railStyle={{ backgroundColor: '#e5e7eb', height: 4 }}
          />
          <div className="flex justify-between mt-4 text-[10px] font-black text-gray-500 uppercase">
            <span>{priceRange[0]} CVE</span>
            <span>{priceRange[1]} CVE</span>
          </div>
        </div>
      </div>

      {/* CATEGORIAS */}
      <div>
        <h4 className="text-sm font-black text-gray-900 mb-4 italic uppercase tracking-tighter">{t('categoria')}</h4>
        <div className="space-y-3">
          {categorias.map((cat) => (
            <label key={cat} className="flex items-center gap-3 cursor-pointer group">
              <input 
                type="checkbox" 
                checked={categoriasSelecionadas.includes(cat)}
                onChange={() => handleCategoriaChange(cat)}
                className="w-4 h-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500" 
              />
              <span className="text-sm font-medium text-gray-600 group-hover:text-blue-600 transition-colors">{cat}</span>
            </label>
          ))}
        </div>
      </div>

      <button 
        onClick={handleLimparFiltros}
        className="w-full bg-blue-600 text-white py-3 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-blue-700 transition-colors"
      >
        {t('limpar_filtros')}
      </button>
    </div>
  );
};

export default SidebarFiltros;

// src/components/Common/Toast.jsx
import React, { createContext, useContext, useState, useCallback, useMemo } from 'react';
import { CheckCircle, AlertCircle, X, Info } from 'lucide-react';

const ToastContext = createContext(null);

export const ToastProvider = ({ children }) => {
  const [toast, setToast] = useState(null);

  const showToast = useCallback((message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => setToast(null), 3500);
  }, []);

  const value = useMemo(() => ({ showToast }), [showToast]);

  return (
    <ToastContext.Provider value={value}>
      {children}
      {toast && (
        <div className="fixed bottom-6 right-6 z-[9999] flex items-center gap-3 px-5 py-3 rounded-xl shadow-2xl text-white bg-gray-900 border border-gray-800">
          {toast.type === 'success' && <CheckCircle size={20} className="text-green-400 shrink-0" />}
          {toast.type === 'error' && <AlertCircle size={20} className="text-red-400 shrink-0" />}
          {toast.type === 'info' && <Info size={20} className="text-blue-400 shrink-0" />}
          <span className="text-sm font-medium tracking-wide">{toast.message}</span>
          <button onClick={() => setToast(null)} className="ml-2 text-gray-400 hover:text-white transition-colors">
            <X size={16} />
          </button>
        </div>
      )}
    </ToastContext.Provider>
  );
};

// 🔓 Fallback quando NÃO há ToastProvider — não rebenta, só loga
const fallbackToast = {
  showToast: (message, type = 'info') => {
    console.warn(`[Toast:${type}]`, message);
  },
};

export const useToast = () => {
  const context = useContext(ToastContext);
  // Em vez de lançar erro, devolve fallback seguro
  return context || fallbackToast;
};

