// COMPONENTE PRINCIPAL
// ============================================================
export const CarrosDetalhes = ({ slugOverride, onClose, embedded = false }) => {
  const { t } = useTranslation();
  const params = useParams();
  const slug = slugOverride || params?.slug;
  const navigate = useNavigate();
  const { showToast } = useToast();

  const [activeTab, setActiveTab] = useState(0);
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [carro, setCarro] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [images, setImages] = useState([]);
  const [usuarioLogado, setUsuarioLogado] = useState(null);
  const [validandoDisponibilidade, setValidandoDisponibilidade] = useState(false);
  const [mostrarChat, setMostrarChat] = useState(false);

  const tracking = useCarroTracking(carro?.id, usuarioLogado?.id);
  const registrarCliqueReserva = tracking?.registrarCliqueReserva || (() => {});
  const registrarVisualizacaoMapa = tracking?.registrarVisualizacaoMapa || (() => {});
  const registrarCliqueContato = tracking?.registrarCliqueContato || (() => {});

  // Bloqueia scroll do body em modo embedded
  useEffect(() => {
    if (!embedded) return;
    const prevOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = prevOverflow; };
  }, [embedded]);

  // Fecha com ESC em modo embedded
  useEffect(() => {
    if (!embedded || !onClose) return;
    const onKey = (e) => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [embedded, onClose]);

  // Carrega utilizador (JWT robusto)
  useEffect(() => {
    try {
      const token = localStorage.getItem('token') 
                 || localStorage.getItem('morabeza_token')
                 || localStorage.getItem('access_token')
                 || localStorage.getItem('jwt');
      if (token) {
        const base64Url = token.split('.')[1];
        const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
        const parsed = JSON.parse(decodeURIComponent(
          atob(base64).split('').map(c => '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2)).join('')
        ));
        const user = parsed?.data || parsed?.user || parsed?.usuario || parsed;
        const id = user?.id || user?.userId || user?.user_id || user?.usuario_id || parsed?.sub;
        if (id) {
          setUsuarioLogado({
            id: Number(id),
            nome: user.nome || user.name || 'Utilizador',
            foto: user.foto || user.picture || null
          });
          return;
        }
      }
      const savedUser = localStorage.getItem('user') || localStorage.getItem('morabeza_user');
      if (savedUser) {
        setUsuarioLogado(JSON.parse(savedUser));
      }
    } catch (e) { console.error(e); }
  }, []);

  // Fetch do carro
  useEffect(() => {
    const fetchCarro = async () => {
      if (!slug) { setError(t('slug_nao_fornecido') || 'Slug não fornecido'); setLoading(false); return; }
      setLoading(true); setError(null);
      try {
        const response = await fetch(`${API_URL}/api/get_carro_detalhes.php?slug=${encodeURIComponent(slug)}&t=${Date.now()}`);
        if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);
        const data = await response.json();
        if (data.error) throw new Error(data.error);

        if (data.success && data.data) {
          setCarro(data.data);
          const imagensExtraidas = extrairImagens(data.data);
          if (imagensExtraidas.length > 0) {
            setImages(imagensExtraidas);
          } else {
            setImages(["https://images.unsplash.com/photo-1533473359331-0135ef1b58bf?w=1200&h=800&fit=crop"]);
          }
        } else {
          throw new Error(data.error || 'Erro ao carregar dados');
        }
      } catch (err) {
        setError(err.message || 'Erro ao carregar dados do veículo');
      } finally {
        setLoading(false);
      }
    };
    fetchCarro();
  }, [slug, t]);

  // Verificação de disponibilidade + navegação para checkout
  const handleContinueToCheckout = async (reservaInfo) => {
    registrarCliqueReserva();

    if (!carro) {
      showToast(t('erro_veiculo') || "Erro ao carregar dados do veículo.", 'error');
      return;
    }

    const checkInStr = reservaInfo.startDate.toISOString().split('T')[0];
    const checkOutStr = reservaInfo.endDate.toISOString().split('T')[0];

    setValidandoDisponibilidade(true);

    try {
      const url = `${API_URL}/api/verificar_disponibilidade_carro.php?carro_id=${encodeURIComponent(carro.id)}&checkin=${encodeURIComponent(checkInStr)}&checkout=${encodeURIComponent(checkOutStr)}&quantidade=${encodeURIComponent(reservaInfo.quantidade)}`;
      const res = await fetch(url, { method: 'GET' });
      const data = await res.json();

      if (data.success && data.disponivel === false) {
        showToast(
          data.mensagem || t('sem_stock_carro', 'Não há carros suficientes disponíveis para as datas selecionadas.'),
          'error'
        );
        setValidandoDisponibilidade(false);
        return;
      }

      if (data.success === false && data.error) {
        console.warn('Aviso da API de disponibilidade:', data.error);
      }
    } catch (err) {
      console.error('Erro ao verificar disponibilidade:', err);
      showToast(
        t('erro_verificar_disponibilidade', 'Erro ao verificar disponibilidade. Tente novamente.'),
        'error'
      );
      setValidandoDisponibilidade(false);
      return;
    }

    setValidandoDisponibilidade(false);

    const dadosParaCheckout = {
      id: carro.id,
      titulo: carro.titulo,
      imagem: images[0] || carro.imagem_url,
      localizacao: carro.localizacao,
      ilha: carro.ilha || 'Cabo Verde',
      precoDia: Number(carro.preco_dia),
      checkIn: checkInStr,
      checkOut: checkOutStr,
      dias: reservaInfo.dias,
      quantidade: reservaInfo.quantidade,
      totalGeral: reservaInfo.totalGeral,
      caucao: reservaInfo.caucao,
      tipo: carro.tipo,
      ano: carro.ano,
      transmissao: carro.transmissao,
    };

    if (onClose) onClose();
    navigate('/checkout-carro', { state: { reservaData: dadosParaCheckout } });
  };

  const irPara = (rota) => {
    if (onClose) onClose();
    navigate(rota);
  };

  // Abre o chat
  const handleContactar = () => {
    if (!usuarioLogado?.id) {
      showToast(t('login_para_mensagens') || 'Faça login para enviar mensagens', 'info');
      return;
    }
    const donoId = carro?.usuario_id || carro?.proprietario?.id;
    if (Number(donoId) === Number(usuarioLogado.id)) {
      showToast(t('nao_pode_contactar_se') || 'Não pode contactar-se a si mesmo', 'error');
      return;
    }
    registrarCliqueContato();
    setMostrarChat(true);
  };

  // Estados de loading/erro
  if (loading) {
    return (
      <div className="w-full min-h-[60vh] flex items-center justify-center">
        <Loader2 size={48} className="animate-spin text-blue-900" />
      </div>
    );
  }

  if (error || !carro) {
    return (
      <div className="w-full min-h-[60vh] flex flex-col items-center justify-center text-center px-6">
        <div className="text-red-500 text-xl mb-4">⚠️</div>
        <h2 className="text-xl font-bold text-slate-800 mb-2">{t('erro_carregar_titulo') || 'Erro ao carregar'}</h2>
        <p className="text-slate-600 mb-4">{error || (t('carro_nao_encontrado') || 'Veículo não encontrado')}</p>
        <button onClick={() => irPara(-1)} className="bg-blue-900 text-white px-6 py-2 rounded-lg hover:bg-blue-950 transition">
          {t('voltar') || 'Voltar'}
        </button>
      </div>
    );
  }

  return (
    <div className={`w-full bg-white font-sans pb-20 relative ${embedded ? 'rounded-3xl' : ''}`}>
      {!embedded && <Helmet><title>MorabezaStay | {carro.titulo}</title></Helmet>}

      {/* Botão fechar em modo embedded */}
      {embedded && onClose && (
        <button
          onClick={onClose}
          aria-label="Fechar"
          className="fixed top-4 right-4 z-[400] bg-white hover:bg-slate-100 text-slate-800 rounded-full p-3 shadow-2xl border border-slate-200 transition-all active:scale-95"
        >
          <X size={22} />
        </button>
      )}

      {isModalOpen && (
        <ImageSliderModal
          images={images}
          currentIndex={currentImageIndex}
          onClose={() => setIsModalOpen(false)}
          onPrev={() => setCurrentImageIndex(p => p === 0 ? images.length - 1 : p - 1)}
          onNext={() => setCurrentImageIndex(p => p === images.length - 1 ? 0 : p + 1)}
        />
      )}

      {/* Breadcrumb */}
      <nav className="max-w-7xl mx-auto px-6 py-4 flex items-center gap-2 text-[11px] font-medium text-slate-500 text-left">
        <span onClick={() => irPara('/')} className="hover:text-blue-900 cursor-pointer">{t('inicio') || 'Início'}</span>
        <ChevronRight size={10} />
        <span onClick={() => irPara('/carros')} className="hover:text-blue-900 cursor-pointer">{t('veiculos') || 'Veículos'}</span>
        <ChevronRight size={10} />
        <span className="text-slate-500 font-semibold truncate">{carro.titulo}</span>
      </nav>

      {/* Conteúdo principal */}
      <div className="max-w-7xl mx-auto px-6">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-2 space-y-6">
            <ImageGallery
              images={images}
              onImageChange={setCurrentImageIndex}
              onOpenModal={() => setIsModalOpen(true)}
              titulo={carro.titulo}
            />
            <div className="mt-6 pt-6 border-t border-slate-100 text-left space-y-6">
              <EspecificacoesBar caracteristicas={carro.caracteristicas} />
              <InclusoesCarroBar inclusoes={carro.inclusoes} localizacao={carro.localizacao} />
            </div>
          </div>

          <div className="lg:self-start">
            <div className="sticky top-24 z-30">
              <SidebarReservaCarro
                precoDia={Number(carro.preco_dia)}
                estrelas={carro.estrelas}
                totalReviews={carro.total_avaliacoes}
                quantidadeDisponivel={carro.quantidade_disponivel || 5}
                valorCaucao={carro.valor_caucao || 20000}
                onContinueToCheckout={handleContinueToCheckout}
                validando={validandoDisponibilidade}
              />
            </div>
          </div>
        </div>
      </div>

      {/* Título + Denúncia */}
      <div className="max-w-7xl mx-auto px-6 mt-8 text-left">
        <div className="flex flex-wrap justify-between items-start gap-4">
          <div>
            <div className="flex items-center gap-3">
              <h1 className="text-2xl md:text-3xl font-bold">{carro.titulo}</h1>
              <span className="bg-slate-100 text-slate-600 text-xs px-2 py-1 rounded">{carro.tipo || 'SUV'}</span>
            </div>
          </div>
          <BotaoDenuncia tipo="carro" itemId={carro.id} itemTitulo={carro.titulo} />
        </div>
      </div>

      {/* Tabs + Mapa + Dono */}
      <div className="max-w-7xl mx-auto px-6 mt-6 text-left">
        <TabsNavegacaoCarros activeTab={activeTab} onTabChange={setActiveTab} />
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-2">
            <TabContent activeTab={activeTab} carro={carro} />
          </div>
          <div className="space-y-4">
            {/* ⭐ DONO DO CARRO ⭐ */}
            {carro.proprietario && (
              <DonoCarroInfo
                proprietario={carro.proprietario}
                carroTitulo={carro.titulo}
                onContactClick={registrarCliqueContato}
                onContactar={handleContactar}
                usuarioLogado={usuarioLogado}
              />
            )}

            <MapLocationCarro
              localizacao={carro.localizacao}
              ilha={carro.ilha}
              latitude={carro.latitude}
              longitude={carro.longitude}
              carroId={carro.id}
              onMapClick={registrarVisualizacaoMapa}
            />
          </div>
        </div>
      </div>

      {/* Avaliações */}
      <div className="w-full bg-white border-t border-slate-100 mt-12 pt-12">
        <div className="max-w-7xl mx-auto px-6">
          <AvaliacoesSeccaoCarro
            carroId={carro.id}
            usuarioLogado={usuarioLogado}
            onOpenLoginModal={() => showToast(t('login_para_avaliar') || "Por favor, faça login para avaliar.", 'info')}
          />
        </div>
      </div>

      {/* ⭐ MODAL DO CHAT ⭐ */}
      {mostrarChat && (
        <ChatSimples
          anuncioId={carro.id}
          tipoAnuncio="carro"
          anuncioTitulo={carro.titulo}
          proprietarioId={carro.usuario_id || carro.proprietario?.id}
          onClose={() => setMostrarChat(false)}
        />
      )}

      <style>{`
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
        .react-datepicker__day--in-range { background-color: #f1f5f9 !important; }
        .react-datepicker__day--range-start, .react-datepicker__day--range-end { background-color: #2563eb !important; color: white !important; border-radius: 50% !important; }
      `}</style>
    </div>
  );
};

export default CarrosDetalhes;

// CheckoutCarro.jsx - Com verificação OTP (design padrão do site)
import React, { useState, useEffect, useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { useLocation, useNavigate } from 'react-router-dom';
import {
  Check, ArrowLeft, Loader, AlertCircle, ChevronRight, Calendar, Users, Home, ShieldCheck, Lock, Gauge, Fuel, Info, MapPin, Clock, FileText, Upload, X
} from 'lucide-react';
import DataModalCarro from './DataModalCarro';
import { useToast } from '../../../Toast';

const API_BASE = 'https://welovepalop.com';

// ============================================================
// CONDUTOR PRINCIPAL
// ============================================================
const CondutorPrincipal = ({ condutor, updateCondutor }) => {
  const { t } = useTranslation();

  return (
    <div className="mb-8 p-6 bg-white border border-slate-200 rounded-2xl shadow-sm text-left">
      <h3 className="text-lg font-bold text-blue-900 mb-4 flex items-center gap-2">
        <span className="w-6 h-6 bg-blue-600 text-white rounded-full flex items-center justify-center text-xs font-sans">1</span>
        {t('condutor_principal', 'Condutor Principal')}
      </h3>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div>
          <label className="text-xs font-bold text-slate-700 block mb-1">{t('nome_completo', 'Nome completo')} *</label>
          <input
            type="text"
            value={condutor.nome_completo}
            onChange={(e) => updateCondutor('nome_completo', e.target.value)}
            className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-600/20 text-slate-900"
            placeholder={t('placeholder_nome_documento', 'Nome como consta no documento')}
          />
        </div>

        <div>
          <label className="text-xs font-bold text-slate-700 block mb-1">{t('email', 'E-mail')} *</label>
          <input
            type="email"
            value={condutor.email}
            onChange={(e) => updateCondutor('email', e.target.value)}
            className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-600/20 text-slate-900"
            placeholder="seu@email.com"
          />
        </div>

        <div>
          <label className="text-xs font-bold text-slate-700 block mb-1">{t('telefone_whatsapp', 'Telefone / WhatsApp')} *</label>
          <input
            type="tel"
            value={condutor.phone}
            onChange={(e) => updateCondutor('phone', e.target.value)}
            className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-600/20 text-slate-900"
            placeholder="+238 991 23 45"
          />
        </div>

        <div>
          <label className="text-xs font-bold text-slate-700 block mb-1">{t('pais_nacionalidade', 'País / Nacionalidade')} *</label>
          <select
            value={condutor.nacionalidade}
            onChange={(e) => updateCondutor('nacionalidade', e.target.value)}
            className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-600/20 text-slate-900 bg-white"
          >
            <option value="Cabo Verde">{t('cabo_verde', 'Cabo Verde')}</option>
            <option value="Portugal">{t('portugal', 'Portugal')}</option>
            <option value="Brasil">{t('brasil', 'Brasil')}</option>
            <option value="Angola">{t('angola', 'Angola')}</option>
            <option value="Moçambique">{t('mocambique', 'Moçambique')}</option>
            <option value="Estados Unidos">{t('estados_unidos', 'Estados Unidos')}</option>
            <option value="França">{t('franca', 'França')}</option>
            <option value="Outro">{t('outro', 'Outro')}</option>
          </select>
        </div>
      </div>

      <div className="border-t border-slate-100 my-6"></div>

      <div className="space-y-5">
        <div>
          <label className="text-xs font-bold text-slate-700 block mb-1 flex items-center gap-1">
            <Clock size={12} /> {t('hora_levantamento', 'Hora de levantamento')} *
          </label>
          <select
            value={condutor.hora_levantamento || '10:00'}
            onChange={(e) => updateCondutor('hora_levantamento', e.target.value)}
            className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-600/20 text-slate-900 bg-white"
          >
            {['08:00','09:00','10:00','11:00','12:00','13:00','14:00','15:00','16:00','17:00'].map(h => (
              <option key={h} value={h}>{h}</option>
            ))}
          </select>
        </div>

        <div>
          <label className="text-xs font-bold text-slate-700 block mb-1 flex items-center gap-1">
            <Upload size={12} /> {t('carta_conducao_upload', 'Carta de condução')} *
          </label>
          <div className="border-2 border-dashed border-slate-300 rounded-xl p-4 text-center hover:border-blue-500 transition-colors cursor-pointer bg-slate-50/30">
            <input
              type="file"
              id="carta-conducao"
              accept=".pdf,.doc,.docx,image/*"
              onChange={(e) => {
                const file = e.target.files[0];
                if (file) {
                  updateCondutor('carta_conducao_file', file);
                  updateCondutor('carta_conducao_nome', file.name);
                }
              }}
              className="hidden"
            />
            <label htmlFor="carta-conducao" className="cursor-pointer block">
              <Upload size={24} className="mx-auto text-slate-400 mb-2" />
              {condutor.carta_conducao_nome ? (
                <div className="text-green-600 text-sm font-medium flex items-center justify-center gap-2">
                  <Check size={16} /> {condutor.carta_conducao_nome}
                </div>
              ) : (
                <>
                  <p className="text-sm font-medium text-slate-600">{t('clique_upload', 'Clique para carregar o documento')}</p>
                  <p className="text-[10px] text-slate-400 mt-1">{t('upload_limite', 'PDF ou Imagem')}</p>
                </>
              )}
            </label>
          </div>
        </div>

        <div>
          <label className="text-xs font-bold text-slate-700 block mb-1 flex items-center gap-1">
            <FileText size={12} /> {t('observacoes_pedidos', 'Observações')}
          </label>
          <textarea
            rows="3"
            value={condutor.observacoes || ''}
            onChange={(e) => updateCondutor('observacoes', e.target.value)}
            className="w-full border border-slate-200 rounded-xl p-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-600/20 text-slate-900 resize-none"
            placeholder={t('placeholder_observacoes', 'Informações adicionais...')}
          />
        </div>
      </div>
    </div>
  );
};

// ============================================================
// RESUMO RESERVA CARRO
// ============================================================
const ResumoReservaCarro = ({ reserva, precoTotal, setDataModalOpen }) => {
  const { t } = useTranslation();

  const formatNumber = (value) => {
    if (value === undefined || value === null) return '0';
    return Number(value).toLocaleString('pt-PT');
  };

  const formatarData = (data) => {
    if (!data) return t('nao_selecionada', 'Não selecionada');
    const d = new Date(data);
    return d.toLocaleDateString('pt-PT', { day: '2-digit', month: 'short', year: 'numeric' });
  };

  return (
    <div className="border border-slate-200 rounded-2xl p-5 bg-white shadow-sm sticky top-6 text-left">
      <h2 className="text-lg font-bold text-blue-900 mb-5">{t('resumo_reserva', 'Resumo da Reserva')}</h2>

      <div className="flex gap-4 mb-6">
        <img
          src={reserva?.imagem || 'https://images.unsplash.com/photo-1533473359331-0135ef1b58bf?w=200'}
          className="w-20 h-20 rounded-xl object-cover shrink-0"
          alt={reserva?.titulo || 'Veículo'}
          onError={(e) => e.target.src = 'https://images.unsplash.com/photo-1533473359331-0135ef1b58bf?w=200'}
        />
        <div className="flex-1">
          <h4 className="text-sm font-bold text-blue-900 leading-tight">{reserva?.titulo || 'Morabeza Rent'}</h4>
          <p className="text-[10px] text-slate-500 mt-1 font-medium flex items-center gap-1">
            <MapPin size={10} className="text-orange-500" /> {reserva?.localizacao || 'Cabo Verde'}
          </p>
          <button
            onClick={() => setDataModalOpen && setDataModalOpen(true)}
            className="text-[10px] text-blue-600 underline mt-2 font-bold block"
          >
            {t('alterar_datas', 'Alterar datas')}
          </button>
        </div>
      </div>

      <div className="space-y-4 border-t border-slate-100 pt-5">
        <div className="flex justify-between">
          <span className="text-xs text-slate-600 font-medium">{t('levantamento', 'Levantamento')}</span>
          <span className="text-xs font-bold text-blue-900">{formatarData(reserva?.checkIn)} - {reserva?.horaLevantamento || '10:00'}</span>
        </div>
        <div className="flex justify-between">
          <span className="text-xs text-slate-600 font-medium">{t('devolucao', 'Devolução')}</span>
          <span className="text-xs font-bold text-blue-900">{formatarData(reserva?.checkOut)} - {reserva?.horaLevantamento || '10:00'}</span>
        </div>
        <div className="flex justify-between">
          <span className="text-xs text-slate-600 font-medium">{t('dias', 'Dias')}</span>
          <span className="text-xs font-bold text-blue-900">{reserva?.dias || 0} {Number(reserva?.dias) === 1 ? 'dia' : 'dias'}</span>
        </div>

        <div className="pt-3 space-y-2 border-t border-slate-100">
          <div className="flex justify-between text-[11px] font-medium">
            <span className="text-slate-500">{t('preco_por_dia', 'Preço por dia')}</span>
            <span className="text-slate-800">{formatNumber(reserva?.precoDia)} CVE</span>
          </div>
          <div className="flex justify-between text-[11px] font-medium">
            <span className="text-slate-500">{t('subtotal_dias', { dias: reserva?.dias || 0, defaultValue: 'Subtotal' })}</span>
            <span className="text-slate-800">{formatNumber(reserva?.subtotal)} CVE</span>
          </div>
        </div>

        <div className="flex justify-between items-center pt-3 border-t border-slate-100">
          <span className="text-base font-bold text-blue-900">{t('total', 'Total')}</span>
          <span className="text-xl font-bold text-blue-600">{formatNumber(precoTotal)} CVE</span>
        </div>
      </div>
    </div>
  );
};

// ============================================================
// COMPONENTE PRINCIPAL
// ============================================================
const CheckoutCarro = () => {
  const { t } = useTranslation();
  const location = useLocation();
  const navigate = useNavigate();
  const { showToast } = useToast();
  const { reservaData } = location.state || {};

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [isDataModalOpen, setDataModalOpen] = useState(false);

  // Estados OTP (padrão do site)
  const [showOtpModal, setShowOtpModal] = useState(false);
  const [otpValues, setOtpValues] = useState(['', '', '', '', '', '']);
  const [loadingOtp, setLoadingOtp] = useState(false);
  const [enviandoOtp, setEnviandoOtp] = useState(false);
  const inputRefs = useRef([]);

  const [condutor, setCondutor] = useState({
    nome_completo: '',
    email: '',
    phone: '',
    idade: 'adulto',
    nacionalidade: 'Cabo Verde',
    hora_levantamento: '10:00',
    carta_conducao_file: null,
    carta_conducao_nome: '',
    observacoes: ''
  });

  const [reserva, setReserva] = useState({
    id: reservaData?.carroId || reservaData?.id || null,
    titulo: reservaData?.titulo || '',
    imagem: reservaData?.imagem || '',
    localizacao: reservaData?.localizacao || '',
    checkIn: reservaData?.checkIn || '',
    checkOut: reservaData?.checkOut || '',
    dias: reservaData?.dias || 1,
    precoDia: reservaData?.precoDia || 0,
    subtotal: reservaData?.subtotal || reservaData?.totalGeral || 0,
    totalGeral: reservaData?.totalGeral || 0,
    tipo: reservaData?.tipo || 'SUV',
    horaLevantamento: reservaData?.horaLevantamento || '10:00'
  });

  useEffect(() => {
    const savedUser = localStorage.getItem('user');
    if (savedUser) {
      try {
        const userData = JSON.parse(savedUser);
        setCondutor(prev => ({
          ...prev,
          nome_completo: userData.name || userData.full_name || '',
          email: userData.email || '',
          phone: userData.phone || ''
        }));
      } catch (e) {
        console.error('Erro ao parsear utilizador:', e);
      }
    }
    window.scrollTo(0, 0);
  }, []);

  useEffect(() => {
    if (!reservaData) {
      navigate('/carros');
    }
  }, [reservaData, navigate]);

  const handleSelectData = (dataObj) => {
    const novosDias = dataObj.dias;
    const novoSubtotal = reserva.precoDia * novosDias;
    setReserva(prev => ({
      ...prev,
      checkIn: dataObj.checkIn,
      checkOut: dataObj.checkOut,
      dias: novosDias,
      subtotal: novoSubtotal,
      totalGeral: novoSubtotal
    }));
    setDataModalOpen(false);
  };

  const updateCondutor = (field, value) => {
    setCondutor(prev => ({ ...prev, [field]: value }));
  };

  const validateForm = () => {
    setError('');
    if (!condutor.nome_completo.trim()) {
      setError(t('erro_nome_obrigatorio', 'O nome completo é obrigatório.'));
      return false;
    }
    if (!condutor.email.trim()) {
      setError(t('erro_email_obrigatorio', 'O e-mail é obrigatório.'));
      return false;
    }
    if (!condutor.phone.trim()) {
      setError(t('erro_telefone_obrigatorio', 'O telefone é obrigatório.'));
      return false;
    }
    if (!condutor.nacionalidade.trim()) {
      setError(t('erro_nacionalidade_obrigatoria', 'A nacionalidade é obrigatória.'));
      return false;
    }
    if (!reserva.checkIn || !reserva.checkOut) {
      setError(t('erro_datas_obrigatorias', 'As datas de levantamento e devolução são obrigatórias.'));
      return false;
    }
    return true;
  };

  const mascararEmail = (email) => {
    if (!email || !email.includes('@')) return 'seu***@gmail.com';
    const [nome, dominio] = email.split('@');
    if (nome.length <= 3) return `${nome[0]}***@${dominio}`;
    return `${nome.substring(0, 3)}***@${dominio}`;
  };

  const handleEnviarOtp = async () => {
    if (!validateForm()) return;
    setEnviandoOtp(true);
    try {
      const res = await fetch(`${API_BASE}/api/send_otp.php`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'send_otp', email: condutor.email })
      });
      const data = await res.json();
      if (data.status === 'otp_sent' || data.status === 'success') {
        setOtpValues(['', '', '', '', '', '']);
        setShowOtpModal(true);
      } else {
        showToast(data.message || t('erro_enviar_codigo', 'Não foi possível enviar o código.'), 'error');
      }
    } catch (e) {
      showToast(t('erro_conexao', 'Erro de conexão ao enviar OTP.'), 'error');
    } finally {
      setEnviandoOtp(false);
    }
  };

  const handleResendOtp = async () => {
    try {
      const res = await fetch(`${API_BASE}/api/send_otp.php`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'resend_otp', email: condutor.email })
      });
      const data = await res.json();
      if (data.status === 'success' || data.status === 'otp_sent') {
        showToast(t('codigo_reenviado', 'Novo código enviado para o seu email'), 'success');
      } else {
        showToast(data.message || t('erro_reenviar', 'Erro ao reenviar código'), 'error');
      }
    } catch (err) {
      console.error('Erro ao reenviar OTP:', err);
    }
  };

  const handleOtpChange = (index, value) => {
    const val = value.replace(/\D/g, '');
    if (!val) {
      const newValues = [...otpValues];
      newValues[index] = '';
      setOtpValues(newValues);
      return;
    }
    const newValues = [...otpValues];
    newValues[index] = val[val.length - 1];
    setOtpValues(newValues);

    if (index < 5 && val) {
      inputRefs.current[index + 1]?.focus();
    }
  };

  const handleOtpKeyDown = (index, e) => {
    if (e.key === 'Backspace' && !otpValues[index] && index > 0) {
      inputRefs.current[index - 1]?.focus();
    }
  };

  const handleVerifyOtpAndProceed = async () => {
    const codigoCompleto = otpValues.join('');
    if (codigoCompleto.length < 6) {
      showToast(t('erro_codigo_incompleto', 'Por favor, insira o código completo de 6 dígitos'), 'error');
      return;
    }

    setLoadingOtp(true);
    try {
      const res = await fetch(`${API_BASE}/api/send_otp.php`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'verify_otp',
          email: condutor.email,
          otp: codigoCompleto
        })
      });
      const data = await res.json();
      if (data.status === 'success') {
        setShowOtpModal(false);
        showToast(t('email_verificado_sucesso', 'Email verificado com sucesso!'), 'success');
        concluirReserva();
      } else {
        showToast(data.message || t('erro_codigo_invalido', 'Código inválido ou expirado.'), 'error');
      }
    } catch (e) {
      showToast(t('erro_conexao', 'Erro de conexão ao verificar código'), 'error');
    } finally {
      setLoadingOtp(false);
    }
  };

  const concluirReserva = () => {
    const dadosReserva = {
      reservaData: {
        ...reserva,
        precoTotal: reserva.totalGeral,
        tipo: 'carro'
      },
      participantePrincipal: {
        nome_completo: condutor.nome_completo,
        email: condutor.email,
        phone: condutor.phone,
        idade: condutor.idade,
        nacionalidade: condutor.nacionalidade,
        hora_levantamento: condutor.hora_levantamento,
        carta_conducao_nome: condutor.carta_conducao_nome,
        observacoes: condutor.observacoes
      },
      participantesAdicionais: [],
      usuario: JSON.parse(localStorage.getItem('user') || 'null') || { email: condutor.email, nome: condutor.nome_completo }
    };

    sessionStorage.setItem('reservaCarroPendente', JSON.stringify(dadosReserva));

    navigate('/pagamento', {
      state: {
        reservaData: {
          ...reserva,
          precoTotal: reserva.totalGeral,
          tipo: 'carro'
        },
        dadosParticipantes: {
          participantePrincipal: condutor,
          participantes: []
        },
        tipo: 'carro'
      }
    });
  };

  const handleSubmit = () => {
    if (!validateForm()) return;
    handleEnviarOtp();
  };

  const totalPreco = reserva.totalGeral;

  if (!reservaData) {
    return (
      <div className="h-screen flex flex-col items-center justify-center bg-white">
        <Loader className="animate-spin text-blue-600 mb-4" size={40} />
        <p className="font-bold text-gray-500 font-medium">{t('carregando_dados_reserva', 'A carregar...')}</p>
      </div>
    );
  }

  const formatarData = (data) => {
    if (!data) return '';
    const d = new Date(data);
    return d.toLocaleDateString('pt-PT', { day: '2-digit', month: 'short', year: 'numeric' });
  };

  return (
    <>
      <div className="min-h-screen bg-white font-sans text-slate-900 p-4 md:p-10">
        <div className="max-w-7xl mx-auto">
          {error && (
            <div className="mb-6 p-4 bg-red-50 border border-red-200 rounded-lg flex items-start gap-3 text-left">
              <AlertCircle className="text-red-500 shrink-0 mt-0.5" size={20} />
              <p className="text-red-700 text-sm font-medium">{error}</p>
            </div>
          )}

          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
            <div className="lg:col-span-8">
              <h1 className="text-2xl font-bold text-blue-900 mb-2 text-left">{t('dados_condutor', 'Dados do Condutor')}</h1>
              <p className="text-slate-500 text-sm mb-6 text-left font-medium">{t('preencha_dados_condutor', 'Preencha os dados abaixo para continuar.')}</p>

              <CondutorPrincipal
                condutor={condutor}
                updateCondutor={updateCondutor}
              />

              <div className="mt-10 flex flex-col sm:flex-row justify-between gap-3">
                <button
                  onClick={() => navigate(-1)}
                  className="px-6 py-3 border border-slate-200 rounded-lg text-sm font-bold flex items-center justify-center gap-2 hover:bg-slate-50 transition-all text-slate-700 shadow-sm"
                >
                  <ArrowLeft size={18} /> {t('voltar', 'Voltar')}
                </button>
                <button
                  onClick={handleSubmit}
                  disabled={enviandoOtp || loading}
                  className="px-8 py-3 bg-blue-600 text-white rounded-lg text-sm font-bold flex items-center justify-center gap-2 hover:bg-blue-700 transition-all shadow-md disabled:opacity-50"
                >
                  {(enviandoOtp || loading) ? <Loader size={18} className="animate-spin" /> : null}
                  {(enviandoOtp || loading) ? (t('processando', 'A processar...')) : (t('continuar_pagamento', 'Continuar para o pagamento'))} <ChevronRight size={18} />
                </button>
              </div>
            </div>

            <div className="lg:col-span-4">
              <ResumoReservaCarro
                reserva={reserva}
                precoTotal={totalPreco}
                setDataModalOpen={setDataModalOpen}
              />
            </div>
          </div>
        </div>
      </div>

      {isDataModalOpen && (
        <DataModalCarro
          onClose={() => setDataModalOpen(false)}
          onSelectData={handleSelectData}
          carroTitulo={reserva.titulo}
          currentCheckIn={reserva.checkIn}
          currentCheckOut={reserva.checkOut}
        />
      )}

      {/* MODAL OTP — DESIGN PADRÃO DO SITE */}
      {showOtpModal && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 p-4 font-sans">
          <div className="bg-white rounded-3xl max-w-[420px] w-full p-8 shadow-2xl relative border border-slate-100 text-center animate-in fade-in zoom-in duration-200">

            <button
              onClick={() => setShowOtpModal(false)}
              className="absolute top-5 right-5 text-slate-400 hover:text-slate-600 transition"
            >
              <X size={20} />
            </button>

            <div className="flex justify-center mb-5">
              <div className="w-14 h-14 bg-blue-50 text-blue-600 rounded-full flex items-center justify-center shadow-inner">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z"></path>
                </svg>
              </div>
            </div>

            <h3 className="text-xl font-bold text-slate-900 mb-2">Confirmar email</h3>
            <p className="text-xs text-slate-500 mb-6 leading-relaxed">
              Enviámos um código de 6 dígitos para<br />
              <strong className="text-slate-800">{mascararEmail(condutor.email)}</strong>
            </p>

            <div className="text-left mb-2">
              <label className="text-xs font-bold text-slate-700">Código de confirmação</label>
            </div>

            <div className="flex justify-between gap-2 mb-4">
              {otpValues.map((digit, idx) => (
                <input
                  key={idx}
                  ref={(el) => (inputRefs.current[idx] = el)}
                  type="text"
                  maxLength={1}
                  value={digit}
                  onChange={(e) => handleOtpChange(idx, e.target.value)}
                  onKeyDown={(e) => handleOtpKeyDown(idx, e)}
                  className="w-12 h-12 text-center text-xl font-bold border border-slate-200 rounded-xl bg-slate-50 focus:bg-white focus:outline-none focus:ring-2 focus:ring-blue-600 text-slate-900 shadow-sm transition-all"
                />
              ))}
            </div>

            <p className="text-[11px] text-slate-400 mb-6">O código é válido por 5 minutos.</p>

            <button
              type="button"
              onClick={handleVerifyOtpAndProceed}
              disabled={loadingOtp || otpValues.some(v => !v)}
              className="w-full bg-[#003580] hover:bg-[#002560] text-white font-semibold py-3.5 rounded-xl text-sm transition shadow-lg shadow-blue-900/10 disabled:opacity-50"
            >
              {loadingOtp ? 'A verificar...' : 'Confirmar email'}
            </button>

            <div className="flex justify-between items-center text-xs mt-6 px-1">
              <button
                type="button"
                onClick={handleResendOtp}
                className="text-blue-600 font-medium hover:underline"
              >
                Reenviar código
              </button>
              <button
                type="button"
                onClick={() => setShowOtpModal(false)}
                className="text-slate-500 font-medium hover:underline"
              >
                Alterar email
              </button>
            </div>

          </div>
        </div>
      )}
    </>
  );
};

export default CheckoutCarro;

// MapaInterativo.jsx
import React from 'react';
import { useTranslation } from 'react-i18next';
import { X } from 'lucide-react';

const MapaInterativo = ({ isOpen, onClose, dadosAlojamentos }) => {
  const { t } = useTranslation();
  
  if (!isOpen) return null;
  
  return (
    <div className="fixed inset-0 z-[200] bg-black/95 flex items-center justify-center">
      <button 
        onClick={onClose}
        className="absolute top-4 right-4 text-white bg-black/50 rounded-full p-2 hover:bg-black/70"
      >
        <X size={24} />
      </button>
      <div className="text-white text-center">
        <h2 className="text-2xl font-bold mb-4">{t('mapa_interativo_titulo')}</h2>
        <p className="text-slate-400">{t('mapa_desenvolvimento')}</p>
      </div>
    </div>
  );
};

export default MapaInterativo;

// MapaCarros.jsx - Sem sidebar, vista geral inicial, marcadores com preços
import React, { useState, useEffect, useMemo, useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { Map, Marker, NavigationControl } from 'react-map-gl';
import { useNavigate, useLocation } from 'react-router-dom';
import { ArrowLeft, Star, MapPin, ChevronRight, Gauge, X } from 'lucide-react';
import axios from 'axios';

// Importar o CSS do Mapbox
import 'mapbox-gl/dist/mapbox-gl.css';

const MAPBOX_TOKEN = import.meta.env.VITE_MAPBOX_TOKEN;

// ============================================================
// DICIONÁRIO DE COORDENADAS (ilhas + cidades + zonas)
// ============================================================
const COORDENADAS_ILHAS = {
  // ILHAS
  'Santo Antão': { lat: 17.0667, lng: -25.1667 },
  'São Vicente': { lat: 16.8333, lng: -24.9833 },
  'Santa Luzia': { lat: 16.75, lng: -24.75 },
  'São Nicolau': { lat: 16.6167, lng: -24.2667 },
  'Sal': { lat: 16.7167, lng: -22.9167 },
  'Ilha do Sal': { lat: 16.7167, lng: -22.9167 },
  'Boa Vista': { lat: 16.1, lng: -22.8 },
  'Maio': { lat: 15.1333, lng: -23.2167 },
  'Santiago': { lat: 15.0667, lng: -23.5833 },
  'Fogo': { lat: 14.9167, lng: -24.3333 },
  'Ilha do Fogo': { lat: 14.9167, lng: -24.3333 },
  'Brava': { lat: 14.8667, lng: -24.7 },

  // CIDADES / LOCALIZAÇÕES
  'Praia': { lat: 14.9315, lng: -23.5125 },
  'Mindelo': { lat: 16.8884, lng: -24.9896 },
  'Santa Maria': { lat: 16.5999, lng: -22.9086 },
  'Espargos': { lat: 16.7551, lng: -22.9454 },
  'Sal Rei': { lat: 16.1761, lng: -22.9172 },
  'Porto Novo': { lat: 17.0194, lng: -25.0647 },
  'Cidade Velha': { lat: 14.9153, lng: -23.6053 },
  'Tarrafal': { lat: 15.2781, lng: -23.7517 },
  'Assomada': { lat: 15.1, lng: -23.6833 },
  'São Domingos': { lat: 15.0253, lng: -23.4994 },
  'São Salvador do Mundo': { lat: 15.0667, lng: -23.6333 },
  'Achada Santo António': { lat: 14.9213, lng: -23.5065 },
  'Platô': { lat: 14.9176, lng: -23.5091 },
  'Palmarejo': { lat: 14.925, lng: -23.518 },
  'Prainha': { lat: 14.91, lng: -23.515 },
  'Quebra Canela': { lat: 14.905, lng: -23.518 },
  'Terra Branca': { lat: 14.929, lng: -23.503 },
  'Achada Grande': { lat: 14.938, lng: -23.487 },
  'Cidadela': { lat: 14.923, lng: -23.508 },
};

const MapaCarros = () => {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const location = useLocation();

  // ============================================================
  // REFS DO MAPA
  // ============================================================
  const mapRef = useRef(null);

  const [carros, setCarros] = useState([]);
  const [selectedCarro, setSelectedCarro] = useState(null);
  const [modalCarro, setModalCarro] = useState(null);
  const [loading, setLoading] = useState(true);
  const [focoId, setFocoId] = useState(null);
  const [isModalClosing, setIsModalClosing] = useState(false);

  // ============================================================
  // VISTA INICIAL — CABO VERDE INTEIRO (zoom 7)
  // ============================================================
  const [viewState, setViewState] = useState({
    latitude: 15.3,
    longitude: -23.8,
    zoom: 7,
    pitch: 0,
    bearing: 0,
  });

  // ============================================================
  // LÊ O PARÂMETRO ?foco=ID DA URL
  // ============================================================
  useEffect(() => {
    const params = new URLSearchParams(location.search);
    const foco = params.get('foco');
    if (foco) setFocoId(parseInt(foco, 10));
  }, [location.search]);

  // ============================================================
  // OBTÉM COORDENADAS VÁLIDAS (com fallback inteligente)
  // ============================================================
  const obterCoordenadasValidas = (carro) => {
    const lat = parseFloat(carro?.latitude);
    const lng = parseFloat(carro?.longitude);

    // 1. Se tem coordenadas reais na DB, usa-as
    if (!isNaN(lat) && !isNaN(lng) && lat !== 0 && lng !== 0) {
      return { lat, lng, zoom: 15 };
    }

    // 2. Tenta encontrar a localização no dicionário
    const candidatos = [
      carro?.ilha,
      carro?.cidade,
      carro?.localizacao,
      carro?.levantamento_local,
      carro?.levantamento_ilha,
    ].filter(Boolean);

    for (const nome of candidatos) {
      if (!nome) continue;

      // Procura exata
      if (COORDENADAS_ILHAS[nome]) {
        return {
          lat: COORDENADAS_ILHAS[nome].lat,
          lng: COORDENADAS_ILHAS[nome].lng,
          zoom: 12,
        };
      }

      // Procura parcial (ex: "Praia de Santa Maria" contém "Santa Maria")
      for (const chave of Object.keys(COORDENADAS_ILHAS)) {
        if (nome.toLowerCase().includes(chave.toLowerCase())) {
          return {
            lat: COORDENADAS_ILHAS[chave].lat,
            lng: COORDENADAS_ILHAS[chave].lng,
            zoom: 12,
          };
        }
      }
    }

    // 3. Fallback final: centro de Cabo Verde
    return { lat: 15.5, lng: -24.0, zoom: 8 };
  };

  // ============================================================
  // PROCESSA COORDENADAS ÚNICAS (espiral de Fibonacci)
  // ============================================================
  const processarCoordenadasUnicas = (lista) => {
    const contagem = {};
    const ANGULO_AUREO = Math.PI * (3 - Math.sqrt(5)); // ~2.39996 rad

    return lista.map((carro) => {
      const ponto = obterCoordenadasValidas(carro);
      const chave = `${ponto.lat.toFixed(5)}-${ponto.lng.toFixed(5)}`;

      if (contagem[chave] === undefined) contagem[chave] = 0;
      const index = contagem[chave];
      contagem[chave]++;

      let latFinal = ponto.lat;
      let lngFinal = ponto.lng;

      if (index > 0) {
        const raioBase = 0.0012; // ~130m por anel
        const raio = raioBase * Math.sqrt(index);
        const angulo = index * ANGULO_AUREO;
        const ajusteLng = 1 / Math.cos((ponto.lat * Math.PI) / 180);

        latFinal += raio * Math.cos(angulo);
        lngFinal += raio * Math.sin(angulo) * ajusteLng;
      }

      return { ...carro, latFinal, lngFinal, zoomFinal: ponto.zoom };
    });
  };

  // ============================================================
  // CARREGA DADOS DA API
  // ============================================================
  useEffect(() => {
    const carregarDados = async () => {
      try {
        setLoading(true);
        const res = await axios.get(
          'https://welovepalop.com/api/get_carro_detalhes.php'
        );

        let dados = [];
        if (res.data && res.data.success && res.data.data) {
          dados = Array.isArray(res.data.data)
            ? res.data.data
            : [res.data.data];
        } else if (res.data && res.data.data) {
          dados = Array.isArray(res.data.data)
            ? res.data.data
            : [res.data.data];
        } else {
          dados = Array.isArray(res.data) ? res.data : [];
        }

        console.log('Carros recebidos:', dados.length, dados);

        const dadosProcessados = processarCoordenadasUnicas(dados);
        setCarros(dadosProcessados);

        // Só faz zoom automático se vier ?foco=ID na URL
        if (focoId) {
          const focoCarro = dadosProcessados.find(
            (c) => parseInt(c.id, 10) === focoId
          );
          if (focoCarro) {
            setViewState((prev) => ({
              ...prev,
              latitude: focoCarro.latFinal,
              longitude: focoCarro.lngFinal,
              zoom: focoCarro.zoomFinal || 15,
            }));
            setSelectedCarro(focoCarro);
            setModalCarro(focoCarro);
          }
        }
        // Se NÃO houver foco, mantém a vista inicial (Cabo Verde inteiro)
      } catch (err) {
        console.error('Erro ao carregar mapa de carros:', err);
      } finally {
        setLoading(false);
      }
    };

    carregarDados();
  }, [focoId]);

  // ============================================================
  // FORÇA RESIZE QUANDO OS DADOS CHEGAM
  // ============================================================
  useEffect(() => {
    if (!mapRef.current) return;

    const timer = setTimeout(() => {
      if (mapRef.current) {
        mapRef.current.resize();
      }
    }, 150);

    return () => clearTimeout(timer);
  }, [carros, loading]);

  // ============================================================
  // ABRE O MODAL
  // ============================================================
  const handleAbrirModal = (carro) => {
    setSelectedCarro(carro);
    setViewState((prev) => ({
      ...prev,
      latitude: carro.latFinal,
      longitude: carro.lngFinal,
      zoom: carro.zoomFinal || 15,
    }));
    setModalCarro(carro);
    if (navigator.vibrate) navigator.vibrate(30);
  };

  // ============================================================
  // FECHA O MODAL
  // ============================================================
  const handleFecharModal = () => {
    setIsModalClosing(true);
    setTimeout(() => {
      setModalCarro(null);
      setIsModalClosing(false);
    }, 200);
  };

  // ============================================================
  // MARCADORES (memoizados)
  // ============================================================
  const marcadores = useMemo(
    () =>
      carros.map((carro) => {
        const isSelected = selectedCarro?.id === carro.id;
        const preco = Number(carro.preco_dia || 0);

        return (
          <Marker
            key={carro.id}
            latitude={carro.latFinal}
            longitude={carro.lngFinal}
            anchor="bottom"
            onClick={(e) => {
              e.originalEvent.stopPropagation();
              handleAbrirModal(carro);
            }}
          >
            <div
              className={`
                px-3 py-1.5 rounded-full border-2 border-white shadow-xl font-black text-[11px] transition-all cursor-pointer whitespace-nowrap
                ${
                  isSelected
                    ? 'bg-black text-white scale-110 z-50 relative ring-4 ring-blue-400/50'
                    : 'bg-blue-600 text-white hover:bg-blue-700 hover:scale-105 z-10'
                }
              `}
            >
              {preco.toLocaleString()} {t('cve')}
            </div>
          </Marker>
        );
      }),
    [carros, selectedCarro, t]
  );

  // ============================================================
  // RENDER
  // ============================================================
  return (
    <div className="w-screen h-screen relative bg-slate-100 overflow-hidden">
      {/* Botão Voltar */}
      <div className="absolute top-6 left-6 z-50">
        <button
          onClick={() => navigate(-1)}
          className="bg-white hover:bg-gray-50 text-gray-900 px-6 py-3 rounded-2xl shadow-2xl flex items-center gap-3 font-black text-xs uppercase tracking-widest border border-gray-100 transition-all cursor-pointer"
        >
          <ArrowLeft size={18} /> {t('voltar')}
        </button>
      </div>

      {/* Loading — sempre no DOM, escondido com opacity */}
      <div
        className={`absolute inset-0 z-40 bg-white/80 backdrop-blur-md flex flex-col items-center justify-center transition-opacity duration-300 ${
          loading ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'
        }`}
      >
        <div className="w-12 h-12 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mb-4"></div>
        <p className="font-black text-[10px] uppercase tracking-[0.2em] text-blue-600">
          {t('carregando_mapa_frotas')}
        </p>
      </div>

      {/* Mapa em Tela Cheia */}
      <Map
        ref={mapRef}
        {...viewState}
        onMove={(evt) => setViewState(evt.viewState)}
        onLoad={() => {
          if (!mapRef.current) return;

          mapRef.current.resize();
          setTimeout(() => mapRef.current?.resize(), 200);
          setTimeout(() => mapRef.current?.resize(), 600);
        }}
        mapStyle="mapbox://styles/mapbox/streets-v12"
        mapboxAccessToken={MAPBOX_TOKEN}
        style={{ width: '100%', height: '100%' }}
        onClick={() => setSelectedCarro(null)}
      >
        <NavigationControl position="bottom-right" />
        {marcadores}
      </Map>

      {/* ===== MODAL CENTRAL DIRETO COM FLASH ===== */}
      {modalCarro && (
        <>
          {/* Overlay escuro com blur */}
          <div
            className={`fixed inset-0 z-[9998] bg-black/50 backdrop-blur-sm transition-opacity duration-200 ${
              isModalClosing ? 'opacity-0' : 'opacity-100'
            }`}
            onClick={handleFecharModal}
          />

          {/* Flash effect */}
          <div
            className={`fixed inset-0 z-[9999] pointer-events-none ${
              isModalClosing ? 'opacity-0' : 'opacity-100'
            }`}
            style={{
              background:
                'radial-gradient(circle at center, rgba(59,130,246,0.25) 0%, transparent 65%)',
              animation: isModalClosing ? 'none' : 'flashPulse 0.5s ease-out',
            }}
          />

          {/* Modal — sempre centrado */}
          <div
            className="fixed top-1/2 left-1/2 z-[10000] w-[92%] max-w-md bg-white rounded-3xl shadow-2xl border border-slate-200 overflow-hidden"
            style={{
              transform: 'translate(-50%, -50%)',
              animation: isModalClosing
                ? 'modalClose 0.2s ease-in forwards'
                : 'modalPop 0.35s cubic-bezier(0.34, 1.56, 0.64, 1) forwards',
            }}
          >
            {/* Imagem de capa */}
            <div className="relative w-full h-48 overflow-hidden">
              <img
                src={
                  modalCarro.imagem_url ||
                  (modalCarro.imagens && modalCarro.imagens[0]) ||
                  'https://images.unsplash.com/photo-1533473359331-0135ef1b58bf?w=600'
                }
                alt={modalCarro.titulo}
                className="w-full h-full object-cover"
                onError={(e) =>
                  (e.target.src =
                    'https://images.unsplash.com/photo-1533473359331-0135ef1b58bf?w=600')
                }
              />
              <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent" />

              <button
                onClick={handleFecharModal}
                className="absolute top-3 right-3 z-10 bg-black/60 hover:bg-black/80 text-white p-2 rounded-full transition-all backdrop-blur-sm cursor-pointer hover:scale-110 active:scale-95"
              >
                <X size={18} />
              </button>

              <div className="absolute top-3 left-3 bg-white/95 px-2.5 py-1 rounded-lg text-xs font-black flex items-center gap-1 shadow-lg">
                <Star size={12} className="fill-yellow-400 text-yellow-400" />
                {Number(modalCarro.estrelas || 5).toFixed(1)}
              </div>

              <div className="absolute top-3 right-14 bg-blue-600/90 text-white text-[9px] font-black px-2 py-1 rounded-lg uppercase">
                {modalCarro.tipo || 'SUV'}
              </div>

              <div className="absolute bottom-3 left-4 right-4">
                <h3 className="font-black text-lg text-white drop-shadow-lg leading-tight">
                  {modalCarro.titulo}
                </h3>
                <p className="text-xs text-white/80 font-medium flex items-center gap-1 mt-1">
                  <MapPin size={12} className="text-orange-400 shrink-0" />
                  {modalCarro.ilha}, {modalCarro.localizacao}
                </p>
              </div>
            </div>

            {/* Conteúdo */}
            <div className="p-5">
              <div className="flex items-center justify-between mb-4">
                <div>
                  <span className="text-[10px] font-black uppercase text-slate-400 tracking-wider">
                    {t('preco_dia') || 'Preço por dia'}
                  </span>
                  <div className="flex items-baseline gap-1">
                    <span className="text-2xl font-black text-blue-600">
                      {Number(modalCarro.preco_dia).toLocaleString()}
                    </span>
                    <span className="text-xs font-bold text-slate-400">
                      {t('cve')}
                    </span>
                  </div>
                </div>
                <div className="text-right">
                  <span className="text-[10px] font-black uppercase text-slate-400 tracking-wider">
                    {t('transmissao') || 'Transmissão'}
                  </span>
                  <div className="flex items-center gap-1 justify-end mt-1">
                    <Gauge size={14} className="text-slate-500" />
                    <span className="text-sm font-black text-gray-900">
                      {modalCarro.transmissao || t('manual')}
                    </span>
                  </div>
                </div>
              </div>

              {/* Info extra: marca / modelo / lugares */}
              <div className="grid grid-cols-3 gap-2 mb-4">
                {modalCarro.marca && (
                  <div className="bg-slate-50 rounded-lg p-2 text-center">
                    <span className="text-[8px] font-black uppercase text-slate-400 block">
                      Marca
                    </span>
                    <span className="text-[10px] font-bold text-slate-700 line-clamp-1">
                      {modalCarro.marca}
                    </span>
                  </div>
                )}
                {modalCarro.modelo && (
                  <div className="bg-slate-50 rounded-lg p-2 text-center">
                    <span className="text-[8px] font-black uppercase text-slate-400 block">
                      Modelo
                    </span>
                    <span className="text-[10px] font-bold text-slate-700 line-clamp-1">
                      {modalCarro.modelo}
                    </span>
                  </div>
                )}
                {modalCarro.lugares && (
                  <div className="bg-slate-50 rounded-lg p-2 text-center">
                    <span className="text-[8px] font-black uppercase text-slate-400 block">
                      Lugares
                    </span>
                    <span className="text-[10px] font-bold text-slate-700">
                      {modalCarro.lugares}
                    </span>
                  </div>
                )}
              </div>

              {modalCarro.descricao_curta && (
                <p className="text-xs text-slate-500 leading-relaxed mb-4 line-clamp-2">
                  {modalCarro.descricao_curta}
                </p>
              )}

              <div className="flex gap-3">
                <button
                  onClick={handleFecharModal}
                  className="flex-1 py-3 rounded-xl border-2 border-slate-200 text-slate-600 font-black text-xs uppercase tracking-wider hover:bg-slate-50 transition-all cursor-pointer active:scale-95"
                >
                  {t('fechar') || 'Fechar'}
                </button>
                <button
                  onClick={() =>
                    navigate(`/carro/${modalCarro.slug || modalCarro.id}`)
                  }
                  className="flex-[2] py-3 rounded-xl bg-blue-600 hover:bg-blue-700 text-white font-black text-xs uppercase tracking-wider transition-all cursor-pointer active:scale-95 shadow-lg shadow-blue-600/30 flex items-center justify-center gap-2"
                >
                  {t('alugar') || 'Alugar'}{' '}
                  <ChevronRight size={14} />
                </button>
              </div>
            </div>
          </div>

          {/* Keyframes CSS */}
          <style>{`
            @keyframes modalPop {
              0% {
                opacity: 0;
                transform: translate(-50%, -50%) scale(0.7);
              }
              60% {
                opacity: 1;
                transform: translate(-50%, -50%) scale(1.03);
              }
              100% {
                opacity: 1;
                transform: translate(-50%, -50%) scale(1);
              }
            }
            @keyframes modalClose {
              0% {
                opacity: 1;
                transform: translate(-50%, -50%) scale(1);
              }
              100% {
                opacity: 0;
                transform: translate(-50%, -50%) scale(0.9);
              }
            }
            @keyframes flashPulse {
              0% {
                opacity: 0;
                transform: scale(0.5);
              }
              35% {
                opacity: 1;
              }
              100% {
                opacity: 0;
                transform: scale(1.6);
              }
            }
          `}</style>
        </>
      )}
    </div>
  );
};

export default MapaCarros;

