const MAPBOX_TOKEN = import.meta.env.VITE_MAPBOX_TOKEN;

// ============================================================
// DICIONÁRIO DE COORDENADAS (ilhas + cidades + zonas)
// ============================================================
const COORDENADAS_ILHAS = {
  // ILHAS
  'Santo Antão': { lat: 17.0667, lng: -25.1667 },
