          <div className="lg:col-span-4">
            {tipo === 'alojamento' ? (
              <ResumoReservaAlojamento 
                reserva={reservaData || {}}
                totalHospedes={totalPessoas}
                precoTotal={precoTotal}
                showPaymentInfo={true}
                paymentStatus="paid"
                isConfirmed={true}
                codigoReserva={codigoReserva}
              />
            ) : tipo === 'carro' ? (
              <ResumoReservaCarro 
                reserva={reservaData || {}}
                precoTotal={precoTotal}
                showPaymentInfo={true}
                paymentStatus="paid"
                isConfirmed={true}
                codigoReserva={codigoReserva}
              />
            ) : (
              <ResumoReservaExperiencia 
                reserva={reservaData || {}}
                totalPessoas={totalPessoas}
                precoTotal={precoTotal}
                showPaymentInfo={true}
                paymentStatus="paid"
                isConfirmed={true}
                codigoReserva={codigoReserva}
              />
            )}
          </div>
        </div>
      </div>

      {/* CSS para impressão */}
      <style>{`
        @media print {
          body * {
            visibility: hidden;
          }
          .print-area, .print-area * {
            visibility: visible;
          }
          .print-area {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
          }
          button, .no-print {
            display: none !important;
          }
        }
      `}</style>
    </div>
  );
};

