// src/pages/Favoritos.jsx
import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { useFavoritos } from '../hooks/useFavoritos';
import { Link } from 'react-router-dom';
import { Home, Car, Palmtree, Trash2, MapPin, Star } from 'lucide-react';

const Favoritos = () => {
  const { t } = useTranslation();
  const { favoritos, removeFavorito, recarregar, loading } = useFavoritos();
  const [activeTab, setActiveTab] = useState('alojamentos');
  const [removendoId, setRemovendoId] = useState(null);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [user, setUser] = useState(null);

  // Verificação segura de autenticação (JWT + LocalStorage)
  useEffect(() => {
    try {
      const token = localStorage.getItem('token') || localStorage.getItem('morabeza_token');
      if (token) {
        const base64Url = token.split('.')[1];
        const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
        const jsonPayload = decodeURIComponent(atob(base64).split('').map(c => {
          return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
        }).join(''));
        const parsed = JSON.parse(jsonPayload);
        const userData = parsed.data || parsed;
        if (userData?.id) {
          setIsLoggedIn(true);
          setUser(userData);
          return;
        }
      }

      // Fallback para as chaves tradicionais de utilizador no LocalStorage
      const savedUser = localStorage.getItem('user') || 
                        localStorage.getItem('morabeza_user') || 
                        localStorage.getItem('morabeza_admin');
      if (savedUser) {
        const parsedUser = JSON.parse(savedUser);
        if (parsedUser) {
          setIsLoggedIn(true);
          setUser(parsedUser);
        }
      }
    } catch (e) {
      console.error('Erro ao verificar autenticação:', e);
    }
  }, []);

  const tabs = [
    { id: 'alojamentos', label: t('alojamentos'), icon: <Home size={14} />, count: favoritos.alojamentos?.length || 0 },
    { id: 'carros', label: t('carros'), icon: <Car size={14} />, count: favoritos.carros?.length || 0 },
    { id: 'experiencias', label: t('experiencias'), icon: <Palmtree size={14} />, count: favoritos.experiencias?.length || 0 }
  ];

  const getLinkTo = (tipo, item) => {
    if (tipo === 'alojamentos') return `/alojamentos/${item.slug || item.id}`;
    if (tipo === 'carros') return `/carros/${item.slug || item.id}`;
    return `/experiencia/${item.slug || item.id}`;
  };

  const getPreco = (tipo, item) => {
    if (tipo === 'alojamentos') return item.preco_noite;
    if (tipo === 'carros') return item.preco_dia;
    return item.preco;
  };

  const getPrecoLabel = (tipo) => {
    if (tipo === 'alojamentos') return t('por_noite_curto');
    if (tipo === 'carros') return t('por_dia');
    return t('por_pessoa');
  };

  const handleRemover = async (e, tipo, itemId) => {
    e.preventDefault();
    e.stopPropagation();
    setRemovendoId(itemId);
    await removeFavorito(tipo.slice(0, -1), itemId);
    setRemovendoId(null);
  };

  const currentItems = favoritos[activeTab] || [];

  useEffect(() => {
    if (isLoggedIn) {
      recarregar();
    }
  }, [activeTab, isLoggedIn, recarregar]);

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-white font-sans pt-24 pb-16">
        <div className="max-w-7xl mx-auto px-4 md:px-6">
          <div className="text-center py-16 bg-slate-50 rounded-3xl border border-slate-100">
            <div className="text-6xl mb-4">🔐</div>
            <h2 className="text-2xl font-bold text-[#1a2b6d] mb-2">{t('login_para_favoritos')}</h2>
            <p className="text-slate-500 mb-6">{t('faça_login_para_ver_favoritos')}</p>
            <Link 
              to="/"
              className="inline-block bg-blue-600 text-white px-6 py-3 rounded-xl font-bold hover:bg-blue-700 transition"
            >
              {t('voltar_inicio')}
            </Link>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-white font-sans pt-24 pb-16">
      <div className="max-w-7xl mx-auto px-4 md:px-6">
        <div className="mb-8">
          <h1 className="text-2xl md:text-3xl font-black text-[#1a2b6d] tracking-tighter italic uppercase">
            {t('meus_favoritos')}
          </h1>
          <div className="h-1.5 w-20 bg-blue-600 mt-2"></div>
          <p className="text-sm text-slate-500 mt-3">
            {t('olá')}, <span className="font-bold text-blue-600">{user?.name || user?.nome || user?.full_name || 'Utilizador'}</span>! 
            {t('estes_sao_seus_favoritos')}
          </p>
        </div>

        {/* Tabs */}
        <div className="flex flex-wrap gap-2 mb-6 border-b border-slate-200 pb-3">
          {tabs.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg font-bold text-[11px] transition-all ${
                activeTab === tab.id
                  ? 'bg-blue-600 text-white shadow-md'
                  : 'bg-white border border-slate-200 text-slate-600 hover:bg-slate-50'
              }`}
            >
              {tab.icon}
              {tab.label}
              <span className={`text-[9px] px-1.5 py-0.5 rounded-full ${
                activeTab === tab.id ? 'bg-white/20 text-white' : 'bg-slate-100 text-slate-500'
              }`}>
                {tab.count}
              </span>
            </button>
          ))}
        </div>

        {/* Lista de Favoritos */}
        {loading ? (
          <div className="flex justify-center py-12">
            <div className="w-8 h-8 border-2 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
          </div>
        ) : currentItems.length === 0 ? (
          <div className="text-center py-12 bg-slate-50 rounded-2xl border border-slate-100">
            <div className="text-5xl mb-3">❤️</div>
            <p className="text-slate-500 font-medium text-sm">{t('sem_favoritos', { categoria: tabs.find(t => t.id === activeTab)?.label })}</p>
            <Link 
              to={`/${activeTab}`}
              className="inline-block mt-3 text-blue-600 font-bold text-[11px] hover:underline"
            >
              {t('explorar')} {tabs.find(t => t.id === activeTab)?.label}
            </Link>
          </div>
        ) : (
          <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-3">
            {currentItems.map((item) => (
              <div key={item.id} className="relative group bg-white rounded-xl border border-gray-100 overflow-hidden hover:shadow-md transition-all duration-300">
                <Link to={getLinkTo(activeTab, item)} className="block">
                  <div className="relative aspect-square overflow-hidden bg-gray-100">
                    <img 
                      src={item.imagem_url || 'https://images.unsplash.com/photo-1566073771259-6a8506099945?w=200'}
                      alt={item.titulo}
                      className="w-full h-full object-cover transition-transform duration-300 group-hover:scale-105"
                      onError={(e) => e.target.src = 'https://images.unsplash.com/photo-1566073771259-6a8506099945?w=200'}
                    />
                    <button
                      onClick={(e) => handleRemover(e, activeTab, item.id)}
                      disabled={removendoId === item.id}
                      className="absolute top-2 right-2 p-1.5 bg-white/90 backdrop-blur-sm rounded-full shadow-md z-20 hover:scale-110 transition-transform disabled:opacity-50"
                    >
                      {removendoId === item.id ? (
                        <div className="w-3 h-3 border-2 border-red-500 border-t-transparent rounded-full animate-spin"></div>
                      ) : (
                        <Trash2 size={12} className="text-red-500" />
                      )}
                    </button>
                    {item.estrelas && (
                      <div className="absolute bottom-2 left-2 flex items-center gap-0.5 bg-black/50 backdrop-blur-sm px-1.5 py-0.5 rounded-full">
                        <Star size={10} className="fill-yellow-400 text-yellow-400" />
                        <span className="text-[9px] font-bold text-white">
                          {typeof item.estrelas === 'number' ? item.estrelas.toFixed(1) : (Number(item.estrelas) || 4.5).toFixed(1)}
                        </span>
                      </div>
                    )}
                  </div>
                  <div className="p-2 text-left">
                    <h3 className="text-xs font-bold text-[#1a2b6d] line-clamp-1 group-hover:text-blue-600 transition-colors">
                      {item.titulo}
                    </h3>
                    <div className="flex items-center gap-0.5 mt-0.5">
                      <MapPin size={10} className="text-blue-500" />
                      <span className="text-[9px] text-slate-500 truncate">
                        {item.localizacao || t('cabo_verde')}
                      </span>
                    </div>
                    <div className="flex items-center justify-between mt-1.5 pt-1 border-t border-gray-50">
                      <div className="flex items-baseline gap-0.5">
                        <span className="text-xs font-black text-[#1a2b6d]">
                          {Number(getPreco(activeTab, item)).toLocaleString('pt-PT')}
                        </span>
                        <span className="text-[8px] font-bold text-gray-400 uppercase">{t('cve')}</span>
                      </div>
                      <span className="text-[8px] text-gray-400">{getPrecoLabel(activeTab)}</span>
                    </div>
                  </div>
                </Link>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default Favoritos;

// Pagamento.jsx - v6 (sem holds / quarto_ocupacao) + FormularioPagamentoStripe UI + fetch robusto
import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { useLocation, useNavigate } from 'react-router-dom';
import { Check, ArrowLeft, ShieldCheck, AlertCircle } from 'lucide-react';
import { loadStripe } from '@stripe/stripe-js';
import { Elements, useStripe, useElements, CardNumberElement } from '@stripe/react-stripe-js';
import { useToast } from '../Toast';
import FormularioPagamentoStripe from './FormularioPagamentoStripe';

const ResumoReservaExperiencia = React.lazy(() => import('../features/experiencias/components/ResumoReservaExperiencia'));
const ResumoReservaAlojamento = React.lazy(() => import('../features/alojamento/components/ResumoReservaAlojamento'));
const ResumoReservaCarro = React.lazy(() => import('../features/carros/components/ResumoReservaCarro'));

const API_BASE = 'https://welovepalop.com';
const TAXA_CONVERSAO_CVE_EUR = 110.265;

const CACHE_KEYS = {
  alojamento: 'reservaAlojamentoPendente',
  carro: 'reservaCarroPendente',
  experiencia: 'reservaPendente',
};

const getTotalPagar = (tipo, reserva) => {
  if (!reserva) return 0;
  return Number(reserva.precoTotal || reserva.totalGeral || 0);
};

let stripePromise = null;
const getStripePromise = () => {
  if (!stripePromise) {
    stripePromise = loadStripe(import.meta.env.VITE_STRIPE_PUBLIC_KEY);
  }
  return stripePromise;
};

// Helper robusto: lê a resposta como texto e só depois faz JSON.parse
const lerJsonSeguro = async (response) => {
  const texto = await response.text();
  if (!texto || !texto.trim()) {
    throw new Error('Resposta vazia do servidor.');
  }
  try {
    return JSON.parse(texto);
  } catch (e) {
    console.error('Resposta não-JSON do servidor:', texto.slice(0, 300));
    throw new Error('Resposta inválida do servidor.');
  }
};

const fetchComTimeout = async (url, options = {}, timeoutMs = 8000) => {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await fetch(url, { ...options, signal: controller.signal });
    clearTimeout(timeoutId);
    return response;
  } catch (err) {
    clearTimeout(timeoutId);
    if (err.name === 'AbortError') {
      throw new Error('Tempo limite excedido. Tente novamente.');
    }
    throw new Error('Falha de rede. Verifique a sua ligação.');
  }
};

const PagamentoContent = () => {
  const { t } = useTranslation();
  const { showToast } = useToast();
  const location = useLocation();
  const navigate = useNavigate();
  const stripe = useStripe();
  const elements = useElements();

  const isProcessingRef = useRef(false);
  const hasMountedRef = useRef(false);

  const { reservaData, tipo: tipoState } = location.state || {};

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [reserva, setReserva] = useState(reservaData || {});
  const [tipo, setTipo] = useState(tipoState || 'experiencia');

  // ---------------------------------------------------------
  // Bootstrap
  // ---------------------------------------------------------
  useEffect(() => {
    if (hasMountedRef.current) return;
    hasMountedRef.current = true;

    window.scrollTo(0, 0);

    if (reservaData && Object.keys(reservaData).length > 0) {
      if (tipoState === 'carro') setTipo('carro');
      else if (tipoState === 'alojamento') setTipo('alojamento');
      else setTipo('experiencia');
      return;
    }

    for (const [key, storageKey] of Object.entries(CACHE_KEYS)) {
      const cache = sessionStorage.getItem(storageKey);
      if (cache) {
        try {
          const dados = JSON.parse(cache);
          setReserva(dados.reservaData || {});
          setTipo(key);
          break;
        } catch (e) {
          console.error('Erro parse cache:', e);
        }
      }
    }
  }, [reservaData, tipoState]);

  // ---------------------------------------------------------
  // Emails
  // ---------------------------------------------------------
  const enviarEmailsConfirmacao = useCallback(async (dadosAPI) => {
    try {
      const keyStorage = CACHE_KEYS[tipo];
      const cache = sessionStorage.getItem(keyStorage);
      if (!cache) return;
      const dados = JSON.parse(cache);
      const { reservaData: rD, participantePrincipal, participantesAdicionais } = dados;
      if (!participantePrincipal?.email) return;

      let dataFormatada, horarioFormatado, quantidadeLabel;
      if (tipo === 'alojamento') {
        dataFormatada = `${rD?.checkIn || ''} até ${rD?.checkOut || ''}`;
        horarioFormatado = `${rD?.noites || 0} ${t('noites')}`;
        quantidadeLabel = rD?.totalHospedes || 1;
      } else if (tipo === 'carro') {
        dataFormatada = `${rD?.checkIn || ''} até ${rD?.checkOut || ''}`;
        horarioFormatado = `${rD?.dias || 0} ${t('dias')}`;
        quantidadeLabel = 1;
      } else {
        dataFormatada = rD?.data || new Date().toLocaleDateString('pt-PT');
        horarioFormatado = `${rD?.periodo || ''} ${rD?.horario || ''}`.trim();
        quantidadeLabel = rD?.participantes || 1;
      }

      const emailPayload = {
        email_cliente: participantePrincipal.email,
        nome_cliente: participantePrincipal.nome_completo || t('cliente'),
        phone_cliente: participantePrincipal.phone || '',
        codigo_reserva: dadosAPI?.codigo_reserva || '',
        reserva_id: String(dadosAPI?.reserva_id || ''),
        experiencia: rD?.titulo || t('reserva_morabeza'),
        data: dataFormatada,
        horario: horarioFormatado,
        quantidade_pessoas: quantidadeLabel,
        preco_total: getTotalPagar(tipo, rD),
        metodo_pagamento: 'cartao',
        status_pagamento: 'pago',
        participante_principal: {
          nome_completo: participantePrincipal.nome_completo || '',
          email: participantePrincipal.email || '',
          phone: participantePrincipal.phone || '',
        },
        participantes_adicionais: (participantesAdicionais || []).map(p => ({
          nome_completo: p?.nome_completo || '',
          email: p?.email || '',
          phone: p?.phone || '',
        })),
      };

      fetch(`${API_BASE}/api/send_email.php`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(emailPayload),
      }).catch(() => {});
    } catch (err) {
      console.error('❌ Erro ao enviar e-mails:', err);
    }
  }, [tipo, t]);

  // ---------------------------------------------------------
  // Salvar reserva (sem holds, sem quarto_ocupacao)
  // ---------------------------------------------------------
  const salvarReservaNoBackend = useCallback(async (dadosTransacao) => {
    const keyStorage = CACHE_KEYS[tipo];
    const cache = sessionStorage.getItem(keyStorage);
    if (!cache) throw new Error(t('erro_sessao_expirada'));

    const dados = JSON.parse(cache);
    const { reservaData: rD, participantePrincipal, participantesAdicionais, usuario } = dados;

    if (!participantePrincipal) {
      throw new Error(t('erro_participante_nao_encontrado'));
    }

    const fin = rD?.financeiro || {};
    let payload;

    if (tipo === 'alojamento') {
      payload = {
        category: 'Alojamento',
        usuario: {
          email: participantePrincipal.email || '',
          nome_completo: participantePrincipal.nome_completo || '',
          phone: participantePrincipal.phone || '',
          google_id: usuario?.google_id || null,
        },
        reserva: {
          alojamento_id: rD?.id,
          quartos: (rD?.quartos || []).map(q => ({
            tipo_quarto_id: q.tipoQuartoId,
            quantidade: q.quantidade,
            preco_noite: q.precoNoite,
            capacidade: q.capacidade,
          })),
          data_checkin: rD?.checkIn,
          data_checkout: rD?.checkOut,
          quantidade_hospedes: rD?.totalHospedes,
          preco_total: getTotalPagar('alojamento', rD),
          noites: rD?.noites,
          financeiro: {
            subtotalNoites: fin.subtotalNoites || 0,
            taxaLimpeza: fin.taxaLimpeza || 0,
            comissaoMorabeza: fin.comissaoMorabeza || 0,
            valorLiquidoAnfitriao: fin.valorLiquidoAnfitriao || 0,
            valorTotalCliente: fin.valorTotalCliente || 0,
          },
        },
        participante_principal: { ...participantePrincipal },
        participantes_adicionais: (participantesAdicionais || []).map(p => ({ ...p })),
        metodo_pagamento: 'cartao',
        status_pagamento: 'pago',
        stripe_id: dadosTransacao?.id || null,
      };
    } else if (tipo === 'carro') {
      payload = {
        category: 'Carro',
        usuario: {
          email: participantePrincipal.email || '',
          nome_completo: participantePrincipal.nome_completo || '',
          phone: participantePrincipal.phone || '',
          google_id: usuario?.google_id || null,
        },
        reserva: {
          id: rD?.id,
          checkIn: rD?.checkIn,
          checkOut: rD?.checkOut,
          dias: rD?.dias,
          preco_total: getTotalPagar('carro', rD),
          carro_id: rD?.id,
        },
        participante_principal: {
          ...participantePrincipal,
          hora_levantamento: participantePrincipal.hora_levantamento || '10:00',
          carta_conducao_nome: participantePrincipal.carta_conducao_nome || '',
          observacoes: participantePrincipal.observacoes || '',
        },
        participantes_adicionais: [],
        metodo_pagamento: 'cartao',
        status_pagamento: 'pago',
        stripe_id: dadosTransacao?.id || null,
      };
    } else {
      payload = {
        category: 'Experiencia',
        usuario: {
          email: participantePrincipal.email || '',
          nome_completo: participantePrincipal.nome_completo || '',
          phone: participantePrincipal.phone || '',
          google_id: usuario?.google_id || null,
        },
        reserva: {
          experiencia_id: rD?.id,
          data_participacao: rD?.dataISO,
          horario: `${rD?.periodo || ''} ${rD?.horario || ''}`.trim(),
          quantidade_pessoas: rD?.participantes,
          preco_total: getTotalPagar('experiencia', rD),
        },
        participante_principal: { ...participantePrincipal },
        participantes_adicionais: (participantesAdicionais || []).map(p => ({ ...p })),
        metodo_pagamento: 'cartao',
        status_pagamento: 'pago',
        stripe_id: dadosTransacao?.id || null,
      };
    }

    const response = await fetchComTimeout(`${API_BASE}/api/checkout_api.php`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    }, 8000);

    const result = await lerJsonSeguro(response);

    if (result.success && result.data) {
      enviarEmailsConfirmacao(result.data);
    }
    return result;
  }, [tipo, t, enviarEmailsConfirmacao]);

  // ---------------------------------------------------------
  // Finalizar pagamento
  // ---------------------------------------------------------
  const handleFinalizarPagamento = useCallback(async ({ zip } = {}) => {
    if (isProcessingRef.current || loading) return;
    isProcessingRef.current = true;
    setLoading(true);
    setError('');

    try {
      if (!stripe || !elements) {
        setError(t('erro_stripe_nao_carregado', 'Stripe não carregado. Recarregue a página.'));
        return;
      }

      const cardNumberElement = elements.getElement(CardNumberElement);
      if (!cardNumberElement) {
        setError(t('erro_cartao_invalido', 'Dados do cartão inválidos.'));
        return;
      }

      const totalPagar = getTotalPagar(tipo, reserva);
      const valorEmEUR = totalPagar / TAXA_CONVERSAO_CVE_EUR;

      if (valorEmEUR < 0.5) {
        setError(t('erro_valor_minimo_cartao', { valor: valorEmEUR.toFixed(2) }));
        return;
      }

      const valorEmCentavos = Math.round(valorEmEUR * 100);

      const resIntent = await fetchComTimeout(`${API_BASE}/api/create-payment-intent.php`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ amount: valorEmCentavos, currency: 'eur' }),
      }, 8000);

      if (!resIntent.ok) {
        throw new Error(t('erro_servidor_pagamentos', 'Servidor de pagamentos indisponível.'));
      }

      const dataIntent = await lerJsonSeguro(resIntent);

      if (!dataIntent.clientSecret) {
        throw new Error(dataIntent.error || t('erro_servidor_pagamentos', 'Servidor de pagamentos indisponível.'));
      }

      const result = await stripe.confirmCardPayment(dataIntent.clientSecret, {
        payment_method: {
          card: cardNumberElement,
          billing_details: zip ? { address: { postal_code: zip } } : undefined,
        },
      });

      if (result.error) {
        setError(result.error.message);
        return;
      }

      const saveResult = await salvarReservaNoBackend(result.paymentIntent);

      if (saveResult.success) {
        sessionStorage.removeItem(CACHE_KEYS[tipo]);
        isProcessingRef.current = false;
        navigate('/confirmacao', {
          state: {
            reservaId: saveResult.data?.reserva_id,
            codigoReserva: saveResult.data?.codigo_reserva,
            reservaData: reserva,
            metodoPagamento: 'cartao',
            tipo,
            status: 'pago',
          },
        });
        return;
      } else {
        setError(saveResult.error || t('erro_registar_reserva', 'Erro ao registar a reserva.'));
        showToast(
          t('pagamento_cobrado_reserva_falhou', 'Pagamento efetuado mas houve um erro ao registar. Contacte o suporte.'),
          'error'
        );
      }
    } catch (err) {
      console.error('Erro no pagamento:', err);
      setError(err.message || t('erro_geral_pagamento', 'Erro ao processar o pagamento.'));
    } finally {
      setLoading(false);
      isProcessingRef.current = false;
    }
  }, [stripe, elements, reserva, tipo, t, navigate, salvarReservaNoBackend, showToast, loading]);

  const getTituloStepper = () => {
    if (tipo === 'alojamento') return t('dados_hospedes');
    if (tipo === 'carro') return t('dados_condutor');
    return t('dados_participantes');
  };

  const steps = [
    { n: 1, label: getTituloStepper(), check: true },
    { n: 2, label: t('step_pagamento'), active: true },
    { n: 3, label: t('step_confirmacao') },
  ];

  return (
    <div className="min-h-screen bg-white font-sans text-slate-900 p-4 md:p-10">
      <div className="max-w-7xl mx-auto">
        <div className="flex items-center justify-between mb-12 overflow-x-auto pb-4">
          {steps.map((s, i, arr) => (
            <React.Fragment key={i}>
              <div className="flex flex-col items-center min-w-[120px]">
                <div className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold mb-2 ${
                  s.active ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' :
                  s.check ? 'bg-blue-600 text-white' : 'border border-slate-200 text-slate-400'
                }`}>
                  {s.check ? <Check size={14} strokeWidth={3} /> : s.n}
                </div>
                <span className={`text-[10px] font-medium whitespace-nowrap ${s.active || s.check ? 'text-blue-900 font-bold' : 'text-slate-400'}`}>
                  {s.label}
                </span>
              </div>
              {i < arr.length - 1 && <div className="flex-1 border-t border-dashed border-slate-200 mx-2 mb-6"></div>}
            </React.Fragment>
          ))}
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
          <div className="lg:col-span-8">
            <h1 className="text-2xl font-bold text-blue-900 mb-2 text-left">{t('pagamento')}</h1>
            <p className="text-slate-500 text-sm mb-6 text-left font-medium">{t('pagamento_com_cartao')}</p>

            <div className="bg-[#F8FFF9] border border-green-100 rounded-2xl p-4 flex gap-3 mb-8 text-left">
              <ShieldCheck className="text-green-500 shrink-0" size={20} />
              <div>
                <p className="text-sm font-bold text-green-900">{t('ambiente_pagamento_seguro')}</p>
                <p className="text-xs text-green-700 font-medium">{t('dados_protegidos_ssl')}</p>
              </div>
            </div>

            {error && (
              <div className="mb-6 p-4 bg-red-50 border border-red-200 rounded-lg flex items-center gap-3 text-red-700 text-sm text-left font-medium">
                <AlertCircle className="shrink-0 text-red-500" size={20} /> {error}
              </div>
            )}

            <div className="space-y-4 text-left">
              <h3 className="text-xs font-black text-blue-900 uppercase tracking-wider mb-4">
                {t('dados_cartao')}
              </h3>

              <FormularioPagamentoStripe
                valorTotal={getTotalPagar(tipo, reserva)}
                moeda="CVE"
                onPagar={handleFinalizarPagamento}
              />
            </div>

            <div className="mt-8 flex flex-col sm:flex-row justify-start gap-4">
              <button
                onClick={() => navigate(-1)}
                disabled={loading}
                className="px-6 py-3 border border-slate-200 rounded-lg text-sm font-bold flex items-center justify-center gap-2 hover:bg-slate-50 transition text-slate-700 shadow-sm disabled:opacity-50"
              >
                <ArrowLeft size={18}/> {t('voltar')}
              </button>
            </div>
          </div>

          <div className="lg:col-span-4">
            <React.Suspense fallback={<div className="p-8 text-center">Carregando...</div>}>
              {tipo === 'alojamento' ? (
                <ResumoReservaAlojamento
                  reserva={reserva}
                  totalHospedes={reserva?.totalHospedes}
                  precoTotal={getTotalPagar('alojamento', reserva)}
                  showPaymentInfo={true}
                  paymentStatus="pending"
                />
              ) : tipo === 'carro' ? (
                <ResumoReservaCarro
                  reserva={reserva}
                  precoTotal={getTotalPagar('carro', reserva)}
                  showPaymentInfo={true}
                  paymentStatus="pending"
                />
              ) : (
                <ResumoReservaExperiencia
                  reserva={reserva}
                  totalPessoas={reserva?.participantes}
                  precoTotal={getTotalPagar('experiencia', reserva)}
                  showPaymentInfo={true}
                  paymentStatus="pending"
                />
              )}
            </React.Suspense>
          </div>
        </div>
      </div>
    </div>
  );
};

const Pagamento = () => (
  <Elements stripe={getStripePromise()}>
    <PagamentoContent />
  </Elements>
);

